import type { CurrencyCode } from './utils/localization';
import type { PERMISSION_KEYS } from './permissions';

export type PermissionKey = typeof PERMISSION_KEYS[number];
export type Permissions = Partial<Record<PermissionKey, boolean>>;

export interface User {
  id: string;
  name: string;
  email: string;
  roleId: string;
  permissions?: Permissions;
  avatarUrl?: string;
  commissionRate?: number;
}

export interface Role {
  id: string;
  name: string;
  permissions: Permissions;
}

export interface ProductAttribute {
  id: string;
  name: string;
  values: string[];
}

export interface ProductVariant {
  id: string;
  sku: string;
  attributes: Record<string, string>;
  stock: number;
  price?: number;
}

export interface Product {
  id: string;
  name: string;
  category: string;
  sku: string;
  stock: number;
  warehouseStocks: Record<string, number>;
  reorderLevel: number;
  costPrice: number;
  sellPrice: number;
  description?: string;
  imageUrl?: string;
  isFeatured?: boolean;
  expiryDate?: string;
  hasVariants?: boolean;
  isSerialized?: boolean;
}

export type CustomerTier = 'Silver' | 'Gold' | 'VIP';

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  debt: number;
  points: number;
  tier?: CustomerTier;
  totalSpent?: number;
}

export interface SaleItem {
  id: string;
  name: string;
  quantity: number;
  sellPrice: number;
  discount?: number;
}

export interface Sale {
  id: string;
  date: string;
  customer: { id: string; name: string };
  cashier: { id: string; name: string };
  items: SaleItem[];
  total: number;
  amountPaid: number;
  paymentMethod: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit';
  discount: number;
  vatAmount?: number;
  status: 'Completed' | 'Refunded';
  warehouseId: string;
  treasuryId: string;
  pointsRedeemed?: number;
  installmentPlan?: any;
  shipping?: number;
  payments?: PaymentDetail[];
  shiftId?: string;
}

export interface Supplier {
  id: string;
  name: string;
  contactPerson: string;
  phone: string;
  email?: string;
  address?: string;
}

export interface Purchase {
  id: string;
  date: string;
  supplier: { id: string; name: string };
  items: any[];
  total: number;
  amountPaid: number;
  paymentMethod: string;
  status: 'Paid' | 'Partial' | 'Unpaid';
  discount: number;
  discountType: 'amount' | 'percent';
  warehouseId: string;
  treasuryId: string;
}

export interface Warehouse {
  id: string;
  name: string;
  location: string;
  isDefault?: boolean;
}

export interface StoreSettings {
  storeName: string;
  vatRate: number;
  taxRegisterNumber: string;
  invoiceFooter: string;
  logoUrl: string;
  currency: CurrencyCode;
  nextInvoiceNumber: number;
  invoiceNumberPrefix: string;
  navigationStyle: 'sidebar' | 'grid';
  posLayout: 'classic' | 'horizontal' | 'streamlined';
  visiblePages: string[];
  homeGridItems: string[]; 
  enableSoundEffects: boolean;
  enablePosCategories: boolean;
  enableShiftManagement: boolean;
  autoLockTimeout?: number;
  fontSize?: 'small' | 'medium' | 'large';
  activeTheme?: AppTheme;
  fontFamily?: string;
  animationPreset?: string;
  enableChatPower?: boolean;
  notificationSettings?: {
    backupReminder: boolean;
    systemEvents: boolean;
  };
  autoBackup?: {
    enabled: boolean;
    lastBackupAt: number;
    intervalMinutes: number;
  };
  invoiceDesign: {
    template: 'modern' | 'classic' | 'minimal' | 'thermal' | 'free';
    showLogo: boolean;
    showQrCode: boolean;
    accentColor: string;
    customCss?: string;
    vatNumber?: string;
  };
  loyaltySettings: {
    enabled: boolean;
    earningRate: number;
    redemptionRate: number;
  };
  hardwareSettings?: {
    enableScanner: boolean;
  };
}

export interface ActivityLog {
  id: string;
  timestamp: string;
  action: string;
  details: string;
  user: string;
}

export interface FinancialReport {
  totalRevenue: number;
  totalCOGS: number;
  totalExpenses: number;
  totalPurchases: number;
  totalReturns: number;
  netProfit: number;
  dailyStats: any[];
}

export interface Partner {
  id: string;
  name: string;
  phone: string;
  sharePercentage: number;
  capitalInvested: number;
  joinedDate: string;
}

export interface Treasury {
  id: string;
  name: string;
  balance: number;
  currency: string;
  isDefault?: boolean;
}

export interface InstallmentPlan {
  id: string;
  customerName: string;
  saleId: string;
  remainingAmount: number;
  totalWithInterest: number;
  downPayment: number;
  interestRate: number;
  interestAmount: number;
  monthlyPayment: number;
  numberOfInstallments: number;
  status: 'Active' | 'Paid Off';
  payments: any[];
}

export interface SatisfactionAnalytics {
  happy: number;
  neutral: number;
  unhappy: number;
  total: number;
}

export interface SalesHistoryData {
  date: string;
  totalSales: number;
}

export interface SupplierPerformanceData {
  supplierId: string;
  supplierName: string;
  totalPurchaseValue: number;
  purchaseCount: number;
  returnRate: number;
}

export interface SuggestedOffer {
  discount: number;
  reason: string;
}

export interface SalesReturnItem {
  id: string;
  name: string;
  quantity: number;
  sellPrice: number;
  returnQuantity: number;
}

export interface SalesReturn {
  id: string;
  date: string;
  originalSaleId: string;
  items: SalesReturnItem[];
  totalRefund: number;
  user: { id: string; name: string };
  warehouseId: string;
  treasuryId: string;
}

export interface PurchaseReturnItem {
  productId: string;
  name: string;
  costPrice: number;
  quantity: number;
}

export interface PurchaseReturn {
  id: string;
  date: string;
  originalPurchaseId: string;
  items: PurchaseReturnItem[];
  totalRecovered: number;
  reason?: string;
  user: { id: string; name: string };
  warehouseId: string;
  treasuryId: string;
}

export interface Transaction {
  id: string;
  date: string;
  type: 'income' | 'expense';
  category: string;
  amount: number;
  description: string;
  user: string;
  treasuryId: string;
}

export interface StockTransfer {
  id: string;
  date: string;
  productId: string;
  fromWarehouseId: string;
  toWarehouseId: string;
  quantity: number;
}

export interface Notification {
  id: string;
  date: string;
  type: 'LOW_STOCK' | 'PROFIT_ALERT' | 'UNUSUAL_EXPENSE' | 'INFO';
  message: string;
}

export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface ToastMessage {
  id: string;
  message: string;
  type: ToastType;
}

export interface DashboardAnalytics {
  totalSalesToday: number;
  todaysTransactions: number;
  totalReceivables: number;
  totalStockValue: number;
  monthlySales: { name: string; sales: number }[];
  salesByCategory: { name: string; value: number }[];
  topProducts: { id: string; name: string; totalRevenue: number }[];
}

export interface EmployeePerformanceData {
  userId: string;
  userName: string;
  totalSalesValue: number;
  totalSalesCount: number;
  averageSaleValue: number;
  totalReturnsValue: number;
  returnRate: number;
}

export interface EmployeePerformanceAnalytics {
  performanceData: EmployeePerformanceData[];
  topPerformerByValue?: EmployeePerformanceData;
  topPerformerByCount?: EmployeePerformanceData;
}

export type LicenseType = 'Free' | 'Trial' | 'Monthly' | 'Semiannual' | 'Yearly' | 'Lifetime';

export interface LicenseInfo {
  status: 'UNLICENSED' | 'LICENSED' | 'TRIAL' | 'EXPIRED' | 'INVALID_DEVICE' | 'TAMPERED' | 'GRACE_PERIOD';
  key?: string;
  type?: LicenseType;
  activationDate?: string;
  deviceId?: string;
  blockchainHash?: string;
}

export interface SyncLog {
  tableName: string;
  recordCount: number;
  lastSynced: string;
}

export interface ChatMessage {
  id: string;
  text: string;
  sender: 'user' | 'bot';
  timestamp: number;
}

export interface InactiveCustomer {
  id: string;
  name: string;
  phone: string;
  lastPurchaseDate: string;
}

export interface StagnantProduct {
  id: string;
  name: string;
  stock: number;
  lastSoldDate?: string;
  daysSinceLastSale: number;
}

export interface GlobalSearchResults {
  products: Product[];
  sales: Sale[];
  customers: Customer[];
  purchases: Purchase[];
  suppliers: Supplier[];
  partners: Partner[];
  salesReturns: SalesReturn[];
  purchaseReturns: PurchaseReturn[];
  installments: InstallmentPlan[];
  stockTransfers: StockTransfer[];
}

export type AppTheme = 'light' | 'dark' | 'gold' | 'ramadan' | 'neumorphism' | 'forbed' | 'cyberpunk';

export interface ShippingCompany {
  id: string;
  name: string;
  contactPerson: string;
  phone: string;
  trackingUrl?: string;
}

export interface PaymentDetail {
  method: 'Cash' | 'Card' | 'Transfer' | 'Credit';
  amount: number;
}

export interface UpdatePackage {
  version: string;
  buildDate: string;
  changes: string[];
  hotfixes?: {
    patchVersion: string;
    securityLevel: string;
  };
  migrations?: any[];
}

export interface JournalEntry {
  id: string;
  date: string;
  reference: string;
  description: string;
  debit: { account: string; amount: number };
  credit: { account: string; amount: number };
}

export interface Shift {
  id: string;
  userId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  status: 'Open' | 'Closed';
  totalSales?: number;
  totalCashSales?: number;
  notes?: string;
}

export interface AdminAuditLog {
  id: string;
  timestamp: string;
  actor: string;
  action: string;
  details: string;
}

export interface AdminSecret {
  key: string;
  valueEncrypted: string;
  valueHmac: string;
}

import React, { useState, useEffect } from 'react';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { useSettings } from '../hooks/useSettings';
import { api } from '../services/mockApi';
import type { StoreSettings, User, Role } from '../types';
import { 
    Save, Monitor, Shield, Database, ImageIcon, LayoutGrid, Crown,
    Palette, Info, ShoppingCart, Heart, Download, RefreshCw, Smartphone, 
    Copy, CheckCircle, ExternalLink, Cpu, Code2, ShieldCheck, Upload
} from 'lucide-react';
import { useToasts } from '../hooks/useToasts';
import { useLicense } from '../hooks/useLicense';
import { CURRENCIES, toArabicIndic } from '../utils/localization';
import { processImageFile } from '../utils/imageHelpers';
import Modal from '../components/ui/Modal';

const SettingsPage: React.FC = () => {
    const { settings, updateSettings } = useSettings();
    const { addToast } = useToasts();
    const { licenseInfo, deviceId } = useLicense();

    const [activeTab, setActiveTab] = useState('general');
    const [localSettings, setLocalSettings] = useState<StoreSettings | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        if (settings) setLocalSettings(JSON.parse(JSON.stringify(settings)));
    }, [settings]);

    const handleSave = async () => {
        if (!localSettings) return;
        setIsSaving(true);
        try {
            await updateSettings(localSettings);
            addToast('تم حفظ كافة الإعدادات بنجاح', 'success');
        } catch (e) { addToast('خطأ في الحفظ', 'error'); }
        finally { setIsSaving(false); }
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file && localSettings) {
            try {
                const base64 = await processImageFile(file, 300);
                setLocalSettings({ ...localSettings, logoUrl: base64 });
                addToast('تم رفع الشعار بنجاح، اضغط حفظ لتأكيد التغيير.', 'success');
            } catch (err) { addToast('فشل معالجة الصورة', 'error'); }
        }
    };

    if (!localSettings) return <div className="p-20 text-center animate-pulse">جاري التحميل...</div>;

    const isPaid = !['Free', 'Trial'].includes(licenseInfo.type || '');

    const navItems = [
        { id: 'general', label: 'المتجر والضرائب', icon: <Monitor size={18} /> },
        { id: 'pos', label: 'البيع والولاء', icon: <ShoppingCart size={18} /> },
        { id: 'invoice', label: 'مصمم الفاتورة', icon: <Palette size={18} /> },
        { id: 'subscription', label: 'حالة الاشتراك', icon: <Crown size={18} /> },
        { id: 'maintenance', label: 'البيانات والصيانة', icon: <Database size={18} /> },
        { id: 'about', label: 'حول النظام', icon: <Info size={18} /> },
    ];

    return (
        <div className="max-w-7xl mx-auto animate-fadeIn pb-20">
            <div className="flex justify-between items-center mb-10">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white">إعدادات النظام</h1>
                    <p className="text-slate-500 font-medium">تحكم في هوية المنظومة وقواعد العمل المالية.</p>
                </div>
                <Button onClick={handleSave} isLoading={isSaving} className="h-12 px-8 rounded-2xl font-black shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                    <Save size={20} className="me-2" /> حفظ التغييرات
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <nav className="lg:col-span-1 space-y-1 bg-white/50 dark:bg-slate-900/50 p-2 rounded-3xl border border-slate-100 dark:border-slate-800 backdrop-blur-xl h-fit sticky top-32">
                    {navItems.map(item => (
                        <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl font-black text-xs transition-all ${activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/30' : 'text-slate-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20'}`}>
                            {item.icon} {item.label}
                        </button>
                    ))}
                </nav>

                <div className="lg:col-span-3 space-y-8">
                    {activeTab === 'general' && (
                        <Card title="هوية المتجر">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-6">
                                    <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">اسم المنشأة</label><input type="text" value={localSettings.storeName} onChange={e => setLocalSettings({...localSettings, storeName: e.target.value})} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                                    <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">العملة</label><select value={localSettings.currency} onChange={e => setLocalSettings({...localSettings, currency: e.target.value as any})} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-bold outline-none">{Object.keys(CURRENCIES).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                                </div>
                                <div className="flex flex-col items-center justify-center p-6 bg-slate-50 dark:bg-slate-800/40 rounded-4xl border-2 border-dashed dark:border-slate-700">
                                    {localSettings.logoUrl ? <img src={localSettings.logoUrl} className="w-32 h-32 object-contain mb-4 rounded-xl shadow-md" /> : <ImageIcon size={64} className="text-slate-300" />}
                                    <input type="file" id="logoUp" hidden accept="image/*" onChange={handleLogoUpload} />
                                    <Button variant="secondary" size="sm" onClick={() => document.getElementById('logoUp')?.click()} className="rounded-xl">تغيير الشعار</Button>
                                </div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'pos' && (
                        <Card title="إعدادات البيع والولاء">
                            <div className="space-y-6">
                                <label className="flex items-center gap-4 p-4 bg-indigo-50 dark:bg-indigo-900/10 rounded-2xl cursor-pointer">
                                    <Heart className="text-indigo-600" />
                                    <div className="flex-1"><h4 className="font-black text-sm">تفعيل برنامج الولاء</h4><p className="text-xs text-slate-500">تمكين العملاء من تجميع النقاط واستبدالها بخصومات.</p></div>
                                    <input type="checkbox" checked={localSettings.loyaltySettings.enabled} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, enabled: e.target.checked}})} className="w-6 h-6 rounded-lg text-indigo-600" />
                                </label>
                                <div className="grid grid-cols-2 gap-4">
                                    <div><label className="text-xs font-bold block mb-1">معدل الربح (١ جنية = كم نقطة؟)</label><input type="number" step="0.1" value={localSettings.loyaltySettings.earningRate} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, earningRate: parseFloat(e.target.value)||0}})} className="w-full p-3 border rounded-xl dark:bg-slate-800" /></div>
                                    <div><label className="text-xs font-bold block mb-1">قيمة النقطة (١ نقطة = كم جنية؟)</label><input type="number" step="0.1" value={localSettings.loyaltySettings.redemptionRate} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, redemptionRate: parseFloat(e.target.value)||0}})} className="w-full p-3 border rounded-xl dark:bg-slate-800" /></div>
                                </div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'invoice' && (
                        <Card title="مصمم الفاتورة الاحترافي">
                            <div className="space-y-6">
                                <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                                    {[
                                        { id: 'modern', label: 'عصري' },
                                        { id: 'classic', label: 'كلاسيكي' },
                                        { id: 'minimal', label: 'بسيط' },
                                        { id: 'thermal', label: 'حراري' },
                                        { id: 'free', label: 'تصميم حر' },
                                    ].map(t => (
                                        <button key={t.id} onClick={() => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, template: t.id as any}})} className={`p-4 rounded-2xl border-2 text-xs font-black transition-all ${localSettings.invoiceDesign.template === t.id ? 'border-indigo-600 bg-indigo-50 text-indigo-600 shadow-md' : 'border-slate-100 dark:border-slate-800 hover:border-indigo-200'}`}>{t.label}</button>
                                    ))}
                                </div>
                                {localSettings.invoiceDesign.template === 'free' && (
                                    <div className="animate-slideDown"><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">تنسيق CSS مخصص</label><textarea value={localSettings.invoiceDesign.customCss} onChange={e => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, customCss: e.target.value}})} className="w-full p-4 border rounded-2xl font-mono text-xs dark:bg-slate-900 bg-slate-50" rows={8} placeholder=".invoice-container { background: #fff; ... }" /></div>
                                )}
                                <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">تذييل الفاتورة</label><textarea value={localSettings.invoiceFooter} onChange={e => setLocalSettings({...localSettings, invoiceFooter: e.target.value})} className="w-full p-3 border rounded-xl dark:bg-slate-800" rows={3} /></div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'subscription' && (
                        <Card className="bg-gradient-to-br from-indigo-600 to-blue-700 text-white border-none shadow-xl relative overflow-hidden">
                            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
                            <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-10 p-4">
                                <div className="space-y-4 text-center md:text-start">
                                    <div className="p-4 bg-white/20 backdrop-blur-xl rounded-3xl w-fit mx-auto md:mx-0 shadow-lg border border-white/30"><Crown size={48} /></div>
                                    <h3 className="text-3xl font-black">حالة الاشتراك: {licenseInfo.type === 'Free' ? 'الخطة المجانية' : 'النسخة المدفوعة'}</h3>
                                    <p className="text-indigo-100 font-bold opacity-80">جهازك مرخص ومرتبط بالبصمة الرقمية لهذا النظام.</p>
                                </div>
                                <div className="bg-white/10 backdrop-blur-3xl p-6 rounded-4xl border border-white/20 text-center shadow-inner">
                                    <p className="text-[10px] font-black uppercase mb-2 opacity-70">معرف الجهاز الرقمي</p>
                                    <code className="text-2xl font-black font-mono tracking-widest">{deviceId}</code>
                                    <button onClick={() => {navigator.clipboard.writeText(deviceId); addToast('تم النسخ', 'success');}} className="block mt-4 text-xs font-black hover:underline mx-auto"><Copy size={12} className="inline ms-1"/> نسخ المعرف للمطور</button>
                                </div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'maintenance' && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-slideDown">
                            <Card title="النسخ الاحتياطي" className={!isPaid ? 'opacity-50 grayscale pointer-events-none' : ''}>
                                <div className="flex items-center gap-4 mb-6">
                                    <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl"><RefreshCw size={32} /></div>
                                    <h4 className="text-xl font-black">حماية البيانات</h4>
                                </div>
                                <p className="text-sm text-slate-500 mb-8 font-medium">قم بتنزيل نسخة كاملة من بياناتك (منتجات، عملاء، فواتير) في ملف مشفر.</p>
                                <div className="flex flex-col gap-3">
                                    <Button variant="secondary" className="w-full h-12 rounded-2xl font-black" onClick={async () => {
                                        const data = await api.getBackupData();
                                        const blob = new Blob([data], {type: 'application/json'});
                                        const url = URL.createObjectURL(blob);
                                        const a = document.createElement('a'); a.href = url; a.download = `backup_${new Date().toISOString().split('T')[0]}.json`; a.click();
                                    }}><Download size={18} className="me-2"/> تحميل نسخة احتياطية</Button>
                                    <Button variant="secondary" className="w-full h-12 rounded-2xl font-black border-2 border-slate-200"><Upload size={18} className="me-2"/> استيراد من ملف</Button>
                                </div>
                            </Card>
                            <Card title="إعادة الضبط" className="bg-rose-50/30 dark:bg-rose-900/5 border-rose-100 dark:border-rose-900/20">
                                <div className="flex items-center gap-4 mb-6 text-rose-600">
                                    <div className="p-3 bg-rose-100 rounded-2xl"><RefreshCw size={32} /></div>
                                    <h4 className="text-xl font-black">منطقة الخطر</h4>
                                </div>
                                <p className="text-sm text-rose-600/70 mb-8 font-medium">تحذير: سيتم مسح كافة البيانات بشكل نهائي من هذا المتصفح. لا يمكن التراجع عن هذا الإجراء.</p>
                                <Button variant="danger" className="w-full h-12 rounded-2xl font-black shadow-lg" onClick={() => { if(confirm('تأكيد مسح كافة بيانات المحل؟')) api.wipeBusinessData(); }}>إعادة تعيين المصنع</Button>
                            </Card>
                        </div>
