    SatisfactionAnalytics, User, SupplierPerformanceData
} from '../types';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: {
            storeName: 'تكنو باور POS',
            vatRate: 15,
            currency: 'SAR',
            nextInvoiceNumber: 1000,
            invoiceNumberPrefix: 'INV-',
