    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string): Promise<FinancialReport> => {
        const db = getDb();
        let sales = db.sales.filter((s: any) => s.date >= start && s.date <= end);
        if (cashierId) sales = sales.filter((s: any) => s.cashier.id === cashierId);

        const totalRevenue = sales.reduce((a: number, b: any) => a + b.total, 0);
        const purs = db.purchases.filter((p: any) => p.date >= start && p.date <= end);
        const totalPurchases = purs.reduce((a: number, b: any) => a + b.total, 0);
        const rets = db.salesReturns.filter((r: any) => r.date >= start && r.date <= end);
        const totalReturns = rets.reduce((a: number, b: any) => a + b.totalRefund, 0);

        return {
            totalRevenue,
            totalCOGS: totalPurchases, 
            totalExpenses: 0,
            totalPurchases,
            totalReturns,
            netProfit: totalRevenue - totalPurchases - totalReturns,
            dailyStats: []
        };
