        if (w.id) db.warehouses = db.warehouses.map((item: any) => item.id === w.id ? w : item);
        else { w.id = `w-${Date.now()}`; db.warehouses.push(w); }
        saveDb(db); return w;
    },
    deleteWarehouse: async (id: string) => {
        const db = getDb();
        db.warehouses = db.warehouses.filter((w: any) => w.id !== id);
        saveDb(db); return true;
    },
    getTreasuries: async () => getDb().treasuries,
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `t-${Date.now()}`; db.treasuries.push(t); }
        saveDb(db); return t;
    },
    deleteTreasury: async (id: string) => {
        const db = getDb();
        db.treasuries = db.treasuries.filter((t: any) => t.id !== id);
        saveDb(db); return true;
    },
    getTransactions: async () => getDb().transactions || [],
    saveTransaction: async (t: any) => {
        const db = getDb();
        if (t.id) db.transactions = db.transactions.map((item: any) => item.id === t.id ? t : item);
        else { 
            t.id = `tr-${Date.now()}`; 
            t.date = new Date().toISOString();
            t.user = 'المدير';
            db.transactions.push(t); 
        }
        updateTreasury(db, t.treasuryId, t.amount, t.type);
        saveDb(db); return t;
    },
    deleteTransaction: async (id: string) => {
        const db = getDb();
        db.transactions = db.transactions.filter((t: any) => t.id !== id);
        saveDb(db); return true;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
        else { c.id = `cust-${Date.now()}`; db.customers.push(c); }
        saveDb(db); return c;
    },
    getSuppliers: async () => getDb().suppliers,
    saveSupplier: async (s: any) => {
        const db = getDb();
        if (s.id) db.suppliers = db.suppliers.map((item: any) => item.id === s.id ? s : item);
        else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); }
        saveDb(db); return s;
    },
    deleteSupplier: async (id: string) => {
        const db = getDb();
        db.suppliers = db.suppliers.filter((s: any) => s.id !== id);
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (s: any) => {
        const db = getDb();
        if (s.id) db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === s.id ? s : item);
        else { s.id = `ship-${Date.now()}`; db.shippingCompanies.push(s); }
        saveDb(db); return s;
    },
    deleteShippingCompany: async (id: string) => {
        const db = getDb();
        db.shippingCompanies = db.shippingCompanies.filter((s: any) => s.id !== id);
        saveDb(db); return true;
    },
    getSales: async () => getDb().sales,
    getPurchases: async () => getDb().purchases,
    getSalesReturns: async () => getDb().salesReturns,
    getInstallmentPlans: async () => getDb().installments,
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let success = false;
        db.installments.forEach((plan: any) => {
            const pay = plan.payments.find((p: any) => p.id === paymentId);
            if (pay && pay.status === 'Pending') {
                pay.status = 'Paid';
                pay.paidDate = new Date().toISOString();
                plan.remainingAmount -= pay.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                updateTreasury(db, plan.treasuryId || 't-1', pay.amount, 'income');
                success = true;
            }
        });
        if (success) saveDb(db);
        return success;
    },
    getActivityLogs: async () => getDb().activityLogs,
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any): Promise<boolean> => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if (!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);

            if (!db.stockTransfers) db.stockTransfers = [];
            st.id = `st-${Date.now()}`;
            st.date = new Date().toISOString();
            db.stockTransfers.unshift(st);
            logAction(db, 'تحويل مخزون', `تحويل ${st.quantity} من ${p.name}`);
            saveDb(db);
            return true;
        }
        return false;
    },
    getUsers: async () => getDb().users || [],
    login: async (name: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.name === name);
        if (user && password === 'password') return user;
        return null;
    },
    reset: () => {
        localStorage.removeItem(DB_KEY);
        window.location.reload();
    },
    verifyPassword: async (userId: string, password: string) => {
        return password === 'password';
    },
    addNotification: async (n: any) => {
        const db = getDb();
        if (!db.notifications) db.notifications = [];
        const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n };
        db.notifications.unshift(newN);
        saveDb(db);
    },
    getNotifications: async () => getDb().notifications || [],
    getBackupData: async () => JSON.stringify(getDb()),
    wipeBusinessData: async () => {
        localStorage.clear();
        window.location.reload();
    },
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const today = new Date().toISOString().split('T')[0];
        const todaysSales = db.sales.filter((s: any) => s.date.startsWith(today));
        return {
            totalSalesToday: todaysSales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaysSales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + b.debt, 0),
            totalStockValue: db.products.reduce((a: number, b: any) => a + (b.stock * b.costPrice), 0),
            monthlySales: [
                { name: 'يناير', sales: 4000 }, { name: 'فبراير', sales: 3000 }, { name: 'مارس', sales: 2000 }
            ],
            salesByCategory: [],
            topProducts: db.products.slice(0, 5).map((p: any) => ({ id: p.id, name: p.name, totalRevenue: p.sellPrice * 10 }))
        };
    },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const data = db.users.map((u: any) => ({
            userId: u.id, userName: u.name, totalSalesValue: 0, totalSalesCount: 0, 
            averageSaleValue: 0, totalReturnsValue: 0, returnRate: 0
        }));
        return { performanceData: data, topPerformerByValue: data[0], topPerformerByCount: data[0] };
    },
    getSyncLogs: async (): Promise<SyncLog[]> => [
        { tableName: 'المنتجات', recordCount: 150, lastSynced: new Date().toISOString() },
        { tableName: 'المبيعات', recordCount: 500, lastSynced: new Date().toISOString() }
    ],
    getQueueCount: async () => 0,
    processQueue: async () => {},
    setOnlineStatus: (status: boolean) => {},
    getSatisfactionAnalytics: async (): Promise<SatisfactionAnalytics> => ({ happy: 85, neutral: 10, unhappy: 5, total: 100 }),
    submitFeedback: async (f: any) => {},
    getSalesHistoryForForecast: async () => [
        { date: '2023-01-01', totalSales: 100 }, { date: '2023-01-02', totalSales: 150 }
    ],
    getSupplierPerformanceData: async (): Promise<SupplierPerformanceData[]> => {
        const db = getDb();
        return db.suppliers.map((s: any) => ({
            supplierId: s.id, supplierName: s.name, totalPurchaseValue: 5000, 
            purchaseCount: 10, returnRate: 2
        }));
    },
    getInactiveCustomers: async (days: number) => {
        const db = getDb();
        return db.customers.slice(0, 3).map((c: any) => ({ ...c, lastPurchaseDate: '2023-01-01' }));
    },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const filter = (arr: any[]) => (arr || []).filter(i => (i.name || i.id || "").toLowerCase().includes(q.toLowerCase()));
        return {
            products: filter(db.products), sales: filter(db.sales), customers: filter(db.customers),
            purchases: filter(db.purchases), suppliers: filter(db.suppliers), partners: filter(db.partners),
            salesReturns: filter(db.salesReturns), purchaseReturns: filter(db.purchaseReturns),
            installments: filter(db.installments), stockTransfers: filter(db.stockTransfers)
        };
    },
    getStagnantProducts: async (days: number) => {
        const db = getDb();
        return db.products.slice(0, 3).map((p: any) => ({ ...p, stock: p.stock, daysSinceLastSale: 120 }));
    },
    getCustomerPurchaseHistory: async (cid: string) => {
        const db = getDb();
        return db.sales.filter((s: any) => s.customer.id === cid);
    },
    getCustomerReturnsHistory: async (cid: string) => {
        const db = getDb();
        return db.salesReturns.filter((r: any) => {
            const sale = db.sales.find((s: any) => s.id === r.originalSaleId);
            return sale && sale.customer.id === cid;
        });
    },
    updateSystemVersion: async (v: string, pkg: any) => {
        const db = getDb();
        db.settings.version = v;
        saveDb(db);
    },
    getJournalEntries: async (): Promise<JournalEntry[]> => [],
    getCurrentShift: async (uid: string) => {
        const db = getDb();
        return db.shifts.find((s: any) => s.userId === uid && s.status === 'Open') || null;
    },
    openShift: async (uid: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId: uid, startTime: new Date().toISOString(), startCash: amount, status: 'Open' } as Shift;
        db.shifts.push(shift);
        saveDb(db);
        return shift;
    },
    closeShift: async (sid: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === sid);
        if (shift) {
            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = notes;
            saveDb(db);
            return shift;
        }
        throw new Error("Shift not found");
    }
};

