    },
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        db.products = db.products.map((p: any) => {
            const up = products.find(u => u.id === p.id);
            return up ? up : p;
        });
        saveDb(db); return true;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber}`;
        if (!sale.id) db.settings.nextInvoiceNumber++;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);
        updateTreasury(db, sale.treasuryId, sale.amountPaid, 'income');
        logAction(db, 'عملية بيع', `فاتورة مبيعات #${id} بقيمة ${sale.total}`);
        saveDb(db); return finalSale;
    },
    updateSale: async (id: string, data: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...data } : s);
        saveDb(db); return true;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        updateTreasury(db, pur.treasuryId, pur.amountPaid, 'expense');
        logAction(db, 'عملية شراء', `شراء بضاعة من ${pur.supplier.name} بقيمة ${pur.total}`);
        saveDb(db); return pur;
    },
    updatePurchase: async (id: string, data: any) => {
        const db = getDb();
        db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...data } : p);
        saveDb(db); return true;
    },
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `sr-${Date.now()}`;
        ret.date = new Date().toISOString();
        db.salesReturns.unshift(ret);
        updateTreasury(db, ret.treasuryId, ret.totalRefund, 'expense');
        logAction(db, 'مرتجع مبيعات', `مرتجع للفاتورة #${ret.originalSaleId}`);
        saveDb(db); return ret;
    },
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    savePurchaseReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `pr-${Date.now()}`;
        ret.date = new Date().toISOString();
        db.purchaseReturns.push(ret);
        updateTreasury(db, ret.treasuryId, ret.totalRecovered, 'income');
        saveDb(db); return ret;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string): Promise<FinancialReport> => {
        const db = getDb();
        let sales = db.sales.filter((s: any) => s.date >= start && s.date <= end);
        const totalRevenue = sales.reduce((a: number, b: any) => a + b.total, 0);
        return { totalRevenue, totalCOGS: 0, totalExpenses: 0, totalPurchases: 0, totalReturns: 0, netProfit: 0, dailyStats: [] };
    },
    getPartners: async () => getDb().partners,
    savePartner: async (p: any) => {
        const db = getDb();
        if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `part-${Date.now()}`; db.partners.push(p); }
        saveDb(db); return p;
    },
    getWarehouses: async () => getDb().warehouses,
    saveWarehouse: async (w: any) => {
        const db = getDb();
        if (w.id) db.warehouses = db.warehouses.map((item: any) => item.id === w.id ? w : item);
        else { w.id = `w-${Date.now()}`; db.warehouses.push(w); }
        saveDb(db); return w;
    },
    deleteWarehouse: async (id: string) => {
        const db = getDb();
        db.warehouses = db.warehouses.filter((w: any) => w.id !== id);
        saveDb(db); return true;
    },
    getTreasuries: async () => getDb().treasuries,
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `t-${Date.now()}`; db.treasuries.push(t); }
        saveDb(db); return t;
    },
    deleteTreasury: async (id: string) => {
        const db = getDb();
        db.treasuries = db.treasuries.filter((t: any) => t.id !== id);
        saveDb(db); return true;
    },
    getTransactions: async () => getDb().transactions || [],
    saveTransaction: async (t: any) => {
        const db = getDb();
        if (t.id) db.transactions = db.transactions.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `tr-${Date.now()}`; t.date = new Date().toISOString(); t.user = 'المدير'; db.transactions.push(t); }
        updateTreasury(db, t.treasuryId, t.amount, t.type);
        saveDb(db); return t;
    },
    deleteTransaction: async (id: string) => {
        const db = getDb();
        db.transactions = db.transactions.filter((t: any) => t.id !== id);
        saveDb(db); return true;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
        else { c.id = `cust-${Date.now()}`; db.customers.push(c); }
        saveDb(db); return c;
    },
    getSuppliers: async () => getDb().suppliers,
    saveSupplier: async (s: any) => {
        const db = getDb();
        if (s.id) db.suppliers = db.suppliers.map((item: any) => item.id === s.id ? s : item);
        else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); }
        saveDb(db); return s;
    },
    deleteSupplier: async (id: string) => {
        const db = getDb();
        db.suppliers = db.suppliers.filter((s: any) => s.id !== id);
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (s: any) => {
        const db = getDb();
        if (s.id) db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === s.id ? s : item);
        else { s.id = `ship-${Date.now()}`; db.shippingCompanies.push(s); }
        saveDb(db); return s;
    },
    deleteShippingCompany: async (id: string) => {
        const db = getDb();
        db.shippingCompanies = db.shippingCompanies.filter((s: any) => s.id !== id);
        saveDb(db); return true;
    },
    getSales: async () => getDb().sales,
    getPurchases: async () => getDb().purchases,
    getSalesReturns: async () => getDb().salesReturns,
    getInstallmentPlans: async () => getDb().installments,
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let success = false;
        db.installments.forEach((plan: any) => {
            const pay = plan.payments.find((p: any) => p.id === paymentId);
            if (pay && pay.status === 'Pending') {
                pay.status = 'Paid'; pay.paidDate = new Date().toISOString();
                plan.remainingAmount -= pay.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                updateTreasury(db, plan.treasuryId || 't-1', pay.amount, 'income');
                success = true;
            }
        });
        if (success) saveDb(db); return success;
    },
    getActivityLogs: async () => getDb().activityLogs,
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any): Promise<boolean> => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if (!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            st.id = `st-${Date.now()}`;
            st.date = new Date().toISOString();
            db.stockTransfers.unshift(st);
            logAction(db, 'تحويل مخزون', `تحويل ${st.quantity} من ${p.name}`);
            saveDb(db); return true;
        }
        return false;
    },
    getUsers: async () => getDb().users || [],
    login: async (name: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.name === name);
        if (user && password === 'password') return user;
        return null;
    },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    verifyPassword: async (userId: string, password: string) => password === 'password',
    addNotification: async (n: any) => {
        const db = getDb();
        if (!db.notifications) db.notifications = [];
        const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n };
        db.notifications.unshift(newN);
        saveDb(db);
    },
    getNotifications: async () => getDb().notifications || [],
    getBackupData: async () => JSON.stringify(getDb()),
    wipeBusinessData: async () => { localStorage.clear(); window.location.reload(); },
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const today = new Date().toISOString().split('T')[0];
        const todaysSales = db.sales.filter((s: any) => s.date.startsWith(today));
        return {
            totalSalesToday: todaysSales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaysSales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + b.debt, 0),
            totalStockValue: db.products.reduce((a: number, b: any) => a + (b.stock * b.costPrice), 0),
            monthlySales: [], salesByCategory: [], topProducts: []
        };
    },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const data = db.users.map((u: any) => ({
            userId: u.id, userName: u.name, totalSalesValue: 0, totalSalesCount: 0, 
            averageSaleValue: 0, totalReturnsValue: 0, returnRate: 0
        }));
        return { performanceData: data };
    },
    getSyncLogs: async (): Promise<SyncLog[]> => [],
    getQueueCount: async () => 0,
    processQueue: async () => {},
    setOnlineStatus: (status: boolean) => {},
    getSatisfactionAnalytics: async (): Promise<SatisfactionAnalytics> => ({ happy: 85, neutral: 10, unhappy: 5, total: 100 }),
    submitFeedback: async (f: any) => {},
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async (): Promise<SupplierPerformanceData[]> => [],
    getInactiveCustomers: async (days: number) => [],
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const filter = (arr: any[]) => (arr || []).filter(i => (i.name || i.id || "").toLowerCase().includes(q.toLowerCase()));
        return {
            products: filter(db.products), sales: filter(db.sales), customers: filter(db.customers),
            purchases: filter(db.purchases), suppliers: filter(db.suppliers), partners: filter(db.partners),
            salesReturns: filter(db.salesReturns), purchaseReturns: filter(db.purchaseReturns),
            installments: filter(db.installments), stockTransfers: filter(db.stockTransfers)
        };
    },
    getStagnantProducts: async (days: number) => [],
    getCustomerPurchaseHistory: async (cid: string) => getDb().sales.filter((s: any) => s.customer.id === cid),
    getCustomerReturnsHistory: async (cid: string) => getDb().salesReturns.filter((r: any) => {
        const sale = getDb().sales.find((s: any) => s.id === r.originalSaleId);
        return sale && sale.customer.id === cid;
    }),
    updateSystemVersion: async (v: string, pkg: any) => { const db = getDb(); db.settings.version = v; saveDb(db); },
    getJournalEntries: async (): Promise<JournalEntry[]> => [],
    getCurrentShift: async (uid: string) => getDb().shifts.find((s: any) => s.userId === uid && s.status === 'Open') || null,
    openShift: async (uid: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId: uid, startTime: new Date().toISOString(), startCash: amount, status: 'Open' } as Shift;
        db.shifts.push(shift); saveDb(db); return shift;
    },
    closeShift: async (sid: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === sid);
        if (shift) { shift.status = 'Closed'; shift.endTime = new Date().toISOString(); shift.endCash = endCash; shift.notes = notes; saveDb(db); return shift; }
        throw new Error("Shift not found");
    }
};

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import type { Product, Supplier, Treasury, Warehouse } from '../types';
import { api } from '../services/mockApi';
import { useSettings } from '../hooks/useSettings';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { Trash2, Search, Tag, Warehouse as WhIcon } from 'lucide-react';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';

const AddPurchasePage: React.FC = () => {
    const { settings } = useSettings();
    const navigate = useNavigate();
    const { addToast } = useToasts();

    const [products, setProducts] = useState<Product[]>([]);
    const [suppliers, setSuppliers] = useState<Supplier[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [items, setItems] = useState<any[]>([]);
    const [selectedSupId, setSelectedSupId] = useState('');
    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');
    const [discount, setDiscount] = useState(0);
    const [discountType, setDiscountType] = useState<'amount' | 'percent'>('amount');
    const [amountPaid, setAmountPaid] = useState(0);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        Promise.all([api.getProducts(), api.getSuppliers(), api.getWarehouses(), api.getTreasuries()]).then(([p, s, w, t]) => {
            setProducts(p); setSuppliers(s); setWarehouses(w); setTreasuries(t);
            if (s.length) setSelectedSupId(s[0].id);
            if (w.length) setSelectedWhId(w[0].id);
            if (t.length) setSelectedTrId(t[0].id);
        });
    }, []);

    const subtotal = items.reduce((s, i) => s + (i.costPrice * i.quantity), 0);
    const discountVal = discountType === 'percent' ? (subtotal * discount / 100) : discount;
    const finalTotal = Math.max(0, subtotal - discountVal);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!items.length || !selectedWhId || !selectedTrId) { 
            addToast('يرجى اختيار المنتجات وتحديد المستودع والخزينة', 'warning'); 
            return; 
        }
        try {
            await api.savePurchase({
                supplier: suppliers.find(s => s.id === selectedSupId),
                items, 
                total: finalTotal, 
                amountPaid, 
                warehouseId: selectedWhId, 
                treasuryId: selectedTrId, 
                discount, 
                discountType
            });
            addToast('تم حفظ طلب الشراء بنجاح وتحديث المخزون المخصص للمستودع', 'success');
            navigate('/purchases');
        } catch (e) { addToast('خطأ في الحفظ', 'error'); }
    };

    return (
        <form onSubmit={handleSubmit} className="animate-fadeIn pb-10">
            <div className="flex justify-between items-center mb-8">
                <h1 className="text-4xl font-black">إضافة طلب شراء</h1>
                <div className="flex gap-2">
                    <Button type="button" variant="secondary" onClick={() => navigate('/purchases')}>تراجع</Button>
                    <Button type="submit">حفظ الطلب</Button>
                </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 space-y-6">
                    <Card title="الأصناف المختارة">
                        <div className="relative mb-6">
                            <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" />
                            <input type="text" placeholder="ابحث عن منتج بالاسم أو الباركود..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-10 border rounded-xl dark:bg-slate-800 font-bold" />
                            {searchTerm && (
                                <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white dark:bg-slate-800 border rounded-xl shadow-2xl overflow-hidden max-h-60 overflow-y-auto">
                                    {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                        <button key={p.id} type="button" onClick={() => { 
                                            const existing = items.find(i => i.productId === p.id);
                                            if (existing) {
                                                setItems(items.map(i => i.productId === p.id ? {...i, quantity: i.quantity + 1} : i));
                                            } else {
                                                setItems([...items, { productId: p.id, name: p.name, quantity: 1, costPrice: p.costPrice }]); 
                                            }
                                            setSearchTerm(''); 
                                        }} className="w-full p-3 text-start hover:bg-indigo-50 border-b last:border-0 font-black text-xs flex justify-between">
                                            <span>{p.name}</span>
                                            <span className="text-slate-400">SKU: {p.sku}</span>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                        <div className="space-y-4">
                            {items.map((item, idx) => (
                                <div key={idx} className="flex items-center gap-4 p-4 border rounded-2xl bg-slate-50 dark:bg-slate-800/50">
                                    <div className="flex-grow font-black text-sm">{item.name}</div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-400">الكمية:</span>
                                        <input type="number" value={item.quantity} onChange={e => setItems(items.map((it, i) => i === idx ? {...it, quantity: parseFloat(e.target.value)||0} : it))} className="w-20 p-2 border rounded-xl text-center font-bold" />
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-400">التكلفة:</span>
                                        <input type="number" value={item.costPrice} onChange={e => setItems(items.map((it, i) => i === idx ? {...it, costPrice: parseFloat(e.target.value)||0} : it))} className="w-28 p-2 border rounded-xl text-center font-bold" />
                                    </div>
                                    <button type="button" onClick={() => setItems(items.filter((_, i) => i !== idx))} className="text-rose-500 p-2 hover:bg-rose-50 rounded-lg transition-colors"><Trash2 size={18} /></button>
                                </div>
                            ))}
                            {!items.length && <div className="text-center py-10 text-slate-400 font-bold">لم يتم اختيار أي أصناف بعد.</div>}
                        </div>
                    </Card>
                </div>
                <div className="space-y-6">
                    <Card title="إعدادات العملية">
                        <div className="space-y-4">
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">المورد</label><select value={selectedSupId} onChange={e => setSelectedSupId(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold">{suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div>
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">المستودع المستلم</label><select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold border-indigo-200">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></div>
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">الخزينة (صرف)</label><select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></div>
                            <div className="pt-4 border-t dark:border-slate-800">
                                <label className="text-[10px] font-black text-slate-400 block mb-1">الخصم على الفاتورة</label>
                                <div className="flex gap-2">
                                    <input type="number" value={discount} onChange={e => setDiscount(parseFloat(e.target.value)||0)} className="flex-1 p-2 border rounded-xl dark:bg-slate-800 font-bold" />
                                    <button type="button" onClick={() => setDiscountType(discountType === 'amount' ? 'percent' : 'amount')} className="w-12 bg-slate-100 dark:bg-slate-700 rounded-xl font-black text-xs hover:bg-indigo-50 hover:text-indigo-600 transition-colors">
                                        {discountType === 'amount' ? settings?.currency : '%'}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </Card>
                    <Card className="bg-indigo-600 text-white border-none shadow-xl text-center">
                        <p className="text-[10px] font-black opacity-80 uppercase tracking-widest">الصافي المطلوب سداده</p>
                        <p className="text-3xl font-black mt-1">{formatCurrency(finalTotal, settings?.currency)}</p>
                        <div className="mt-6 pt-4 border-t border-white/20">
                            <label className="text-[10px] font-black opacity-70 block mb-2">المبلغ المدفوع فعلياً</label>
                            <input type="number" value={amountPaid} onChange={e => setAmountPaid(parseFloat(e.target.value)||0)} className="w-full p-3 bg-white/10 rounded-xl text-center font-black border-none text-xl placeholder:text-white/30" placeholder="أدخل المبلغ..." />
                        </div>
                    </Card>
                </div>
            </div>
        </form>
    );
};

export default AddPurchasePage;

import React, { useState, useEffect, useMemo } from 'react';
