            s.id.toLowerCase().includes(q) || 
            s.customer.name.toLowerCase().includes(q) ||
            // افترضنا أن بيانات العميل متاحة من خلال api.getCustomers أو أننا سنبحث في الاسم فقط حالياً لضمان الدقة
            s.customer.id.includes(q)
