    }, [sales, query]);

    useEffect(() => {
        if (selectedSaleId) {
            const sale = sales.find(s => s.id === selectedSaleId);
            if (sale) {
                setItems(sale.items.map(i => ({ 
                    ...i, 
                    originalQuantity: i.quantity, 
                    returnQuantity: 0 
                })));
            }
        }
    }, [selectedSaleId, sales]);

    const totalRefund = items.reduce((sum, i) => sum + (i.returnQuantity * i.sellPrice), 0);

