import type { 
    Sale, Product, StoreSettings, ActivityLog, FinancialReport, 
    SalesReturn, Purchase, Partner, Treasury, InstallmentPlan,
    Notification, ShippingCompany, PurchaseReturn, Transaction,
    SyncLog, InactiveCustomer, StagnantProduct, GlobalSearchResults,
    JournalEntry, Shift, UpdatePackage, Supplier, Customer, EmployeePerformanceAnalytics,
    SatisfactionAnalytics, User, SupplierPerformanceData, DashboardAnalytics, PermissionKey
} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const ALL_PERMISSIONS = PERMISSION_KEYS.reduce((acc, key) => {
    acc[key as PermissionKey] = true;
    return acc;
}, {} as Record<PermissionKey, boolean>);

const DEFAULT_SETTINGS: StoreSettings = {
    storeName: 'تكنو باور POS',
    vatRate: 15,
    taxRegisterNumber: '',
    invoiceFooter: 'شكراً لتعاملكم معنا',
    logoUrl: '',
    currency: 'SAR',
    nextInvoiceNumber: 1000,
    invoiceNumberPrefix: 'INV-',
    navigationStyle: 'grid',
    posLayout: 'classic',
    homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'],
    visiblePages: ['home', 'dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'suppliers', 'treasury', 'reports', 'partners', 'settings', 'warehouses', 'stock-transfer', 'sales-returns', 'purchase-returns', 'installments', 'activity-logs'],
    enableSoundEffects: true,
    enablePosCategories: true,
    enableShiftManagement: true,
    invoiceDesign: { template: 'modern', showLogo: true, showQrCode: true, accentColor: '#4f46e5', customCss: '' },
    loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5 }
};

const getDb = () => {
    const defaultDb = {
        settings: DEFAULT_SETTINGS,
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        feedback: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', roleId: 'r-1', permissions: ALL_PERMISSIONS }],
        roles: [{ id: 'r-1', name: 'مدير النظام', permissions: ALL_PERMISSIONS }],
        stockTransfers: [],
        notifications: [],
        shippingCompanies: [],
        transactions: [],
        shifts: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        if (!stored) return defaultDb;
        const parsed = JSON.parse(stored);
        parsed.settings = { ...DEFAULT_SETTINGS, ...parsed.settings };
        if (parsed.users && parsed.users.length > 0) {
            const admin = parsed.users.find((u: any) => u.id === 'u-1');
            if (admin && (!admin.permissions || Object.keys(admin.permissions).length === 0)) {
                admin.permissions = ALL_PERMISSIONS;
            }
        }
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logAction = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({ id: `log-${Date.now()}`, timestamp: new Date().toISOString(), action, details, user: 'المدير' });
};

const updateTreasury = (db: any, treasuryId: string, amount: number, type: 'income' | 'expense') => {
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'income') t.balance += amount;
        else t.balance -= amount;
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb();
        db.settings = s;
        logAction(db, 'تحديث الإعدادات', 'تم تعديل إعدادات النظام وتصميم الفاتورة');
        saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (!p.warehouseStocks) p.warehouseStocks = {};
        p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        if (p.id) db.products = db.products.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `prod-${Date.now()}`; db.products.push(p); }
        saveDb(db); return p;
    },
    deleteProduct: async (id: string) => {
        const db = getDb();
        db.products = db.products.filter((p: any) => p.id !== id);
        saveDb(db); return true;
    },
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        db.products = db.products.map((p: any) => {
            const up = products.find(u => u.id === p.id);
            return up ? up : p;
        });
        saveDb(db); return true;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        // خصم المخزون
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber}`;
        if (!sale.id) db.settings.nextInvoiceNumber++;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        // تحديث نقاط الولاء
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);
        if (customer) {
            if (sale.pointsRedeemed) customer.points -= sale.pointsRedeemed;
            const pointsEarned = Math.floor(sale.total * (db.settings.loyaltySettings.earningRate || 0.1));
            customer.points = (customer.points || 0) + pointsEarned;
            customer.totalSpent = (customer.totalSpent || 0) + sale.total;
        }

        // تسجيل خطة التقسيط إذا وجدت
        if (sale.installmentPlan) {
            db.installments.unshift({ ...sale.installmentPlan, id: `inst-${Date.now()}`, saleId: id, customerName: sale.customer.name, status: 'Active' });
        }

        updateTreasury(db, sale.treasuryId, sale.amountPaid, 'income');
        logAction(db, 'عملية بيع', `فاتورة مبيعات #${id} بقيمة ${sale.total}`);
        saveDb(db); return finalSale;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string): Promise<FinancialReport> => {
        const db = getDb();
        const sales = db.sales.filter((s: any) => s.date >= start && s.date <= end);
        const purchases = db.purchases.filter((p: any) => p.date >= start && p.date <= end);
        const returns = db.salesReturns.filter((r: any) => r.date >= start && r.date <= end);

        const totalRevenue = sales.reduce((a: number, b: any) => a + b.total, 0);
        const totalPurchases = purchases.reduce((a: number, b: any) => a + b.total, 0);
        const totalReturns = returns.reduce((a: number, b: any) => a + b.totalRefund, 0);

        return {
            totalRevenue,
            totalCOGS: totalPurchases, 
            totalExpenses: 0,
            totalPurchases,
            totalReturns,
            netProfit: totalRevenue - totalPurchases - totalReturns,
            dailyStats: []
        };
    },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const data = db.users.map((u: any) => {
            const userSales = db.sales.filter((s: any) => s.cashier.id === u.id);
            const totalValue = userSales.reduce((a: number, b: any) => a + b.total, 0);
            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue: totalValue,
                totalSalesCount: userSales.length,
                averageSaleValue: userSales.length ? totalValue / userSales.length : 0,
                totalReturnsValue: 0,
                returnRate: 0
            };
        });
        return { performanceData: data, topPerformerByValue: [...data].sort((a,b) => b.totalSalesValue - a.totalSalesValue)[0] };
    },
    getSatisfactionAnalytics: async (): Promise<SatisfactionAnalytics> => {
        const db = getDb();
        const feedback = db.feedback || [];
        return {
            happy: feedback.filter((f: any) => f.rating >= 4).length,
            neutral: feedback.filter((f: any) => f.rating === 3).length,
            unhappy: feedback.filter((f: any) => f.rating <= 2).length,
            total: feedback.length
        };
    },
    submitFeedback: async (f: any) => {
        const db = getDb();
        if (!db.feedback) db.feedback = [];
        db.feedback.push({ ...f, date: new Date().toISOString() });
        saveDb(db);
    },
    getPartners: async () => getDb().partners,
    savePartner: async (p: any) => {
        const db = getDb();
        if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `part-${Date.now()}`; db.partners.push(p); }
        saveDb(db); return p;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
        else { c.id = `cust-${Date.now()}`; db.customers.push(c); }
        saveDb(db); return c;
    },
    getSales: async () => getDb().sales,
    getPurchases: async () => getDb().purchases,
    getSalesReturns: async () => getDb().salesReturns,
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getInstallmentPlans: async () => getDb().installments,
    getActivityLogs: async () => getDb().activityLogs,
    getUsers: async () => getDb().users || [],
    login: async (name: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.name === name);
        if (user && password === 'password') return user;
        return null;
    },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    verifyPassword: async (userId: string, password: string) => password === 'password',
    wipeBusinessData: async () => { localStorage.clear(); window.location.reload(); },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const filter = (arr: any[]) => (arr || []).filter(i => (i.name || i.id || "").toLowerCase().includes(q.toLowerCase()));
        return {
            products: filter(db.products), sales: filter(db.sales), customers: filter(db.customers),
            purchases: filter(db.purchases), suppliers: filter(db.suppliers), partners: filter(db.partners),
            salesReturns: filter(db.salesReturns), purchaseReturns: filter(db.purchaseReturns),
            installments: filter(db.installments), stockTransfers: filter(db.stockTransfers)
        };
    },
    getCustomerPurchaseHistory: async (cid: string) => getDb().sales.filter((s: any) => s.customer.id === cid),
    getCustomerReturnsHistory: async (cid: string) => getDb().salesReturns.filter((r: any) => {
        const sale = getDb().sales.find((s: any) => s.id === r.originalSaleId);
        return sale && sale.customer.id === cid;
    }),
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `sr-${Date.now()}`;
        ret.date = new Date().toISOString();
        db.salesReturns.unshift(ret);
        updateTreasury(db, ret.treasuryId, ret.totalRefund, 'expense');
        saveDb(db); return ret;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        updateTreasury(db, pur.treasuryId, pur.amountPaid, 'expense');
        saveDb(db); return pur;
    },
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `t-${Date.now()}`; db.treasuries.push(t); }
        saveDb(db); return t;
    },
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    saveWarehouse: async (w: any) => {
        const db = getDb();
        if (w.id) db.warehouses = db.warehouses.map((item: any) => item.id === w.id ? w : item);
        else { w.id = `w-${Date.now()}`; db.warehouses.push(w); }
        saveDb(db); return w;
    },
    saveTransaction: async (t: any) => {
        const db = getDb();
        if (t.id) db.transactions = db.transactions.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `tr-${Date.now()}`; t.date = new Date().toISOString(); t.user = 'المدير'; db.transactions.push(t); }
        updateTreasury(db, t.treasuryId, t.amount, t.type);
        saveDb(db); return t;
    },
    getTransactions: async () => getDb().transactions || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any): Promise<boolean> => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if (!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            st.id = `st-${Date.now()}`;
            st.date = new Date().toISOString();
            db.stockTransfers.unshift(st);
            saveDb(db); return true;
        }
        return false;
    }
};

import React, { useState, useEffect, useMemo } from 'react';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, SaleItem, Warehouse, Treasury } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { Search, ShoppingCart, Trash2, Plus, Minus, User, Gift, Warehouse as WhIcon, Wallet, Calculator } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);
    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');
    const [usePoints, setUsePoints] = useState(false);

    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t] = await Promise.all([api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries()]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
        };
        load();
    }, []);

    const selectedCustomer = useMemo(() => customers.find(c => c.id === selectedCustomerId), [customers, selectedCustomerId]);
    const pointsDiscount = useMemo(() => (usePoints && selectedCustomer) ? (selectedCustomer.points * (settings?.loyaltySettings.redemptionRate || 0)) : 0, [usePoints, selectedCustomer, settings]);

    const subtotal = cart.reduce((s, i) => s + (i.sellPrice * i.quantity), 0);
    const finalTotal = Math.max(0, subtotal - pointsDiscount);

    const handleCheckout = async (method: any) => {
        if (!cart.length || !selectedWhId || !selectedTrId) {
            addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning');
            return;
        }
        try {
            const res = await api.saveSale({
                customer: { id: selectedCustomer!.id, name: selectedCustomer!.name },
                cashier: { id: 'u-1', name: 'المدير' },
                items: cart,
                total: finalTotal,
                amountPaid: finalTotal,
                paymentMethod: method,
                warehouseId: selectedWhId,
                treasuryId: selectedTrId,
                pointsRedeemed: usePoints ? selectedCustomer!.points : 0
            });
            setLastSale(res); setShowReceipt(true); setCart([]); setUsePoints(false);
            addToast('تمت عملية البيع بنجاح وتحديث الرصيد', 'success');
        } catch (e) { addToast('فشل إتمام البيع', 'error'); }
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
                <div className="lg:col-span-2 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث بالاسم أو الباركود..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-14 ps-12 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 font-black outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm transition-all"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-2 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                <button key={p.id} onClick={() => {
                                    setCart(prev => {
                                        const ex = prev.find(i => i.id === p.id);
                                        if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
                                        return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice }];
                                    });
                                    setSearchTerm('');
                                }} className="w-full p-4 border-b dark:border-slate-700 flex justify-between hover:bg-slate-50 dark:hover:bg-slate-700 font-black">
                                    <span>{p.name}</span><span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="h-14 px-4 rounded-2xl bg-white dark:bg-slate-900 border font-black shadow-sm outline-none">
                    {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
            </div>

            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 shadow-sm overflow-hidden flex flex-col p-4">
                <div className="flex-1 overflow-y-auto space-y-3 custom-scrollbar">
                    {cart.map(item => (
                        <div key={item.id} className="grid grid-cols-12 gap-4 items-center p-3 bg-slate-50 dark:bg-slate-800/40 rounded-2xl border dark:border-slate-700/50">
                            <div className="col-span-6 font-black text-sm">{item.name}</div>
                            <div className="col-span-2 flex items-center justify-center gap-2">
                                <button onClick={() => setCart(cart.map(i => i.id === item.id ? {...i, quantity: Math.max(1, i.quantity - 1)} : i))}><Minus size={14}/></button>
                                <span className="font-black text-xs">{toArabicIndic(item.quantity)}</span>
                                <button onClick={() => setCart(cart.map(i => i.id === item.id ? {...i, quantity: i.quantity + 1} : i))}><Plus size={14}/></button>
                            </div>
                            <div className="col-span-4 text-end font-black">{formatAmount(item.sellPrice * item.quantity)}</div>
                        </div>
                    ))}
                    {!cart.length && <div className="h-full flex flex-col items-center justify-center opacity-30"><ShoppingCart size={64}/><p className="font-black mt-2">السلة فارغة</p></div>}
                </div>
            </div>

            {selectedCustomer && selectedCustomer.points > 0 && settings?.loyaltySettings.enabled && (
                <div className="bg-indigo-600 text-white p-4 rounded-2xl flex justify-between items-center animate-slideDown shadow-lg mx-1">
                    <div className="flex items-center gap-3">
                        <Gift size={20}/>
                        <div>
                            <p className="text-sm font-black">تحويل نقاط الولاء لخصم نقدي</p>
                            <p className="text-xs opacity-80">لدى العميل {toArabicIndic(selectedCustomer.points)} نقطة (قيمتها {formatCurrency(pointsDiscount, settings.currency)})</p>
                        </div>
                    </div>
                    <label className="flex items-center gap-2 cursor-pointer bg-white/10 px-4 py-2 rounded-xl"><input type="checkbox" checked={usePoints} onChange={e => setUsePoints(e.target.checked)} className="w-5 h-5 rounded" /><span className="font-black text-xs">استخدام النقاط</span></label>
                </div>
            )}

            <Card className="mx-1 p-4 shadow-2xl bg-white/80 dark:bg-slate-900/80 backdrop-blur-md">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-center">
                    <div className="space-y-2 border-e dark:border-slate-800 pe-4">
                        <div className="flex justify-between items-center text-[10px] font-black text-slate-400"><WhIcon size={12}/> المخزن <select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="bg-transparent text-slate-800 dark:text-white">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></div>
                        <div className="flex justify-between items-center text-[10px] font-black text-slate-400"><Wallet size={12}/> الخزينة <select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="bg-transparent text-slate-800 dark:text-white">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></div>
                    </div>
                    <div className="col-span-2 text-center border-e dark:border-slate-800 pe-4">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">المجموع النهائي</p>
                        <p className="text-4xl font-black text-indigo-600 leading-none mt-1">{formatCurrency(finalTotal, settings?.currency)}</p>
                    </div>
                    <Button onClick={() => handleCheckout('Cash')} className="h-12 rounded-2xl bg-emerald-600 font-black shadow-lg">إتمام البيع (كاش)</Button>
                </div>
            </Card>

            <ReceiptModal isOpen={showReceipt} onClose={() => setShowReceipt(false)} sale={lastSale} />
        </div>
    );
};

export default PosPage;

