    getInactiveCustomers: async (days: number) => {
        const db = getDb();
        const cutoff = new Date();
        cutoff.setDate(cutoff.getDate() - days);
        return db.customers.filter((c: any) => {
            const lastSale = db.sales.find((s: any) => s.customer.id === c.id);
            return !lastSale || new Date(lastSale.date) < cutoff;
        }).map((c: any) => ({
            id: c.id,
            name: c.name,
            phone: c.phone,
            lastPurchaseDate: db.sales.find((s: any) => s.customer.id === c.id)?.date || 'لا يوجد مشتريات'
        }));
