    getStagnantProducts: async (days: number) => {
        const db = getDb();
        const cutoff = new Date();
        cutoff.setDate(cutoff.getDate() - days);
        return db.products.filter((p: any) => {
            const lastSale = db.sales.find((s: any) => s.items.some((i: any) => i.id === p.id));
            return !lastSale || new Date(lastSale.date) < cutoff;
        }).map((p: any) => {
            const lastSale = db.sales.find((s: any) => s.items.some((i: any) => i.id === p.id));
            const diff = lastSale ? Math.floor((Date.now() - new Date(lastSale.date).getTime()) / 86400000) : 365;
            return {
                id: p.id,
                name: p.name,
                stock: p.stock,
                lastSoldDate: lastSale?.date,
                daysSinceLastSale: diff
            };
        });
    },
