        const db = getDb();
        db.settings.currentVersion = version;
        saveDb(db); return true;
    },
    getJournalEntries: async () => [
        { id: 'j-1', date: new Date().toISOString(), reference: 'OB-001', description: 'الرصيد الافتتاحي', debit: { account: 'النقدية', amount: 1000 }, credit: { account: 'رأس المال', amount: 1000 } }
    ],
    // FIX: Added shift management methods for useShift.tsx
    getCurrentShift: async (userId: string) => {
        const db = getDb();
        return db.shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null;
    },
    openShift: async (userId: string, startCash: number) => {
        const db = getDb();
        if (db.shifts.some((s: any) => s.userId === userId && s.status === 'Open')) {
            throw new Error("لديك وردية مفتوحة بالفعل.");
        }
        const shift = { id: `sh-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash, status: 'Open' };
        db.shifts.push(shift);
        saveDb(db); return shift;
    },
    closeShift: async (shiftId: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === shiftId);
        if (shift) {
            const shiftSales = db.sales.filter((s: any) => s.shiftId === shiftId);
            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = notes;
            shift.totalSales = shiftSales.reduce((sum: number, s: any) => sum + s.total, 0);
            saveDb(db); return shift;
        }
        throw new Error("Shift not found");
    }
};

