                                        <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">تذييل الفاتورة</label><textarea value={localSettings.invoiceFooter} onChange={e => setLocalSettings({...localSettings, invoiceFooter: e.target.value})} className="w-full p-3 border rounded-xl dark:bg-slate-800 text-xs font-bold" rows={3} placeholder="شكراً لزيارتكم... البضاعة المباعة لا ترد ولا تستبدل..." /></div>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    )}

                    {/* باقي التبويبات (Maintenance, About) تظل كما هي */}
                </div>
            </div>

            {/* Modals */}
            <Modal isOpen={isUserModalOpen} onClose={() => setIsUserModalOpen(false)} title={editingUser ? 'تعديل موظف' : 'إضافة موظف جديد'}>
                <UserForm user={editingUser} roles={roles} onSave={async (d) => { await api.saveProduct(d as any); setIsUserModalOpen(false); addToast('تم الحفظ', 'success'); }} onCancel={() => setIsUserModalOpen(false)} isLoading={false} />
            </Modal>
        </div>
    );
};

