        try {
            const data = await api.getBackupData();
            const blob = new Blob([data], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
            a.click();
            addToast('تم تصدير النسخة الاحتياطية بنجاح.', 'success');
        } catch (e) { addToast('فشل النسخ الاحتياطي', 'error'); }
    };

    if (!localSettings) return <div className="p-20 text-center animate-pulse">جاري التحميل...</div>;

    const isPaid = !['Free', 'Trial'].includes(licenseInfo.type || '');

    const navItems = [
        { id: 'general', label: 'المتجر والضرائب', icon: <Monitor size={18} /> },
        { id: 'pos', label: 'البيع والولاء', icon: <ShoppingCart size={18} /> },
        { id: 'homepage', label: 'تخصيص الواجهة', icon: <LayoutGrid size={18} /> },
        { id: 'employees', label: 'الموظفين والصلاحيات', icon: <Users size={18} /> },
        { id: 'invoice', label: 'مصمم الفاتورة', icon: <Palette size={18} /> },
        { id: 'subscription', label: 'حالة الاشتراك', icon: <Crown size={18} /> },
        { id: 'maintenance', label: 'البيانات والصيانة', icon: <Database size={18} /> },
        { id: 'about', label: 'حول النظام', icon: <Info size={18} /> },
    ];

    const activationDate = licenseInfo.activationDate ? new Date(licenseInfo.activationDate) : new Date();
    const expiryDate = new Date(activationDate);
    if (licenseInfo.type === 'Monthly') expiryDate.setMonth(expiryDate.getMonth() + 1);
    else if (licenseInfo.type === 'Yearly') expiryDate.setFullYear(expiryDate.getFullYear() + 1);
    else if (licenseInfo.type === 'Lifetime') expiryDate.setFullYear(expiryDate.getFullYear() + 99);

    const daysRemaining = Math.max(0, Math.ceil((expiryDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)));
    const progressPercent = licenseInfo.type === 'Lifetime' ? 100 : Math.min(100, Math.max(0, (daysRemaining / 365) * 100));

    return (
        <div className="max-w-7xl mx-auto animate-fadeIn pb-20">
            <div className="flex justify-between items-center mb-10">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white">مركز التحكم</h1>
