import React, { useState, useEffect } from 'react';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { useSettings } from '../hooks/useSettings';
import { api } from '../services/mockApi';
import type { StoreSettings, User, Role } from '../types';
import { 
    Save, Monitor, Shield, Database, ImageIcon, LayoutGrid, Crown,
    Palette, Info, ShoppingCart, Heart, Download, RefreshCw, Smartphone, 
    Copy, CheckCircle, ExternalLink, Cpu, Code2, ShieldCheck, Upload,
    Users, UserPlus, Lock, Check, X, Calendar, Zap, FileText, Trash2, Settings2, Key, History
} from 'lucide-react';
import { useToasts } from '../hooks/useToasts';
import { useLicense } from '../hooks/useLicense';
import { CURRENCIES, toArabicIndic, formatCurrency } from '../utils/localization';
import { processImageFile } from '../utils/imageHelpers';
import Modal from '../components/ui/Modal';
import UserForm from '../components/users/UserForm';
import RoleFormModal from '../components/settings/RoleFormModal';
import { NAV_LINKS } from '../constants';
import { useTranslation } from '../hooks/useTranslation';

const SettingsPage: React.FC = () => {
    const { settings, updateSettings } = useSettings();
    const { addToast } = useToasts();
    const { licenseInfo, deviceId } = useLicense();
    const { t } = useTranslation();

    const [activeTab, setActiveTab] = useState('general');
    const [employeeSubTab, setEmployeeSubTab] = useState<'users' | 'roles'>('users');
    const [localSettings, setLocalSettings] = useState<StoreSettings | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    // للموظفين والصلاحيات
    const [users, setUsers] = useState<User[]>([]);
    const [roles, setRoles] = useState<Role[]>([]);
    const [isUserModalOpen, setIsUserModalOpen] = useState(false);
    const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [editingRole, setEditingRole] = useState<Role | null>(null);

    useEffect(() => {
        if (settings) setLocalSettings(JSON.parse(JSON.stringify(settings)));
        fetchEmployeesData();
    }, [settings]);

    const fetchEmployeesData = async () => {
        try {
            const u = await api.getUsers();
            setUsers(u);
            setRoles([
                { id: 'r-1', name: 'مدير النظام', permissions: {} },
                { id: 'r-2', name: 'كاشير مبيعات', permissions: {} },
                { id: 'r-3', name: 'أمين مخزن', permissions: {} }
            ]);
        } catch (e) {
            console.error(e);
        }
    };

    const handleSave = async () => {
        if (!localSettings) return;
        setIsSaving(true);
        try {
            await updateSettings(localSettings);
            addToast('تم حفظ كافة الإعدادات بنجاح', 'success');
        } catch (e) { addToast('خطأ في الحفظ', 'error'); }
        finally { setIsSaving(false); }
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file && localSettings) {
            try {
                const base64 = await processImageFile(file, 300);
                setLocalSettings({ ...localSettings, logoUrl: base64 });
                addToast('تم رفع الشعار، اضغط حفظ للتأكيد.', 'success');
            } catch (err) { addToast('فشل معالجة الصورة', 'error'); }
        }
    };

    const isPaid = !['Free', 'Trial'].includes(licenseInfo.type || '');

    const handleBackup = async () => {
        if (!isPaid) {
            addToast('عذراً، ميزة النسخ الاحتياطي متاحة فقط في النسخ المدفوعة.', 'warning');
            return;
        }
        try {
            const data = await api.getBackupData();
            const blob = new Blob([data], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
            a.click();
            addToast('تم تصدير النسخة الاحتياطية بنجاح.', 'success');
        } catch (e) { addToast('فشل النسخ الاحتياطي', 'error'); }
    };

    if (!localSettings) return <div className="p-20 text-center animate-pulse">جاري التحميل...</div>;

    const navItems = [
        { id: 'general', label: 'المتجر والضرائب', icon: <Monitor size={18} /> },
        { id: 'pos', label: 'البيع والولاء', icon: <ShoppingCart size={18} /> },
        { id: 'homepage', label: 'تخصيص الواجهة', icon: <LayoutGrid size={18} /> },
        { id: 'employees', label: 'الموظفين والصلاحيات', icon: <Users size={18} /> },
        { id: 'invoice', label: 'مصمم الفاتورة', icon: <Palette size={18} /> },
        { id: 'subscription', label: 'حالة الاشتراك', icon: <Crown size={18} /> },
        { id: 'maintenance', label: 'البيانات والصيانة', icon: <Database size={18} /> },
        { id: 'about', label: 'حول النظام', icon: <Info size={18} /> },
    ];

    // حسابات الاشتراك الشاملة
    const activationDate = licenseInfo.activationDate ? new Date(licenseInfo.activationDate) : new Date();
    const expiryDate = new Date(activationDate);
    if (licenseInfo.type === 'Monthly') expiryDate.setMonth(expiryDate.getMonth() + 1);
    else if (licenseInfo.type === 'Semiannual') expiryDate.setMonth(expiryDate.getMonth() + 6);
    else if (licenseInfo.type === 'Yearly') expiryDate.setFullYear(expiryDate.getFullYear() + 1);
    else if (licenseInfo.type === 'Lifetime') expiryDate.setFullYear(expiryDate.getFullYear() + 99);
    else if (licenseInfo.type === 'Trial') expiryDate.setDate(expiryDate.getDate() + 3);

    const daysRemaining = Math.max(0, Math.ceil((expiryDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)));
    const progressPercent = licenseInfo.type === 'Lifetime' ? 100 : Math.min(100, Math.max(0, (daysRemaining / (licenseInfo.type === 'Trial' ? 3 : 365)) * 100));

    return (
        <div className="max-w-7xl mx-auto animate-fadeIn pb-20">
            <div className="flex justify-between items-center mb-10">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white">مركز التحكم</h1>
                    <p className="text-slate-500 font-medium">إدارة شاملة لهوية النظام، الموظفين، والاشتراكات.</p>
                </div>
                <Button onClick={handleSave} isLoading={isSaving} className="h-12 px-8 rounded-2xl font-black shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                    <Save size={20} className="me-2" /> حفظ الإعدادات
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <nav className="lg:col-span-1 space-y-1 bg-white/50 dark:bg-slate-900/50 p-2 rounded-3xl border border-slate-100 dark:border-slate-800 backdrop-blur-xl h-fit sticky top-32">
                    {navItems.map(item => (
                        <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl font-black text-xs transition-all ${activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/30' : 'text-slate-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20'}`}>
                            {item.icon} {item.label}
                        </button>
                    ))}
                </nav>

                <div className="lg:col-span-3 space-y-8">
                    {activeTab === 'general' && (
                        <Card title="إعدادات المنشأة والضرائب">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-6">
                                    <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">اسم المنشأة التجاري</label><input type="text" value={localSettings.storeName} onChange={e => setLocalSettings({...localSettings, storeName: e.target.value})} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">العملة</label><select value={localSettings.currency} onChange={e => setLocalSettings({...localSettings, currency: e.target.value as any})} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-bold outline-none">{Object.keys(CURRENCIES).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                                        <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">نسبة الضريبة (%)</label><input type="number" value={localSettings.vatRate} onChange={e => setLocalSettings({...localSettings, vatRate: parseFloat(e.target.value)||0})} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-bold outline-none" /></div>
                                    </div>
                                    <div><label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">الرقم الضريبي / السجل</label><input type="text" value={localSettings.taxRegisterNumber} onChange={e => setLocalSettings({...localSettings, taxRegisterNumber: e.target.value})} className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-bold outline-none" placeholder="مثال: 300012345600003" /></div>
                                </div>
                                <div className="flex flex-col items-center justify-center p-6 bg-slate-50 dark:bg-slate-800/40 rounded-4xl border-2 border-dashed dark:border-slate-700">
                                    {localSettings.logoUrl ? <img src={localSettings.logoUrl} className="w-32 h-32 object-contain mb-4 rounded-xl shadow-md" /> : <ImageIcon size={64} className="text-slate-300" />}
                                    <input type="file" id="logoUp" hidden accept="image/*" onChange={handleLogoUpload} />
                                    <Button variant="secondary" size="sm" onClick={() => document.getElementById('logoUp')?.click()} className="rounded-xl">تغيير الشعار</Button>
                                </div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'pos' && (
                        <Card title="إعدادات البيع والولاء">
                            <div className="space-y-6">
                                <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                                    <div><h4 className="text-xs font-black">تفعيل برنامج الولاء</h4><p className="text-[10px] text-slate-500">تمكين العملاء من تجميع النقاط عند كل عملية شراء.</p></div>
                                    <input type="checkbox" checked={localSettings.loyaltySettings.enabled} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, enabled: e.target.checked}})} className="w-6 h-6 rounded-lg text-indigo-600" />
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div><label className="text-[10px] font-black text-slate-400 mb-1 block">معدل الربح (نقاط لكل 1 {localSettings.currency})</label><input type="number" step="0.1" value={localSettings.loyaltySettings.earningRate} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, earningRate: parseFloat(e.target.value)||0}})} className="w-full p-3 border rounded-xl dark:bg-slate-800 font-bold" /></div>
                                    <div><label className="text-[10px] font-black text-slate-400 mb-1 block">معدل الاستبدال ({localSettings.currency} لكل 1 نقطة)</label><input type="number" step="0.1" value={localSettings.loyaltySettings.redemptionRate} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, redemptionRate: parseFloat(e.target.value)||0}})} className="w-full p-3 border rounded-xl dark:bg-slate-800 font-bold" /></div>
                                </div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'homepage' && (
                        <Card title="تخصيص الشاشة الرئيسية">
                            <p className="text-sm text-slate-500 mb-6 font-bold">اختر الأيقونات التي تظهر في الواجهة الرئيسية.</p>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                                {NAV_LINKS.map(link => {
                                    const items = 'children' in link ? link.children : [link];
                                    return items.map(item => (
                                        <label key={item.id} className={`flex items-center justify-between p-4 rounded-2xl border-2 cursor-pointer transition-all ${localSettings.homeGridItems.includes(item.id) ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20' : 'border-slate-100 dark:border-slate-800 opacity-60'}`}>
                                            <div className="flex items-center gap-3">
                                                <item.icon size={18} className={localSettings.homeGridItems.includes(item.id) ? 'text-indigo-600' : 'text-slate-400'} />
                                                <span className="text-xs font-black">{t(item.t_key)}</span>
                                            </div>
                                            <input 
                                                type="checkbox" 
                                                checked={localSettings.homeGridItems.includes(item.id)} 
                                                onChange={e => {
                                                    const newItems = e.target.checked 
                                                        ? [...localSettings.homeGridItems, item.id]
                                                        : localSettings.homeGridItems.filter(i => i !== item.id);
                                                    setLocalSettings({...localSettings, homeGridItems: newItems});
                                                }}
                                                className="w-5 h-5 rounded border-slate-300 text-indigo-600"
                                            />
                                        </label>
                                    ));
                                })}
                            </div>
                        </Card>
                    )}

                    {activeTab === 'employees' && (
                        <div className="space-y-6">
                            <div className="flex bg-white/50 dark:bg-slate-900/50 p-1 rounded-2xl border w-fit">
                                <button onClick={() => setEmployeeSubTab('users')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${employeeSubTab === 'users' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>المستخدمين</button>
                                <button onClick={() => setEmployeeSubTab('roles')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${employeeSubTab === 'roles' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>الأدوار والصلاحيات</button>
                            </div>

                            {employeeSubTab === 'users' ? (
                                <Card title="قائمة الموظفين">
                                    <div className="flex justify-end mb-4"><Button size="sm" onClick={() => { setEditingUser(null); setIsUserModalOpen(true); }} className="rounded-xl"><UserPlus size={16} /> إضافة موظف</Button></div>
                                    <div className="overflow-x-auto"><table className="w-full text-sm">
                                        <thead className="bg-slate-50 dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400">
                                            <tr><th className="px-4 py-3 text-start">الموظف</th><th className="px-4 py-3 text-start">البريد</th><th className="px-4 py-3 text-center">الإجراء</th></tr>
                                        </thead>
                                        <tbody className="divide-y dark:divide-slate-800">{users.map(u => (
                                            <tr key={u.id}><td className="px-4 py-3 font-bold">{u.name}</td><td className="px-4 py-3 text-slate-500">{u.email}</td><td className="px-4 py-3 text-center">
                                                <button onClick={() => { setEditingUser(u); setIsUserModalOpen(true); }} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg"><Save size={16}/></button>
                                            </td></tr>
                                        ))}</tbody>
                                    </table></div>
                                </Card>
                            ) : (
                                <Card title="أدوار العمل (Roles)">
                                    <div className="flex justify-end mb-4"><Button size="sm" onClick={() => { setEditingRole(null); setIsRoleModalOpen(true); }} className="rounded-xl"><Key size={16} /> إضافة دور</Button></div>
                                    <div className="overflow-x-auto"><table className="w-full text-sm">
                                        <thead className="bg-slate-50 dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400">
                                            <tr><th className="px-4 py-3 text-start">اسم الدور</th><th className="px-4 py-3 text-center">الإجراء</th></tr>
                                        </thead>
                                        <tbody className="divide-y dark:divide-slate-800">{roles.map(r => (
                                            <tr key={r.id}><td className="px-4 py-3 font-bold">{r.name}</td><td className="px-4 py-3 text-center">
                                                <button onClick={() => { setEditingRole(r); setIsRoleModalOpen(true); }} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg"><Settings2 size={16}/></button>
                                            </td></tr>
                                        ))}</tbody>
                                    </table></div>
                                </Card>
                            )}
                        </div>
                    )}

                    {activeTab === 'invoice' && (
                        <Card title="تخصيص الفاتورة">
                            <div className="space-y-8">
                                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                                    {[
                                        { id: 'modern', label: 'عصري', desc: 'A4 مطور' },
                                        { id: 'classic', label: 'كلاسيكي', desc: 'رسمي' },
                                        { id: 'minimal', label: 'بسيط', desc: 'توفير حبر' },
                                        { id: 'thermal', label: 'حراري', desc: '80mm' },
                                        { id: 'free', label: 'تصميم حر', desc: 'CSS مخصص' },
                                    ].map(t => (
                                        <button key={t.id} onClick={() => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, template: t.id as any}})} className={`flex flex-col items-center gap-2 p-4 rounded-3xl border-2 transition-all ${localSettings.invoiceDesign.template === t.id ? 'border-indigo-600 bg-indigo-50 text-indigo-600' : 'border-slate-100 dark:border-slate-800'}`}>
                                            <div className={`p-3 rounded-2xl ${localSettings.invoiceDesign.template === t.id ? 'bg-indigo-600 text-white' : 'bg-slate-100 dark:bg-slate-800'}`}><Palette size={20} /></div>
                                            <span className="text-[11px] font-black">{t.label}</span>
                                            <span className="text-[8px] opacity-60 font-bold">{t.desc}</span>
                                        </button>
                                    ))}
                                </div>

                                {localSettings.invoiceDesign.template === 'free' && (
                                    <div className="animate-fadeIn">
                                        <label className="text-[10px] font-black text-slate-400 uppercase block mb-2">CSS مخصص للتصميم الحر</label>
                                        <textarea value={localSettings.invoiceDesign.customCss} onChange={e => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, customCss: e.target.value}})} className="w-full p-4 h-48 bg-slate-900 text-green-400 font-mono text-xs rounded-2xl border-none outline-none" placeholder=".receipt { font-family: 'Arial'; color: #000; }" />
                                    </div>
                                )}

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6 border-t dark:border-slate-800">
                                    <div className="space-y-4">
                                        <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl">
                                            <span className="text-xs font-black">إظهار الشعار</span>
                                            <input type="checkbox" checked={localSettings.invoiceDesign.showLogo} onChange={e => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, showLogo: e.target.checked}})} className="w-5 h-5 rounded text-indigo-600" />
                                        </div>
                                        <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl">
                                            <span className="text-xs font-black">رمز QR الضريبي</span>
                                            <input type="checkbox" checked={localSettings.invoiceDesign.showQrCode} onChange={e => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, showQrCode: e.target.checked}})} className="w-5 h-5 rounded text-indigo-600" />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-black text-slate-400 mb-2 block uppercase">لون العلامة التجارية</label>
                                        <input type="color" value={localSettings.invoiceDesign.accentColor} onChange={e => setLocalSettings({...localSettings, invoiceDesign: {...localSettings.invoiceDesign, accentColor: e.target.value}})} className="w-full h-12 rounded-xl cursor-pointer border-none bg-transparent" />
                                    </div>
                                </div>
                            </div>
                        </Card>
                    )}

                    {activeTab === 'subscription' && (
                        <div className="space-y-6 animate-fadeIn">
                            <div className="relative overflow-hidden bg-slate-900 rounded-4xl p-8 md:p-12 text-white shadow-2xl border border-white/5">
                                <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-600/20 rounded-full blur-[100px] -translate-y-1/2 translate-x-1/2"></div>
                                <div className="absolute bottom-0 left-0 w-64 h-64 bg-purple-600/10 rounded-full blur-[80px] translate-y-1/2 -translate-x-1/2"></div>

                                <div className="relative z-10 flex flex-col md:flex-row gap-12 items-start">
                                    <div className="flex-1 space-y-8 w-full">
                                        <div className="flex items-center gap-4">
                                            <div className="w-16 h-16 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-500/20">
                                                <Crown size={32} />
                                            </div>
                                            <div>
                                                <h3 className="text-3xl font-black">باقة {licenseInfo.type === 'Lifetime' ? 'مدى الحياة' : licenseInfo.type}</h3>
                                                <p className="text-indigo-300 font-bold">{licenseInfo.status === 'LICENSED' ? 'الاشتراك نشط وآمن' : 'حالة الترخيص: ' + licenseInfo.status}</p>
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                            <div className="p-5 bg-white/5 rounded-3xl border border-white/10 backdrop-blur-md">
                                                <p className="text-[10px] font-black uppercase text-indigo-300 mb-1 flex items-center gap-1"><Calendar size={12}/> تاريخ التفعيل</p>
                                                <p className="text-lg font-black">{new Date(licenseInfo.activationDate || '').toLocaleDateString('ar-EG')}</p>
                                            </div>
                                            <div className="p-5 bg-white/5 rounded-3xl border border-white/10 backdrop-blur-md">
                                                <p className="text-[10px] font-black uppercase text-rose-300 mb-1 flex items-center gap-1"><Zap size={12}/> تاريخ الانتهاء</p>
                                                <p className="text-lg font-black">{licenseInfo.type === 'Lifetime' ? 'غير محدود' : expiryDate.toLocaleDateString('ar-EG')}</p>
                                            </div>
                                        </div>

                                        <div className="space-y-3">
                                            <div className="flex justify-between text-xs font-black uppercase tracking-widest">
                                                <span>استهلاك الاشتراك</span>
                                                <span className="text-indigo-400">{licenseInfo.type === 'Lifetime' ? 'مفعل للأبد' : toArabicIndic(daysRemaining) + ' يوم متبقي'}</span>
                                            </div>
                                            <div className="h-4 w-full bg-white/10 rounded-full overflow-hidden p-1 border border-white/5">
                                                <div className="h-full bg-gradient-to-r from-indigo-500 to-sky-400 rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(99,102,241,0.5)]" style={{ width: `${progressPercent}%` }}></div>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="w-full md:w-80 bg-white/5 backdrop-blur-3xl rounded-4xl p-6 border border-white/10 shadow-inner">
                                        <h4 className="text-sm font-black mb-4 border-b border-white/10 pb-3 flex items-center gap-2 text-indigo-300"><ShieldCheck size={18}/> المميزات النشطة</h4>
                                        <ul className="space-y-4">
                                            {[
                                                { label: 'ذكاء اصطناعي (AI)', active: isPaid },
                                                { label: 'دعم فني VIP', active: isPaid },
                                                { label: 'مخازن غير محدودة', active: ['Lifetime', 'Yearly'].includes(licenseInfo.type || '') },
                                                { label: 'نسخ احتياطي', active: isPaid },
