import React, { useState, useEffect } from 'react';
import { Outlet, Navigate } from 'react-router-dom';
import Header from './Header';
import Sidebar from './Sidebar';
import { useAuth } from '../../hooks/useAuth';
import { useLicense } from '../../hooks/useLicense';
import { useSettings } from '../../hooks/useSettings';
import SplashScreen from './SplashScreen';
import ToastContainer from '../ui/ToastContainer';
import { AlertTriangle } from 'lucide-react';
import { api } from '../../services/mockApi';
import { useToasts } from '../../hooks/useToasts';

const MainLayout: React.FC = () => {
  const { user, isLoading: authLoading } = useAuth();
  const { isLicensed, isLoading: licenseLoading, licenseInfo } = useLicense();
  const { settings, updateSettings } = useSettings();
  const { addToast } = useToasts();

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  useEffect(() => {
      const savedCollapsed = localStorage.getItem('sidebar_collapsed');
      if (savedCollapsed) {
          setIsSidebarCollapsed(JSON.parse(savedCollapsed));
      }
  }, []);

  const toggleSidebarCollapse = () => {
      const newState = !isSidebarCollapsed;
      setIsSidebarCollapsed(newState);
      localStorage.setItem('sidebar_collapsed', JSON.stringify(newState));
  };

  useEffect(() => {
      if (!settings) return;

      const checkSystemEvents = async () => {
          const todayStr = new Date().toISOString().split('T')[0];
          const lastCheckDate = localStorage.getItem('pos_last_system_check_date');

          if (lastCheckDate === todayStr) return;

          // تعديل: النسخ الاحتياطي متاح فقط للنسخ المدفوعة
          const isPaidLicense = !['Free', 'Trial'].includes(licenseInfo.type || '');

          if (settings.notificationSettings?.backupReminder !== false && isPaidLicense) {
              const lastBackup = settings.autoBackup?.lastBackupAt || 0;
              const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;
              const timeSinceBackup = Date.now() - lastBackup;

              if (timeSinceBackup > thirtyDaysMs) {
                  await api.addNotification({
                      type: 'PROFIT_ALERT',
                      message: 'تنبيه هام: لم تقم بعمل نسخ احتياطي لبياناتك منذ أكثر من 30 يوماً. يرجى الذهاب للإعدادات وحفظ نسخة احتياطية.',
                  });
              }
          }

          if (settings.notificationSettings?.systemEvents !== false) {
              const today = new Date();
              if (today.getDay() === 5) {
                  await api.addNotification({
                      type: 'INFO',
                      message: 'جمعة مباركة! 🕌 نتمنى لك أسبوعاً مليئاً بالنجاح والتوفيق.',
                  });
              }

              try {
                  const hijriDatePart = new Intl.DateTimeFormat('en-US-u-ca-islamic-umalqura', {
                      day: 'numeric',
                      month: 'numeric',
                  }).formatToParts(today);

                  const hMonth = parseInt(hijriDatePart.find(p => p.type === 'month')?.value || '0');
                  const hDay = parseInt(hijriDatePart.find(p => p.type === 'day')?.value || '0');

                  if (hMonth === 8 && (hDay === 28 || hDay === 29)) {
                      await api.addNotification({
                          type: 'INFO',
                          message: '🌙 رمضان كريم! كل عام وأنتم بخير بمناسبة قرب حلول الشهر الفضيل.',
                      });
                  }
                  if (hMonth === 10 && hDay === 1) {
                      await api.addNotification({
                          type: 'INFO',
                          message: '🎉 عيد فطر مبارك! كل عام وأنتم بخير، أعاده الله عليكم باليمن والبركات.',
                      });
                  }
                  if (hMonth === 12 && hDay === 10) {
                      await api.addNotification({
                          type: 'INFO',
                          message: '🐏 عيد أضحى مبارك! تقبل الله منا ومنكم صالح الأعمال.',
                      });
                  }
              } catch (e) {
                  console.error("Error calculating Hijri date", e);
              }
          }
          localStorage.setItem('pos_last_system_check_date', todayStr);
      };
      checkSystemEvents();
  }, [settings, licenseInfo.type]);

  useEffect(() => {
      // حصر النسخ التلقائي للنسخ المدفوعة فقط
      const isPaidLicense = isLicensed && !['Free', 'Trial'].includes(licenseInfo.type || '');

      if (!settings || !settings.autoBackup || !settings.autoBackup.enabled || !isPaidLicense) return;

      const checkBackup = async () => {
          const now = Date.now();
          const { lastBackupAt, intervalMinutes } = settings.autoBackup!;
          const intervalMs = intervalMinutes * 60 * 1000;

          if (now - lastBackupAt > intervalMs) {
              try {
                  const d = await api.getBackupData();
                  const b = new Blob([d], { type: 'application/json' });
                  const u = URL.createObjectURL(b);
                  const l = document.createElement('a');
                  l.href = u;
                  l.download = `auto_backup_${new Date().toISOString().split('T')[0]}.json`;
                  l.click();
                  const newSettings = { 
                      ...settings, 
                      autoBackup: { ...settings.autoBackup!, lastBackupAt: now } 
                  };
                  updateSettings(newSettings);
                  addToast('تم إجراء نسخ احتياطي تلقائي.', 'info');
              } catch (e) {
                  console.error("Auto backup failed", e);
              }
          }
      };
      const intervalId = setInterval(checkBackup, 60000);
      checkBackup();
      return () => clearInterval(intervalId);
  }, [settings, isLicensed, licenseInfo.type, updateSettings, addToast]);

  if (authLoading || licenseLoading) {
    return <SplashScreen />;
  }

  if (!isLicensed) {
    return <Navigate to="/license" replace />;
  }

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  const navStyle = settings?.navigationStyle || 'grid';
  const showSidebar = navStyle === 'sidebar';

  return (
    <div className="flex flex-col min-h-screen text-slate-800 dark:text-slate-200 transition-colors duration-300 bg-transparent">
      {licenseInfo.status === 'GRACE_PERIOD' && (
          <div className="fixed top-0 left-0 right-0 z-[60] bg-yellow-500 text-black px-4 py-1 text-center font-bold flex items-center justify-center gap-2 animate-pulse text-xs">
              <AlertTriangle size={14} />
              <span>تحذير: انتهت صلاحية الترخيص. أنت الآن في فترة سماح مدتها 90 يوماً. يرجى التجديد لتجنب فقدان البيانات.</span>
          </div>
      )}
      <Header />
      <div className={`flex flex-1 pt-32 px-4 md:px-6 gap-6 max-w-[1920px] mx-auto w-full`}>
          {showSidebar && (
              <div className={`hidden lg:block flex-shrink-0 relative transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'w-24' : 'w-72'}`}>
                  <Sidebar 
                    sidebarOpen={sidebarOpen} 
                    setSidebarOpen={setSidebarOpen} 
                    isCollapsed={isSidebarCollapsed}
                    toggleCollapse={toggleSidebarCollapse}
                  />
              </div>
          )}
          <main className={`flex-1 min-w-0 pb-10 transition-all duration-300`}>
              <Outlet />
          </main>
      </div>
      <ToastContainer />
      {showSidebar && (
          <>
            <div className="lg:hidden">
                <Sidebar sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen} isCollapsed={false} toggleCollapse={() => {}} />
            </div>
            <button 
                className="lg:hidden fixed bottom-6 left-6 z-40 p-4 bg-indigo-600 text-white rounded-full shadow-xl shadow-indigo-500/30 active:scale-95 transition-transform glass-panel border-none"
                onClick={() => setSidebarOpen(true)}
            >
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
            </button>
          </>
      )}
    </div>
  );
};

