    SatisfactionAnalytics, User, SupplierPerformanceData, DashboardAnalytics, PermissionKey
} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const ALL_PERMISSIONS = PERMISSION_KEYS.reduce((acc, key) => {
    acc[key as PermissionKey] = true;
    return acc;
}, {} as Record<PermissionKey, boolean>);

const DEFAULT_SETTINGS: StoreSettings = {
    storeName: 'تكنو باور POS',
    vatRate: 15,
    taxRegisterNumber: '',
    invoiceFooter: 'شكراً لتعاملكم معنا',
    logoUrl: '',
    currency: 'SAR',
    nextInvoiceNumber: 1000,
    invoiceNumberPrefix: 'INV-',
    navigationStyle: 'grid',
    posLayout: 'classic',
    homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'],
    visiblePages: ['home', 'dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'suppliers', 'treasury', 'reports', 'partners', 'settings', 'warehouses', 'stock-transfer', 'sales-returns', 'purchase-returns', 'installments', 'activity-logs'],
    enableSoundEffects: true,
    enablePosCategories: true,
    enableShiftManagement: true,
    invoiceDesign: { template: 'modern', showLogo: true, showQrCode: true, accentColor: '#4f46e5', customCss: '' },
    loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5 }
};

const getDb = () => {
    const defaultDb = {
        settings: DEFAULT_SETTINGS,
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        feedback: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', roleId: 'r-1', permissions: ALL_PERMISSIONS }],
        roles: [{ id: 'r-1', name: 'مدير النظام', permissions: ALL_PERMISSIONS }],
        stockTransfers: [],
        notifications: [],
        shippingCompanies: [],
        transactions: [],
        shifts: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        if (!stored) return defaultDb;
        const parsed = JSON.parse(stored);
        parsed.settings = { ...DEFAULT_SETTINGS, ...parsed.settings };
        if (!parsed.settings.homeGridItems) parsed.settings.homeGridItems = DEFAULT_SETTINGS.homeGridItems;
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logAction = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({ id: `log-${Date.now()}`, timestamp: new Date().toISOString(), action, details, user: 'النظام' });
};

const updateTreasury = (db: any, treasuryId: string, amount: number, type: 'income' | 'expense') => {
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'income') t.balance += amount;
        else t.balance -= amount;
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb();
        db.settings = s;
        logAction(db, 'تعديل الإعدادات', 'تم تحديث إعدادات المتجر العامة');
        saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (!p.warehouseStocks) p.warehouseStocks = {};
        p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? p : item);
            logAction(db, 'تعديل منتج', `تعديل بيانات المنتج: ${p.name}`);
        } else {
            p.id = `prod-${Date.now()}`;
            db.products.push(p);
            logAction(db, 'إضافة منتج', `إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    deleteProduct: async (id: string) => {
        const db = getDb();
        const p = db.products.find((i:any) => i.id === id);
        db.products = db.products.filter((p: any) => p.id !== id);
        logAction(db, 'حذف منتج', `حذف المنتج: ${p?.name || id}`);
        saveDb(db); return true;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber}`;
        if (!sale.id) db.settings.nextInvoiceNumber++;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        const customer = db.customers.find((c: any) => c.id === sale.customer.id);
        if (customer) {
            if (sale.paymentMethod === 'Credit' || (sale.payments && sale.payments.some((p:any) => p.method === 'Credit'))) {
               const creditAmount = sale.paymentMethod === 'Credit' ? sale.total : sale.payments.find((p:any) => p.method === 'Credit').amount;
               customer.debt = (customer.debt || 0) + creditAmount;
            }
            customer.totalSpent = (customer.totalSpent || 0) + sale.total;
        }

        if (sale.installmentPlan) {
            db.installments.unshift({ ...sale.installmentPlan, id: `inst-${Date.now()}`, saleId: id, customerName: sale.customer.name, status: 'Active' });
            logAction(db, 'خطة تقسيط', `إنشاء خطة تقسيط للفاتورة #${id}`);
        }

        updateTreasury(db, sale.treasuryId, sale.amountPaid, 'income');
        logAction(db, 'عملية بيع', `إصدار فاتورة مبيعات #${id} بقيمة ${sale.total}`);
        saveDb(db); return finalSale;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) {
            db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
            logAction(db, 'تعديل عميل', `تعديل بيانات العميل: ${c.name}`);
        } else {
            c.id = `cust-${Date.now()}`;
            c.debt = 0; c.points = 0;
            db.customers.push(c);
            logAction(db, 'إضافة عميل', `إضافة عميل جديد: ${c.name}`);
        }
        saveDb(db); return c;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        updateTreasury(db, pur.treasuryId, pur.amountPaid, 'expense');
        logAction(db, 'عملية شراء', `تسجيل طلب شراء بقيمة ${pur.total}`);
        saveDb(db); return pur;
    },
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `sr-${Date.now()}`;
        ret.date = new Date().toISOString();
        db.salesReturns.unshift(ret);
        updateTreasury(db, ret.treasuryId, ret.totalRefund, 'expense');
        logAction(db, 'مرتجع مبيعات', `إرجاع فاتورة #${ret.originalSaleId} بقيمة ${ret.totalRefund}`);
        saveDb(db); return ret;
    },
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let success = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                updateTreasury(db, 't-1', payment.amount, 'income');
                logAction(db, 'تحصيل قسط', `تحصيل مبلغ ${payment.amount} من ${plan.customerName}`);
                success = true;
            }
        });
        if (success) saveDb(db); return success;
    },
    savePartner: async (p: any) => {
        const db = getDb();
        if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `part-${Date.now()}`; db.partners.push(p); }
        logAction(db, 'نظام الشركاء', `تحديث بيانات الشريك: ${p.name}`);
        saveDb(db); return p;
    },
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `t-${Date.now()}`; db.treasuries.push(t); }
        logAction(db, 'تعديل خزينة', `تحديث بيانات الخزينة: ${t.name}`);
        saveDb(db); return t;
    },
    saveTransaction: async (t: any) => {
        const db = getDb();
        if (t.id) db.transactions = db.transactions.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `tr-${Date.now()}`; t.date = new Date().toISOString(); t.user = 'المدير'; db.transactions.push(t); }
        updateTreasury(db, t.treasuryId, t.amount, t.type);
        logAction(db, 'حركة مالية', `تسجيل ${t.type === 'income' ? 'إيداع' : 'سحب'} بقيمة ${t.amount} - ${t.description}`);
        saveDb(db); return t;
    },
    saveWarehouse: async (w: any) => {
        const db = getDb();
        if (w.id) db.warehouses = db.warehouses.map((item: any) => item.id === w.id ? w : item);
        else { w.id = `w-${Date.now()}`; db.warehouses.push(w); }
        logAction(db, 'المستودعات', `تحديث بيانات المستودع: ${w.name}`);
        saveDb(db); return w;
    },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    wipeBusinessData: async () => { localStorage.clear(); window.location.reload(); },
    getUsers: async () => getDb().users,
    getSales: async () => getDb().sales,
    getSalesReturns: async () => getDb().salesReturns,
    getPurchases: async () => getDb().purchases,
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getInstallmentPlans: async () => getDb().installments,
    getTransactions: async () => getDb().transactions || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getNotifications: async () => getDb().notifications || [],
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const now = new Date().toISOString().split('T')[0];
        const todaySales = db.sales.filter((s: any) => s.date.startsWith(now));
        return {
            totalSalesToday: todaySales.reduce((acc: number, s: any) => acc + s.total, 0),
            todaysTransactions: todaySales.length,
            totalReceivables: db.customers.reduce((acc: number, c: any) => acc + (c.debt || 0), 0),
            totalStockValue: db.products.reduce((acc: number, p: any) => acc + (p.stock * p.costPrice), 0),
            monthlySales: [], salesByCategory: [], topProducts: []
        };
    },
    login: async (name: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.name === name);
        if (user && password === 'password') return user;
        return null;
    },
    verifyPassword: async (userId: string, password: string) => password === 'password',
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const filter = (arr: any[]) => (arr || []).filter(i => (i.name || i.id || "").toLowerCase().includes(q.toLowerCase()));
        return {
            products: filter(db.products), sales: filter(db.sales), customers: filter(db.customers),
            purchases: filter(db.purchases), suppliers: filter(db.suppliers), partners: filter(db.partners),
            salesReturns: filter(db.salesReturns), purchaseReturns: filter(db.purchaseReturns),
            installments: filter(db.installments), stockTransfers: filter(db.stockTransfers)
        };
    },
    getCustomerPurchaseHistory: async (cid: string) => getDb().sales.filter((s: any) => s.customer.id === cid),
    getCustomerReturnsHistory: async (cid: string) => getDb().salesReturns.filter((r: any) => {
        const sale = getDb().sales.find((s: any) => s.id === r.originalSaleId);
        return sale && sale.customer.id === cid;
    }),
    saveStockTransfer: async (st: any) => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            st.id = `st-${Date.now()}`;
            st.date = new Date().toISOString();
            db.stockTransfers.unshift(st);
            logAction(db, 'نقل مخزون', `نقل ${st.quantity} من المنتج ${p.name}`);
            saveDb(db); return true;
        }
        return false;
    },
    updateSale: async (id: string, data: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...data } : s);
        logAction(db, 'تعديل فاتورة', `تعديل بيانات الفاتورة #${id}`);
        saveDb(db); return true;
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s: any) => s.date >= start && s.date <= end);
        const totalRevenue = sales.reduce((a: number, b: any) => a + b.total, 0);
        return { totalRevenue, totalCOGS: 0, totalExpenses: 0, totalPurchases: 0, totalReturns: 0, netProfit: 0, dailyStats: [] };
    }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, SaleItem, Warehouse, Treasury, PaymentDetail } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import { Search, ShoppingCart, Trash2, Plus, Minus, User, Gift, Warehouse as WhIcon, Wallet, Percent, Truck, CreditCard, PlusCircle, UserPlus, X } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';
import SplitPaymentModal from '../components/pos/SplitPaymentModal';
import InstallmentSetupModal from '../components/sales/InstallmentSetupModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    // إدارة العملاء
    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [customerQuery, setCustomerQuery] = useState('');
    const [showCustResults, setShowCustResults] = useState(false);
    const [isNewCustModalOpen, setIsNewCustModalOpen] = useState(false);

    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    // الخصومات والشحن الكلي
    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [shippingCost, setShippingCost] = useState(0);

    // إدارة الدفع
    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [showSplitModal, setShowSplitModal] = useState(false);
    const [showInstallmentModal, setShowInstallmentModal] = useState(false);
    const [tempPayments, setTempPayments] = useState<PaymentDetail[] | null>(null);

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t] = await Promise.all([api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries()]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
        };
        load();
    }, []);

    const selectedCustomer = useMemo(() => customers.find(c => c.id === selectedCustomerId), [customers, selectedCustomerId]);

    // حسابات السلة
    const subtotal = useMemo(() => cart.reduce((s, i) => {
        const price = i.sellPrice || 0;
        const discount = i.discountPercent ? (price * i.discountPercent / 100) : 0;
        return s + ((price - discount) * i.quantity);
    }, 0), [cart]);

    const discountVal = useMemo(() => globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount, [subtotal, globalDiscount, globalDiscountType]);
    const finalTotal = Math.max(0, subtotal - discountVal + shippingCost);

    const handleCheckout = async (method: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit', payments?: PaymentDetail[], installmentPlan?: any) => {
        if (!cart.length || !selectedWhId || !selectedTrId) {
            addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning');
            return;
        }

        if (method === 'Credit' && !installmentPlan) {
            setShowInstallmentModal(true);
            return;
        }

        try {
            const res = await api.saveSale({
                customer: { id: selectedCustomer!.id, name: selectedCustomer!.name },
                cashier: { id: 'u-1', name: 'المدير' },
                items: cart.map(i => ({ ...i, originalPrice: products.find(p => p.id === i.id)?.sellPrice || i.sellPrice })),
                subtotal: subtotal,
                total: finalTotal,
                amountPaid: method === 'Credit' ? (installmentPlan?.downPayment || 0) : finalTotal,
                paymentMethod: method,
                discount: globalDiscount,
                discountType: globalDiscountType,
                shipping: shippingCost,
                warehouseId: selectedWhId,
                treasuryId: selectedTrId,
                payments: payments,
                installmentPlan: installmentPlan
            });
            setLastSale(res); setShowReceipt(true); setCart([]); 
            setGlobalDiscount(0); setShippingCost(0);
            addToast('تم إتمام البيع بنجاح', 'success');
        } catch (e) { addToast('فشل إتمام البيع', 'error'); }
    };

    const addToCart = (p: Product) => {
        setCart(prev => {
            const ex = prev.find(i => i.id === p.id);
            if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
            return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice, discountPercent: 0 }];
        });
        setSearchTerm('');
    };

    const updateItem = (id: string, field: string, value: any) => {
        setCart(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const filteredCustomers = customers.filter(c => 
        c.name.toLowerCase().includes(customerQuery.toLowerCase()) || 
        c.phone.includes(customerQuery)
    );

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            {/* Header: Customer & Product Search */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
                <div className="lg:col-span-8 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج بالاسم أو الباركود..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-14 ps-12 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 font-black outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm transition-all"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-2 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                <button key={p.id} onClick={() => addToCart(p)} className="w-full p-4 border-b dark:border-slate-700 flex justify-between hover:bg-indigo-50 dark:hover:bg-indigo-900/20 font-black text-sm">
                                    <span>{p.name} <span className="text-[10px] text-slate-400 font-normal">({p.category})</span></span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                <div className="lg:col-span-4 flex gap-2">
                    <div className="relative flex-1">
                        <User className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="بحث عن عميل..." 
                            value={showCustResults ? customerQuery : (selectedCustomer?.name || '')} 
                            onFocus={() => { setShowCustResults(true); setCustomerQuery(''); }}
                            onChange={e => setCustomerQuery(e.target.value)}
                            className="w-full h-14 ps-11 pe-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 font-black text-sm outline-none shadow-sm"
                        />
                        {showCustResults && (
                            <div className="absolute top-full left-0 right-0 z-[100] mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border dark:border-slate-700 overflow-hidden">
                                <div className="max-h-60 overflow-y-auto">
                                    {filteredCustomers.map(c => (
                                        <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setShowCustResults(false); }} className="w-full p-3 text-start hover:bg-slate-50 dark:hover:bg-slate-700 border-b last:border-0 flex justify-between items-center">
                                            <span className="font-bold text-xs">{c.name}</span>
                                            <span className="text-[10px] text-slate-400">{c.phone}</span>
                                        </button>
                                    ))}
                                </div>
                                <button onClick={() => { setIsNewCustModalOpen(true); setShowCustResults(false); }} className="w-full p-3 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 text-[11px] font-black flex items-center justify-center gap-2">
                                    <UserPlus size={14} /> إضافة عميل جديد
                                </button>
                            </div>
                        )}
                    </div>
                    <Button onClick={() => setIsNewCustModalOpen(true)} className="h-14 w-14 rounded-2xl p-0 bg-slate-100 dark:bg-slate-800 text-indigo-600 border border-slate-200 dark:border-slate-700 hover:bg-indigo-50"><UserPlus size={24}/></Button>
                </div>
            </div>

            {/* Cart Items Area */}
            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden flex flex-col">
                <div className="bg-slate-50 dark:bg-slate-800/50 px-6 py-3 border-b dark:border-slate-700 grid grid-cols-12 text-[10px] font-black uppercase text-slate-400">
                    <div className="col-span-5">المنتج / السعر</div>
                    <div className="col-span-2 text-center">الكمية</div>
                    <div className="col-span-2 text-center">خصم %</div>
                    <div className="col-span-3 text-end">الإجمالي</div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                    {cart.map(item => (
                        <div key={item.id} className="grid grid-cols-12 gap-2 items-center p-3 bg-slate-50 dark:bg-slate-800/40 rounded-2xl border border-slate-100 dark:border-slate-700/50 hover:border-indigo-300 transition-colors">
                            <div className="col-span-5">
                                <p className="font-black text-sm truncate">{item.name}</p>
                                <div className="flex items-center gap-1 mt-1">
                                    <span className="text-[10px] text-slate-400">السعر:</span>
                                    <input 
                                        type="number" 
                                        value={item.sellPrice} 
                                        onChange={e => updateItem(item.id, 'sellPrice', parseFloat(e.target.value)||0)}
                                        className="w-20 bg-white dark:bg-slate-700 border-none rounded p-0 text-[11px] font-black text-indigo-600 focus:ring-1 focus:ring-indigo-400"
                                    />
                                </div>
                            </div>
                            <div className="col-span-2 flex flex-col items-center justify-center gap-1">
                                <div className="flex items-center gap-2">
                                    <button onClick={() => updateItem(item.id, 'quantity', Math.max(1, item.quantity - 1))} className="p-1 hover:bg-white dark:hover:bg-slate-700 rounded-lg text-slate-400"><Minus size={12}/></button>
                                    <span className="font-black text-xs min-w-[20px] text-center">{toArabicIndic(item.quantity)}</span>
                                    <button onClick={() => updateItem(item.id, 'quantity', item.quantity + 1)} className="p-1 hover:bg-white dark:hover:bg-slate-700 rounded-lg text-indigo-600"><Plus size={12}/></button>
                                </div>
                            </div>
                            <div className="col-span-2 flex justify-center">
                                <input 
                                    type="number" 
                                    max="100" min="0"
                                    value={item.discountPercent} 
                                    onChange={e => updateItem(item.id, 'discountPercent', parseFloat(e.target.value)||0)}
                                    className="w-12 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-center text-[11px] font-bold"
                                />
                            </div>
                            <div className="col-span-3 text-end flex flex-col items-end gap-1">
                                <p className="font-black text-sm">{formatAmount((item.sellPrice - (item.sellPrice * (item.discountPercent || 0) / 100)) * item.quantity)}</p>
                                <button onClick={() => setCart(cart.filter(i => i.id !== item.id))} className="text-rose-400 hover:text-rose-600 p-1"><Trash2 size={14}/></button>
                            </div>
                        </div>
                    ))}
                    {!cart.length && (
                        <div className="h-full flex flex-col items-center justify-center opacity-30">
                            <ShoppingCart size={80} strokeWidth={1} />
                            <p className="font-black text-xl mt-4">بانتظار إضافة الأصناف...</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Global Summary Area */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
                {/* Adjustments: Discount & Shipping */}
                <Card className="lg:col-span-4 p-4 shadow-xl border-none">
                    <div className="space-y-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-amber-50 dark:bg-amber-900/20 text-amber-600 rounded-xl"><Percent size={18}/></div>
                            <div className="flex-1 flex gap-2">
                                <input 
                                    type="number" 
                                    placeholder="الخصم الكلي" 
                                    value={globalDiscount || ''} 
                                    onChange={e => setGlobalDiscount(parseFloat(e.target.value)||0)}
                                    className="w-full p-2 border border-slate-200 dark:border-slate-700 rounded-xl dark:bg-slate-800 font-bold text-xs" 
                                />
                                <button 
                                    onClick={() => setGlobalDiscountType(globalDiscountType === 'amount' ? 'percent' : 'amount')}
                                    className="px-3 bg-slate-100 dark:bg-slate-700 rounded-xl font-black text-[10px]"
                                >
                                    {globalDiscountType === 'amount' ? settings?.currency : '%'}
                                </button>
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl"><Truck size={18}/></div>
                            <input 
                                type="number" 
                                placeholder="تكلفة الشحن" 
                                value={shippingCost || ''} 
                                onChange={e => setShippingCost(parseFloat(e.target.value)||0)}
                                className="flex-1 p-2 border border-slate-200 dark:border-slate-700 rounded-xl dark:bg-slate-800 font-bold text-xs" 
                            />
                        </div>
                    </div>
                </Card>

                {/* Final Total & Payments */}
                <Card className="lg:col-span-8 p-4 shadow-2xl bg-indigo-600 text-white border-none flex flex-col md:flex-row items-center justify-between gap-6 overflow-hidden relative">
                    <div className="absolute -right-4 -bottom-4 opacity-10 rotate-12"><ShoppingCart size={120}/></div>

                    <div className="text-center md:text-start relative z-10">
                        <p className="text-[10px] font-black uppercase tracking-widest opacity-70">المجموع النهائي (شامل الضريبة)</p>
                        <p className="text-5xl font-black tracking-tighter leading-none mt-1">
                            {formatCurrency(finalTotal, settings?.currency)}
                        </p>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 w-full md:w-auto relative z-10">
                        <Button onClick={() => handleCheckout('Cash')} className="bg-white text-indigo-600 h-14 rounded-2xl font-black shadow-lg">كاش</Button>
                        <Button onClick={() => handleCheckout('Card')} className="bg-white/20 hover:bg-white/30 text-white h-14 rounded-2xl font-black border border-white/20">بطاقة</Button>
                        <Button onClick={() => setShowSplitModal(true)} className="bg-emerald-500 hover:bg-emerald-600 text-white h-14 rounded-2xl font-black">مختلط</Button>
                        <Button onClick={() => handleCheckout('Credit')} className="bg-amber-500 hover:bg-amber-600 text-white h-14 rounded-2xl font-black col-span-2 sm:col-span-3">دفع آجل / أقساط</Button>
                    </div>
                </Card>
            </div>

            {/* Meta: Warehouse & Treasury Selectors */}
            <div className="flex justify-between px-2 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1"><WhIcon size={12}/> المستودع: <select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="bg-transparent text-slate-600 dark:text-slate-300 border-none p-0 outline-none">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></span>
                    <span className="flex items-center gap-1"><Wallet size={12}/> الخزينة: <select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="bg-transparent text-slate-600 dark:text-slate-300 border-none p-0 outline-none">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></span>
                </div>
                <span>نظام تكنو باور POS - الإصدار الترا v1.18</span>
            </div>

            {/* Modals */}
            <ReceiptModal isOpen={showReceipt} onClose={() => setShowReceipt(false)} sale={lastSale} />
            <SplitPaymentModal isOpen={showSplitModal} onClose={() => setShowSplitModal(false)} totalAmount={finalTotal} onConfirm={(p) => { setTempPayments(p); handleCheckout('Split', p); setShowSplitModal(false); }} />
            <InstallmentSetupModal isOpen={showInstallmentModal} onClose={() => setShowInstallmentModal(false)} totalAmount={finalTotal} downPayment={0} defaultInterestRate={0} onSave={(plan) => { handleCheckout('Credit', undefined, { ...plan, status: 'Active' }); setShowInstallmentModal(false); }} />
            <Modal isOpen={isNewCustModalOpen} onClose={() => setIsNewCustModalOpen(false)} title="إضافة عميل جديد">
                <CustomerForm customer={null} onCancel={() => setIsNewCustModalOpen(false)} isLoading={false} onSave={async (d) => { const newC = await api.saveCustomer(d); setCustomers([...customers, newC]); setSelectedCustomerId(newC.id); setIsNewCustModalOpen(false); addToast('تمت إضافة العميل بنجاح', 'success'); }} />
            </Modal>
        </div>
    );
};

