            const matchesDate = (!start || s.date >= start) && (!end || s.date <= end);
            const matchesCategory = !category || s.items.some((i: any) => i.category === category);
            const matchesCashier = !cashierId || s.cashier.id === cashierId;
            return matchesDate && matchesCategory && matchesCashier;
        });
        const totalRevenue = sales.reduce((a: number, b: any) => a + b.total, 0);
        return { totalRevenue, totalCOGS: 0, totalExpenses: 0, totalPurchases: 0, totalReturns: 0, netProfit: totalRevenue, dailyStats: [] };
