        db.transactions = db.transactions.filter((t: any) => t.id !== id);
        saveDb(db); return true;
    },
    saveTransaction: async (t: any) => {
        const db = getDb();
        if (t.id) db.transactions = db.transactions.map((item: any) => item.id === t.id ? t : item);
        else { t.id = `tr-${Date.now()}`; t.date = new Date().toISOString(); t.user = 'المدير'; db.transactions.push(t); }
        updateTreasury(db, t.treasuryId, t.amount, t.type);
        logAction(db, 'حركة مالية', `تسجيل ${t.type === 'income' ? 'إيداع' : 'سحب'} بقيمة ${t.amount} - ${t.description}`);
        saveDb(db); return t;
    },
    deleteWarehouse: async (id: string) => {
        const db = getDb();
        db.warehouses = db.warehouses.filter((w: any) => w.id !== id);
        saveDb(db); return true;
    },
    saveWarehouse: async (w: any) => {
        const db = getDb();
        if (w.id) db.warehouses = db.warehouses.map((item: any) => item.id === w.id ? w : item);
        else { w.id = `w-${Date.now()}`; db.warehouses.push(w); }
        logAction(db, 'المستودعات', `تحديث بيانات المستودع: ${w.name}`);
        saveDb(db); return w;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => {
        const db = getDb();
        if (!db.shippingCompanies) db.shippingCompanies = [];
        if (c.id) {
            db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === c.id ? c : item);
        } else {
            c.id = `ship-${Date.now()}`;
            db.shippingCompanies.push(c);
        }
        saveDb(db); return c;
    },
    deleteShippingCompany: async (id: string) => {
        const db = getDb();
        db.shippingCompanies = db.shippingCompanies.filter((c: any) => c.id !== id);
        saveDb(db); return true;
    },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    wipeBusinessData: async () => { localStorage.clear(); window.location.reload(); },
    getUsers: async () => getDb().users,
    saveUser: async (u: any) => {
        const db = getDb();
        if (u.id) {
            db.users = db.users.map((item: any) => item.id === u.id ? { ...item, ...u } : item);
            logAction(db, 'تعديل موظف', `تحديث بيانات الموظف: ${u.name}`);
        } else {
            u.id = `u-${Date.now()}`;
            db.users.push(u);
            logAction(db, 'إضافة موظف', `تسجيل موظف جديد: ${u.name}`);
        }
        saveDb(db); return u;
    },
    getSales: async () => getDb().sales,
    getSalesReturns: async () => getDb().salesReturns,
    getPurchases: async () => getDb().purchases,
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getInstallmentPlans: async () => getDb().installments,
    getTransactions: async () => getDb().transactions || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getNotifications: async () => getDb().notifications || [],
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const now = new Date().toISOString().split('T')[0];
        const todaySales = db.sales.filter((s: any) => s.date.startsWith(now));
        return {
            totalSalesToday: todaySales.reduce((acc: number, s: any) => acc + s.total, 0),
            todaysTransactions: todaySales.length,
            totalReceivables: db.customers.reduce((acc: number, c: any) => acc + (c.debt || 0), 0),
            totalStockValue: db.products.reduce((acc: number, p: any) => acc + (p.stock * p.costPrice), 0),
            monthlySales: [], salesByCategory: [], topProducts: []
        };
    },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        return {
            performanceData: db.users.map((u: any) => ({
                userId: u.id,
                userName: u.name,
                totalSalesValue: 0,
                totalSalesCount: 0,
                averageSaleValue: 0,
                totalReturnsValue: 0,
                returnRate: 0
            })),
        };
    },
    getSyncLogs: async (): Promise<SyncLog[]> => {
        return [
            { tableName: 'products', recordCount: getDb().products.length, lastSynced: new Date().toISOString() },
            { tableName: 'sales', recordCount: getDb().sales.length, lastSynced: new Date().toISOString() },
        ];
    },
    getQueueCount: async () => 0,
    processQueue: async () => {},
    setOnlineStatus: (status: boolean) => {},
    getSatisfactionAnalytics: async (): Promise<SatisfactionAnalytics> => {
        return { happy: 0, neutral: 0, unhappy: 0, total: 0 };
    },
    submitFeedback: async (f: any) => {
        const db = getDb();
        if (!db.feedback) db.feedback = [];
        db.feedback.push(f);
        saveDb(db);
        return true;
    },
    login: async (name: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.name === name);
        if (user && password === 'password') return user;
        return null;
    },
    verifyPassword: async (userId: string, password: string) => password === 'password',
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const filter = (arr: any[]) => (arr || []).filter(i => (i.name || i.id || "").toLowerCase().includes(q.toLowerCase()));
        return {
            products: filter(db.products), sales: filter(db.sales), customers: filter(db.customers),
            purchases: filter(db.purchases), suppliers: filter(db.suppliers), partners: filter(db.partners),
            salesReturns: filter(db.salesReturns), purchaseReturns: filter(db.purchaseReturns),
            installments: filter(db.installments), stockTransfers: filter(db.stockTransfers)
        };
    },
    getCustomerPurchaseHistory: async (cid: string) => getDb().sales.filter((s: any) => s.customer.id === cid),
    getCustomerReturnsHistory: async (cid: string) => getDb().salesReturns.filter((r: any) => {
        const sale = getDb().sales.find((s: any) => s.id === r.originalSaleId);
        return sale && sale.customer.id === cid;
    }),
    getSalesHistoryForForecast: async (): Promise<SalesHistoryData[]> => [],
    getSupplierPerformanceData: async (): Promise<SupplierPerformanceData[]> => [],
    getInactiveCustomers: async (days: number): Promise<InactiveCustomer[]> => [],
    getStagnantProducts: async (days: number): Promise<StagnantProduct[]> => [],
    saveStockTransfer: async (st: any) => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            st.id = `st-${Date.now()}`;
            st.date = new Date().toISOString();
            db.stockTransfers.unshift(st);
            logAction(db, 'نقل مخزون', `نقل ${st.quantity} من المنتج ${p.name}`);
            saveDb(db); return true;
        }
        return false;
    },
    updateSale: async (id: string, data: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...data } : s);
        logAction(db, 'تعديل فاتورة', `تعديل بيانات الفاتورة #${id}`);
        saveDb(db); return true;
    },
    updatePurchase: async (id: string, data: any) => {
        const db = getDb();
        db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...data } : p);
        saveDb(db); return true;
    },
    updateSystemVersion: async (version: string, pkg: any) => {
        const db = getDb();
        logAction(db, 'تحديث النظام', `ترقية النظام للإصدار ${version}`);
        saveDb(db); return true;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string) => {
        const db = getDb();
        const sales = db.sales.filter((s: any) => {
            const matchesDate = (!start || s.date >= start) && (!end || s.date <= end);
            const matchesCategory = !category || s.items.some((i: any) => i.category === category);
            const matchesCashier = !cashierId || s.cashier.id === cashierId;
            return matchesDate && matchesCategory && matchesCashier;
        });
        const totalRevenue = sales.reduce((a: number, b: any) => a + b.total, 0);
        return { totalRevenue, totalCOGS: 0, totalExpenses: 0, totalPurchases: 0, totalReturns: 0, netProfit: totalRevenue, dailyStats: [] };
    },
    getJournalEntries: async (): Promise<JournalEntry[]> => [],
    getCurrentShift: async (userId: string): Promise<Shift | null> => {
        const db = getDb();
        return db.shifts.find((s: Shift) => s.userId === userId && s.status === 'Open') || null;
    },
    openShift: async (userId: string, amount: number): Promise<Shift> => {
        const db = getDb();
        const newShift: Shift = {
            id: `shift-${Date.now()}`,
            userId,
            startTime: new Date().toISOString(),
            startCash: amount,
            status: 'Open'
        };
        db.shifts.push(newShift);
        saveDb(db);
        return newShift;
    },
    closeShift: async (id: string, endCash: number, notes?: string): Promise<Shift> => {
        const db = getDb();
        const shift = db.shifts.find((s: Shift) => s.id === id);
        if (shift) {
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = notes;
            shift.status = 'Closed';
            saveDb(db);
            return shift;
        }
        throw new Error("Shift not found");
    }
};

