import React, { createContext, useState, useContext, useEffect, ReactNode, useCallback } from 'react';
import { secureStorage } from '../utils/secureStorage';

interface DevModeContextType {
  isDevMode: boolean;
  enableDevMode: (code: string) => boolean;
  disableDevMode: () => void;
}

const DevModeContext = createContext<DevModeContextType | undefined>(undefined);

const DEV_MODE_STORAGE_KEY = 'pos_dev_mode';
const DEV_MODE_SECRET_CODE = '219180729136';

export const DevModeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isDevMode, setIsDevMode] = useState(false);

  useEffect(() => {
    const savedState = secureStorage.getItem<boolean>(DEV_MODE_STORAGE_KEY);
    if (savedState) {
      setIsDevMode(true);
    }
  }, []);

  const enableDevMode = useCallback((code: string): boolean => {
    if (code === DEV_MODE_SECRET_CODE) {
      secureStorage.setItem(DEV_MODE_STORAGE_KEY, true);
      setIsDevMode(true);
      window.location.reload();
      return true;
    }
    return false;
  }, []);

  const disableDevMode = useCallback(() => {
    if (isDevMode) {
      secureStorage.removeItem(DEV_MODE_STORAGE_KEY);
      setIsDevMode(false);
      window.location.reload();
    }
  }, [isDevMode]);

  const value = { isDevMode, enableDevMode, disableDevMode };

  return (
    <DevModeContext.Provider value={value}>
      {children}
    </DevModeContext.Provider>
  );
};

export const useDevMode = () => {
  const context = useContext(DevModeContext);
  if (context === undefined) {
    throw new Error('useDevMode must be used within a DevModeProvider');
  }
  return context;
};

import { useEffect } from 'react';

export const useAppGuard = () => {
    useEffect(() => {
        // حماية الذاكرة (Memory Protection)
        const originalSetItem = localStorage.setItem;
        localStorage.setItem = function(key, value) {
            if (key.includes('license') && typeof value === 'string' && !value.includes('_sys_')) {
                // منع التلاعب الخارجي بالترخيص
                return;
            }
            try {
                originalSetItem.apply(localStorage, [key, value]);
            } catch (e) {
                console.error("Local Storage Error", e);
            }
        };

        // تعطيل الاختصارات الحساسة (F12, Ctrl+U)
        const disableKeys = (e: KeyboardEvent) => {
            if (
                e.keyCode === 123 || // F12
                (e.ctrlKey && e.shiftKey && e.keyCode === 73) || // Ctrl+Shift+I
                (e.ctrlKey && e.shiftKey && e.keyCode === 74) || // Ctrl+Shift+J
                (e.ctrlKey && e.keyCode === 85) // Ctrl+U (View Source)
            ) {
                e.preventDefault();
                return false;
            }
        };

        window.addEventListener('keydown', disableKeys);

        return () => {
            window.removeEventListener('keydown', disableKeys);
        };
    }, []);
};

