};

const getDb = () => {
    const defaultDb = {
        settings: DEFAULT_SETTINGS,
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        feedback: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', roleId: 'r-1', permissions: ALL_PERMISSIONS }],
        roles: [{ id: 'r-1', name: 'مدير النظام', permissions: ALL_PERMISSIONS }],
        stockTransfers: [],
        notifications: [],
        shippingCompanies: [],
        transactions: [],
        shifts: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        if (!stored) return defaultDb;
        const parsed = JSON.parse(stored);
        parsed.settings = { ...DEFAULT_SETTINGS, ...parsed.settings };
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logAction = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({ id: `log-${Date.now()}`, timestamp: new Date().toISOString(), action, details, user: 'النظام' });
};

const updateTreasury = (db: any, treasuryId: string, amount: number, type: 'income' | 'expense') => {
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t && amount > 0) {
        if (type === 'income') t.balance += amount;
        else t.balance -= amount;
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb();
        db.settings = s;
        logAction(db, 'تعديل الإعدادات', 'تم تحديث إعدادات المتجر العامة');
        saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (!p.warehouseStocks) p.warehouseStocks = {};
        p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? p : item);
        } else {
            p.id = `prod-${Date.now()}`;
            db.products.push(p);
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const existingSale = sale.id ? db.sales.find((s: any) => s.id === sale.id) : null;

        // عكس المخزون القديم إذا كان تعديل
        if (existingSale) {
            existingSale.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.id);
                if (p) {
                    p.warehouseStocks[existingSale.warehouseId] = (p.warehouseStocks[existingSale.warehouseId] || 0) + item.quantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
                }
            });
            updateTreasury(db, existingSale.treasuryId, existingSale.amountPaid, 'expense');
        }

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber}`;
        if (!sale.id) db.settings.nextInvoiceNumber++;
        const finalSale = { ...sale, id, date: sale.date || new Date().toISOString(), status: 'Completed' };

        if (existingSale) {
            db.sales = db.sales.map((s: any) => s.id === sale.id ? finalSale : s);
        } else {
            db.sales.unshift(finalSale);
        }

        updateTreasury(db, sale.treasuryId, sale.amountPaid, 'income');
        logAction(db, existingSale ? 'تعديل بيع' : 'عملية بيع', `فاتورة #${id} بقيمة ${sale.total}`);
        saveDb(db); return finalSale;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) {
            db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
        } else {
            c.id = `cust-${Date.now()}`;
            c.debt = 0; c.points = 0;
            db.customers.push(c);
        }
        saveDb(db); return c;
    },
    getSuppliers: async () => getDb().suppliers,
    saveSupplier: async (s: any) => {
        const db = getDb();
        if (s.id) db.suppliers = db.suppliers.map((item: any) => item.id === s.id ? s : item);
        else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); }
        saveDb(db); return s;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        const existingPur = pur.id ? db.purchases.find((p: any) => p.id === pur.id) : null;

        // عكس المخزون والميزانية القديمة إذا كان تعديل
        if (existingPur) {
            existingPur.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.productId);
                if (p) {
                    p.warehouseStocks[existingPur.warehouseId] = (p.warehouseStocks[existingPur.warehouseId] || 0) - item.quantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
                }
            });
            updateTreasury(db, existingPur.treasuryId, existingPur.amountPaid, 'income');
        }

        // تحديث المخزون بالجديد
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        // تحديد الحالة تلقائياً
        let status: Purchase['status'] = 'Unpaid';
        if (pur.amountPaid >= pur.total) status = 'Paid';
        else if (pur.amountPaid > 0) status = 'Partial';

        const finalPur = { 
            ...pur, 
            id: pur.id || `pur-${Date.now()}`, 
            date: pur.date || new Date().toISOString(),
            status 
        };

        if (existingPur) {
            db.purchases = db.purchases.map((p: any) => p.id === pur.id ? finalPur : p);
        } else {
            db.purchases.unshift(finalPur);
        }

        updateTreasury(db, pur.treasuryId, pur.amountPaid, 'expense');
        logAction(db, existingPur ? 'تعديل شراء' : 'عملية شراء', `طلب شراء بقيمة ${pur.total}`);
        saveDb(db); return finalPur;
    },
    getSales: async () => getDb().sales || [],
    getPurchases: async () => getDb().purchases || [],
    getSalesReturns: async () => getDb().salesReturns || [],
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getTreasuries: async () => getDb().treasuries || [],
    getWarehouses: async () => getDb().warehouses || [],
    getActivityLogs: async () => getDb().activityLogs || [],
    getInstallmentPlans: async () => getDb().installments || [],
    getTransactions: async () => getDb().transactions || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getNotifications: async () => getDb().notifications || [],
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const now = new Date().toISOString().split('T')[0];
        const todaySales = db.sales.filter((s: any) => s.date.startsWith(now));
        return {
            totalSalesToday: todaySales.reduce((acc: number, s: any) => acc + s.total, 0),
            todaysTransactions: todaySales.length,
            totalReceivables: db.customers.reduce((acc: number, c: any) => acc + (c.debt || 0), 0),
            totalStockValue: db.products.reduce((acc: number, p: any) => acc + (p.stock * p.costPrice), 0),
            monthlySales: [], salesByCategory: [], topProducts: []
        };
    },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const filter = (arr: any[]) => (arr || []).filter(i => (i.name || i.id || "").toLowerCase().includes(q.toLowerCase()));
        return {
            products: filter(db.products), sales: filter(db.sales), customers: filter(db.customers),
            purchases: filter(db.purchases), suppliers: filter(db.suppliers), partners: filter(db.partners),
            salesReturns: filter(db.salesReturns), purchaseReturns: filter(db.purchaseReturns),
            installments: filter(db.installments), stockTransfers: filter(db.stockTransfers)
        };
    },
    saveStockTransfer: async (st: any) => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            st.id = `st-${Date.now()}`;
            st.date = new Date().toISOString();
            db.stockTransfers.unshift(st);
            saveDb(db); return true;
        }
        return false;
    },
    updateSale: async (id: string, data: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...data } : s);
        saveDb(db); return true;
    },
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `sr-${Date.now()}`;
        ret.date = new Date().toISOString();
        ret.user = { id: 'u-1', name: 'المدير' };
        db.salesReturns.unshift(ret);
        updateTreasury(db, ret.treasuryId, ret.totalRefund, 'expense');
        logAction(db, 'مرتجع مبيعات', `إرجاع فاتورة #${ret.originalSaleId}`);
        saveDb(db); return ret;
    },
    login: async (name: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.name === name);
        if (user && password === 'password') return user;
        return null;
    },
    verifyPassword: async (userId: string, password: string) => password === 'password',
    getUsers: async () => getDb().users,
    saveUser: async (u: any) => {
        const db = getDb();
        if (u.id) db.users = db.users.map((item: any) => item.id === u.id ? { ...item, ...u } : item);
        else { u.id = `u-${Date.now()}`; db.users.push(u); }
        saveDb(db); return u;
    },
    getFinancialReport: async (start: string, end: string) => {
        return { totalRevenue: 0, totalCOGS: 0, totalExpenses: 0, totalPurchases: 0, totalReturns: 0, netProfit: 0, dailyStats: [] };
    },
    wipeBusinessData: async () => { localStorage.clear(); window.location.reload(); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    recordInstallmentPayment: async (id: string) => true,
    getSuppliersPerformance: async () => [],
    getSyncLogs: async () => [],
    getEmployeePerformanceAnalytics: async () => ({ performanceData: [] }),
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    getInactiveCustomers: async (days: number) => [],
    getStagnantProducts: async (days: number) => [],
    updatePurchase: async (id: string, data: any) => true,
    updateSystemVersion: async (v: string, p: any) => true,
    getJournalEntries: async () => [],
    getCurrentShift: async (uid: string) => null,
    openShift: async (uid: string, a: number) => ({ id: '1', userId: uid, startTime: '', startCash: a, status: 'Open' as const }),
    closeShift: async (id: string, a: number) => ({ id, userId: '', startTime: '', startCash: 0, status: 'Closed' as const }),
    getBackupData: async () => '',
    addNotification: async (n: any) => n,
    bulkUpdateProducts: async (p: any) => true,
    deleteProduct: async (id: string) => true,
    deleteTreasury: async (id: string) => true,
    deleteTransaction: async (id: string) => true,
    deleteWarehouse: async (id: string) => true,
    getShippingCompanies: async () => [],
    saveShippingCompany: async (c: any) => c,
    deleteShippingCompany: async (id: string) => true,
    savePurchaseReturn: async (r: any) => r,
    getPartners: async () => [],
    savePartner: async (p: any) => p,
    getCustomerPurchaseHistory: async (id: string) => [],
    getCustomerReturnsHistory: async (id: string) => [],
    submitFeedback: async (f: any) => true
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, Warehouse, Treasury, PaymentDetail } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import { Search, ShoppingCart, Trash2, Plus, Minus, User, Warehouse as WhIcon, Wallet, Percent, Truck, UserPlus } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';
import SplitPaymentModal from '../components/pos/SplitPaymentModal';
import InstallmentSetupModal from '../components/sales/InstallmentSetupModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();
    const [searchParams] = useSearchParams();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [customerQuery, setCustomerQuery] = useState('');
    const [showCustResults, setShowCustResults] = useState(false);
    const [isNewCustModalOpen, setIsNewCustModalOpen] = useState(false);

    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [shippingCost, setShippingCost] = useState(0);

    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [showSplitModal, setShowSplitModal] = useState(false);
    const [showInstallmentModal, setShowInstallmentModal] = useState(false);

    const editSaleId = searchParams.get('edit');

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t, allSales] = await Promise.all([
                api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries(), api.getSales()
            ]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);

            if (editSaleId) {
                const saleToEdit = allSales.find((s:any) => s.id === editSaleId);
                if (saleToEdit) {
                    setCart(saleToEdit.items);
                    setSelectedCustomerId(saleToEdit.customer.id);
                    setGlobalDiscount(saleToEdit.discount);
                    setGlobalDiscountType(saleToEdit.discountType);
                    setShippingCost(saleToEdit.shipping);
                    setSelectedWhId(saleToEdit.warehouseId);
                    setSelectedTrId(saleToEdit.treasuryId);
                }
            }
        };
        load();
    }, [editSaleId]);

    const subtotal = useMemo(() => cart.reduce((s, i) => {
        const price = i.sellPrice || 0;
        const discount = i.discountPercent ? (price * i.discountPercent / 100) : 0;
        return s + ((price - discount) * i.quantity);
    }, 0), [cart]);

    const discountVal = useMemo(() => globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount, [subtotal, globalDiscount, globalDiscountType]);
    const finalTotal = Math.max(0, subtotal - discountVal + shippingCost);

    const handleCheckout = async (method: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit', payments?: PaymentDetail[], installmentPlan?: any) => {
        if (!cart.length || !selectedWhId || !selectedTrId) {
            addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning');
            return;
        }
        try {
            const res = await api.saveSale({
                id: editSaleId || undefined,
                customer: { id: selectedCustomerId, name: customers.find(c=>c.id===selectedCustomerId)?.name },
                cashier: { id: 'u-1', name: 'المدير' },
                items: cart,
                subtotal, total: finalTotal, amountPaid: method === 'Credit' ? 0 : finalTotal,
                paymentMethod: method, discount: globalDiscount, discountType: globalDiscountType,
                shipping: shippingCost, warehouseId: selectedWhId, treasuryId: selectedTrId,
                payments, installmentPlan, date: editSaleId ? undefined : new Date().toISOString()
            });
            setLastSale(res); setShowReceipt(true); setCart([]); setGlobalDiscount(0); setShippingCost(0);
            addToast('تمت العملية بنجاح', 'success');
        } catch (e) { addToast('فشل إتمام العملية', 'error'); }
    };

    const addToCart = (p: Product) => {
        if (p.stock <= 0) {
            addToast('هذا المنتج غير متوفر حالياً (رصيده صفر)', 'error');
            return;
        }
        setCart(prev => {
            const ex = prev.find(i => i.id === p.id);
            if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
            return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice, discountPercent: 0 }];
        });
        setSearchTerm('');
    };

    const updateItem = (id: string, field: string, value: any) => {
        setCart(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const selectedCustomer = customers.find(c => c.id === selectedCustomerId);

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 flex-shrink-0">
                <div className="lg:col-span-8 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-12 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black outline-none shadow-sm"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                <button key={p.id} onClick={() => addToCart(p)} className="w-full p-3 border-b dark:border-slate-700 flex justify-between hover:bg-indigo-50 font-black text-xs">
                                    <span>{p.name} <span className={`text-[9px] ms-2 ${p.stock > 0 ? 'text-emerald-500' : 'text-rose-500'}`}>(المتاح: {toArabicIndic(p.stock)})</span></span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>
                <div className="lg:col-span-4 flex gap-2">
                    <div className="relative flex-1">
                        <User className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <input type="text" placeholder="بحث عن عميل..." value={showCustResults ? customerQuery : (selectedCustomer?.name || '')} onFocus={() => setShowCustResults(true)} onChange={e => setCustomerQuery(e.target.value)} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black text-xs outline-none"/>
                        {showCustResults && (
                            <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border overflow-hidden">
                                {customers.filter(c => c.name.includes(customerQuery)).map(c => (
                                    <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setShowCustResults(false); }} className="w-full p-2.5 text-start hover:bg-slate-50 border-b last:border-0 font-bold text-xs">{c.name}</button>
                                ))}
                                <button onClick={() => setIsNewCustModalOpen(true)} className="w-full p-2.5 bg-indigo-50 text-indigo-600 text-[10px] font-black flex items-center justify-center gap-2"><UserPlus size={14}/> إضافة عميل</button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 shadow-sm overflow-hidden flex flex-col">
                <div className="bg-slate-50 dark:bg-slate-800/50 px-6 py-2 border-b dark:border-slate-700 grid grid-cols-12 text-[10px] font-black text-slate-400">
                    <div className="col-span-6">المنتج</div>
                    <div className="col-span-2 text-center">الكمية</div>
                    <div className="col-span-2 text-center">خصم %</div>
                    <div className="col-span-2 text-end">الإجمالي</div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2">
                    {cart.map(item => (
                        <div key={item.id} className="grid grid-cols-12 gap-2 items-center p-2.5 bg-slate-50 dark:bg-slate-800/40 rounded-xl border border-slate-100 dark:border-slate-700/50">
                            <div className="col-span-6 flex flex-col">
                                <span className="font-black text-xs truncate">{item.name}</span>
                                <input type="number" value={item.sellPrice} onChange={e => updateItem(item.id, 'sellPrice', parseFloat(e.target.value))} className="w-20 bg-transparent text-[10px] font-bold text-indigo-600 border-none p-0 focus:ring-0" />
                            </div>
                            <div className="col-span-2 flex items-center justify-center gap-2">
                                <button onClick={() => updateItem(item.id, 'quantity', Math.max(1, item.quantity - 1))} className="p-1 text-slate-400 hover:bg-white rounded"><Minus size={10}/></button>
                                <span className="font-black text-xs">{toArabicIndic(item.quantity)}</span>
                                <button onClick={() => updateItem(item.id, 'quantity', item.quantity + 1)} className="p-1 text-indigo-600 hover:bg-white rounded"><Plus size={10}/></button>
                            </div>
                            <div className="col-span-2 flex justify-center">
                                <input type="number" value={item.discountPercent} onChange={e => updateItem(item.id, 'discountPercent', parseFloat(e.target.value))} className="w-10 bg-white dark:bg-slate-700 border rounded text-center text-[10px] font-bold"/>
                            </div>
                            <div className="col-span-2 text-end flex flex-col items-end">
                                <span className="font-black text-xs">{formatAmount((item.sellPrice - (item.sellPrice * (item.discountPercent || 0) / 100)) * item.quantity)}</span>
                                <button onClick={() => setCart(cart.filter(i => i.id !== item.id))} className="text-rose-400 p-1"><Trash2 size={12}/></button>
                            </div>
                        </div>
                    ))}
                    {!cart.length && <div className="h-full flex flex-col items-center justify-center opacity-20"><ShoppingCart size={60}/><p className="font-black mt-2">السلة فارغة</p></div>}
                </div>
            </div>

            <div className="bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 p-3 shadow-xl flex-shrink-0">
                <div className="grid grid-cols-2 md:grid-cols-6 gap-3 items-center">
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black text-slate-400">الخصم الكلي</label>
                        <div className="flex gap-1 h-9">
                            <input type="number" value={globalDiscount || ''} onChange={e => setGlobalDiscount(parseFloat(e.target.value)||0)} className="flex-1 min-w-0 p-1 px-2 border rounded-xl dark:bg-slate-800 font-bold text-xs" />
                            <button onClick={() => setGlobalDiscountType(globalDiscountType === 'amount' ? 'percent' : 'amount')} className="px-2 bg-slate-100 dark:bg-slate-700 rounded-xl font-black text-[9px]">{globalDiscountType === 'amount' ? settings?.currency : '%'}</button>
                        </div>
                    </div>
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black text-slate-400">تكلفة الشحن</label>
                        <input type="number" value={shippingCost || ''} onChange={e => setShippingCost(parseFloat(e.target.value)||0)} className="h-9 p-1 px-2 border rounded-xl dark:bg-slate-800 font-bold text-xs" />
                    </div>
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black text-slate-400">المستودع</label>
                        <select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="h-9 p-1 px-2 border rounded-xl dark:bg-slate-800 font-bold text-xs">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select>
                    </div>
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black text-slate-400">الخزينة</label>
                        <select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="h-9 p-1 px-2 border rounded-xl dark:bg-slate-800 font-bold text-xs">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select>
                    </div>
                    <div className="bg-indigo-600 text-white p-2 rounded-2xl flex flex-col items-center justify-center shadow-lg h-[54px] md:mt-4">
                        <span className="text-[9px] font-black opacity-70 uppercase">الإجمالي النهائي</span>
                        <span className="text-sm font-black">{formatCurrency(finalTotal, settings?.currency)}</span>
                    </div>
                    <div className="grid grid-cols-2 gap-1 md:mt-4">
                        <Button onClick={() => handleCheckout('Cash')} className="bg-emerald-500 h-[54px] rounded-xl text-[10px] font-black">كاش</Button>
                        <Button onClick={() => setShowSplitModal(true)} className="bg-amber-500 h-[54px] rounded-xl text-[10px] font-black">طرق دفع</Button>
                    </div>
                </div>
            </div>

            <ReceiptModal isOpen={showReceipt} onClose={() => setShowReceipt(false)} sale={lastSale} />
            <SplitPaymentModal isOpen={showSplitModal} onClose={() => setShowSplitModal(false)} totalAmount={finalTotal} onConfirm={(p) => { handleCheckout('Split', p); setShowSplitModal(false); }} />
            <InstallmentSetupModal isOpen={showInstallmentModal} onClose={() => setShowInstallmentModal(false)} totalAmount={finalTotal} downPayment={0} defaultInterestRate={0} onSave={(plan) => { handleCheckout('Credit', undefined, plan); setShowInstallmentModal(false); }} />
            <Modal isOpen={isNewCustModalOpen} onClose={() => setIsNewCustModalOpen(false)} title="إضافة عميل"><CustomerForm customer={null} onCancel={() => setIsNewCustModalOpen(false)} isLoading={false} onSave={async (d) => { const newC = await api.saveCustomer(d); setCustomers([...customers, newC]); setSelectedCustomerId(newC.id); setIsNewCustModalOpen(false); addToast('تم الحفظ', 'success'); }} /></Modal>
        </div>
    );
};

