import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import type { Product, Supplier, Treasury, Warehouse } from '../types';
import { api } from '../services/mockApi';
import { useSettings } from '../hooks/useSettings';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { Trash2, Search } from 'lucide-react';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';

const AddPurchasePage: React.FC = () => {
    const { settings } = useSettings();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const { addToast } = useToasts();

    const [products, setProducts] = useState<Product[]>([]);
    const [suppliers, setSuppliers] = useState<Supplier[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [items, setItems] = useState<any[]>([]);
    const [selectedSupId, setSelectedSupId] = useState('');
    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');
    const [discount, setDiscount] = useState(0);
    const [discountType, setDiscountType] = useState<'amount' | 'percent'>('amount');
    const [amountPaid, setAmountPaid] = useState(0);
    const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Card' | 'Transfer' | 'Credit'>('Cash');
    const [searchTerm, setSearchTerm] = useState('');

    const editId = searchParams.get('edit');

    useEffect(() => {
        Promise.all([api.getProducts(), api.getSuppliers(), api.getWarehouses(), api.getTreasuries(), api.getPurchases()]).then(([p, s, w, t, allP]) => {
            setProducts(p); setSuppliers(s); setWarehouses(w); setTreasuries(t);
            if (s.length) setSelectedSupId(s[0].id);
            if (w.length) setSelectedWhId(w.find(i=>i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i=>i.isDefault)?.id || t[0].id);

            if (editId) {
                const pToEdit = allP.find((i:any) => i.id === editId);
                if (pToEdit) {
                    setItems(pToEdit.items);
                    setSelectedSupId(pToEdit.supplier.id);
                    setSelectedWhId(pToEdit.warehouseId);
                    setSelectedTrId(pToEdit.treasuryId);
                    setDiscount(pToEdit.discount);
                    setDiscountType(pToEdit.discountType);
                    setAmountPaid(pToEdit.amountPaid);
                    setPaymentMethod(pToEdit.paymentMethod as any);
                }
            }
        });
    }, [editId]);

    const subtotal = items.reduce((s, i) => s + (i.costPrice * i.quantity), 0);
    const discountVal = discountType === 'percent' ? (subtotal * discount / 100) : discount;
    const finalTotal = Math.max(0, subtotal - discountVal);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!items.length || !selectedWhId || !selectedTrId) { 
            addToast('يرجى اختيار المنتجات وتحديد المستودع والخزينة', 'warning'); return; 
        }
        try {
            await api.savePurchase({
                id: editId || undefined,
                supplier: suppliers.find(s => s.id === selectedSupId),
                items, total: finalTotal, amountPaid: paymentMethod === 'Credit' ? 0 : amountPaid, 
                warehouseId: selectedWhId, treasuryId: selectedTrId, 
                discount, discountType, paymentMethod
            });
            addToast(editId ? 'تم تحديث طلب الشراء' : 'تم حفظ طلب الشراء', 'success');
            navigate('/purchases');
        } catch (e) { addToast('خطأ في الحفظ', 'error'); }
    };

    return (
        <form onSubmit={handleSubmit} className="animate-fadeIn pb-10">
            <div className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-black">{editId ? 'تعديل طلب شراء' : 'إضافة طلب شراء'}</h1>
                <div className="flex gap-2">
                    <Button type="button" variant="secondary" onClick={() => navigate('/purchases')}>تراجع</Button>
                    <Button type="submit">حفظ الطلب</Button>
                </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 space-y-6">
                    <Card title="الأصناف">
                        <div className="relative mb-6">
                            <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" />
                            <input type="text" placeholder="ابحث عن منتج..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-10 border rounded-xl dark:bg-slate-800 font-bold" />
                            {searchTerm && (
                                <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white dark:bg-slate-800 border rounded-xl shadow-xl overflow-hidden max-h-60 overflow-y-auto">
                                    {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                        <button key={p.id} type="button" onClick={() => { 
                                            const ex = items.find(i => i.productId === p.id);
                                            if (ex) setItems(items.map(i => i.productId === p.id ? {...i, quantity: i.quantity + 1} : i));
                                            else setItems([...items, { productId: p.id, name: p.name, quantity: 1, costPrice: p.costPrice }]); 
                                            setSearchTerm(''); 
                                        }} className="w-full p-3 text-start hover:bg-slate-50 border-b last:border-0 font-black text-xs flex justify-between">
                                            <span>{p.name} <span className="text-[10px] text-slate-400 ms-2">(المتوفر حالياً: {toArabicIndic(p.stock)})</span></span>
                                            <span className="text-indigo-600">SKU: {p.sku}</span>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                        <div className="space-y-3">
                            {items.map((item, idx) => (
                                <div key={idx} className="flex items-center gap-4 p-3 border rounded-2xl bg-slate-50 dark:bg-slate-800/50">
                                    <div className="flex-grow font-black text-xs">{item.name}</div>
                                    <input type="number" value={item.quantity} onChange={e => setItems(items.map((it, i) => i === idx ? {...it, quantity: parseFloat(e.target.value)||0} : it))} className="w-16 p-2 border rounded-lg text-center font-bold text-xs" />
                                    <input type="number" value={item.costPrice} onChange={e => setItems(items.map((it, i) => i === idx ? {...it, costPrice: parseFloat(e.target.value)||0} : it))} className="w-24 p-2 border rounded-lg text-center font-bold text-xs" />
                                    <button type="button" onClick={() => setItems(items.filter((_, i) => i !== idx))} className="text-rose-500 p-2"><Trash2 size={16} /></button>
                                </div>
                            ))}
                        </div>
                    </Card>
                </div>
                <div className="space-y-6">
                    <Card title="بيانات الفاتورة">
                        <div className="space-y-4">
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">المورد</label><select value={selectedSupId} onChange={e => setSelectedSupId(e.target.value)} className="w-full p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs">{suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div>
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">طريقة الدفع</label><select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value as any)} className="w-full p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs"><option value="Cash">كاش</option><option value="Card">بطاقة</option><option value="Transfer">تحويل</option><option value="Credit">آجل (دين)</option></select></div>
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">المستودع</label><select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="w-full p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></div>
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">الخزينة</label><select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="w-full p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></div>
                        </div>
                    </Card>
                    <Card className="bg-indigo-600 text-white text-center">
                        <p className="text-[10px] font-black opacity-80 uppercase">المطلوب سداده</p>
                        <p className="text-2xl font-black">{formatCurrency(finalTotal, settings?.currency)}</p>
                        {paymentMethod !== 'Credit' && (
                            <div className="mt-4 pt-4 border-t border-white/20">
                                <label className="text-[10px] font-black opacity-70 block mb-2">المبلغ المدفوع</label>
                                <input type="number" value={amountPaid} onChange={e => setAmountPaid(parseFloat(e.target.value)||0)} className="w-full p-2 bg-white/10 rounded-xl text-center font-black border-none text-lg" />
                            </div>
                        )}
                    </Card>
                </div>
            </div>
        </form>
    );
};

