                userName: u.name,
                totalSalesValue: totalValue,
                totalSalesCount: userSales.length,
                averageSaleValue: userSales.length ? totalValue / userSales.length : 0,
                totalReturnsValue: 0,
                returnRate: 0
            };
        });
        return { performanceData, topPerformerByValue: [...performanceData].sort((a,b) => b.totalSalesValue - a.totalSalesValue)[0] };
    },
