} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5 }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' } },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        return stored ? JSON.parse(stored) : defaultDb;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logTransaction = (db: any, type: 'income' | 'expense', amount: number, description: string, treasuryId: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: type === 'income' ? 'مبيعات/تحصيل' : 'مشتريات/مصاريف',
            user: 'النظام',
            treasuryId
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) db.products = db.products.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `prod-${Date.now()}`; db.products.push(p); }
        saveDb(db); return p;
    },
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => {
            const index = db.products.findIndex((item: any) => item.id === p.id);
            if (index !== -1) db.products[index] = p;
        });
        saveDb(db);
        return products;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString() };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `دفعة من فاتورة مبيعات #${id}`, sale.treasuryId);
        }

        if (sale.installmentPlan) {
            db.installments.unshift({ ...sale.installmentPlan, id: `inst-${Date.now()}`, saleId: id, customerName: sale.customer.name, status: 'Active' });
        }

        const customer = db.customers.find((c: any) => c.id === sale.customer.id);
        if (customer) {
            const creditAmount = sale.total - sale.amountPaid;
            if (creditAmount > 0) customer.debt = (customer.debt || 0) + creditAmount;
            if (db.settings.loyaltySettings.enabled) {
                if (sale.pointsRedeemed) customer.points -= sale.pointsRedeemed;
                customer.points = (customer.points || 0) + (sale.total * db.settings.loyaltySettings.earningRate);
            }
        }
        saveDb(db); return finalSale;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
        else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); }
        saveDb(db); return c;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = pur.id || `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        if (pur.amountPaid > 0) {
            logTransaction(db, 'expense', pur.amountPaid, `دفعة لطلب شراء #${pur.id}`, pur.treasuryId);
        }
        saveDb(db); return pur;
    },
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `sr-${Date.now()}`;
        ret.date = new Date().toISOString();
        db.salesReturns.unshift(ret);
        logTransaction(db, 'expense', ret.totalRefund, `رد مبلغ لمرتجع مبيعات #${ret.originalSaleId}`, ret.treasuryId);
        saveDb(db); return ret;
    },
    deleteSalesReturn: async (id: string) => {
        const db = getDb();
        const ret = db.salesReturns.find((r: any) => r.id === id);
        if (ret) {
            ret.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.id);
                if (p) {
                    p.warehouseStocks[ret.warehouseId] -= item.returnQuantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
                }
            });
            logTransaction(db, 'income', ret.totalRefund, `تراجع عن مرتجع مبيعات #${ret.id}`, ret.treasuryId);
            db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id);
            saveDb(db); return true;
        }
        return false;
    },
    getUsers: async () => getDb().users,
    saveUser: async (u: any) => {
        const db = getDb();
        if (u.id) {
            db.users = db.users.map((item: any) => {
                if (item.id === u.id) {
                    const updated = { ...item, ...u };
                    if (!u.password) updated.password = item.password;
                    return updated;
                }
                return item;
            });
        } else {
            u.id = `u-${Date.now()}`;
            u.password = u.password || 'password';
            db.users.push(u);
        }
        saveDb(db); return u;
    },
    login: async (name: string, password: string) => {
        const db = getDb();
        return db.users.find((u: any) => u.name === name && u.password === password) || null;
    },
    verifyPassword: async (userId: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.id === userId);
        return user?.password === password;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string) => {
        const db = getDb();
        const sales = db.sales.filter(s => (!start || s.date >= start) && (!end || s.date <= end));
        const purchases = db.purchases.filter(p => (!start || p.date >= start) && (!end || p.date <= end));
        const expenses = db.transactions.filter(t => t.type === 'expense' && (!start || t.date >= start) && (!end || t.date <= end));
        const returns = db.salesReturns.filter(r => (!start || r.date >= start) && (!end || r.date <= end));

        const totalRevenue = sales.reduce((a, b) => a + b.total, 0) - returns.reduce((a, b) => a + b.totalRefund, 0);

        let totalCOGS = 0;
        sales.forEach(s => {
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                totalCOGS += (prod?.costPrice || 0) * item.quantity;
            });
        });

        const totalPurchases = purchases.reduce((a, b) => a + b.total, 0);
        const otherExpenses = expenses.filter(e => !e.description.includes('مرتجع')).reduce((a, b) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - otherExpenses;

        return { totalRevenue, totalCOGS, totalExpenses: otherExpenses, totalPurchases, totalReturns: returns.length, netProfit, dailyStats: [] };
    },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const performanceData = db.users.map((u: any) => {
            const userSales = db.sales.filter(s => s.cashier.id === u.id);
            const totalValue = userSales.reduce((a, b) => a + b.total, 0);
            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue: totalValue,
                totalSalesCount: userSales.length,
                averageSaleValue: userSales.length ? totalValue / userSales.length : 0,
                totalReturnsValue: 0,
                returnRate: 0
            };
        });
        return { performanceData, topPerformerByValue: [...performanceData].sort((a,b) => b.totalSalesValue - a.totalSalesValue)[0] };
    },
