import React, { useState, useEffect } from 'react';
import { useLicense } from '../hooks/useLicense';
import { useDevMode } from '../hooks/useDevMode';
import Button from '../components/ui/Button';
import { Key, Rocket, ShieldAlert, Copy, Smartphone, Ban, Gift, ShieldCheck, AlertCircle } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from '../hooks/useTranslation';
import { secureStorage } from '../utils/secureStorage';
import Modal from '../components/ui/Modal';
import { useToasts } from '../hooks/useToasts';
import ConfirmDialog from '../components/ui/ConfirmDialog';
import { api } from '../services/mockApi';

const LicensePage: React.FC = () => {
  const [licenseKey, setLicenseKey] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const { activateLicense, startTrial, activateFreePlan, licenseInfo, deviceId } = useLicense();
  const { enableDevMode } = useDevMode();
  const { t } = useTranslation();
  const [trialUsed, setTrialUsed] = useState(false);
  const { addToast } = useToasts();
  const navigate = useNavigate();

  const [showGiftModal, setShowGiftModal] = useState(false);
  const [showFreeConfirm, setShowFreeConfirm] = useState(false);

  useEffect(() => {
      const isUsed = secureStorage.getItem<boolean>('pos_trial_used_flag_v2');
      if (isUsed) {
          setTrialUsed(true);
      }
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    setTimeout(async () => {
        if (enableDevMode(licenseKey)) return;

        const result = await activateLicense(licenseKey);
        if (result.success) {
             if (result.type === 'Yearly') {
                 setIsLoading(false);
                 setShowGiftModal(true);
             } 
        } else {
             setError('كود الترخيص غير صالح. يرجى التأكد من كتابة الأرقام بشكل صحيح.');
             setIsLoading(false);
        }
    }, 1000);
  };

  const handleStartTrial = () => {
    setIsLoading(true);
    setError('');
    setTimeout(async () => {
        const success = await startTrial();
        if (!success) {
            setTrialUsed(true);
            setError('عذراً، لقد استنفذت فرصتك في التجربة المجانية سابقاً.');
        }
        setIsLoading(false);
    }, 500);
  };

  const handleActivateFree = async () => {
      setIsLoading(true);
      setShowFreeConfirm(false);
      try {
          // 1. مسح البيانات أولاً لتهيئة النظام
          await api.wipeBusinessData();
          // 2. ثم تفعيل الخطة (هذا سيؤدي لتغيير الحالة وتوجيه التطبيق تلقائياً)
          await activateFreePlan();
          addToast('تم تفعيل الخطة المجانية بنجاح.', 'success');
          // لا حاجة لعمل reload يدوي هنا لأن AppRoutes سيتكفل بالتحويل
      } catch (e) {
          addToast('فشل تفعيل الخطة المجانية.', 'error');
          setIsLoading(false);
      }
  };

  const copyDeviceId = () => {
      if (!deviceId) {
          addToast('جاري استخراج معرف الجهاز...', 'info');
          return;
      }
      navigator.clipboard.writeText(deviceId);
      addToast('تم نسخ معرف الجهاز بنجاح!', 'success');
  };

  const getMessage = () => {
    switch(licenseInfo.status) {
        case 'EXPIRED':
            return { title: "انتهت الفترة التجريبية", text: "تم انتهاء مدة الـ 3 أيام التجريبية. يرجى إدخال كود تفعيل رقمي للاستمرار.", icon: <ShieldAlert className="text-red-500 dark:text-red-400" size={24}/> };
        case 'INVALID_DEVICE':
            return { title: "جهاز غير صالح", text: "هذا الترخيص مرتبط بجهاز آخر.", icon: <ShieldAlert className="text-red-500 dark:text-red-400" size={24}/> };
        case 'TAMPERED':
            return { title: t('security.tampering_detected_title'), text: t('security.tampering_detected_text'), icon: <ShieldAlert className="text-red-500 dark:text-red-400" size={24}/> };
        default:
            return { title: "مرحبًا بك في تكنو باور", text: "نظام نقاط البيع وإدارة المخزون المتكامل" };
    }
