                    </Tooltip>

                    <Button onClick={() => handleOpenModal()} className="h-12 rounded-2xl px-6 bg-indigo-600 font-black shadow-lg shadow-indigo-500/20 gap-2">
                        <PlusCircle size={20} /> إضافة منتج
