import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Product, Warehouse } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import { ClipboardList, Warehouse as WhIcon, Search, Printer, Download, DollarSign } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { exportToCsv } from '../utils/export';
import { useToasts } from '../hooks/useToasts';
import TableSkeleton from '../components/ui/TableSkeleton';

const InventoryAuditPage: React.FC = () => {
    const [products, setProducts] = useState<Product[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [selectedWhId, setSelectedWhId] = useState<string>('');
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');

    const { settings } = useSettings();
    const { addToast } = useToasts();

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [pData, wData] = await Promise.all([api.getProducts(), api.getWarehouses()]);
            setProducts(pData);
            setWarehouses(wData);
            if (wData.length > 0 && !selectedWhId) setSelectedWhId(wData[0].id);
        } catch (e) {
            addToast("خطأ في تحميل البيانات", "error");
        } finally {
            setLoading(false);
        }
    }, [addToast, selectedWhId]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const auditData = useMemo(() => {
        return products.filter(p => {
            const inWh = p.warehouseStocks?.[selectedWhId] || 0;
            const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                 p.sku.toLowerCase().includes(searchTerm.toLowerCase());
            return inWh > 0 && matchesSearch;
        });
    }, [products, selectedWhId, searchTerm]);

    const totalValue = useMemo(() => {
        return auditData.reduce((sum, p) => sum + ((p.warehouseStocks?.[selectedWhId] || 0) * p.costPrice), 0);
    }, [auditData, selectedWhId]);

    const handleExport = () => {
        const whName = warehouses.find(w => w.id === selectedWhId)?.name || 'مخزن';
        const data = auditData.map(p => ({
            "الباركود": p.sku,
            "المنتج": p.name,
            "الفئة": p.category,
            "الكمية المتاحة": p.warehouseStocks?.[selectedWhId] || 0,
            "سعر التكلفة": p.costPrice,
            "إجمالي القيمة": (p.warehouseStocks?.[selectedWhId] || 0) * p.costPrice
        }));
        exportToCsv(`audit-${whName}-${new Date().toISOString().split('T')[0]}.csv`, data);
        addToast("تم تصدير التقرير بنجاح", "success");
    };

    return (
        <div className="animate-fadeIn pb-10">
            <div className="flex flex-col md:flex-row justify-between items-start gap-4 mb-8">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white tracking-tight flex items-center gap-3">
                        <ClipboardList className="text-indigo-600" /> جرد المخزون التفصيلي
                    </h1>
                    <p className="text-slate-500 font-medium mt-1">تقرير شامل بحالة المنتجات والكميات والقيم في كل مستودع</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => window.print()} className="h-12 px-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl font-bold flex items-center gap-2 hover:bg-slate-50 shadow-sm">
                        <Printer size={18} /> طباعة
                    </button>
                    <button onClick={handleExport} className="h-12 px-6 bg-indigo-600 text-white rounded-2xl font-black flex items-center gap-2 shadow-lg shadow-indigo-500/20">
                        <Download size={18} /> تصدير التقرير
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-8">
                <Card className="lg:col-span-1 p-6">
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">المستودع المستهدف</label>
                    <select 
                        value={selectedWhId} 
                        onChange={e => setSelectedWhId(e.target.value)}
                        className="w-full p-3 bg-white dark:bg-slate-800 border rounded-2xl font-black outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                        {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                    </select>

                    <div className="mt-8 pt-6 border-t dark:border-slate-800">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">إجمالي قيمة المخزون الحالي</p>
                        <p className="text-3xl font-black text-emerald-600">{formatCurrency(totalValue, settings?.currency || 'SAR')}</p>
                        <p className="text-[10px] text-slate-400 mt-1 font-bold">بناءً على سعر التكلفة لـ {toArabicIndic(auditData.length)} منتج</p>
                    </div>
                </Card>

                <div className="lg:col-span-3">
                    <Card className="p-0 overflow-hidden shadow-premium border-none">
                        <div className="p-4 border-b dark:border-slate-800 bg-slate-50/50 flex items-center gap-4">
                            <div className="relative flex-grow">
                                <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={18} />
                                <input 
                                    type="text" 
                                    placeholder="بحث سريع في نتائج الجرد..." 
                                    value={searchTerm}
                                    onChange={e => setSearchTerm(e.target.value)}
                                    className="w-full p-2.5 ps-10 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 font-bold text-xs"
                                />
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-start">
                                <thead className="bg-slate-50 dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400">
                                    <tr>
                                        <th className="px-6 py-4">المنتج والباركود</th>
                                        <th className="px-6 py-4 text-center">الكمية</th>
                                        <th className="px-6 py-4 text-center">التكلفة</th>
                                        <th className="px-6 py-4 text-end">إجمالي القيمة</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y dark:divide-slate-800">
                                    {loading ? <tr><td colSpan={4}><TableSkeleton cols={4} /></td></tr> : auditData.map(p => {
                                        const qty = p.warehouseStocks?.[selectedWhId] || 0;
                                        return (
                                            <tr key={p.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                                                <td className="px-6 py-4">
                                                    <p className="font-black text-slate-800 dark:text-slate-200">{p.name}</p>
                                                    <p className="text-[10px] font-mono text-slate-400 uppercase">{p.sku}</p>
                                                </td>
                                                <td className="px-6 py-4 text-center font-black">
                                                    <span className="px-3 py-1 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 rounded-lg">{toArabicIndic(qty)}</span>
                                                </td>
                                                <td className="px-6 py-4 text-center font-bold text-slate-500">
                                                    {formatCurrency(p.costPrice, settings?.currency || 'SAR')}
                                                </td>
                                                <td className="px-6 py-4 text-end font-black text-slate-800 dark:text-white">
                                                    {formatCurrency(qty * p.costPrice, settings?.currency || 'SAR')}
                                                </td>
                                            </tr>
                                        )
                                    })}
                                </tbody>
                            </table>
                            {!loading && auditData.length === 0 && (
                                <div className="p-20 text-center text-slate-400 font-bold">لا يوجد بيانات لعرضها في هذا المخزن</div>
                            )}
                        </div>
                    </Card>
                </div>
            </div>
        </div>
    );
};

export default InventoryAuditPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, Warehouse, Treasury, PaymentDetail } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import { Search, ShoppingCart, Trash2, Plus, Minus, User, Warehouse as WhIcon, Wallet, Percent, Truck, UserPlus, Gift, CreditCard, DollarSign } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';
import SplitPaymentModal from '../components/pos/SplitPaymentModal';
import InstallmentSetupModal from '../components/sales/InstallmentSetupModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();
    const [searchParams] = useSearchParams();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [customerQuery, setCustomerQuery] = useState('');
    const [showCustResults, setShowCustResults] = useState(false);
    const [isNewCustModalOpen, setIsNewCustModalOpen] = useState(false);

    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [shippingCost, setShippingCost] = useState(0);
    const [pointsToRedeem, setPointsToRedeem] = useState(0);

    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [showSplitModal, setShowSplitModal] = useState(false);
    const [showInstallmentModal, setShowInstallmentModal] = useState(false);
    const [pendingSplitPayments, setPendingSplitPayments] = useState<PaymentDetail[] | null>(null);

    const editSaleId = searchParams.get('edit');

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t, allSales] = await Promise.all([
                api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries(), api.getSales()
            ]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
            if (editSaleId) {
                const saleToEdit = allSales.find((s:any) => s.id === editSaleId);
                if (saleToEdit) { 
                    setCart(saleToEdit.items); 
                    setSelectedCustomerId(saleToEdit.customer.id); 
                    setGlobalDiscount(saleToEdit.discount); 
                    setGlobalDiscountType(saleToEdit.discountType); 
                    setShippingCost(saleToEdit.shipping); 
                    setSelectedWhId(saleToEdit.warehouseId); 
                    setSelectedTrId(saleToEdit.treasuryId); 
                }
            }
        };
        load();
    }, [editSaleId]);

    const selectedCustomer = useMemo(() => customers.find(c => c.id === selectedCustomerId), [customers, selectedCustomerId]);

    const pointsDiscount = useMemo(() => {
        if (!settings?.loyaltySettings.enabled || !selectedCustomer) return 0;
        return Math.min(pointsToRedeem * settings.loyaltySettings.redemptionRate, selectedCustomer.points * settings.loyaltySettings.redemptionRate);
    }, [pointsToRedeem, selectedCustomer, settings]);

    const subtotalRaw = useMemo(() => cart.reduce((s, i) => s + ((i.sellPrice || 0) * i.quantity), 0), [cart]);

    const subtotal = useMemo(() => cart.reduce((s, i) => {
        const price = i.sellPrice || 0;
        const discount = i.discountPercent ? (price * i.discountPercent / 100) : 0;
        return s + ((price - discount) * i.quantity);
    }, 0), [cart]);

    const discountVal = useMemo(() => globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount, [subtotal, globalDiscount, globalDiscountType]);
    const finalTotal = Math.max(0, subtotal - discountVal - pointsDiscount + shippingCost);

    const handleCheckout = async (method: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit', payments?: PaymentDetail[], plan?: any) => {
        if (!cart.length || !selectedWhId || !selectedTrId) { addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning'); return; }

        const hasCredit = method === 'Credit' || (payments && payments.some(p => p.method === 'Credit'));
        if (hasCredit && !plan) {
            setPendingSplitPayments(payments || null);
            setShowInstallmentModal(true);
            return;
        }

        try {
            const amountPaid = method === 'Split' ? (payments?.filter(p => p.method !== 'Credit').reduce((a, b) => a + b.amount, 0) || 0) : (method === 'Credit' ? 0 : finalTotal);
            const res = await api.saveSale({
                id: editSaleId || undefined,
                customer: { id: selectedCustomerId, name: selectedCustomer?.name },
                cashier: { id: 'u-1', name: 'المدير' },
                items: cart,
                subtotal, total: finalTotal, amountPaid,
                paymentMethod: method, discount: globalDiscount, discountType: globalDiscountType,
                shipping: shippingCost, warehouseId: selectedWhId, treasuryId: selectedTrId,
                payments: payments || (method !== 'Split' ? [{ method: method as any, amount: finalTotal }] : []),
                installmentPlan: plan, pointsRedeemed: pointsToRedeem
            });
            setLastSale(res); setShowReceipt(true); setCart([]); setGlobalDiscount(0); setShippingCost(0); setPointsToRedeem(0); setPendingSplitPayments(null);
            addToast('تمت العملية بنجاح', 'success');
        } catch (e) { addToast('فشل إتمام العملية', 'error'); }
    };

    const addToCart = (p: Product) => {
        const stockInWh = p.warehouseStocks?.[selectedWhId] || 0;
        if (stockInWh <= 0) { addToast('المنتج غير متوفر في المستودع المحدد', 'error'); return; }
        setCart(prev => {
            const ex = prev.find(i => i.id === p.id);
            if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
            return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice, discountPercent: 0 }];
        });
        setSearchTerm('');
    };

    const filteredSearchResults = useMemo(() => {
        if (!searchTerm.trim()) return [];
        return products.filter(p => {
            const matchesQuery = p.name.includes(searchTerm) || p.sku.includes(searchTerm);
            const hasStockInWh = (p.warehouseStocks?.[selectedWhId] || 0) > 0;
            return matchesQuery && hasStockInWh;
        });
    }, [searchTerm, products, selectedWhId]);

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 flex-shrink-0">
                <div className="lg:col-span-3">
                    <div className="relative">
                        <WhIcon className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <select value={selectedWhId} onChange={e => { setSelectedWhId(e.target.value); setCart([]); }} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black text-xs outline-none">
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                        </select>
                    </div>
                </div>
                <div className="lg:col-span-5 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج في المخزن المحدد..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-12 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black outline-none shadow-sm"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {filteredSearchResults.map(p => (
                                <button key={p.id} onClick={() => addToCart(p)} className="w-full p-3 border-b dark:border-slate-700 flex justify-between hover:bg-indigo-50 font-black text-xs">
                                    <span>{p.name} <span className="text-emerald-500 ms-2">({toArabicIndic(p.warehouseStocks?.[selectedWhId] || 0)})</span></span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                            {filteredSearchResults.length === 0 && <p className="p-4 text-center text-xs text-slate-400 font-bold">لا توجد نتائج في هذا المخزن</p>}
                        </div>
                    )}
                </div>
                <div className="lg:col-span-4 flex gap-2">
                    <div className="relative flex-1">
                        <User className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <input type="text" placeholder="بحث عن عميل..." value={showCustResults ? customerQuery : (selectedCustomer?.name || '')} onFocus={() => setShowCustResults(true)} onChange={e => setCustomerQuery(e.target.value)} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black text-xs outline-none"/>
                        {showCustResults && (
                            <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border overflow-hidden">
                                {customers.filter(c => c.name.includes(customerQuery)).map(c => (
                                    <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setShowCustResults(false); }} className="w-full p-2.5 text-start hover:bg-slate-50 border-b last:border-0 font-bold text-xs">{c.name}</button>
                                ))}
                                <button onClick={() => setIsNewCustModalOpen(true)} className="w-full p-2.5 bg-indigo-50 text-indigo-600 text-[10px] font-black flex items-center justify-center gap-2"><UserPlus size={14}/> إضافة عميل</button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 shadow-sm overflow-hidden flex flex-col">
                <div className="bg-slate-50 dark:bg-slate-800/50 px-6 py-2 border-b dark:border-slate-700 grid grid-cols-12 text-[10px] font-black text-slate-400 uppercase">
                    <div className="col-span-5">المنتج</div>
                    <div className="col-span-2 text-center">السعر</div>
                    <div className="col-span-1 text-center">الكمية</div>
                    <div className="col-span-2 text-center">خصم %</div>
                    <div className="col-span-2 text-end">الإجمالي</div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2">
                    {cart.map(item => (
                        <div key={item.id} className="grid grid-cols-12 gap-2 items-center p-2.5 bg-slate-50 dark:bg-slate-800/40 rounded-xl border border-slate-100 dark:border-slate-700/50">
                            <div className="col-span-5 flex flex-col">
                                <span className="font-black text-xs truncate">{item.name}</span>
                                <span className="text-[10px] text-slate-400">SKU: {products.find(p=>p.id===item.id)?.sku}</span>
                            </div>
                            <div className="col-span-2">
                                <input type="number" step="0.01" value={item.sellPrice} onChange={e => setCart(prev => prev.map(i => i.id === item.id ? {...i, sellPrice: parseFloat(e.target.value)||0} : i))} className="w-full p-1.5 border rounded-lg text-center font-black text-xs text-indigo-600"/>
                            </div>
                            <div className="col-span-1 flex items-center justify-center gap-2">
                                <button onClick={() => setCart(prev => prev.map(i => i.id === item.id ? {...i, quantity: Math.max(1, i.quantity - 1)} : i))} className="p-1 text-slate-400 hover:bg-white rounded"><Minus size={10}/></button>
                                <span className="font-black text-xs">{toArabicIndic(item.quantity)}</span>
                                <button onClick={() => setCart(prev => prev.map(i => i.id === item.id ? {...i, quantity: i.quantity + 1} : i))} className="p-1 text-indigo-600 hover:bg-white rounded"><Plus size={10}/></button>
                            </div>
                            <div className="col-span-2 flex justify-center">
                                <input type="number" value={item.discountPercent} onChange={e => setCart(prev => prev.map(i => i.id === item.id ? {...i, discountPercent: parseFloat(e.target.value)||0} : i))} className="w-12 bg-white dark:bg-slate-700 border rounded-lg text-center text-[10px] font-bold py-1.5"/>
                            </div>
                            <div className="col-span-2 text-end flex flex-col items-end">
                                <span className="font-black text-xs">{formatAmount((item.sellPrice - (item.sellPrice * (item.discountPercent || 0) / 100)) * item.quantity)}</span>
                                <button onClick={() => setCart(cart.filter(i => i.id !== item.id))} className="text-rose-400 p-1 mt-1"><Trash2 size={12}/></button>
                            </div>
                        </div>
                    ))}
                    {!cart.length && <div className="h-full flex flex-col items-center justify-center opacity-20"><ShoppingCart size={60}/><p className="font-black mt-2">السلة فارغة</p></div>}
                </div>
            </div>

            <div className="bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 p-4 shadow-xl flex-shrink-0">
                <div className="grid grid-cols-2 md:grid-cols-8 gap-3 items-end">
                    <div className="flex flex-col gap-1 col-span-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase">الخزينة</label>
                        <select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="h-10 p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select>
                    </div>
                    <div className="flex flex-col gap-1 col-span-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase">الخصم</label>
                        <div className="flex gap-1 h-10">
                            <input type="number" value={globalDiscount || ''} onChange={e => setGlobalDiscount(parseFloat(e.target.value)||0)} className="w-full p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs" />
                            <button onClick={() => setGlobalDiscountType(globalDiscountType === 'amount' ? 'percent' : 'amount')} className="px-2 bg-slate-100 dark:bg-slate-700 rounded-xl font-black text-[9px]">{globalDiscountType === 'amount' ? settings?.currency : '%'}</button>
                        </div>
                    </div>
                    <div className="flex flex-col gap-1 col-span-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase">النقاط ({toArabicIndic(selectedCustomer?.points || 0)})</label>
                        <div className="relative">
                            <input type="number" value={pointsToRedeem || ''} onChange={e => setPointsToRedeem(parseFloat(e.target.value)||0)} className="w-full h-10 p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs" placeholder="استبدال..." />
                        </div>
                    </div>
                    <div className="flex flex-col gap-1 col-span-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase">الشحن</label>
                        <input type="number" value={shippingCost || ''} onChange={e => setShippingCost(parseFloat(e.target.value)||0)} className="h-10 p-2 border rounded-xl dark:bg-slate-800 font-bold text-xs" />
                    </div>

                    <div className="bg-slate-50 dark:bg-slate-800 p-2 rounded-xl flex flex-col items-center justify-center h-14 col-span-1">
                        <span className="text-[8px] font-black text-slate-400 uppercase">قبل الخصم</span>
                        <span className="text-xs font-bold text-slate-600 dark:text-slate-300">{formatAmount(subtotalRaw)}</span>
                    </div>

                    <div className="bg-indigo-600 text-white p-2 rounded-2xl flex flex-col items-center justify-center shadow-lg h-14 col-span-1">
                        <span className="text-[8px] font-black opacity-70 uppercase">الصافي</span>
                        <span className="text-sm font-black">{formatCurrency(finalTotal, settings?.currency)}</span>
                    </div>

                    <div className="flex gap-2 col-span-2">
                        <Button onClick={() => handleCheckout('Cash')} className="bg-emerald-500 h-14 flex-1 rounded-xl text-xs font-black shadow-lg">كاش</Button>
                        <Button onClick={() => setShowSplitModal(true)} className="bg-amber-500 h-14 flex-1 rounded-xl text-xs font-black shadow-lg"><CreditCard size={16}/></Button>
                    </div>
                </div>
            </div>

            <ReceiptModal isOpen={showReceipt} onClose={() => setShowReceipt(false)} sale={lastSale} />
            <SplitPaymentModal isOpen={showSplitModal} onClose={() => setShowSplitModal(false)} totalAmount={finalTotal} onConfirm={(p) => { handleCheckout('Split', p); setShowSplitModal(false); }} />
            <InstallmentSetupModal 
                isOpen={showInstallmentModal} 
                onClose={() => setShowInstallmentModal(false)} 
                totalAmount={finalTotal} 
                downPayment={pendingSplitPayments ? pendingSplitPayments.filter(p => p.method !== 'Credit').reduce((a,b) => a + b.amount, 0) : 0} 
                defaultInterestRate={0} 
                onSave={(plan) => { handleCheckout('Split', pendingSplitPayments || undefined, plan); setShowInstallmentModal(false); }} 
            />
            <Modal isOpen={isNewCustModalOpen} onClose={() => setIsNewCustModalOpen(false)} title="إضافة عميل"><CustomerForm customer={null} onCancel={() => setIsNewCustModalOpen(false)} isLoading={false} onSave={async (d) => { const newC = await api.saveCustomer(d); setCustomers([...customers, newC]); setSelectedCustomerId(newC.id); setIsNewCustModalOpen(false); addToast('تم الحفظ', 'success'); }} /></Modal>
        </div>
    );
};

