};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({
        id: `act-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    });
};

const logTransaction = (db: any, type: 'income' | 'expense', amount: number, description: string, treasuryId: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: type === 'income' ? 'مبيعات/تحصيل' : 'مشتريات/مصاريف',
            user: 'النظام',
            treasuryId
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? p : item);
            logActivity(db, 'تعديل منتج', `تم تعديل بيانات المنتج: ${p.name}`);
        }
        else { 
            p.id = `prod-${Date.now()}`; 
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `تم إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => {
            const index = db.products.findIndex((item: any) => item.id === p.id);
            if (index !== -1) db.products[index] = p;
        });
        saveDb(db);
        return products;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString() };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `دفعة من فاتورة مبيعات #${id}`, sale.treasuryId);
        }

        if (sale.installmentPlan) {
            db.installments.unshift({ ...sale.installmentPlan, id: `inst-${Date.now()}`, saleId: id, customerName: sale.customer.name, status: 'Active' });
        }

        logActivity(db, 'فاتورة مبيعات', `إنشاء فاتورة مبيعات #${id} بقيمة ${sale.total}`);

        const customer = db.customers.find((c: any) => c.id === sale.customer.id);
        if (customer) {
            const creditAmount = sale.total - sale.amountPaid;
            if (creditAmount > 0) customer.debt = (customer.debt || 0) + creditAmount;
            if (db.settings.loyaltySettings.enabled) {
                if (sale.pointsRedeemed) customer.points -= sale.pointsRedeemed;
                customer.points = (customer.points || 0) + (sale.total * db.settings.loyaltySettings.earningRate);
            }
        }
        saveDb(db); return finalSale;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) db.customers = db.customers.map((item: any) => item.id === c.id ? c : item);
        else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); }
        saveDb(db); return c;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = pur.id || `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        if (pur.amountPaid > 0) {
            logTransaction(db, 'expense', pur.amountPaid, `دفعة لطلب شراء #${pur.id}`, pur.treasuryId);
        }
        logActivity(db, 'طلب شراء', `تسجيل طلب شراء #${pur.id} من المورد ${pur.supplier?.name}`);
        saveDb(db); return pur;
    },
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        ret.id = `sr-${Date.now()}`;
        ret.date = new Date().toISOString();
        db.salesReturns.unshift(ret);
        logTransaction(db, 'expense', ret.totalRefund, `رد مبلغ لمرتجع مبيعات #${ret.originalSaleId}`, ret.treasuryId);
        logActivity(db, 'مرتجع مبيعات', `إصدار مرتجع للفاتورة #${ret.originalSaleId}`);
        saveDb(db); return ret;
    },
    deleteSalesReturn: async (id: string) => {
        const db = getDb();
        const ret = db.salesReturns.find((r: any) => r.id === id);
        if (ret) {
            ret.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.id);
                if (p) {
                    p.warehouseStocks[ret.warehouseId] -= item.returnQuantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
                }
            });
            logTransaction(db, 'income', ret.totalRefund, `تراجع عن مرتجع مبيعات #${ret.id}`, ret.treasuryId);
            db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id);
            logActivity(db, 'حذف مرتجع', `تم التراجع عن سجل المرتجع #${id}`);
            saveDb(db); return true;
        }
        return false;
    },
    getUsers: async () => getDb().users,
    saveUser: async (u: any) => {
        const db = getDb();
        if (u.id) {
            db.users = db.users.map((item: any) => {
                if (item.id === u.id) {
                    const updated = { ...item, ...u };
                    if (!u.password) updated.password = item.password;
                    return updated;
                }
                return item;
            });
        } else {
            u.id = `u-${Date.now()}`;
            u.password = u.password || 'password';
            db.users.push(u);
        }
        saveDb(db); return u;
    },
    login: async (name: string, password: string) => {
        const db = getDb();
        return db.users.find((u: any) => u.name === name && u.password === password) || null;
    },
    verifyPassword: async (userId: string, password: string) => {
        const db = getDb();
        const user = db.users.find((u: any) => u.id === userId);
        return user?.password === password;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const purchases = db.purchases.filter((p:any) => (!start || p.date >= start) && (!end || p.date <= end));
        const expenses = (db.transactions || []).filter((t:any) => t.type === 'expense' && (!start || t.date >= start) && (!end || t.date <= end));
        const returns = (db.salesReturns || []).filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        const totalRevenue = sales.reduce((a:any, b:any) => a + b.total, 0) - returns.reduce((a:any, b:any) => a + b.totalRefund, 0);

        let totalCOGS = 0;
        sales.forEach((s:any) => {
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                totalCOGS += (prod?.costPrice || 0) * item.quantity;
            });
        });

        const totalPurchases = purchases.reduce((a:any, b:any) => a + b.total, 0);
        const otherExpenses = expenses.filter((e:any) => !e.description.includes('مرتجع')).reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - otherExpenses;

        return { totalRevenue, totalCOGS, totalExpenses: otherExpenses, totalPurchases, totalReturns: returns.length, netProfit, dailyStats: [] };
    },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const performanceData = db.users.map((u: any) => {
            const userSales = db.sales.filter((s:any) => s.cashier.id === u.id);
            const totalValue = userSales.reduce((a:any, b:any) => a + b.total, 0);
            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue: totalValue,
                totalSalesCount: userSales.length,
                averageSaleValue: userSales.length ? totalValue / userSales.length : 0,
                totalReturnsValue: 0,
                returnRate: 0
            };
        });
        return { performanceData, topPerformerByValue: [...performanceData].sort((a,b) => b.totalSalesValue - a.totalSalesValue)[0] };
    },
    getSales: async () => getDb().sales,
    getSalesReturns: async () => getDb().salesReturns,
    getPurchases: async () => getDb().purchases,
    getTransactions: async () => getDb().transactions,
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getInstallmentPlans: async () => getDb().installments || [],
    getCurrentShift: async (uid: string) => getDb().shifts.find((s:any) => s.userId === uid && s.status === 'Open') || null,
    openShift: async (uid: string, a: number) => { const db = getDb(); const s = { id: `sh-${Date.now()}`, userId: uid, startTime: new Date().toISOString(), startCash: a, status: 'Open' }; db.shifts.push(s); saveDb(db); return s; },
    closeShift: async (id: string, a: number, n?: string) => { 
        const db = getDb(); 
        const s = db.shifts.find((i:any)=>i.id===id); 
        if(s){
            s.status='Closed'; 
            s.endTime=new Date().toISOString(); 
            s.endCash=a;
            s.notes=n;
        } 
        saveDb(db); 
        return s; 
    },
    getJournalEntries: async () => [],
    recordInstallmentPayment: async (id: string) => {
        const db = getDb();
        let planFound = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === id);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                logTransaction(db, 'income', payment.amount, `تحصيل قسط من ${plan.customerName}`, 't-1');
                planFound = true;
            }
        });
        if (planFound) { saveDb(db); return true; }
        return false;
    },
    globalSearch: async (q: string) => ({ products: [], sales: [], customers: [], purchases: [], suppliers: [], partners: [], salesReturns: [], purchaseReturns: [], installments: [], stockTransfers: [] }),
    getSuppliers: async () => getDb().suppliers,
    saveSupplier: async (s: any) => { const db = getDb(); s.id = s.id || `sup-${Date.now()}`; db.suppliers.push(s); saveDb(db); return s; },
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s:any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r:any) => { const s = getDb().sales.find((s:any)=>s.id === r.originalSaleId); return s?.customer.id === id; }),
    getInactiveCustomers: async (d: number) => [],
    getStagnantProducts: async (d: number) => [],
    saveTreasury: async (t: any) => { const db = getDb(); t.id = t.id || `t-${Date.now()}`; db.treasuries.push(t); saveDb(db); return t; },
    saveTransaction: async (tr: any) => { const db = getDb(); tr.id = `tr-${Date.now()}`; db.transactions.unshift(tr); saveDb(db); return tr; },
    saveWarehouse: async (w: any) => { const db = getDb(); w.id = w.id || `w-${Date.now()}`; db.warehouses.push(w); saveDb(db); return w; },
    deleteProduct: async (id: string) => true,
    deleteTreasury: async (id: string) => true,
    deleteTransaction: async (id: string) => true,
    deleteWarehouse: async (id: string) => true,
    deleteSupplier: async (id: string) => true,
    getShippingCompanies: async () => [],
    saveShippingCompany: async (c: any) => c,
    deleteShippingCompany: async (id: string) => true,
    savePurchaseReturn: async (r: any) => r,
    getPartners: async () => getDb().partners || [],
    savePartner: async (p: any) => {
        const db = getDb();
        if (!db.partners) db.partners = [];
        if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `par-${Date.now()}`; db.partners.push(p); }
        saveDb(db);
        return p;
    },
    getNotifications: async () => getDb().notifications || [],
    addNotification: async (n: any) => {
        const db = getDb();
        const notification = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n };
        if (!db.notifications) db.notifications = [];
        db.notifications.unshift(notification);
        saveDb(db);
        return notification;
    },
    getBackupData: async () => JSON.stringify(getDb()),
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const today = new Date().toISOString().split('T')[0];
        const salesToday = db.sales.filter((s:any) => s.date.startsWith(today));
        const totalSalesToday = salesToday.reduce((a:any, b:any) => a + b.total, 0);
        const totalReceivables = db.customers.reduce((a:any, b:any) => a + (b.debt || 0), 0);
        const totalStockValue = db.products.reduce((a:any, b:any) => a + (b.stock * b.costPrice), 0);

        return { 
            totalSalesToday, 
            todaysTransactions: salesToday.length, 
            totalReceivables, 
            totalStockValue, 
            monthlySales: [], 
            salesByCategory: [], 
            topProducts: [] 
        };
    },
    getSyncLogs: async () => [],
    getQueueCount: async () => 0,
    processQueue: async () => true,
    setOnlineStatus: (s: boolean) => {},
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    submitFeedback: async (f: any) => true,
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any) => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        st.id = `st-${Date.now()}`;
        st.date = new Date().toISOString();
        if (!db.stockTransfers) db.stockTransfers = [];
        db.stockTransfers.unshift(st);
        saveDb(db);
        return true;
    },
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    updateSale: async (id: string, d: any) => true,
    updatePurchase: async (id: string, d: any) => true,
    updateSystemVersion: async (v: string, p: any) => true,
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    wipeBusinessData: async () => { 
        localStorage.removeItem(DB_KEY); 
    }
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import type { Product, Supplier, Treasury, Warehouse } from '../types';
import { api } from '../services/mockApi';
import { useSettings } from '../hooks/useSettings';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { Trash2, Search, ShoppingBag } from 'lucide-react';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';

const AddPurchasePage: React.FC = () => {
    const { settings } = useSettings();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const { addToast } = useToasts();

    const [products, setProducts] = useState<Product[]>([]);
    const [suppliers, setSuppliers] = useState<Supplier[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [items, setItems] = useState<any[]>([]);
    const [selectedSupId, setSelectedSupId] = useState('');
    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');
    const [discount, setDiscount] = useState(0);
    const [discountType, setDiscountType] = useState<'amount' | 'percent'>('amount');
    const [amountPaid, setAmountPaid] = useState(0);
    const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Card' | 'Transfer' | 'Credit'>('Cash');
    const [searchTerm, setSearchTerm] = useState('');

    const editId = searchParams.get('edit');

    useEffect(() => {
        Promise.all([api.getProducts(), api.getSuppliers(), api.getWarehouses(), api.getTreasuries(), api.getPurchases()]).then(([p, s, w, t, allP]) => {
            setProducts(p); setSuppliers(s); setWarehouses(w); setTreasuries(t);
            if (s.length) setSelectedSupId(s[0].id);
            if (w.length) setSelectedWhId(w.find(i=>i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i=>i.isDefault)?.id || t[0].id);
            if (editId) {
                const pToEdit = allP.find((i:any) => i.id === editId);
                if (pToEdit) { setItems(pToEdit.items); setSelectedSupId(pToEdit.supplier.id); setSelectedWhId(pToEdit.warehouseId); setSelectedTrId(pToEdit.treasuryId); setDiscount(pToEdit.discount); setDiscountType(pToEdit.discountType); setAmountPaid(pToEdit.amountPaid); setPaymentMethod(pToEdit.paymentMethod as any); }
            }
        });
    }, [editId]);

    const subtotal = items.reduce((s, i) => s + (i.costPrice * i.quantity), 0);
    const discountVal = discountType === 'percent' ? (subtotal * discount / 100) : discount;
    const finalTotal = Math.max(0, subtotal - discountVal);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!items.length || !selectedWhId || !selectedTrId) { addToast('يرجى اختيار المنتجات وتحديد المستودع والخزينة', 'warning'); return; }
        try {
            await api.savePurchase({ id: editId || undefined, supplier: suppliers.find(s => s.id === selectedSupId), items, total: finalTotal, amountPaid: paymentMethod === 'Credit' ? 0 : amountPaid, warehouseId: selectedWhId, treasuryId: selectedTrId, discount, discountType, paymentMethod });
            addToast('تم حفظ طلب الشراء', 'success'); navigate('/purchases');
        } catch (e) { addToast('خطأ في الحفظ', 'error'); }
    };

    return (
        <form onSubmit={handleSubmit} className="animate-fadeIn pb-10">
            <div className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-black">إضافة طلب شراء</h1>
                <div className="flex gap-2">
                    <Button type="button" variant="secondary" onClick={() => navigate('/purchases')} className="rounded-xl">تراجع</Button>
                    <Button type="submit" className="rounded-xl bg-indigo-600 shadow-lg shadow-indigo-500/20 px-8">حفظ الطلب</Button>
                </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                    <Card title="الأصناف المختارة" className="h-[650px] flex flex-col overflow-hidden">
                        <div className="relative mb-6">
                            <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" />
                            <input type="text" placeholder="ابحث عن منتج..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-10 border rounded-xl dark:bg-slate-800 font-bold" />
                            {searchTerm && (
                                <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white dark:bg-slate-800 border rounded-xl shadow-xl overflow-hidden max-h-60 overflow-y-auto">
                                    {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                        <button key={p.id} type="button" onClick={() => { const ex = items.find(i => i.productId === p.id); if (ex) setItems(items.map(i => i.productId === p.id ? {...i, quantity: i.quantity + 1} : i)); else setItems([...items, { productId: p.id, name: p.name, quantity: 1, costPrice: p.costPrice }]); setSearchTerm(''); }} className="w-full p-3 text-start hover:bg-slate-50 border-b last:border-0 font-black text-xs flex justify-between">
                                            <span>{p.name} <span className="text-[10px] text-slate-400 ms-2">({toArabicIndic(p.stock)})</span></span>
                                            <span className="text-indigo-600">{formatCurrency(p.costPrice, settings?.currency)}</span>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 custom-scrollbar pr-2">
                            {items.map((item, idx) => (
                                <div key={idx} className="flex items-center gap-4 p-4 border rounded-2xl bg-slate-50 dark:bg-slate-800/50 hover:border-indigo-300 transition-colors">
                                    <div className="flex-grow">
                                        <p className="font-black text-xs">{item.name}</p>
                                        <p className="text-[10px] text-slate-400 mt-1">تكلفة الوحدة: {formatCurrency(item.costPrice, settings?.currency)}</p>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <input type="number" value={item.quantity} onChange={e => setItems(items.map((it, i) => i === idx ? {...it, quantity: parseFloat(e.target.value)||0} : it))} className="w-20 p-2 border rounded-lg text-center font-bold text-xs" />
                                        <button type="button" onClick={() => setItems(items.filter((_, i) => i !== idx))} className="text-rose-500 p-2 hover:bg-rose-50 rounded-lg"><Trash2 size={16} /></button>
                                    </div>
                                </div>
                            ))}
                            {items.length === 0 && (
                                <div className="h-full flex flex-col items-center justify-center opacity-30">
                                    <ShoppingBag size={80} strokeWidth={1}/>
                                    <p className="font-black mt-4">لم يتم اختيار أصناف بعد</p>
                                </div>
                            )}
                        </div>
                    </Card>
                </div>
                <div className="space-y-6">
                    <Card title="بيانات الطلب">
                        <div className="space-y-4">
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">المورد</label><select value={selectedSupId} onChange={e => setSelectedSupId(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold text-xs">{suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></div>
                            <div><label className="text-[10px] font-black text-slate-400 block mb-1">طريقة الدفع</label><select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value as any)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold text-xs"><option value="Cash">كاش</option><option value="Card">بطاقة</option><option value="Transfer">تحويل</option><option value="Credit">آجل (دين)</option></select></div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><label className="text-[10px] font-black text-slate-400 block mb-1">المستودع</label><select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold text-xs">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></div>
                                <div><label className="text-[10px] font-black text-slate-400 block mb-1">الخزينة</label><select value={selectedTrId} onChange={e => setSelectedTrId(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-800 font-bold text-xs">{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></div>
                            </div>
                        </div>
                    </Card>
                    <div className="p-6 bg-indigo-600 text-white rounded-4xl text-center shadow-xl">
                        <p className="text-[10px] font-black opacity-80 uppercase tracking-widest">إجمالي الطلب</p>
                        <p className="text-3xl font-black mt-1">{formatCurrency(finalTotal, settings?.currency)}</p>
                        {paymentMethod !== 'Credit' && (
                            <div className="mt-6 pt-6 border-t border-white/20">
                                <label className="text-[10px] font-black opacity-70 block mb-2">المبلغ المدفوع فعلياً</label>
                                {/* FIX: Changed background from white/10 to indigo-800 for better contrast against white numbers */}
                                <input type="number" value={amountPaid} onChange={e => setAmountPaid(parseFloat(e.target.value)||0)} className="w-full p-3 bg-indigo-800/50 rounded-2xl text-center font-black border border-white/20 text-white text-2xl outline-none focus:ring-2 focus:ring-white/50" />
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </form>
    );
};

export default AddPurchasePage;

