            logActivity(db, 'إضافة شريك', `تم إضافة شريك جديد: ${p.name}`);
        }
        saveDb(db);
        return p;
    },
    getNotifications: async () => getDb().notifications || [],
    addNotification: async (n: any) => {
        const db = getDb();
        const notification = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n };
        if (!db.notifications) db.notifications = [];
        db.notifications.unshift(notification);
        saveDb(db);
        return notification;
    },
    getBackupData: async () => JSON.stringify(getDb()),
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const todayStr = new Date().toISOString().split('T')[0];
        const salesToday = db.sales.filter((s:any) => s.date.startsWith(todayStr));

        const totalSalesToday = salesToday.reduce((a:any, b:any) => a + b.total, 0);
        const totalReceivables = db.customers.reduce((a:any, b:any) => a + (b.debt || 0), 0);
        const totalStockValue = db.products.reduce((a:any, b:any) => a + (b.stock * b.costPrice), 0);

        // Calculate monthly sales for charts
        const last6Months = Array.from({length: 6}, (_, i) => {
            const d = new Date();
            d.setMonth(d.getMonth() - (5 - i));
            return d.toISOString().substring(0, 7);
        });

        const monthlySales = last6Months.map(month => {
            const mSales = db.sales.filter((s:any) => s.date.startsWith(month));
            const total = mSales.reduce((a:any, b:any) => a + b.total, 0);
            return { name: month, sales: total };
        });

        // Sales by category
        const catMap: Record<string, number> = {};
        db.sales.forEach((s:any) => {
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                const cat = prod?.category || 'عام';
                catMap[cat] = (catMap[cat] || 0) + (item.sellPrice * item.quantity);
            });
        });
        const salesByCategory = Object.entries(catMap).map(([name, value]) => ({ name, value }));

        // Top products
        const prodRev: Record<string, {name: string, total: number}> = {};
        db.sales.forEach((s:any) => {
            s.items.forEach((item: any) => {
                if (!prodRev[item.id]) prodRev[item.id] = { name: item.name, total: 0 };
                prodRev[item.id].total += (item.sellPrice * item.quantity);
            });
        });
        const topProducts = Object.entries(prodRev)
            .map(([id, data]) => ({ id, name: data.name, totalRevenue: data.total }))
            .sort((a,b) => b.totalRevenue - a.totalRevenue)
            .slice(0, 5);

        return { 
            totalSalesToday, 
            todaysTransactions: salesToday.length, 
            totalReceivables, 
            totalStockValue, 
            monthlySales, 
            salesByCategory, 
            topProducts 
        };
    },
    getSyncLogs: async () => [],
    getQueueCount: async () => 0,
    processQueue: async () => true,
    setOnlineStatus: (s: boolean) => {},
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    submitFeedback: async (f: any) => true,
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any) => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        st.id = `st-${Date.now()}`;
        st.date = new Date().toISOString();
        if (!db.stockTransfers) db.stockTransfers = [];
        db.stockTransfers.unshift(st);
        saveDb(db);
        return true;
    },
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    updateSale: async (id: string, d: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...d } : s);
        saveDb(db);
        return true;
    },
    updatePurchase: async (id: string, d: any) => {
        const db = getDb();
        db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...d } : p);
        saveDb(db);
        return true;
    },
    updateSystemVersion: async (v: string, p: any) => true,
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    wipeBusinessData: async () => { 
        localStorage.removeItem(DB_KEY); 
    }
};

import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import { useLicense } from '../../hooks/useLicense';
import type { PermissionKey } from '../../types';
import { Lock, Crown } from 'lucide-react';
import Button from '../ui/Button';
import { Link } from 'react-router-dom';

interface ProtectedRouteProps {
  permission: PermissionKey | PermissionKey[];
  children: React.ReactElement;
}

const LockedFeature: React.FC = () => (
    <div className="flex flex-col items-center justify-center h-[70vh] animate-fadeIn text-center p-6">
        <div className="w-24 h-24 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6 shadow-inner">
            <Lock size={48} className="text-slate-400" />
        </div>
        <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 font-black">ميزة حصرية للمشتركين</h2>
        <p className="text-slate-600 dark:text-slate-400 max-w-md mb-8 font-bold">هذه الميزة غير متاحة في الخطة المجانية. يرجى الترقية لدعم نمو عملك.</p>
        <Link to="/pricing"><Button className="gap-2 px-10 py-4 text-lg bg-indigo-600 rounded-2xl font-black shadow-xl"><Crown size={20} /> عرض خطط الترقية</Button></Link>
    </div>
);

const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ permission, children }) => {
  const { user, userHasPermission } = useAuth();
  const { licenseInfo } = useLicense();
  const location = useLocation();

  if (!user) return <Navigate to="/login" state={{ from: location }} replace />;

  // السماح بالوصول لصفحة البداية '/' فقط لتجنب التعليق، ولكن فحص لوحة التحكم والصفحات الأخرى
  if (location.pathname === '/') return children;

  const hasAccess = Array.isArray(permission) 
    ? permission.some(p => userHasPermission(p))
    : userHasPermission(permission);

  if (!hasAccess) {
    // إذا لم يملك المستخدم صلاحية، يتم توجيهه للرئيسية بدلاً من لوحة التحكم لتجنب التكرار
    return <Navigate to="/" replace />;
  }

  if (licenseInfo.type === 'Free') {
      const restrictedForFree: PermissionKey[] = ['view_dashboard', 'view_reports', 'manage_installments', 'manage_partners', 'view_activity_logs', 'access_admin_tool', 'manage_backups'];
      const isRestricted = Array.isArray(permission) ? permission.some(p => restrictedForFree.includes(p)) : restrictedForFree.includes(permission);
      if (isRestricted) return <LockedFeature />;
  }

  return children;
};

export default ProtectedRoute;

