    saveTreasury: async (t: any) => { const db = getDb(); t.id = t.id || `t-${Date.now()}`; db.treasuries.push(t); saveDb(db); return t; },
    saveTransaction: async (tr: any) => { const db = getDb(); tr.id = `tr-${Date.now()}`; db.transactions.unshift(tr); saveDb(db); return tr; },
    saveWarehouse: async (w: any) => { const db = getDb(); w.id = w.id || `w-${Date.now()}`; db.warehouses.push(w); saveDb(db); return w; },
