    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getPartners: async () => getDb().partners || [],
    savePartner: async (p: any) => {
        const db = getDb();
        if (!db.partners) db.partners = [];
        if (p.id) {
            db.partners = db.partners.map((item: any) => item.id === p.id ? p : item);
