};

import React, { useState } from 'react';
import Modal from '../ui/Modal';
import Button from '../ui/Button';
import type { Sale } from '../../types';
import { useSettings } from '../../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../../utils/localization';
import { Printer, FileText, MessageCircle, Download } from 'lucide-react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

interface ReceiptModalProps {
  isOpen: boolean;
  onClose: () => void;
  sale: Sale | null;
}

const getQrUrl = (data: string) => `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(data)}`;

const ReceiptModal: React.FC<ReceiptModalProps> = ({ isOpen, onClose, sale }) => {
  const { settings } = useSettings();
  const [isExporting, setIsExporting] = useState(false);

  if (!sale || !settings) return null;

  const { template, showLogo, showQrCode, accentColor, customCss } = settings.invoiceDesign;
  const currency = settings.currency;

  const subTotalBeforeItemDiscounts = sale.items.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);
  const totalItemDiscounts = sale.items.reduce((sum, item) => sum + ((item.discount || 0) * item.quantity), 0);
  const subTotalAfterItemDiscounts = subTotalBeforeItemDiscounts - totalItemDiscounts;

  const additionalDiscount = sale.discount || 0;
  const totalDiscount = totalItemDiscounts + additionalDiscount;

  const shipping = sale.shipping || 0;
  const vatAmount = sale.vatAmount || (subTotalAfterItemDiscounts - additionalDiscount) * (settings.vatRate / 100);

  const handlePrint = () => window.print();

  const handleDownloadPDF = async () => {
    const element = document.getElementById('printable-receipt-area');
    if (!element) return;

    setIsExporting(true);
    try {
        const canvas = await html2canvas(element, {
            scale: 2,
            useCORS: true,
            logging: false,
            backgroundColor: "#ffffff"
        });
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({
            orientation: 'portrait',
            unit: 'mm',
            format: template === 'thermal' ? [80, 200] : 'a4'
        });

        const imgProps = pdf.getImageProperties(imgData);
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
        pdf.save(`invoice-${sale.id.toLowerCase()}.pdf`);
    } catch (err) {
        console.error("PDF Export failed", err);
    } finally {
        setIsExporting(false);
    }
  };

  const handleWhatsAppShare = () => {
    const text = `*فاتورة مبيعات من ${settings.storeName}*%0A` +
                 `رقم الفاتورة: ${sale.id.toUpperCase()}%0A` +
                 `التاريخ: ${new Date(sale.date).toLocaleDateString('ar-EG')}%0A` +
                 `*الإجمالي: ${formatCurrency(sale.total, currency)}*`;
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const renderItemsTable = () => (
    <table className="w-full mb-6 text-xs">
        <thead className="border-b-2 border-slate-200">
            <tr>
                <th className="text-start py-3 px-1">الصنف</th>
                <th className="text-center py-3">السعر</th>
                <th className="text-center py-3">الخصم</th>
                <th className="text-center py-3">الكمية</th>
                <th className="text-end py-3">الإجمالي</th>
            </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
            {sale.items.map(item => (
                <tr key={item.id}>
                    <td className="py-3 px-1 font-bold">{item.name}</td>
                    <td className="py-3 text-center">{formatAmount(item.sellPrice)}</td>
                    <td className="py-3 text-center text-rose-500">{item.discount ? `-${formatAmount(item.discount)}` : '٠'}</td>
                    <td className="py-3 text-center">{toArabicIndic(item.quantity)}</td>
                    <td className="py-3 text-end font-black">{formatAmount((item.sellPrice - (item.discount || 0)) * item.quantity)}</td>
                </tr>
            ))}
        </tbody>
    </table>
  );

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={onClose} 
      title={`معاينة فاتورة #${sale.id.toUpperCase()}`}
      footer={
        <div className="flex flex-wrap justify-end gap-2 w-full">
            <Button variant="secondary" onClick={onClose} className="rounded-xl">إغلاق</Button>
            <Button onClick={handleWhatsAppShare} className="bg-green-600 hover:bg-green-700 rounded-xl"><MessageCircle size={18} className="me-2"/> واتساب</Button>
            <Button onClick={handleDownloadPDF} isLoading={isExporting} className="bg-blue-600 rounded-xl"><Download size={18} className="me-2"/> تحميل PDF</Button>
            <Button onClick={handlePrint} className="bg-indigo-600 rounded-xl"><Printer size={18} className="me-2"/> طباعة</Button>
        </div>
      }
    >
        <div className="bg-slate-100 dark:bg-slate-800 p-4 rounded-3xl overflow-hidden max-h-[70vh] overflow-y-auto custom-scrollbar">
            {template === 'free' && customCss && <style>{customCss}</style>}

            <div id="printable-receipt-area" className={`receipt-container bg-white text-black p-8 shadow-sm mx-auto font-sans template-${template}`} style={{ maxWidth: template === 'thermal' ? '80mm' : '210mm' }}>

                <div className="flex flex-col md:flex-row justify-between items-start mb-8 gap-6 border-b pb-6">
                    <div className="flex items-center gap-4">
                        {showLogo && settings.logoUrl && <img src={settings.logoUrl} className="w-20 h-20 object-contain" alt="Logo" />}
