import React, { useState, useEffect } from 'react';
import type { Customer, CustomerTier } from '../../types';
import Button from '../ui/Button';
import { AlertCircle } from 'lucide-react';

interface CustomerFormProps {
  customer: Customer | null;
  onSave: (customer: Omit<Customer, 'id' | 'debt' | 'points'> & { id?: string }) => void;
  onCancel: () => void;
  isLoading: boolean;
  error?: string;
}

const CustomerForm: React.FC<CustomerFormProps> = ({ customer, onSave, onCancel, isLoading, error }) => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    address: '',
    tier: 'Regular' as CustomerTier
  });

  useEffect(() => {
    if (customer) {
      setFormData({
        name: customer.name,
        phone: customer.phone,
        email: customer.email || '',
        address: customer.address || '',
        tier: customer.tier || 'Regular'
      });
    }
  }, [customer]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ ...formData, id: customer?.id });
  };

  const inputStyle = "mt-1 block w-full rounded-md border-slate-400 shadow-sm focus:border-blue-600 focus:ring-blue-600 bg-white dark:bg-gray-700 dark:border-gray-500 dark:text-white dark:focus:border-blue-500 transition-colors";

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {error && (
        <div className="p-4 mb-4 text-sm text-red-800 rounded-lg bg-red-50 dark:bg-gray-800 dark:text-red-400 flex items-center gap-2" role="alert">
            <AlertCircle size={20} />
            <span className="font-medium">خطأ!</span> {error}
        </div>
      )}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-bold text-slate-700 dark:text-slate-200">اسم العميل</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputStyle} placeholder="الاسم الكامل" />
        </div>
        <div>
          <label className="block text-sm font-bold text-slate-700 dark:text-slate-200">تصنيف العميل</label>
          <select name="tier" value={formData.tier} onChange={handleChange} className={inputStyle}>
            <option value="Regular">عادي</option>
            <option value="Wholesale">جملة</option>
            <option value="Retail">قطاعي</option>
            <option value="VIP">VIP</option>
          </select>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-200">الهاتف</label>
            <input type="tel" name="phone" value={formData.phone} onChange={handleChange} required className={inputStyle} placeholder="05xxxxxxxx" />
          </div>
          <div>
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-200">البريد الإلكتروني (اختياري)</label>
            <input type="email" name="email" value={formData.email} onChange={handleChange} className={inputStyle} placeholder="example@mail.com" />
          </div>
      </div>

      <div>
        <label className="block text-sm font-bold text-slate-700 dark:text-slate-200">العنوان</label>
        <textarea name="address" value={formData.address} onChange={handleChange} rows={2} className={inputStyle} placeholder="العنوان التفصيلي" />
      </div>

      <div className="flex justify-end gap-2 pt-4">
        <Button type="button" variant="secondary" onClick={onCancel}>إلغاء</Button>
        <Button type="submit" isLoading={isLoading}>{customer ? 'حفظ التعديلات' : 'إضافة العميل'}</Button>
      </div>
    </form>
  );
};

