import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Transaction, Treasury } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import TransactionFormModal from '../components/treasury/TransactionFormModal';
import { PlusCircle, Download, Edit, Trash2, Wallet, RefreshCw, Search, Calendar, Filter, Lock } from 'lucide-react';
import { exportToCsv } from '../utils/export';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, CURRENCIES } from '../utils/localization';
import ConfirmDialog from '../components/ui/ConfirmDialog';
import { useAuth } from '../hooks/useAuth';
import TreasurySkeleton from '../components/treasury/TreasurySkeleton';
import { useToasts } from '../hooks/useToasts';
import { useLicense } from '../hooks/useLicense';

const TreasuryPage: React.FC = () => {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

    const [isTreasuryModalOpen, setIsTreasuryModalOpen] = useState(false);
    const [newTreasuryName, setNewTreasuryName] = useState('');
    const [newTreasuryCurrency, setNewTreasuryCurrency] = useState('');
    const [isSavingTreasury, setIsSavingTreasury] = useState(false);

    const [searchTerm, setSearchTerm] = useState('');
    const [filterRange, setFilterRange] = useState<'today' | 'week' | 'month' | 'year' | 'all' | 'custom'>('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const { settings } = useSettings();
    const { userHasPermission } = useAuth();
    const { addToast } = useToasts();
    const { licenseInfo } = useLicense();

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [transData, treasuryData] = await Promise.all([
                api.getTransactions(),
                api.getTreasuries()
            ]);
            setTransactions(transData || []);
            setTreasuries(treasuryData || []);
        } catch (e) {
            addToast("فشل تحميل البيانات", "error");
        } finally {
            setLoading(false);
        }
    }, [addToast]);

    useEffect(() => {
        fetchData();
        if (settings) setNewTreasuryCurrency(settings.currency);
    }, [fetchData, settings]);

    const getFormattedDate = (date: Date) => {
        return date.toISOString().split('T')[0];
    };

    const handleRangeChange = (range: typeof filterRange) => {
        setFilterRange(range);
        const now = new Date();
        if (range === 'today') {
            setStartDate(getFormattedDate(now));
            setEndDate(getFormattedDate(now));
        } else if (range === 'week') {
            const weekAgo = new Date();
            weekAgo.setDate(now.getDate() - 7);
            setStartDate(getFormattedDate(weekAgo));
            setEndDate(getFormattedDate(now));
        } else if (range === 'month') {
            const monthAgo = new Date();
            monthAgo.setDate(now.getDate() - 30);
            setStartDate(getFormattedDate(monthAgo));
            setEndDate(getFormattedDate(now));
        } else if (range === 'all') {
            setStartDate('');
            setEndDate('');
        }
    };

    const filteredTransactions = useMemo(() => {
        return (transactions || []).filter(t => {
            if (!t) return false;
            const transDate = t.date?.split('T')[0] || '';
            const matchesDate = (!startDate || transDate >= startDate) && (!endDate || transDate <= endDate);

            const term = searchTerm.toLowerCase();
            const matchesSearch = !term || 
                (t.description || '').toLowerCase().includes(term) || 
                (t.category || '').toLowerCase().includes(term) || 
                (t.user || '').toLowerCase().includes(term);

            return matchesDate && matchesSearch;
        });
    }, [transactions, searchTerm, startDate, endDate]);

    const handleOpenModal = (transaction: Transaction | null = null) => {
        if (!transaction && licenseInfo.type === 'Free') {
            const today = getFormattedDate(new Date());
            const todayCount = (transactions || []).filter(t => t?.date?.startsWith(today)).length;
            if (todayCount >= 4) {
                addToast("لقد وصلت للحد الأقصى لحركات الخزينة اليومية (٤ حركات) في الخطة المجانية.", 'warning');
                return;
            }
        }
        setEditingTransaction(transaction);
        setIsModalOpen(true);
    };

    const treasuryLimits: Record<string, number> = {
        'Free': 1, 'Trial': 1, 'Monthly': 2, 'Semiannual': 3, 'Yearly': 15, 'Lifetime': 999
    };
    const currentLimit = licenseInfo.type ? treasuryLimits[licenseInfo.type] : 1;
    const canAddTreasury = (treasuries || []).length < currentLimit;

    const handleAddTreasury = async () => {
        if (!newTreasuryName.trim()) return;
        setIsSavingTreasury(true);
        try {
            await api.saveTreasury({ name: newTreasuryName, balance: 0, currency: newTreasuryCurrency || settings?.currency });
            await fetchData();
            addToast('تم إضافة الخزينة بنجاح.', 'success');
            setIsTreasuryModalOpen(false);
            setNewTreasuryName('');
        } catch(e) { addToast('فشل إضافة الخزينة.', 'error'); } finally { setIsSavingTreasury(false); }
    };

    const totalIncome = filteredTransactions.filter(t => t.type === 'income').reduce((acc, t) => acc + (t.amount || 0), 0);
    const totalExpense = filteredTransactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + (t.amount || 0), 0);

    if (loading || !settings) return <TreasurySkeleton />;

    return (
        <div className="animate-fadeIn">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-3xl font-black text-slate-800 dark:text-white">الخزينة</h1>
                    <p className="text-sm text-slate-500 font-bold">الخزائن المفتوحة: {toArabicIndic((treasuries || []).length)} / {toArabicIndic(currentLimit)}</p>
                </div>
                <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
                    <div className="flex items-center gap-1 bg-white dark:bg-slate-800 p-1 rounded-2xl border dark:border-slate-700 shadow-sm overflow-x-auto">
                        {(['today', 'week', 'month', 'all', 'custom'] as const).map((r) => (
                            <button key={r} onClick={() => handleRangeChange(r)} className={`px-4 py-2 text-[11px] font-black rounded-xl transition-all whitespace-nowrap ${filterRange === r ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-700'}`}>
                                {r === 'today' ? 'اليوم' : r === 'week' ? 'أسبوع' : r === 'month' ? 'شهر' : r === 'all' ? 'الكل' : 'مخصص'}
                            </button>
                        ))}
                    </div>
                    {userHasPermission('view_treasury') && <Button onClick={() => handleOpenModal()} className="rounded-2xl font-black h-11 px-6 shadow-lg shadow-indigo-500/20"><PlusCircle size={18} /> تسجيل حركة</Button>}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                {(treasuries || []).map(t => (
                    <div key={t.id} className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 shadow-sm relative group hover:border-indigo-200 transition-all">
                        <div className="flex items-center justify-between mb-4">
                            <div className="p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-2xl text-indigo-600"><Wallet size={24} /></div>
                        </div>
                        <h4 className="font-black text-slate-800 dark:text-white text-lg">{t.name}</h4>
                        <p className="text-2xl font-black text-slate-800 dark:text-white leading-none mt-4">{formatCurrency(t.balance || 0, t.currency || settings.currency)}</p>
                    </div>
                ))}
                <button onClick={() => canAddTreasury ? setIsTreasuryModalOpen(true) : addToast("وصلت للحد الأقصى", "warning")} className={`flex flex-col items-center justify-center p-6 rounded-3xl border-2 border-dashed transition-all ${canAddTreasury ? 'border-slate-300 hover:border-indigo-400 hover:bg-indigo-50/30' : 'opacity-50 cursor-not-allowed'}`}>
                    <PlusCircle size={32} className="text-slate-400 mb-2" />
                    <span className="text-sm font-black text-slate-500">إضافة خزينة</span>
                </button>
            </div>

            <Card title="سجل العمليات" className="p-0 border-none shadow-premium overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-start">
                        <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                            <tr>
                                <th className="px-6 py-4">التاريخ</th><th className="px-6 py-4">النوع</th><th className="px-6 py-4">الفئة</th><th className="px-6 py-4">البيان</th><th className="px-6 py-4">المبلغ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y dark:divide-slate-800">
                            {filteredTransactions.map(t => (
                                <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                                    <td className="px-6 py-4 font-bold">{new Date(t.date).toLocaleDateString('ar-EG')}</td>
                                    <td className="px-6 py-4"><span className={`px-3 py-1 text-[10px] font-black rounded-full ${t.type === 'income' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>{t.type === 'income' ? 'إيداع' : 'سحب'}</span></td>
                                    <td className="px-6 py-4 font-medium text-slate-500">{t.category}</td>
                                    <td className="px-6 py-4 font-medium">{t.description}</td>
                                    <td className={`px-6 py-4 font-black text-lg ${t.type === 'income' ? 'text-emerald-600' : 'text-rose-600'}`}>
                                        {formatCurrency(t.amount || 0, (treasuries || []).find(tr => tr.id === t.treasuryId)?.currency || settings.currency)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </Card>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingTransaction ? 'تعديل حركة مالية' : 'تسجيل حركة جديدة'}>
                <TransactionFormModal transaction={editingTransaction} onSave={async (d) => { await api.saveTransaction(d); await fetchData(); setIsModalOpen(false); addToast('تم الحفظ.', 'success'); }} onCancel={() => setIsModalOpen(false)} isLoading={isSaving} />
            </Modal>
        </div>
    );
};

