import React, { useState, useEffect } from 'react';
import type { Partner, Sale, Transaction, SalesReturn } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import PartnerFormModal from '../components/partners/PartnerFormModal';
import { PlusCircle, TrendingUp, TrendingDown, Briefcase, DollarSign, PieChart } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';

const PartnersPage: React.FC = () => {
    const [partners, setPartners] = useState<Partner[]>([]);
    const [sales, setSales] = useState<Sale[]>([]);
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [returns, setReturns] = useState<SalesReturn[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { settings } = useSettings();
    const { addToast } = useToasts();

    const fetchData = async () => {
        setLoading(true);
        const [p, s, t, r] = await Promise.all([
            api.getPartners(), 
            api.getSales(),
            api.getTransactions(),
            api.getSalesReturns()
        ]);
        setPartners(p || []);
        setSales(s || []);
        setTransactions(t || []);
        setReturns(r || []);
        setLoading(false);
    };

    useEffect(() => { fetchData(); }, []);

    // دالة حساب الأرباح الدقيقة لكل شريك من تاريخ انضمامه
    const calculatePartnerProfit = (partner: Partner) => {
        const joinDate = new Date(partner.joinedDate);

        // 1. حساب الإيرادات من تاريخ الانضمام
        const partnerSales = sales.filter(s => new Date(s.date) >= joinDate);
        const partnerReturns = returns.filter(r => new Date(r.date) >= joinDate);

        const totalRevenue = partnerSales.reduce((a, b) => a + b.total, 0) - 
                             partnerReturns.reduce((a, b) => a + b.totalRefund, 0);

        // 2. حساب تكلفة البضاعة (COGS) لتلك المبيعات
        // ملاحظة: نحتاج لبيانات تكلفة المنتجات وقت البيع لضمان الدقة
        // هنا نقوم بمحاكاة سريعة بناءً على البيانات المتاحة
        const totalCOGS = partnerSales.reduce((sum, s) => {
            return sum + s.items.reduce((itemSum, item) => itemSum + (item.originalPrice || 0) * item.quantity, 0);
        }, 0);

        // 3. حساب المصاريف من تاريخ الانضمام
        const partnerExpenses = transactions.filter(t => t.type === 'expense' && new Date(t.date) >= joinDate);
        const totalExpenses = partnerExpenses.reduce((a, b) => a + (b.amount || 0), 0);

        const netProfitSinceJoining = totalRevenue - totalCOGS - totalExpenses;
        return (netProfitSinceJoining * partner.sharePercentage) / 100;
    };

    return (
        <div className="animate-fadeIn pb-20">
            <div className="flex justify-between items-center mb-10">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white">نظام الشركاء والأرباح</h1>
                    <p className="text-slate-500 font-bold mt-1">تُحسب الأرباح آلياً لكل شريك من تاريخ بدء مساهمته.</p>
                </div>
                <Button onClick={() => setIsModalOpen(true)} className="rounded-2xl font-black shadow-lg shadow-indigo-500/20"><PlusCircle size={20} className="me-2"/> إضافة شريك</Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {partners.map(p => {
                    const pProfit = calculatePartnerProfit(p);
                    return (
                        <Card key={p.id} className="relative overflow-hidden border-none shadow-premium hover:animate-subtle-lift group">
