    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const purchases = db.purchases.filter((p:any) => (!start || p.date >= start) && (!end || p.date <= end));
        const expenses = (db.transactions || []).filter((t:any) => t.type === 'expense' && (!start || t.date >= start) && (!end || t.date <= end));
        const returns = (db.salesReturns || []).filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        const totalRevenue = sales.reduce((a:any, b:any) => a + b.total, 0) - returns.reduce((a:any, b:any) => a + b.totalRefund, 0);

        let totalCOGS = 0;
        sales.forEach((s:any) => {
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                totalCOGS += (prod?.costPrice || 0) * item.quantity;
            });
        });

        const totalPurchases = purchases.reduce((a:any, b:any) => a + b.total, 0);
        const otherExpenses = expenses.filter((e:any) => !e.description.includes('مرتجع')).reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - otherExpenses;

        return { totalRevenue, totalCOGS, totalExpenses: otherExpenses, totalPurchases, totalReturns: returns.length, netProfit, dailyStats: [] };
    },
