const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5 }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' } },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.partners) parsed.partners = [];
        if (!parsed.purchaseReturns) parsed.purchaseReturns = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({
        id: `act-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    });
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer', amount: number, description: string, treasuryId: string, toTreasuryId?: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'transfer' && toTreasuryId) {
            const toT = db.treasuries.find((item: any) => item.id === toTreasuryId);
            if (toT) {
                t.balance -= amount;
                toT.balance += amount;
            }
        } else {
            t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        }

        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: type === 'income' ? 'مبيعات/تحصيل' : type === 'expense' ? 'مشتريات/مصاريف' : 'تحويل داخلي',
            user: 'النظام',
            treasuryId,
            toTreasuryId
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => {
                if (item.id === p.id) {
                    return { ...item, ...p, warehouseStocks: p.warehouseStocks || item.warehouseStocks };
                }
                return item;
            });
            logActivity(db, 'تعديل منتج', `تم تعديل بيانات المنتج: ${p.name}`);
        }
        else { 
            p.id = `prod-${Date.now()}`; 
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `تم إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => {
            const index = db.products.findIndex((item: any) => item.id === p.id);
            if (index !== -1) db.products[index] = p;
        });
        saveDb(db);
        return products;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        // فحص حد الائتمان
        if (sale.paymentMethod === 'Credit' && customer && customer.creditLimit > 0) {
            const newDebt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            if (newDebt > customer.creditLimit) {
                throw new Error(`عذراً، العميل تجاوز حد الائتمان المسموح به (${customer.creditLimit}).`);
            }
        }

        if (sale.status === 'Draft') {
            sale.id = sale.id || `DRFT-${Date.now()}`;
            sale.date = new Date().toISOString();
            db.sales.unshift(sale);
            saveDb(db);
            return sale;
        }

        if (sale.id && sale.id.startsWith('DRFT')) {
            db.sales = db.sales.filter((s: any) => s.id !== sale.id);
            sale.id = undefined; 
        } else if (sale.id) {
            db.sales = db.sales.filter((s: any) => s.id !== sale.id);
        }

        // تحديث المخزون
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString() };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `دفعة من فاتورة مبيعات #${id}`, sale.treasuryId);
        }

        // حساب العمولات
        if (sale.representativeId) {
            const rep = db.users.find((u: any) => u.id === sale.representativeId);
            if (rep && rep.commissionRate) {
                finalSale.commissionAmount = (sale.total * rep.commissionRate) / 100;
            }
        }

        if (customer) {
            const creditAmount = sale.total - sale.amountPaid;
            if (creditAmount > 0) customer.debt = (customer.debt || 0) + creditAmount;
        }

        logActivity(db, 'فاتورة مبيعات', `إنشاء فاتورة مبيعات #${id} بقيمة ${sale.total}`);
        saveDb(db); return finalSale;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) {
            db.customers = db.customers.map((item: any) => {
                if (item.id === c.id) {
                    return { ...item, ...c, debt: item.debt, points: item.points };
                }
                return item;
            });
        }
        else { 
            c.id = `cust-${Date.now()}`; 
            c.debt = 0; 
            c.points = 0; 
            c.tier = c.tier || 'Regular';
            c.creditLimit = c.creditLimit || 0;
            db.customers.push(c); 
        }
        saveDb(db); return c;
    },
    savePurchase: async (pur: any) => {
        const db = getDb();
        if (pur.id) db.purchases = db.purchases.filter((p: any) => p.id !== pur.id);

        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = pur.id || `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        if (pur.amountPaid > 0) {
            logTransaction(db, 'expense', pur.amountPaid, `دفعة لطلب شراء #${pur.id}`, pur.treasuryId);
        }
        saveDb(db); return pur;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => s.status !== 'Draft' && (!start || s.date >= start) && (!end || s.date <= end));
        const expenses = (db.transactions || []).filter((t:any) => t.type === 'expense' && (!start || t.date >= start) && (!end || t.date <= end));
        const returns = (db.salesReturns || []).filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        let totalRevenue = 0, totalCOGS = 0, totalTax = 0;
        const prodProfitMap: Record<string, { name: string, profit: number }> = {};

        sales.forEach((s: any) => {
            totalRevenue += s.total;
            totalTax += s.vatAmount || 0;
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                const cost = (prod?.costPrice || 0) * item.quantity;
                const profit = (item.sellPrice * item.quantity) - cost;
                totalCOGS += cost;

                if (!prodProfitMap[item.id]) prodProfitMap[item.id] = { name: item.name, profit: 0 };
                prodProfitMap[item.id].profit += profit;
            });
        });

        const totalExpenses = expenses.reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - totalExpenses;

        return { 
            totalRevenue, totalCOGS, totalExpenses, totalTax, netProfit, 
            productProfits: Object.entries(prodProfitMap).map(([id, d]) => ({ id, name: d.name, profit: d.profit })),
            dailyStats: [] 
        };
    },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => {
        const db = getDb();
        logTransaction(db, 'transfer', amount, desc, fromId, toId);
        saveDb(db);
        return true;
    },
    getSales: async () => getDb().sales,
    getSalesReturns: async () => getDb().salesReturns,
    getPurchases: async () => getDb().purchases,
    getTransactions: async () => getDb().transactions,
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getInstallmentPlans: async () => getDb().installments || [],
    getCurrentShift: async (uid: string) => getDb().shifts.find((s:any) => s.userId === uid && s.status === 'Open') || null,
    openShift: async (uid: string, a: number) => { const db = getDb(); const s = { id: `sh-${Date.now()}`, userId: uid, startTime: new Date().toISOString(), startCash: a, status: 'Open' }; db.shifts.push(s); saveDb(db); return s; },
    closeShift: async (id: string, a: number, n?: string) => { 
        const db = getDb(); 
        const s = db.shifts.find((i:any)=>i.id===id); 
        if(s){
            s.status='Closed'; 
            s.endTime=new Date().toISOString(); 
            s.endCash=a;
            s.notes=n;
        } 
        saveDb(db); 
        return s; 
    },
    getJournalEntries: async () => [],
    recordInstallmentPayment: async (id: string) => {
        const db = getDb();
        let planFound = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === id);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                logTransaction(db, 'income', payment.amount, `تحصيل قسط من العميل: ${plan.customerName}`, 't-1');
                logActivity(db, 'تحصيل قسط', `تم تحصيل قسط بمبلغ ${payment.amount} من ${plan.customerName}`);
                planFound = true;
            }
        });
        if (planFound) { saveDb(db); return true; }
        return false;
    },
    globalSearch: async (q: string) => ({ products: [], sales: [], customers: [], purchases: [], suppliers: [], partners: [], salesReturns: [], purchaseReturns: [], installments: [], stockTransfers: [] }),
    getSuppliers: async () => getDb().suppliers,
    saveSupplier: async (s: any) => { const db = getDb(); s.id = s.id || `sup-${Date.now()}`; db.suppliers.push(s); saveDb(db); return s; },
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s:any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r:any) => { const s = getDb().sales.find((s:any)=>s.id === r.originalSaleId); return s?.customer.id === id; }),
    getInactiveCustomers: async (d: number) => [],
    getStagnantProducts: async (d: number) => [],
    saveTreasury: async (t: any) => { const db = getDb(); t.id = t.id || `t-${Date.now()}`; db.treasuries.push(t); saveDb(db); return t; },
    saveTransaction: async (tr: any) => { const db = getDb(); tr.id = `tr-${Date.now()}`; db.transactions.unshift(tr); saveDb(db); return tr; },
    saveWarehouse: async (w: any) => { const db = getDb(); w.id = w.id || `w-${Date.now()}`; db.warehouses.push(w); saveDb(db); return w; },
    deleteProduct: async (id: string) => true,
    deleteTreasury: async (id: string) => true,
    deleteTransaction: async (id: string) => true,
    deleteWarehouse: async (id: string) => true,
    deleteSupplier: async (id: string) => true,
    getShippingCompanies: async () => [],
    saveShippingCompany: async (c: any) => c,
    deleteShippingCompany: async (id: string) => true,
    savePurchaseReturn: async (r: any) => {
        const db = getDb();
        r.id = `pr-${Date.now()}`;
        r.date = new Date().toISOString();
        db.purchaseReturns.unshift(r);
        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        logTransaction(db, 'income', r.totalRecovered, `رد مبلغ لمرتجع مشتريات #${r.originalPurchaseId}`, r.treasuryId);
        saveDb(db);
        return r;
    },
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getPartners: async () => getDb().partners || [],
    savePartner: async (p: any) => {
        const db = getDb();
        if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? p : item);
        else { p.id = `par-${Date.now()}`; db.partners.push(p); }
        saveDb(db);
        return p;
    },
    getNotifications: async () => getDb().notifications || [],
    addNotification: async (n: any) => {
        const db = getDb();
        const notification = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n };
        if (!db.notifications) db.notifications = [];
        db.notifications.unshift(notification);
        saveDb(db);
        return notification;
    },
    getBackupData: async () => JSON.stringify(getDb()),
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const todayStr = new Date().toISOString().split('T')[0];
        const salesToday = db.sales.filter((s:any) => s.status !== 'Draft' && s.date.startsWith(todayStr));
        return { 
            totalSalesToday: salesToday.reduce((a:any, b:any) => a + b.total, 0), 
            todaysTransactions: salesToday.length, 
            totalReceivables: db.customers.reduce((a:any, b:any) => a + (b.debt || 0), 0), 
            totalStockValue: db.products.reduce((a:any, b:any) => a + (b.stock * b.costPrice), 0), 
            monthlySales: [], salesByCategory: [], topProducts: [] 
        };
    },
    getSyncLogs: async () => [],
    getQueueCount: async () => 0,
    processQueue: async () => true,
    setOnlineStatus: (s: boolean) => {},
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    submitFeedback: async (f: any) => true,
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any) => {
        const db = getDb();
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        st.id = `st-${Date.now()}`;
        st.date = new Date().toISOString();
        if (!db.stockTransfers) db.stockTransfers = [];
        db.stockTransfers.unshift(st);
        saveDb(db);
        return true;
    },
    updateSale: async (id: string, d: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...d } : s);
        saveDb(db);
        return true;
    },
    updatePurchase: async (id: string, d: any) => {
        const db = getDb();
        db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...d } : p);
        saveDb(db);
        return true;
    },
    updateSystemVersion: async (v: string, p: any) => true,
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    wipeBusinessData: async () => { 
        localStorage.removeItem(DB_KEY); 
    }
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, Warehouse, Treasury, PaymentDetail, User } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import { Search, ShoppingCart, Trash2, Plus, Minus, User as UserIcon, Warehouse as WhIcon, Wallet, Percent, Truck, UserPlus, Gift, CreditCard, DollarSign, FileText } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';
import SplitPaymentModal from '../components/pos/SplitPaymentModal';
import InstallmentSetupModal from '../components/sales/InstallmentSetupModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();
    const [searchParams] = useSearchParams();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [users, setUsers] = useState<User[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [selectedRepId, setSelectedRepId] = useState('');
    const [customerQuery, setCustomerQuery] = useState('');
    const [showCustResults, setShowCustResults] = useState(false);
    const [isNewCustModalOpen, setIsNewCustModalOpen] = useState(false);

    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [shippingCost, setShippingCost] = useState(0);
    const [pointsToRedeem, setPointsToRedeem] = useState(0);

    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [showSplitModal, setShowSplitModal] = useState(false);
    const [showInstallmentModal, setShowInstallmentModal] = useState(false);
    const [pendingSplitPayments, setPendingSplitPayments] = useState<PaymentDetail[] | null>(null);

    const editSaleId = searchParams.get('edit');

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t, u, allSales] = await Promise.all([
                api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries(), api.getUsers(), api.getSales()
            ]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t); setUsers(u);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
            if (editSaleId) {
                const saleToEdit = allSales.find((s:any) => s.id === editSaleId);
                if (saleToEdit) { 
                    setCart(saleToEdit.items); 
                    setSelectedCustomerId(saleToEdit.customer.id); 
                    setGlobalDiscount(saleToEdit.discount); 
                    setGlobalDiscountType(saleToEdit.discountType); 
                    setShippingCost(saleToEdit.shipping); 
                    setSelectedWhId(saleToEdit.warehouseId); 
                    setSelectedTrId(saleToEdit.treasuryId); 
                    setSelectedRepId(saleToEdit.representativeId || '');
                }
            }
        };
        load();
    }, [editSaleId]);

    const selectedCustomer = useMemo(() => customers.find(c => c.id === selectedCustomerId), [customers, selectedCustomerId]);

    const subtotal = useMemo(() => cart.reduce((s, i) => {
        const price = i.sellPrice || 0;
        const discount = i.discountPercent ? (price * i.discountPercent / 100) : 0;
        return s + ((price - discount) * i.quantity);
    }, 0), [cart]);

    const discountVal = useMemo(() => globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount, [subtotal, globalDiscount, globalDiscountType]);
    const finalTotal = Math.max(0, subtotal - discountVal + shippingCost);

    const handleCheckout = async (method: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit', payments?: PaymentDetail[], plan?: any, isDraft: boolean = false) => {
        if (!cart.length || !selectedWhId || !selectedTrId) { addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning'); return; }

        try {
            const amountPaid = method === 'Split' ? (payments?.filter(p => p.method !== 'Credit').reduce((a, b) => a + b.amount, 0) || 0) : (method === 'Credit' ? 0 : finalTotal);
            const res = await api.saveSale({
                id: editSaleId || undefined,
                status: isDraft ? 'Draft' : 'Completed',
                customer: { id: selectedCustomerId, name: selectedCustomer?.name },
                cashier: { id: 'u-1', name: 'المدير' },
                representativeId: selectedRepId,
                items: cart,
                subtotal, total: finalTotal, amountPaid,
                paymentMethod: method, discount: globalDiscount, discountType: globalDiscountType,
                shipping: shippingCost, warehouseId: selectedWhId, treasuryId: selectedTrId,
                payments: payments || (method !== 'Split' ? [{ method: method as any, amount: finalTotal }] : []),
                installmentPlan: plan
            });
            if (!isDraft) {
                setLastSale(res); setShowReceipt(true); 
            }
            addToast(isDraft ? 'تم حفظ المسودة بنجاح' : 'تمت العملية بنجاح', 'success');
            setCart([]); setGlobalDiscount(0); setShippingCost(0);
        } catch (e: any) { addToast(e.message || 'فشل إتمام العملية', 'error'); }
    };

    const addToCart = (p: Product) => {
        setCart(prev => {
            const ex = prev.find(i => i.id === p.id);
            if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
            return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice, discountPercent: 0 }];
        });
        setSearchTerm('');
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 flex-shrink-0">
                <div className="lg:col-span-3">
                    <select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="w-full h-12 px-4 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black text-xs outline-none">
                        {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                    </select>
                </div>
                <div className="lg:col-span-5 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-12 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black outline-none shadow-sm"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                <button key={p.id} onClick={() => addToCart(p)} className="w-full p-3 border-b dark:border-slate-700 flex justify-between hover:bg-indigo-50 font-black text-xs">
                                    <span>{p.name}</span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>
                <div className="lg:col-span-4 flex gap-2">
                    <select value={selectedRepId} onChange={e => setSelectedRepId(e.target.value)} className="flex-1 h-12 px-4 rounded-2xl bg-indigo-50 border-indigo-200 dark:bg-slate-900 font-bold text-xs outline-none">
                        <option value="">-- المندوب (العمولة) --</option>
                        {users.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                    </select>
                </div>
            </div>

            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 shadow-sm overflow-hidden flex flex-col">
                <div className="bg-slate-50 dark:bg-slate-800/50 px-6 py-2 border-b dark:border-slate-700 grid grid-cols-12 text-[10px] font-black text-slate-400 uppercase">
                    <div className="col-span-6">المنتج</div>
                    <div className="col-span-2 text-center">السعر</div>
                    <div className="col-span-2 text-center">الكمية</div>
                    <div className="col-span-2 text-end">الإجمالي</div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2">
                    {cart.map(item => (
                        <div key={item.id} className="grid grid-cols-12 gap-2 items-center p-2.5 bg-slate-50 dark:bg-slate-800/40 rounded-xl border border-slate-100 dark:border-slate-700/50">
                            <div className="col-span-6 flex flex-col">
                                <span className="font-black text-xs truncate">{item.name}</span>
                                <span className="text-[10px] text-slate-400">الوحدة: {products.find(p=>p.id===item.id)?.unit || 'قطعة'}</span>
                            </div>
                            <div className="col-span-2 font-black text-xs text-center text-indigo-600">{formatAmount(item.sellPrice)}</div>
                            <div className="col-span-2 flex items-center justify-center gap-2">
                                <button onClick={() => setCart(cart.map(i => i.id === item.id ? {...i, quantity: Math.max(1, i.quantity - 1)} : i))}><Minus size={12}/></button>
                                <span className="font-black text-xs">{toArabicIndic(item.quantity)}</span>
                                <button onClick={() => setCart(cart.map(i => i.id === item.id ? {...i, quantity: i.quantity + 1} : i))}><Plus size={12}/></button>
                            </div>
                            <div className="col-span-2 text-end font-black text-xs">
                                {formatAmount(item.sellPrice * item.quantity)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 p-4 shadow-xl flex-shrink-0">
                <div className="grid grid-cols-2 md:grid-cols-6 gap-3 items-end">
                    <div className="col-span-1">
                        <label className="text-[10px] font-black text-slate-400">العميل</label>
                        <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full h-10 border rounded-xl font-bold text-xs">
                            {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                    </div>
                    <div className="col-span-1">
                        <label className="text-[10px] font-black text-slate-400">الخصم</label>
                        <input type="number" value={globalDiscount || ''} onChange={e => setGlobalDiscount(parseFloat(e.target.value)||0)} className="w-full h-10 border rounded-xl font-bold text-xs" />
                    </div>
                    <div className="bg-indigo-600 text-white p-2 rounded-2xl flex flex-col items-center justify-center shadow-lg h-14 col-span-1">
                        <span className="text-[8px] font-black opacity-70 uppercase">الصافي</span>
                        <span className="text-sm font-black">{formatCurrency(finalTotal, settings?.currency)}</span>
                    </div>
                    <div className="flex gap-2 col-span-3">
                        <Button onClick={() => handleCheckout('Cash')} className="bg-emerald-500 h-14 flex-1 rounded-xl text-xs font-black shadow-lg">إتمام كاش</Button>
                        <Button onClick={() => handleCheckout('Credit')} className="bg-amber-500 h-14 flex-1 rounded-xl text-xs font-black shadow-lg">بيع آجل</Button>
                        <Button onClick={() => handleCheckout('Cash', undefined, undefined, true)} variant="secondary" className="h-14 flex-1 rounded-xl text-xs font-black"><FileText size={16}/></Button>
                    </div>
                </div>
            </div>

            <ReceiptModal isOpen={showReceipt} onClose={() => setShowReceipt(false)} sale={lastSale} />
        </div>
    );
};

export default PosPage;

import React, { useState, useEffect, useRef } from 'react';
import type { Product, ProductUnit } from '../../types';
import Button from '../ui/Button';
import { Wand2, AlertCircle } from 'lucide-react';

interface ProductFormProps {
  product: Product | null;
  onSave: (product: Omit<Product, 'id'> & { id?: string }) => void;
  onCancel: () => void;
  isLoading: boolean;
  error?: string;
}

const ProductForm: React.FC<ProductFormProps> = ({ product, onSave, onCancel, isLoading, error }) => {
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    sku: '',
    stock: 0,
    reorderLevel: 10,
    costPrice: 0,
    sellPrice: 0,
    unit: 'Piece' as ProductUnit,
    description: '',
    imageUrl: '',
    isFeatured: false,
    expiryDate: '',
    hasVariants: false,
    isSerialized: false,
  });

  useEffect(() => {
    if (product) {
      setFormData({
        name: product.name,
        category: product.category,
        sku: product.sku,
        stock: product.stock,
        reorderLevel: product.reorderLevel,
        costPrice: product.costPrice,
        sellPrice: product.sellPrice,
        unit: product.unit || 'Piece',
        description: product.description || '',
        imageUrl: product.imageUrl || '',
        isFeatured: product.isFeatured || false,
        expiryDate: product.expiryDate || '',
        hasVariants: product.hasVariants || false,
        isSerialized: product.isSerialized || false,
      });
    }
  }, [product]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
        setFormData(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setFormData(prev => ({ ...prev, [name]: type === 'number' ? parseFloat(value) || 0 : value }));
    }
  };

  const inputStyle = "mt-1 block w-full rounded-xl border-slate-300 dark:border-slate-600 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 bg-white dark:bg-slate-800 dark:text-white p-2.5 border transition-all";

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave({ ...formData, id: product?.id }); }} className="space-y-5 animate-fadeIn">
      {error && <div className="p-4 mb-4 text-sm text-red-800 rounded-xl bg-red-50 flex items-center gap-2 border border-red-100"><AlertCircle size={20} /> {error}</div>}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">اسم المنتج</label>
            <input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputStyle} />
          </div>
          <div>
            <label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">الفئة</label>
            <input type="text" name="category" value={formData.category} onChange={handleChange} required className={inputStyle} />
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">الباركود (SKU)</label>
          <input type="text" name="sku" value={formData.sku} onChange={handleChange} required className={inputStyle} />
        </div>
        <div>
          <label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">وحدة الصنف</label>
          <select name="unit" value={formData.unit} onChange={handleChange} className={inputStyle}>
            <option value="Piece">قطعة</option>
