import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Transaction, Treasury } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import TransactionFormModal from '../components/treasury/TransactionFormModal';
import { PlusCircle, Wallet, RefreshCw, ArrowRightLeft, Search } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useAuth } from '../hooks/useAuth';
import TreasurySkeleton from '../components/treasury/TreasurySkeleton';
import { useToasts } from '../hooks/useToasts';

const TreasuryPage: React.FC = () => {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // Transfer State
    const [transferFrom, setTransferFrom] = useState('');
    const [transferTo, setTransferTo] = useState('');
    const [transferAmount, setTransferAmount] = useState(0);
    const [transferDesc, setTransferDesc] = useState('تحويل بين الخزائن');

    const { settings } = useSettings();
    const { userHasPermission } = useAuth();
    const { addToast } = useToasts();

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [transData, treasuryData] = await Promise.all([
                api.getTransactions(),
                api.getTreasuries()
            ]);
            setTransactions(transData || []);
            setTreasuries(treasuryData || []);
        } catch (e) {
            addToast("فشل تحميل البيانات", "error");
        } finally {
            setLoading(false);
        }
    }, [addToast]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleTransfer = async () => {
        if (!transferFrom || !transferTo || transferAmount <= 0) {
            addToast("يرجى ملء جميع بيانات التحويل بشكل صحيح", "warning");
            return;
        }
        if (transferFrom === transferTo) {
            addToast("لا يمكن التحويل لنفس الخزينة", "error");
            return;
        }
        setIsSaving(true);
        try {
            await api.transferFunds(transferFrom, transferTo, transferAmount, transferDesc);
            await fetchData();
            setIsTransferModalOpen(false);
            addToast("تم التحويل بنجاح", "success");
        } catch (e) {
            addToast("فشل عملية التحويل", "error");
        } finally {
            setIsSaving(false);
        }
    };

    if (loading || !settings) return <TreasurySkeleton />;

    return (
        <div className="animate-fadeIn">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h1 className="text-3xl font-black text-slate-800 dark:text-white">الخزينة والتحويلات</h1>
                <div className="flex gap-3">
                    <Button onClick={() => setIsTransferModalOpen(true)} variant="secondary" className="rounded-2xl font-black shadow-sm">
                        <ArrowRightLeft size={18} /> تحويل بين الخزائن
                    </Button>
                    <Button onClick={() => setIsModalOpen(true)} className="rounded-2xl font-black shadow-lg shadow-indigo-500/20">
                        <PlusCircle size={18} /> تسجيل حركة
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                {treasuries.map(t => (
                    <div key={t.id} className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 shadow-sm hover:border-indigo-200 transition-all">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-2xl text-indigo-600"><Wallet size={24} /></div>
                            <h4 className="font-black text-slate-800 dark:text-white text-lg">{t.name}</h4>
                        </div>
                        <p className="text-2xl font-black text-indigo-600 dark:text-indigo-400 mt-4">{formatCurrency(t.balance || 0, t.currency || settings.currency)}</p>
                    </div>
                ))}
            </div>

            <Card title="آخر الحركات المالية" className="p-0 overflow-hidden shadow-premium">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-start">
                        <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                            <tr>
                                <th className="px-6 py-4">التاريخ</th><th className="px-6 py-4">النوع</th><th className="px-6 py-4">البيان</th><th className="px-6 py-4">المبلغ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y dark:divide-slate-800">
                            {transactions.map(t => (
                                <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                                    <td className="px-6 py-4 font-bold">{new Date(t.date).toLocaleDateString('ar-EG')}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 text-[10px] font-black rounded-full ${t.type === 'income' ? 'bg-emerald-100 text-emerald-700' : t.type === 'expense' ? 'bg-rose-100 text-rose-700' : 'bg-blue-100 text-blue-700'}`}>
                                            {t.type === 'income' ? 'إيداع' : t.type === 'expense' ? 'سحب' : 'تحويل'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 font-medium">{t.description}</td>
                                    <td className={`px-6 py-4 font-black text-lg ${t.type === 'income' ? 'text-emerald-600' : t.type === 'expense' ? 'text-rose-600' : 'text-blue-600'}`}>
                                        {formatCurrency(t.amount || 0, settings.currency)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </Card>

            <Modal isOpen={isTransferModalOpen} onClose={() => setIsTransferModalOpen(false)} title="تحويل نقدي بين الخزائن">
                <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="text-xs font-black block mb-1">من خزينة</label>
                            <select value={transferFrom} onChange={e => setTransferFrom(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-700 font-bold">
                                <option value="">-- اختر --</option>
                                {treasuries.map(t => <option key={t.id} value={t.id}>{t.name} (رصيد: {formatCurrency(t.balance, t.currency)})</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="text-xs font-black block mb-1">إلى خزينة</label>
                            <select value={transferTo} onChange={e => setTransferTo(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-700 font-bold">
                                <option value="">-- اختر --</option>
                                {treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                            </select>
                        </div>
                    </div>
                    <div>
                        <label className="text-xs font-black block mb-1">المبلغ المراد تحويله</label>
                        <input type="number" value={transferAmount} onChange={e => setTransferAmount(parseFloat(e.target.value)||0)} className="w-full p-3 border rounded-xl font-black text-lg" />
                    </div>
                    <div>
                        <label className="text-xs font-black block mb-1">البيان</label>
                        <input type="text" value={transferDesc} onChange={e => setTransferDesc(e.target.value)} className="w-full p-2.5 border rounded-xl dark:bg-slate-700" />
                    </div>
                    <div className="flex justify-end gap-2 pt-4">
                        <Button variant="secondary" onClick={() => setIsTransferModalOpen(false)}>إلغاء</Button>
                        <Button onClick={handleTransfer} isLoading={isSaving} className="bg-indigo-600 px-8">تأكيد التحويل</Button>
                    </div>
                </div>
            </Modal>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="تسجيل حركة خزينة">
                <TransactionFormModal transaction={null} onSave={async (d) => { await api.saveTransaction(d); await fetchData(); setIsModalOpen(false); }} onCancel={() => setIsModalOpen(false)} isLoading={isSaving} />
            </Modal>
        </div>
    );
};

export default TreasuryPage;

