    setLoading(false);
  }, []);

  useEffect(() => { fetchCustomers(); }, [fetchCustomers]);

  const handleSaveCustomer = async (data: any) => {
    setIsSaving(true);
    try {
      await api.saveCustomer(data);
      await fetchCustomers();
      addToast('تم الحفظ بنجاح.', 'success');
      setIsModalOpen(false);
    } catch (e) { addToast("فشل الحفظ", 'error'); } finally { setIsSaving(false); }
  };

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (event) => {
          try {
              const text = event.target?.result as string;
              const rows = text.split('\n').slice(1);
              for (const row of rows) {
                  const [name, phone, tier, limit] = row.split(',');
                  if (name && phone) {
                      await api.saveCustomer({ name: name.trim(), phone: phone.trim(), tier: (tier?.trim() || 'Regular') as any, creditLimit: parseFloat(limit) || 0 });
                  }
              }
              await fetchCustomers();
              addToast('تم استيراد العملاء بنجاح', 'success');
          } catch (e) { addToast('فشل الاستيراد', 'error'); }
      };
      reader.readAsText(file);
  };

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()) || c.phone.includes(searchTerm));
  }, [customers, searchTerm]);

  return (
    <div className="animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-black text-slate-800 dark:text-white">إدارة العملاء</h1>
        <div className="flex gap-2">
            <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleImportCSV} />
            <Button onClick={() => fileInputRef.current?.click()} variant="secondary" className="rounded-xl"><Upload size={18} /> استيراد CSV</Button>
            <Button onClick={() => { setEditingCustomer(null); setIsModalOpen(true); }} className="rounded-xl"><PlusCircle size={18} /> إضافة عميل</Button>
        </div>
      </div>
      <Card className="p-0 border-none shadow-premium">
        {loading ? <TableSkeleton cols={5} /> : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-start">
              <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-400 text-[10px] font-black uppercase">
                <tr><th className="px-6 py-4">العميل</th><th className="px-6 py-4">الهاتف</th><th className="px-6 py-4">المديونية</th><th className="px-6 py-4">حد الائتمان</th><th className="px-6 py-4 text-center">إجراءات</th></tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-800">
                {filteredCustomers.map((c) => (
                  <tr key={c.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40">
                    <td className="px-6 py-4 font-bold flex flex-col">
                        {c.name}
                        <div className="mt-1"><TierBadge tier={c.tier} /></div>
                    </td>
                    <td className="px-6 py-4 font-mono">{c.phone}</td>
                    <td className={`px-6 py-4 font-black ${c.debt > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{formatCurrency(c.debt, settings?.currency || 'SAR')}</td>
                    <td className="px-6 py-4 font-bold text-slate-400">{c.creditLimit ? formatCurrency(c.creditLimit, settings?.currency || 'SAR') : '---'}</td>
                    <td className="px-6 py-4 text-center">
                       <div className="flex justify-center gap-2">
                        <button onClick={() => {setDetailsCustomer(c); setIsDetailsOpen(true);}} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg"><FileText size={18}/></button>
                        <button onClick={() => {setEditingCustomer(c); setIsModalOpen(true);}} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Edit size={18}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="بيانات العميل"><CustomerForm customer={editingCustomer} onSave={handleSaveCustomer} onCancel={() => setIsModalOpen(false)} isLoading={isSaving}/></Modal>
      <CustomerDetailsModal isOpen={isDetailsOpen} onClose={() => setIsDetailsOpen(false)} customer={detailsCustomer} />
    </div>
  );
};

