        const db = getDb();
        const u = db.users.find((u: any) => u.id === id);
        return u && u.password === pass;
    },
    saveUser: async (user: any) => {
        const db = getDb();
        if (user.id) {
            db.users = db.users.map((u: any) => u.id === user.id ? { ...u, ...user } : u);
        } else {
            user.id = `user-${Date.now()}`;
            db.users.push(user);
        }
        saveDb(db);
        return user;
    },
    // FIX: Add missing sales return methods
    saveSalesReturn: async (ret: any) => {
        const db = getDb();
        ret.id = `ret-${Date.now()}`;
        ret.date = new Date().toISOString();
        if (!db.salesReturns) db.salesReturns = [];
        db.salesReturns.unshift(ret);

        // Update stock
        ret.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        logTransaction(db, 'expense', ret.totalRefund, `رد مبلغ لمرتجع مبيعات #${ret.originalSaleId}`, ret.treasuryId);
        saveDb(db);
        return ret;
    },
    deleteSalesReturn: async (id: string) => {
        const db = getDb();
        const ret = db.salesReturns.find((r: any) => r.id === id);
        if (ret) {
            // Reverse stock
            ret.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.id);
                if (p) {
                    if (!p.warehouseStocks) p.warehouseStocks = {};
                    p.warehouseStocks[ret.warehouseId] = (p.warehouseStocks[ret.warehouseId] || 0) - item.returnQuantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
                }
            });
            // Reverse transaction
            logTransaction(db, 'income', ret.totalRefund, `تراجع عن مرتجع مبيعات #${ret.id}`, ret.treasuryId);
            db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id);
            saveDb(db);
            return true;
        }
        return false;
    },
    // FIX: Add missing employee performance analytics method
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const sales = db.sales.filter((s: any) => s.status !== 'Draft');
        const returns = db.salesReturns || [];

        const performanceMap: Record<string, EmployeePerformanceData> = {};

        db.users.forEach((u: any) => {
            performanceMap[u.id] = {
                userId: u.id,
                userName: u.name,
                totalSalesValue: 0,
                totalSalesCount: 0,
                averageSaleValue: 0,
                totalReturnsValue: 0,
                returnRate: 0
            };
        });

        sales.forEach((s: any) => {
            const data = performanceMap[s.cashier.id];
            if (data) {
                data.totalSalesValue += s.total;
                data.totalSalesCount += 1;
            }
        });

        returns.forEach((r: any) => {
            const originalSale = sales.find((s: any) => s.id === r.originalSaleId);
            if (originalSale) {
                const data = performanceMap[originalSale.cashier.id];
                if (data) {
                    data.totalReturnsValue += r.totalRefund;
                }
            }
        });

        const performanceData = Object.values(performanceMap).map(d => {
            d.averageSaleValue = d.totalSalesCount > 0 ? d.totalSalesValue / d.totalSalesCount : 0;
            d.returnRate = d.totalSalesValue > 0 ? (d.totalReturnsValue / d.totalSalesValue) * 100 : 0;
            return d;
        });

        return {
            performanceData,
            topPerformerByValue: [...performanceData].sort((a, b) => b.totalSalesValue - a.totalSalesValue)[0],
            topPerformerByCount: [...performanceData].sort((a, b) => b.totalSalesCount - a.totalSalesCount)[0],
        };
    },
};

