const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5 }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' } },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.partners) parsed.partners = [];
        if (!parsed.purchaseReturns) parsed.purchaseReturns = [];
        if (!parsed.users) parsed.users = defaultDb.users;
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({
        id: `act-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    });
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer', amount: number, description: string, treasuryId: string, toTreasuryId?: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'transfer' && toTreasuryId) {
            const toT = db.treasuries.find((item: any) => item.id === toTreasuryId);
            if (toT) {
                t.balance -= amount;
                toT.balance += amount;
            }
        } else {
            t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        }

        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: type === 'income' ? 'مبيعات/تحصيل' : type === 'expense' ? 'مشتريات/مصاريف' : 'تحويل داخلي',
            user: 'النظام',
            treasuryId,
            toTreasuryId
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p, warehouseStocks: p.warehouseStocks || item.warehouseStocks } : item);
        } else { 
            p.id = `prod-${Date.now()}`; 
            db.products.push(p); 
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        // فحص حد الائتمان للبيع الآجل
        if (sale.paymentMethod === 'Credit' && customer && customer.creditLimit > 0) {
            const newDebt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            if (newDebt > customer.creditLimit) {
                throw new Error(`تجاوز العميل حد الائتمان المسموح به (${customer.creditLimit}).`);
            }
        }

        if (sale.status === 'Draft') {
            sale.id = sale.id || `DRFT-${Date.now()}`;
            sale.date = new Date().toISOString();
            db.sales.unshift(sale);
            saveDb(db); return sale;
        }

        if (sale.id) db.sales = db.sales.filter((s: any) => s.id !== sale.id);

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString() };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) logTransaction(db, 'income', sale.amountPaid, `دفعة مبيعات #${id}`, sale.treasuryId);

        if (customer) {
            const creditAmount = sale.total - sale.amountPaid;
            if (creditAmount > 0) customer.debt = (customer.debt || 0) + creditAmount;
        }

        saveDb(db); return finalSale;
    },
    getCustomers: async () => getDb().customers,
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) db.customers = db.customers.map((item: any) => item.id === c.id ? { ...item, ...c, debt: item.debt, points: item.points } : item);
        else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); }
        saveDb(db); return c;
    },
    getPurchases: async () => getDb().purchases,
    savePurchase: async (pur: any) => {
        const db = getDb();
        if (pur.id) db.purchases = db.purchases.filter((p: any) => p.id !== pur.id);
        pur.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[pur.warehouseId] = (p.warehouseStocks[pur.warehouseId] || 0) + item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        pur.id = pur.id || `pur-${Date.now()}`;
        pur.date = new Date().toISOString();
        db.purchases.unshift(pur);
        if (pur.amountPaid > 0) logTransaction(db, 'expense', pur.amountPaid, `دفعة مشتريات #${pur.id}`, pur.treasuryId);
        saveDb(db); return pur;
    },
    getFinancialReport: async (start: string, end: string, category?: string, cashierId?: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => s.status !== 'Draft' && (!start || s.date >= start) && (!end || s.date <= end));
        const expenses = (db.transactions || []).filter((t:any) => t.type === 'expense' && (!start || t.date >= start) && (!end || t.date <= end));
        let totalRevenue = 0, totalCOGS = 0, totalTax = 0;
        const prodProfitMap: Record<string, { name: string, profit: number }> = {};
        sales.forEach((s: any) => {
            totalRevenue += s.total;
            totalTax += s.vatAmount || 0;
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                const cost = (prod?.costPrice || 0) * item.quantity;
                const profit = (item.sellPrice * item.quantity) - cost;
                totalCOGS += cost;
                if (!prodProfitMap[item.id]) prodProfitMap[item.id] = { name: item.name, profit: 0 };
                prodProfitMap[item.id].profit += profit;
            });
        });
        const totalExpenses = expenses.reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - totalExpenses;
        return { 
            totalRevenue, totalCOGS, totalExpenses, totalTax, netProfit, 
            productProfits: Object.entries(prodProfitMap).map(([id, d]) => ({ id, name: d.name, profit: d.profit })),
            dailyStats: [] 
        };
    },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => {
        const db = getDb();
        logTransaction(db, 'transfer', amount, desc, fromId, toId);
        saveDb(db); return true;
    },
    getTransactions: async () => getDb().transactions,
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getInstallmentPlans: async () => getDb().installments || [],
    getCurrentShift: async (uid: string) => getDb().shifts.find((s:any) => s.userId === uid && s.status === 'Open') || null,
    openShift: async (uid: string, a: number) => { const db = getDb(); const s = { id: `sh-${Date.now()}`, userId: uid, startTime: new Date().toISOString(), startCash: a, status: 'Open' }; db.shifts.push(s); saveDb(db); return s; },
    closeShift: async (id: string, a: number, n?: string) => { 
        const db = getDb(); const s = db.shifts.find((i:any)=>i.id===id); 
        if(s){ s.status='Closed'; s.endTime=new Date().toISOString(); s.endCash=a; s.notes=n; } 
        saveDb(db); return s; 
    },
    getUsers: async () => getDb().users,
    login: async (name: string, pass: string) => { const db = getDb(); return db.users.find((u: any) => u.name === name && u.password === pass) || null; },
    verifyPassword: async (id: string, pass: string) => { const db = getDb(); const u = db.users.find((u: any) => u.id === id); return u && u.password === pass; },
    saveUser: async (user: any) => { const db = getDb(); if (user.id) db.users = db.users.map((u: any) => u.id === user.id ? { ...u, ...user } : u); else { user.id = `user-${Date.now()}`; db.users.push(user); } saveDb(db); return user; },
    getSuppliers: async () => getDb().suppliers,
    saveSupplier: async (s: any) => { const db = getDb(); s.id = s.id || `sup-${Date.now()}`; db.suppliers.push(s); saveDb(db); return s; },
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s:any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => (getDb().salesReturns || []).filter((r:any) => { const s = getDb().sales.find((s:any)=>s.id === r.originalSaleId); return s?.customer.id === id; }),
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (st: any) => {
        const db = getDb(); const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) { if (!p.warehouseStocks) p.warehouseStocks = {}; p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity; p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity; p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0); }
        st.id = `st-${Date.now()}`; st.date = new Date().toISOString(); if (!db.stockTransfers) db.stockTransfers = []; db.stockTransfers.unshift(st); saveDb(db); return true;
    },
    getSales: async () => getDb().sales,
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb(); const todayStr = new Date().toISOString().split('T')[0];
        const salesToday = db.sales.filter((s:any) => s.status !== 'Draft' && s.date.startsWith(todayStr));
        return { 
            totalSalesToday: salesToday.reduce((a:any, b:any) => a + b.total, 0), 
            todaysTransactions: salesToday.length, 
            totalReceivables: db.customers.reduce((a:any, b:any) => a + (b.debt || 0), 0), 
            totalStockValue: db.products.reduce((a:any, b:any) => a + (b.stock * b.costPrice), 0), 
            monthlySales: [], salesByCategory: [], topProducts: [] 
        };
    },
    saveTreasury: async (t: any) => { const db = getDb(); t.id = t.id || `t-${Date.now()}`; db.treasuries.push(t); saveDb(db); return t; },
    saveTransaction: async (tr: any) => { const db = getDb(); tr.id = `tr-${Date.now()}`; db.transactions.unshift(tr); saveDb(db); return tr; },
    saveWarehouse: async (w: any) => { const db = getDb(); w.id = w.id || `w-${Date.now()}`; db.warehouses.push(w); saveDb(db); return w; },
    addNotification: async (n: any) => { const db = getDb(); const notification = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n }; if (!db.notifications) db.notifications = []; db.notifications.unshift(notification); saveDb(db); return notification; },
    getNotifications: async () => getDb().notifications || [],
    wipeBusinessData: async () => { localStorage.removeItem(DB_KEY); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    getBackupData: async () => JSON.stringify(getDb()),
};

import React, { useState, useEffect, useCallback } from 'react';
import { Outlet, Navigate, useNavigate } from 'react-router-dom';
import Header from './Header';
import Sidebar from './Sidebar';
import { useAuth } from '../../hooks/useAuth';
import { useLicense } from '../../hooks/useLicense';
import { useSettings } from '../../hooks/useSettings';
import SplashScreen from './SplashScreen';
import ToastContainer from '../ui/ToastContainer';
import { AlertTriangle } from 'lucide-react';
import { api } from '../../services/mockApi';
import { useToasts } from '../../hooks/useToasts';

const MainLayout: React.FC = () => {
  const { user, isLoading: authLoading } = useAuth();
  const { isLicensed, isLoading: licenseLoading, licenseInfo } = useLicense();
  const { settings, updateSettings } = useSettings();
  const { addToast } = useToasts();
  const navigate = useNavigate();

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // الكشف عن اختصارات الكيبورد
  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

    switch(e.key) {
        case 'F1': e.preventDefault(); navigate('/pos'); break;
        case 'F2': e.preventDefault(); navigate('/products'); break;
        case 'F4': e.preventDefault(); navigate('/customers'); break;
        case 'F8': e.preventDefault(); navigate('/treasury'); break;
        case 'F9': e.preventDefault(); navigate('/reports'); break;
        case 'F10': e.preventDefault(); navigate('/settings'); break;
        case 'Escape': setSidebarOpen(false); break;
    }
  }, [navigate]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  useEffect(() => {
      const savedCollapsed = localStorage.getItem('sidebar_collapsed');
      if (savedCollapsed) {
          setIsSidebarCollapsed(JSON.parse(savedCollapsed));
      }
  }, []);

  const toggleSidebarCollapse = () => {
      const newState = !isSidebarCollapsed;
      setIsSidebarCollapsed(newState);
      localStorage.setItem('sidebar_collapsed', JSON.stringify(newState));
  };

  useEffect(() => {
      if (!settings) return;

      const checkSystemEvents = async () => {
          const todayStr = new Date().toISOString().split('T')[0];
          const lastCheckDate = localStorage.getItem('pos_last_system_check_date');

          if (lastCheckDate === todayStr) return;

          const isPaidLicense = !['Free', 'Trial'].includes(licenseInfo.type || '');

          if (settings.notificationSettings?.backupReminder !== false && isPaidLicense) {
              const lastBackup = settings.autoBackup?.lastBackupAt || 0;
              const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;
              const timeSinceBackup = Date.now() - lastBackup;

              if (timeSinceBackup > thirtyDaysMs) {
                  await api.addNotification({
                      type: 'PROFIT_ALERT',
                      message: 'تنبيه: لم يتم عمل نسخة احتياطية منذ فترة. يرجى الحفاظ على بياناتك.',
                  });
              }
          }

          if (settings.notificationSettings?.paymentDelays !== false) {
             const allSales = await api.getSales();
             const overdueCount = allSales.filter(s => {
                 if (s.paymentMethod !== 'Credit' || s.status === 'Refunded') return false;
                 const diff = Date.now() - new Date(s.date).getTime();
                 return diff > (30 * 24 * 60 * 60 * 1000);
             }).length;

             if (overdueCount > 0) {
                 await api.addNotification({
                     type: 'PAYMENT_DELAY',
                     message: `يوجد ${overdueCount} فاتورة آجلة متأخرة السداد لأكثر من ٣٠ يوماً.`,
                 });
             }
          }

          localStorage.setItem('pos_last_system_check_date', todayStr);
      };
      checkSystemEvents();
  }, [settings, licenseInfo.type]);

  if (authLoading || licenseLoading) return <SplashScreen />;
  if (!isLicensed) return <Navigate to="/license" replace />;
  if (!user) return <Navigate to="/login" replace />;

  const navStyle = settings?.navigationStyle || 'grid';
  const showSidebar = navStyle === 'sidebar';

  return (
    <div className="flex flex-col min-h-screen text-slate-800 dark:text-slate-200 transition-colors duration-300 bg-transparent">
      {licenseInfo.status === 'GRACE_PERIOD' && (
          <div className="fixed top-0 left-0 right-0 z-[60] bg-yellow-500 text-black px-4 py-1 text-center font-bold flex items-center justify-center gap-2 animate-pulse text-xs">
              <AlertTriangle size={14} />
              <span>تحذير: انتهت صلاحية الترخيص. يرجى التجديد لتجنب فقدان الميزات.</span>
          </div>
      )}
      <Header />
      <div className={`flex flex-1 pt-32 px-4 md:px-6 gap-6 max-w-[1920px] mx-auto w-full`}>
          {showSidebar && (
              <div className={`hidden lg:block flex-shrink-0 relative transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'w-24' : 'w-72'}`}>
                  <Sidebar 
                    sidebarOpen={sidebarOpen} 
                    setSidebarOpen={setSidebarOpen} 
                    isCollapsed={isSidebarCollapsed}
                    toggleCollapse={toggleSidebarCollapse}
                  />
              </div>
          )}
          <main className={`flex-1 min-w-0 pb-10 transition-all duration-300`}>
              <Outlet />
          </main>
      </div>
      <ToastContainer />
      {showSidebar && (
          <div className="lg:hidden">
              <Sidebar sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen} isCollapsed={false} toggleCollapse={() => {}} />
          </div>
      )}
    </div>
  );
};

export default MainLayout;

