import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, Warehouse, Treasury, PaymentDetail, User } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import { Search, ShoppingCart, Trash2, Plus, Minus, User as UserIcon, Warehouse as WhIcon, Wallet, CreditCard, DollarSign } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();
    const [searchParams] = useSearchParams();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [users, setUsers] = useState<User[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [selectedSellerId, setSelectedSellerId] = useState('');
    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);

    useEffect(() => {
        Promise.all([api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries(), api.getUsers()]).then(([p, c, w, t, u]) => {
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t); setUsers(u);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
        });
    }, []);

    const selectedCustomer = customers.find(c => c.id === selectedCustomerId);
    const subtotal = cart.reduce((s, i) => s + (i.sellPrice * i.quantity), 0);
    const discountVal = globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount;
    const finalTotal = Math.max(0, subtotal - discountVal);

    const handleCheckout = async (method: 'Cash' | 'Credit') => {
        if (!cart.length || !selectedWhId || !selectedTrId) { addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning'); return; }
        try {
            const res = await api.saveSale({
                customer: { id: selectedCustomerId, name: selectedCustomer?.name },
                cashier: { id: 'u-1', name: 'المدير' },
                sellerId: selectedSellerId,
                items: cart,
                subtotal, total: finalTotal, amountPaid: method === 'Cash' ? finalTotal : 0,
                paymentMethod: method, discount: globalDiscount, discountType: globalDiscountType,
                warehouseId: selectedWhId, treasuryId: selectedTrId,
                status: 'Completed'
            });
            setLastSale(res); setShowReceipt(true); setCart([]); setGlobalDiscount(0);
            addToast('تمت العملية بنجاح', 'success');
        } catch (e: any) { addToast(e.message || 'فشل إتمام العملية', 'error'); }
    };

    const handleKeyDown = useCallback((e: KeyboardEvent) => {
        if (e.ctrlKey && e.key === 's') { e.preventDefault(); handleCheckout('Cash'); }
    }, [cart, selectedCustomerId, selectedSellerId, selectedWhId, selectedTrId, finalTotal]);

    useEffect(() => {
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [handleKeyDown]);

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 flex-shrink-0">
                <div className="lg:col-span-3"><select value={selectedWhId} onChange={e => setSelectedWhId(e.target.value)} className="w-full h-12 px-4 rounded-2xl border font-black text-xs outline-none bg-white dark:bg-slate-900">{warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></div>
                <div className="lg:col-span-6 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-12 rounded-2xl border font-black outline-none bg-white dark:bg-slate-900 shadow-sm"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border max-h-60 overflow-y-auto">
                            {products.filter(p => p.name.includes(searchTerm) || p.sku.includes(searchTerm)).map(p => (
                                <button key={p.id} onClick={() => { setCart([...cart, { ...p, quantity: 1 }]); setSearchTerm(''); }} className="w-full p-3 border-b text-start hover:bg-indigo-50 font-black text-xs flex justify-between">
                                    <span>{p.name}</span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                        </div>
                    )}
