import React, { useState, useEffect } from 'react';
import type { Customer, CustomerTier } from '../../types';
import Button from '../ui/Button';
import { AlertCircle, CreditCard } from 'lucide-react';

interface CustomerFormProps {
  customer: Customer | null;
  onSave: (customer: Omit<Customer, 'id' | 'debt' | 'points'> & { id?: string }) => void;
  onCancel: () => void;
  isLoading: boolean;
  error?: string;
}

const CustomerForm: React.FC<CustomerFormProps> = ({ customer, onSave, onCancel, isLoading, error }) => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    address: '',
    tier: 'Regular' as CustomerTier,
    creditLimit: 0
  });

  useEffect(() => {
    if (customer) {
      setFormData({
        name: customer.name,
        phone: customer.phone,
        email: customer.email || '',
        address: customer.address || '',
        tier: customer.tier || 'Regular',
        creditLimit: customer.creditLimit || 0
      });
    }
  }, [customer]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'number' ? parseFloat(value) || 0 : value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ ...formData, id: customer?.id });
  };

  const inputStyle = "mt-1 block w-full rounded-xl border-slate-300 shadow-sm focus:border-indigo-600 focus:ring-indigo-600 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white p-2.5 border transition-all";

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {error && (
        <div className="p-4 mb-4 text-sm text-red-800 rounded-lg bg-red-50 flex items-center gap-2" role="alert">
            <AlertCircle size={20} />
            <span className="font-medium">خطأ!</span> {error}
        </div>
      )}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-black text-slate-700 dark:text-slate-200">اسم العميل</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputStyle} />
        </div>
        <div>
          <label className="block text-sm font-black text-slate-700 dark:text-slate-200">تصنيف العميل</label>
          <select name="tier" value={formData.tier} onChange={handleChange} className={inputStyle}>
            <option value="Regular">عادي</option>
            <option value="Wholesale">جملة</option>
            <option value="Retail">قطاعي</option>
            <option value="VIP">VIP</option>
          </select>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-black text-slate-700 dark:text-slate-200">الهاتف</label>
            <input type="tel" name="phone" value={formData.phone} onChange={handleChange} required className={inputStyle} />
          </div>
          <div>
            <label className="block text-sm font-black text-slate-700 dark:text-slate-200 flex items-center gap-1">
                <CreditCard size={14} className="text-indigo-600" /> حد الائتمان (مسموح بالدين حتى)
            </label>
            <input type="number" name="creditLimit" value={formData.creditLimit} onChange={handleChange} className={inputStyle} />
          </div>
      </div>
      <div>
        <label className="block text-sm font-black text-slate-700 dark:text-slate-200">العنوان</label>
        <textarea name="address" value={formData.address} onChange={handleChange} rows={2} className={inputStyle} />
      </div>
      <div className="flex justify-end gap-2 pt-4">
        <Button type="button" variant="secondary" onClick={onCancel} className="rounded-xl">إلغاء</Button>
        <Button type="submit" isLoading={isLoading} className="rounded-xl px-8">{customer ? 'حفظ التعديلات' : 'إضافة العميل'}</Button>
      </div>
    </form>
  );
};

export default CustomerForm;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import type { Customer, CustomerTier } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import CustomerDetailsModal from '../components/customers/CustomerDetailsModal';
import { PlusCircle, Edit, Search, FileText, Crown, Upload, Download } from 'lucide-react';
import { exportToCsv } from '../utils/export';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import TableSkeleton from '../components/ui/TableSkeleton';
import { useToasts } from '../hooks/useToasts';

const CustomersPage: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [detailsCustomer, setDetailsCustomer] = useState<Customer | null>(null);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const { settings } = useSettings();
  const { addToast } = useToasts();

  const fetchCustomers = useCallback(async () => {
    setLoading(true);
    const data = await api.getCustomers();
    setCustomers(data);
    setLoading(false);
  }, []);

  useEffect(() => { fetchCustomers(); }, [fetchCustomers]);

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (event) => {
          try {
              const text = event.target?.result as string;
              const rows = text.split('\n').slice(1);
              for (const row of rows) {
                  const [name, phone, tier, limit] = row.split(',');
                  if (name && phone) await api.saveCustomer({ name: name.trim(), phone: phone.trim(), tier: (tier?.trim() || 'Regular') as any, creditLimit: parseFloat(limit) || 0 });
              }
              await fetchCustomers();
              addToast('تم استيراد العملاء بنجاح', 'success');
          } catch (e) { addToast('فشل الاستيراد', 'error'); }
      };
      reader.readAsText(file);
  };

  const filteredCustomers = useMemo(() => customers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()) || c.phone.includes(searchTerm)), [customers, searchTerm]);

  return (
    <div className="animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-black text-slate-800 dark:text-white">إدارة العملاء</h1>
        <div className="flex gap-2">
            <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleImportCSV} />
            <Button onClick={() => fileInputRef.current?.click()} variant="secondary" className="rounded-xl"><Upload size={18} /> استيراد CSV</Button>
            <Button onClick={() => { setEditingCustomer(null); setIsModalOpen(true); }} className="rounded-xl"><PlusCircle size={18} /> إضافة عميل</Button>
        </div>
      </div>
      <Card className="p-0 border-none shadow-premium">
        {loading ? <TableSkeleton cols={4} hasActions /> : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-start">
              <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-400 text-[10px] font-black uppercase">
                <tr><th className="px-6 py-4">العميل</th><th className="px-6 py-4">الهاتف</th><th className="px-6 py-4">المديونية</th><th className="px-6 py-4">حد الائتمان</th><th className="px-6 py-4 text-center">إجراءات</th></tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-800">
                {filteredCustomers.map((c) => (
                  <tr key={c.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40">
                    <td className="px-6 py-4 font-bold">{c.name}</td>
                    <td className="px-6 py-4 font-mono">{c.phone}</td>
                    <td className={`px-6 py-4 font-black ${c.debt > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{formatCurrency(c.debt, settings?.currency || 'SAR')}</td>
                    <td className="px-6 py-4 font-bold text-slate-400">{c.creditLimit ? formatCurrency(c.creditLimit, settings?.currency || 'SAR') : '---'}</td>
                    <td className="px-6 py-4 text-center">
                       <div className="flex justify-center gap-2">
                        <button onClick={() => {setDetailsCustomer(c); setIsDetailsOpen(true);}} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg"><FileText size={18}/></button>
                        <button onClick={() => {setEditingCustomer(c); setIsModalOpen(true);}} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Edit size={18}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="بيانات العميل"><CustomerForm customer={editingCustomer} onSave={async (d) => { setIsSaving(true); await api.saveCustomer(d); await fetchCustomers(); setIsModalOpen(false); setIsSaving(false); addToast('تم الحفظ', 'success'); }} onCancel={() => setIsModalOpen(false)} isLoading={isSaving}/></Modal>
      <CustomerDetailsModal isOpen={isDetailsOpen} onClose={() => setIsDetailsOpen(false)} customer={detailsCustomer} />
    </div>
  );
};

export default CustomersPage;

import React, { useState, useEffect, useRef } from 'react';
import type { Product, ProductUnit } from '../../types';
import Button from '../ui/Button';
import { AlertCircle } from 'lucide-react';

interface ProductFormProps {
  product: Product | null;
  onSave: (product: Omit<Product, 'id'> & { id?: string }) => void;
  onCancel: () => void;
  isLoading: boolean;
  error?: string;
}

const ProductForm: React.FC<ProductFormProps> = ({ product, onSave, onCancel, isLoading, error }) => {
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    sku: '',
    stock: 0,
    reorderLevel: 10,
    costPrice: 0,
    sellPrice: 0,
    unit: 'Piece' as ProductUnit,
    description: '',
    imageUrl: '',
    isFeatured: false,
    expiryDate: '',
    hasVariants: false,
    isSerialized: false,
  });

  useEffect(() => {
    if (product) {
      setFormData({
        name: product.name,
        category: product.category,
        sku: product.sku,
        stock: product.stock,
        reorderLevel: product.reorderLevel,
        costPrice: product.costPrice,
        sellPrice: product.sellPrice,
        unit: product.unit || 'Piece',
        description: product.description || '',
        imageUrl: product.imageUrl || '',
        isFeatured: product.isFeatured || false,
        expiryDate: product.expiryDate || '',
        hasVariants: product.hasVariants || false,
        isSerialized: product.isSerialized || false,
      });
    }
  }, [product]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') setFormData(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    else setFormData(prev => ({ ...prev, [name]: type === 'number' ? parseFloat(value) || 0 : value }));
  };

  const inputStyle = "mt-1 block w-full rounded-xl border-slate-300 dark:border-slate-600 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 bg-white dark:bg-slate-800 dark:text-white p-2.5 border transition-all";

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave({ ...formData, id: product?.id }); }} className="space-y-5 animate-fadeIn">
      {error && <div className="p-4 mb-4 text-sm text-red-800 rounded-xl bg-red-50 flex items-center gap-2 border border-red-100"><AlertCircle size={20} /> {error}</div>}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">اسم المنتج</label><input type="text" name="name" value={formData.name} onChange={handleChange} required className={inputStyle} /></div>
          <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">الفئة</label><input type="text" name="category" value={formData.category} onChange={handleChange} required className={inputStyle} /></div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">الباركود (SKU)</label><input type="text" name="sku" value={formData.sku} onChange={handleChange} required className={inputStyle} /></div>
        <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">وحدة الصنف</label>
          <select name="unit" value={formData.unit} onChange={handleChange} className={inputStyle}>
            <option value="Piece">قطعة</option>
            <option value="Box">كرتونة</option>
            <option value="KG">كيلو جرام</option>
            <option value="Meter">متر</option>
            <option value="Litre">لتر</option>
            <option value="Set">طقم / مجموعة</option>
          </select>
        </div>
        <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">المخزون</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputStyle} /></div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">سعر التكلفة</label><input type="number" step="0.01" name="costPrice" value={formData.costPrice} onChange={handleChange} required className={inputStyle} /></div>
          <div><label className="block text-sm font-black text-slate-700 dark:text-slate-300 mb-1">سعر البيع</label><input type="number" step="0.01" name="sellPrice" value={formData.sellPrice} onChange={handleChange} required className={inputStyle} /></div>
      </div>
      <div className="flex justify-end gap-3 pt-6 border-t dark:border-slate-700">
        <Button type="button" variant="secondary" onClick={onCancel} className="rounded-xl px-6">إلغاء</Button>
        <Button type="submit" isLoading={isLoading} className="rounded-xl px-10 bg-indigo-600 font-black">{product ? 'تحديث' : 'إضافة'}</Button>
      </div>
    </form>
  );
};

