  return (
    <div className="animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-black text-slate-800 dark:text-white">الموردين</h1>
        <Button onClick={() => { setEditingSupplier(null); setIsModalOpen(true); }} className="rounded-xl"><PlusCircle size={20} /> إضافة مورد</Button>
      </div>
      <Card className="p-0 shadow-premium border-none">
        {loading ? <TableSkeleton cols={4} hasActions /> : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-start">
              <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-400 text-[10px] font-black uppercase">
                <tr><th className="px-6 py-4">المورد</th><th className="px-6 py-4">الهاتف</th><th className="px-6 py-4">مسؤول التواصل</th><th className="px-6 py-4 text-center">إجراءات</th></tr>
