    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let found = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidAt = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';

                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt = Math.max(0, customer.debt - payment.amount);

                const defaultTr = db.treasuries.find((t:any) => t.isDefault) || db.treasuries[0];
                logTransaction(db, 'income', payment.amount, `قسط من ${plan.customerName}`, defaultTr.id);
                found = true;
            }
        });
        saveDb(db);
        return found;
    },
