    // FIX: Added Employee Performance Analytics method
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const users = db.users;
        const sales = db.sales.filter((s:any) => s.status !== 'Draft');
        const returns = db.salesReturns || [];

        const performanceData: EmployeePerformanceData[] = users.map((u: any) => {
            const userSales = sales.filter((s: any) => s.cashier.id === u.id);
            const totalSalesValue = userSales.reduce((a, b) => a + b.total, 0);
            const totalSalesCount = userSales.length;
            const averageSaleValue = totalSalesCount > 0 ? totalSalesValue / totalSalesCount : 0;

            const userReturns = returns.filter((r: any) => r.user?.id === u.id);
            const totalReturnsValue = userReturns.reduce((a, b) => a + b.totalRefund, 0);
            const returnRate = totalSalesValue > 0 ? (totalReturnsValue / totalSalesValue) * 100 : 0;

            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue,
                totalSalesCount,
                averageSaleValue,
                totalReturnsValue,
                returnRate
            };
        });

        return {
            performanceData,
            topPerformerByValue: [...performanceData].sort((a, b) => b.totalSalesValue - a.totalSalesValue)[0],
            topPerformerByCount: [...performanceData].sort((a, b) => b.totalSalesCount - a.totalSalesCount)[0]
        };
    },

