        const returns = db.purchaseReturns || [];

        return suppliers.map((s: any) => {
            const sPurchases = purchases.filter((p: any) => p.supplier.id === s.id);
            const totalPurchaseValue = sPurchases.reduce((a, b) => a + b.total, 0);
            const purchaseCount = sPurchases.length;
            const sReturns = returns.filter((r: any) => r.originalPurchaseId && purchases.find(p => p.id === r.originalPurchaseId)?.supplier.id === s.id);
            const totalReturnValue = sReturns.reduce((a, b) => a + b.totalRecovered, 0);
            const returnRate = totalPurchaseValue > 0 ? (totalReturnValue / totalPurchaseValue) * 100 : 0;

            return {
                supplierId: s.id,
