        const threshold = Date.now() - (days * 24 * 60 * 60 * 1000);

        return customers.map((c: any) => {
            const cSales = sales.filter((s: any) => s.customer.id === c.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
            const lastDate = cSales.length > 0 ? cSales[0].date : null;
            return { id: c.id, name: c.name, phone: c.phone, lastPurchaseDate: lastDate || 'لا يوجد مشتريات' };
        }).filter((c: any) => c.lastPurchaseDate === 'لا يوجد مشتريات' || new Date(c.lastPurchaseDate).getTime() < threshold);
