        const db = getDb();
        const products = db.products;
        const sales = db.sales;
        const threshold = Date.now() - (days * 24 * 60 * 60 * 1000);

        return products.map((p: any) => {
            const pSales = sales.filter((s: any) => s.items.some((i: any) => i.id === p.id)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
            const lastSold = pSales.length > 0 ? pSales[0].date : null;
            const daysSince = lastSold ? Math.floor((Date.now() - new Date(lastSold).getTime()) / (1000 * 60 * 60 * 24)) : 999;
            return { id: p.id, name: p.name, stock: p.stock, lastSoldDate: lastSold, daysSinceLastSale: daysSince };
        }).filter(p => p.daysSinceLastSale >= days && p.stock > 0);
