                const defaultTr = db.treasuries.find((t: any) => t.isDefault) || db.treasuries[0];
                logTransaction(db, 'income', payment.amount, `تحصيل قسط - ${plan.customerName}`, defaultTr.id, 'تحصيل أقساط');
                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt = Math.max(0, (customer.debt || 0) - payment.amount);
                logActivity(db, 'تحصيل قسط', `تحصيل مبلغ ${payment.amount} من العميل ${plan.customerName}`);
