                                            <Tag size={12} className="text-indigo-400" />
                                            {t.category || 'عام'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 font-medium text-xs">{t.description}</td>
                                    <td className={`px-6 py-4 text-end font-black text-lg ${t.type === 'income' ? 'text-emerald-600' : t.type === 'expense' ? 'text-rose-600' : 'text-blue-600'}`}>
                                        {formatCurrency(t.amount || 0, settings.currency)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {transactions.length === 0 && (
                        <div className="p-10 text-center text-slate-400 font-bold">لا يوجد حركات مسجلة حالياً.</div>
                    )}
                </div>
            </Card>

            <Modal isOpen={isTransferModalOpen} onClose={() => setIsTransferModalOpen(false)} title="تحويل نقدي بين الخزائن">
                <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div><label className="text-xs font-black block mb-1">من</label><select value={tFrom} onChange={e => setTFrom(e.target.value)} className="w-full p-2 border rounded-xl dark:bg-slate-700 font-bold"><option value="">-- اختر --</option>{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></div>
                        <div><label className="text-xs font-black block mb-1">إلى</label><select value={tTo} onChange={e => setTTo(e.target.value)} className="w-full p-2 border rounded-xl dark:bg-slate-700 font-bold"><option value="">-- اختر --</option>{treasuries.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></div>
                    </div>
                    <div><label className="text-xs font-black block mb-1">المبلغ</label><input type="number" value={tAmount} onChange={e => setTAmount(parseFloat(e.target.value)||0)} className="w-full p-3 border rounded-xl font-black text-lg" /></div>
                    <div className="flex justify-end gap-2 pt-4"><Button variant="secondary" onClick={() => setIsTransferModalOpen(false)}>إلغاء</Button><Button onClick={handleTransfer} isLoading={isSaving} className="bg-indigo-600 px-8">تأكيد التحويل</Button></div>
                </div>
            </Modal>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="تسجيل حركة">
                <TransactionFormModal transaction={null} onSave={async (d) => { await api.saveTransaction(d); await fetchData(); setIsModalOpen(false); }} onCancel={() => setIsModalOpen(false)} isLoading={isSaving} />
            </Modal>
        </div>
    );
};

