    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => {
                if (item.id === p.id) {
                    const oldStock = item.stock || 0;
                    const diff = p.stock - oldStock;
                    const whStocks = { ...(item.warehouseStocks || {}) };
                    const firstWhId = Object.keys(whStocks)[0] || 'w-1';
                    whStocks[firstWhId] = (whStocks[firstWhId] || 0) + diff;
                    return { ...item, ...p, warehouseStocks: whStocks };
                }
                return item;
            });
            logActivity(db, 'تعديل منتج', `تعديل المنتج: ${p.name}`);
        } else { 
            p.id = `prod-${Date.now()}`; 
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        // منع نقاط الآجل إذا كانت معطلة
        if (sale.paymentMethod === 'Credit' && !db.settings.loyaltySettings.allowCreditPoints) {
            sale.pointsEarned = 0; 
        }

        if (sale.id) {
            // حالة تعديل: خصم المديونية القديمة أولاً
            const oldSale = db.sales.find((s: any) => s.id === sale.id);
            if (oldSale && oldSale.paymentMethod === 'Credit' && customer) {
                customer.debt -= (oldSale.total - oldSale.amountPaid);
            }
            db.sales = db.sales.filter((s: any) => s.id !== sale.id);
            // إزالة خطة التقسيط القديمة إذا وجدت
            db.installments = (db.installments || []).filter((i: any) => i.saleId !== sale.id);
        }

        // فحص حد الائتمان
        if (sale.paymentMethod === 'Credit' && customer && customer.creditLimit > 0) {
            const currentDebt = customer.debt || 0;
            const newDebt = currentDebt + (sale.total - sale.amountPaid);
            if (newDebt > customer.creditLimit) {
                throw new Error(`تجاوز العميل حد الائتمان المسموح به (${customer.creditLimit}).`);
            }
        }

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                // FIX: Added explicit types for reduce to avoid TS errors
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات');

        if (customer) {
            if (sale.paymentMethod === 'Credit') {
                customer.debt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            }
            if (sale.pointsEarned > 0) customer.points = (customer.points || 0) + sale.pointsEarned;
        }

        // تسجيل خطة التقسيط في إدارة الأقساط إذا وجدت
        if (sale.installmentPlan && !sale.id) {
            if (!db.installments) db.installments = [];
            const plan = {
                id: `plan-${Date.now()}`,
                saleId: id,
                customerName: sale.customer.name,
                remainingAmount: sale.total - sale.amountPaid,
                ...sale.installmentPlan,
                status: 'Active',
                payments: sale.installmentPlan.payments || []
            };
            db.installments.push(plan);
        }

        logActivity(db, 'عملية بيع', `إتمام فاتورة مبيعات #${id} بمبلغ ${sale.total}`);
        saveDb(db); return finalSale;
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => s.status !== 'Draft' && (!start || s.date >= start) && (!end || s.date <= end));
        const manualExpenses = (db.transactions || []).filter((t:any) => t.type === 'expense' && t.category !== 'مرتجعات' && (!start || t.date >= start) && (!end || t.date <= end));
        const salesReturns = (db.salesReturns || []).filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        let totalRevenue = 0, totalCOGS = 0, totalTax = 0;
        const prodProfitMap: Record<string, { name: string, profit: number }> = {};

        sales.forEach((s: any) => {
            totalRevenue += s.total;
            totalTax += s.vatAmount || 0;
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                const cost = (prod?.costPrice || 0) * item.quantity;
                totalCOGS += cost;
                if (!prodProfitMap[item.id]) prodProfitMap[item.id] = { name: item.name, profit: 0 };
                prodProfitMap[item.id].profit += (item.sellPrice * item.quantity) - cost;
            });
        });

        // المرتجعات تخصم من الإيرادات ولا تعتبر "مصروفات"
        const totalReturnsValue = salesReturns.reduce((sum: number, r: any) => sum + (r.totalRefund || 0), 0);
        totalRevenue -= totalReturnsValue;

        const totalExpenses = manualExpenses.reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - totalExpenses;

        return { 
            totalRevenue, totalCOGS, totalExpenses, totalTax, netProfit, 
            productProfits: Object.entries(prodProfitMap).map(([id, d]) => ({ id, name: d.name, profit: d.profit })),
            dailyStats: []
        };
    },
    saveSalesReturn: async (data: any) => {
        const db = getDb();
        const id = `RET-${Date.now()}`;
        const finalReturn = { ...data, id, date: new Date().toISOString(), user: { id: 'u-1', name: 'المدير العام' } };
        if (!db.salesReturns) db.salesReturns = [];
        db.salesReturns.unshift(finalReturn);

        // تعديل الفاتورة الأصلية أو حذفها
        const originalSale = db.sales.find((s: any) => s.id === data.originalSaleId);
        if (originalSale) {
            let allReturned = true;
            data.items.forEach((retItem: any) => {
                const saleItem = originalSale.items.find((si: any) => si.id === retItem.id);
                if (saleItem) {
                    saleItem.quantity -= retItem.returnQuantity;
                    if (saleItem.quantity > 0) allReturned = false;
                }
                // استرجاع المخزون
                const p = db.products.find((prod: any) => prod.id === retItem.id);
                if (p) {
                    p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) + retItem.returnQuantity;
                    // FIX: Added explicit types for reduce to avoid TS errors
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                }
            });

            if (allReturned && originalSale.items.every((i: any) => i.quantity <= 0)) {
                db.sales = db.sales.filter((s: any) => s.id !== originalSale.id);
                logActivity(db, 'حذف فاتورة', `تم حذف الفاتورة #${originalSale.id} لإرجاع كامل الأصناف`);
            } else {
                originalSale.total -= data.totalRefund;
                originalSale.amountPaid = Math.max(0, originalSale.amountPaid - data.totalRefund);
            }
        }

        if (data.totalRefund > 0) logTransaction(db, 'expense', data.totalRefund, `مرتجع مبيعات #${data.originalSaleId}`, data.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مبيعات', `تسجيل مرتجع للفاتورة #${data.originalSaleId} بمبلغ ${data.totalRefund}`);
        saveDb(db); return finalReturn;
    },
