    deleteProduct: async (id: string) => {
        const db = getDb();
        db.products = db.products.filter((p: any) => p.id !== id);
        saveDb(db);
    },

    // FIX: Implemented missing customer and data wipe methods
    saveCustomer: async (c: any) => {
        const db = getDb();
        if (c.id) {
            db.customers = db.customers.map((item: any) => item.id === c.id ? { ...item, ...c } : item);
        } else {
            c.id = `cust-${Date.now()}`;
            c.debt = c.debt || 0;
            c.points = c.points || 0;
            db.customers.push(c);
        }
        saveDb(db);
        return c;
    },
    wipeBusinessData: async () => {
        const db = getDb();
        db.products = [];
        db.sales = [];
        db.purchases = [];
        db.customers = db.customers.filter((c: any) => c.id === 'cust-1');
        db.suppliers = [];
        db.partners = [];
        db.transactions = [];
        db.activityLogs = [];
        db.installments = [];
        db.salesReturns = [];
        db.purchaseReturns = [];
        db.shifts = [];
        db.notifications = [];
        db.stockTransfers = [];
        saveDb(db);
    },

    // FIX: Implemented missing supplier and purchase methods
    saveSupplier: async (s: any) => {
        const db = getDb();
        if (s.id) {
            db.suppliers = db.suppliers.map((item: any) => item.id === s.id ? { ...item, ...s } : item);
        } else {
            s.id = `sup-${Date.now()}`;
            db.suppliers.push(s);
        }
        saveDb(db);
        return s;
    },
    savePurchase: async (p: any) => {
        const db = getDb();
        const id = p.id || `PUR-${Date.now()}`;
        const finalP = { ...p, id, date: new Date().toISOString(), status: p.status || 'Paid' };
        db.purchases.unshift(finalP);

        finalP.items.forEach((item: any) => {
            const prod = db.products.find((prod: any) => prod.id === item.productId);
            if (prod) {
                if (!prod.warehouseStocks) prod.warehouseStocks = {};
                prod.warehouseStocks[finalP.warehouseId] = (prod.warehouseStocks[finalP.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
            }
        });

        if (finalP.amountPaid > 0) logTransaction(db, 'expense', finalP.amountPaid, `فاتورة مشتريات #${id}`, finalP.treasuryId, 'مشتريات');
        saveDb(db);
        return finalP;
    },

    // FIX: Implemented missing treasury and transaction methods
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => {
        const db = getDb();
        logTransaction(db, 'transfer', amount, desc, fromId, 'تحويل مالي', toId);
        saveDb(db);
        return true;
    },
    saveTransaction: async (t: any) => {
        const db = getDb();
        logTransaction(db, t.type, t.amount, t.description, t.treasuryId, t.category);
        saveDb(db);
        return t;
    },

    // FIX: Implemented missing warehouse and stock transfer methods
    saveWarehouse: async (w: any) => {
        const db = getDb();
        if (w.id) {
            db.warehouses = db.warehouses.map((item: any) => item.id === w.id ? { ...item, ...w } : item);
        } else {
            w.id = `wh-${Date.now()}`;
            db.warehouses.push(w);
        }
        saveDb(db);
        return w;
    },
    deleteWarehouse: async (id: string) => {
        const db = getDb();
        db.warehouses = db.warehouses.filter((w: any) => w.id !== id);
        saveDb(db);
    },
    getStockTransfers: async () => getDb().stockTransfers || [],
    saveStockTransfer: async (t: any) => {
        const db = getDb();
        const id = `trans-${Date.now()}`;
        const finalT = { ...t, id, date: new Date().toISOString() };
        if (!db.stockTransfers) db.stockTransfers = [];
        db.stockTransfers.unshift(finalT);

        const p = db.products.find((prod: any) => prod.id === t.productId);
        if (p) {
            p.warehouseStocks[t.fromWarehouseId] -= t.quantity;
            p.warehouseStocks[t.toWarehouseId] = (p.warehouseStocks[t.toWarehouseId] || 0) + t.quantity;
        }

        saveDb(db);
        return true;
    },

    // FIX: Implemented missing shipping company methods
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => {
        const db = getDb();
        if (c.id) {
            db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === c.id ? { ...item, ...c } : item);
        } else {
            c.id = `ship-${Date.now()}`;
            db.shippingCompanies.push(c);
        }
        saveDb(db);
        return c;
    },
    deleteShippingCompany: async (id: string) => {
        const db = getDb();
        db.shippingCompanies = db.shippingCompanies.filter((c: any) => c.id !== id);
        saveDb(db);
    },

    // FIX: Implemented missing sales return delete method
    deleteSalesReturn: async (id: string) => {
        const db = getDb();
        db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id);
        saveDb(db);
        return true;
    },

    // FIX: Implemented missing performance analytics methods
    getEmployeePerformanceAnalytics: async () => {
        return {
            performanceData: [],
            topPerformerByValue: undefined,
            topPerformerByCount: undefined
        };
    },

    // FIX: Implemented missing installment payment and sync methods
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        for (const plan of db.installments) {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt -= payment.amount;
                logTransaction(db, 'income', payment.amount, `تحصيل قسط - ${plan.customerName}`, db.treasuries[0].id, 'أقساط');
                saveDb(db);
                return true;
            }
        }
        return false;
    },
    getSyncLogs: async () => [
        { tableName: 'المنتجات', recordCount: getDb().products.length, lastSynced: new Date().toISOString() },
        { tableName: 'المبيعات', recordCount: getDb().sales.length, lastSynced: new Date().toISOString() }
    ],
    getQueueCount: async () => 0,
    processQueue: async () => {},
    setOnlineStatus: (online: boolean) => {},

    // FIX: Implemented missing satisfaction, feedback, and history methods
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    submitFeedback: async (f: any) => {},
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    getInactiveCustomers: async (days: number) => [],
    globalSearch: async (q: string) => ({
        products: [], sales: [], customers: [], purchases: [], suppliers: [], partners: [],
        salesReturns: [], purchaseReturns: [], installments: [], stockTransfers: []
    }),
    updateSale: async (id: string, data: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...data } : s);
        saveDb(db);
    },
    updatePurchase: async (id: string, data: any) => {
        const db = getDb();
        db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...data } : p);
        saveDb(db);
    },
    getStagnantProducts: async (days: number) => [],
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    updateSystemVersion: async (v: string, pkg: any) => {},
    getJournalEntries: async () => getDb().journalEntries || [],

    // FIX: Implemented missing shift management methods
    getCurrentShift: async (userId: string) => getDb().shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null,
    openShift: async (userId: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash: amount, status: 'Open' };
        if (!db.shifts) db.shifts = [];
        db.shifts.push(shift);
        saveDb(db);
        return shift;
    },
    closeShift: async (shiftId: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === shiftId);
        if (shift) {
            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = notes;
            saveDb(db);
            return shift;
        }
        throw new Error("Shift not found");
    }
};

