const LockScreen: React.FC = () => {
    const { user, unlockSession, switchUser } = useAuth();
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');
        const success = await unlockSession(password);
        if (!success) {
            setError('كلمة المرور غير صحيحة.');
            const form = e.target as HTMLFormElement;
            form.classList.add('animate-cart-shake');
            setTimeout(() => form.classList.remove('animate-cart-shake'), 400);
            setIsLoading(false);
            setPassword('');
        }
    };

    const handleSwitchUser = () => {
        switchUser();
    };

    const inputStyle = "mt-1 block w-full px-3 py-2.5 bg-slate-200/50 dark:bg-white/5 border border-slate-300 dark:border-slate-300/20 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 sm:text-sm transition text-slate-800 dark:text-white placeholder:text-slate-500 dark:placeholder:text-slate-400";

    return (
        <div className="relative flex items-center justify-center min-h-screen p-4 overflow-hidden">
            <div className="animated-bg">
                <div className="blob-1"></div>
                <div className="blob-2"></div>
                <div className="blob-3"></div>
            </div>
            <div className="relative z-10 w-full max-w-sm bg-white/50 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-xl shadow-2xl p-8 animate-scaleUp text-slate-800 dark:text-white text-center">
                <div className="mb-6">
                    <div className="w-20 h-20 mx-auto rounded-full bg-slate-200 dark:bg-slate-800/50 border border-slate-300 dark:border-white/10 flex items-center justify-center mb-4">
                        <span className="text-4xl">⚡</span>
                    </div>
                    <h2 className="text-2xl font-bold">مرحباً بعودتك، {user?.name}</h2>
                    <p className="text-slate-600 dark:text-slate-300 mt-1">تم قفل الجلسة بسبب عدم النشاط.</p>
                </div>
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 text-start">
                            كلمة المرور
                        </label>
                        <input
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className={inputStyle}
                            required
                            autoFocus
                        />
                    </div>
                    {error && <p className="text-red-500 dark:text-red-400 text-sm mb-4 text-center">{error}</p>}
                    <Button type="submit" className="w-full text-lg py-3" isLoading={isLoading}>
                        <Lock size={20} />
                        إلغاء القفل
                    </Button>
                </form>
                <div className="text-center mt-6">
                    <button onClick={handleSwitchUser} className="text-sm text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-white transition-colors flex items-center justify-center gap-2 mx-auto">
                       <LogOut size={16} />
                       <span>ليس أنت؟ تسجيل الخروج</span>
                    </button>
                </div>
            </div>
        </div>
    );
};

