    const [editingRole, setEditingRole] = useState<Role | null>(null);

    useEffect(() => {
        if (settings) setLocalSettings(JSON.parse(JSON.stringify(settings)));
        fetchEmployeesData();
    }, [settings]);

    const fetchEmployeesData = async () => {
        try {
            const u = await api.getUsers();
            setUsers(u);
            setRoles([
                { id: 'r-1', name: 'مدير النظام', permissions: {} },
                { id: 'r-2', name: 'كاشير مبيعات', permissions: {} },
                { id: 'r-3', name: 'أمين مخزن', permissions: {} }
            ]);
        } catch (e) {
            console.error(e);
        }
    };

    const handleSave = async () => {
        if (!localSettings) return;
        setIsSaving(true);
        try {
            await updateSettings(localSettings);
            addToast('تم حفظ كافة الإعدادات بنجاح', 'success');
        } catch (e) { addToast('خطأ في الحفظ', 'error'); }
        finally { setIsSaving(false); }
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file && localSettings) {
            try {
                const base64 = await processImageFile(file, 300);
                setLocalSettings({ ...localSettings, logoUrl: base64 });
                addToast('تم رفع الشعار، اضغط حفظ للتأكيد.', 'success');
            } catch (err) { addToast('فشل معالجة الصورة', 'error'); }
        }
    };

    // حساب الأيام المتبقية والمميزات
    const subscriptionDetails = useMemo(() => {
        if (!licenseInfo.activationDate || !licenseInfo.type) return null;

        const start = new Date(licenseInfo.activationDate).getTime();
        const now = new Date().getTime();
        const diffDays = Math.floor((now - start) / (1000 * 60 * 60 * 24));

        let totalDuration = 0;
        let features: string[] = [];

        switch(licenseInfo.type) {
            case 'Free': 
                totalDuration = Infinity; 
                features = ["١ مخزن فقط", "١ خزينة فقط", "٢٥ منتج كحد أقصى", "إدارة عملاء أساسية"];
                break;
            case 'Trial': 
                totalDuration = 3; 
                features = ["كافة ميزات النظام", "تجربة الذكاء الاصطناعي", "تقارير مالية محدودة"];
                break;
            case 'Monthly': 
                totalDuration = 30; 
                features = ["٢ مخزن", "٢ خزينة", "منتجات غير محدودة", "نظام الأقساط"];
                break;
            case 'Semiannual': 
                totalDuration = 182; 
                features = ["٥ مخازن", "٣ خزائن", "ذكاء اصطناعي (AI)", "نظام الولاء"];
                break;
            case 'Yearly': 
                totalDuration = 365; 
                features = ["٢٥ مخزن", "١٥ خزينة", "دعم فني VIP", "تحديثات مجانية"];
                break;
            case 'Lifetime': 
                totalDuration = Infinity; 
                features = ["مخازن غير محدودة", "خزائن غير محدودة", "كافة ميزات الـ Enterprise", "دعم مدى الحياة"];
                break;
        }

        const remaining = totalDuration === Infinity ? Infinity : Math.max(0, totalDuration - diffDays);

        return { remaining, features };
    }, [licenseInfo]);

