                    {navItems.map(item => (
                        <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl font-black text-xs transition-all ${activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/30' : 'text-slate-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20'}`}>
                            {item.icon} {item.label}
                        </button>
                    ))}
                </nav>

                <div className="lg:col-span-3 space-y-8">
                    {activeTab === 'general' && (
                        <Card title="بيانات المتجر والضرائب">
                            <div className="space-y-6">
                                <div className="flex flex-col md:flex-row gap-8 items-center border-b dark:border-slate-800 pb-8">
                                    <div className="relative group">
                                        <div className="w-32 h-32 rounded-4xl bg-slate-100 dark:bg-slate-800 border-2 border-dashed border-slate-300 dark:border-slate-700 flex items-center justify-center overflow-hidden">
                                            {localSettings.logoUrl ? <img src={localSettings.logoUrl} className="w-full h-full object-contain p-2" /> : <ImageIcon size={40} className="text-slate-300" />}
                                        </div>
                                        <label className="absolute inset-0 flex items-center justify-center bg-indigo-600/80 text-white opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer rounded-4xl">
                                            <Upload size={24} />
                                            <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                                        </label>
                                    </div>
                                    <div className="flex-grow space-y-4 w-full">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            <div><label className={labelClass}>اسم المنشأة</label><input type="text" value={localSettings.storeName} onChange={e => setLocalSettings({...localSettings, storeName: e.target.value})} className={inputClass} /></div>
                                            <div><label className={labelClass}>الرقم الضريبي</label><input type="text" value={localSettings.taxRegisterNumber} onChange={e => setLocalSettings({...localSettings, taxRegisterNumber: e.target.value})} className={inputClass} /></div>
