                                    <div><label className={labelClass}>نسبة الضريبة (%)</label><input type="number" value={localSettings.vatRate} onChange={e => setLocalSettings({...localSettings, vatRate: parseFloat(e.target.value)||0})} className={inputClass} /></div>
                                    <div><label className={labelClass}>رقم الفاتورة القادم</label><input type="number" value={localSettings.nextInvoiceNumber} onChange={e => setLocalSettings({...localSettings, nextInvoiceNumber: parseInt(e.target.value)||0})} className={inputClass} /></div>
