                                                <div className="flex-1"><label className={labelClass}>معدل الاستبدال</label><input type="number" step="0.1" value={localSettings.loyaltySettings.redemptionRate} onChange={e => setLocalSettings({...localSettings, loyaltySettings: {...localSettings.loyaltySettings, redemptionRate: parseFloat(e.target.value)||0}})} className={inputClass} /></div>
