import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Transaction, Treasury } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import TransactionFormModal from '../components/treasury/TransactionFormModal';
import { PlusCircle, Wallet, ArrowRightLeft, RefreshCw, Tag, ExternalLink, Download, Search, Filter } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useAuth } from '../hooks/useAuth';
import TreasurySkeleton from '../components/treasury/TreasurySkeleton';
import { useToasts } from '../hooks/useToasts';
import { exportToCsv } from '../utils/export';

const TreasuryPage: React.FC = () => {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // فلاتر البحث
    const [searchTerm, setSearchTerm] = useState('');
    const [typeFilter, setTypeFilter] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    // التحويل والتصدير
    const [tFrom, setTFrom] = useState('');
    const [tTo, setTTo] = useState('');
    const [tAmount, setTAmount] = useState(0);
    const [destAccount, setDestAccount] = useState('');

    const { settings } = useSettings();
    const { addToast } = useToasts();

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [transData, treasuryData] = await Promise.all([api.getTransactions(), api.getTreasuries()]);
            setTransactions(transData || []);
            setTreasuries(treasuryData || []);
        } catch (e) { addToast("خطأ في تحميل البيانات", "error"); } finally { setLoading(false); }
    }, [addToast]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const filteredTransactions = useMemo(() => {
        return transactions.filter(t => {
            const matchesSearch = t.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                 t.category.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesType = typeFilter === 'all' || t.type === typeFilter;
            const tDate = t.date.split('T')[0];
            const matchesDate = (!startDate || tDate >= startDate) && (!endDate || tDate <= endDate);

            return matchesSearch && matchesType && matchesDate;
        });
    }, [transactions, searchTerm, typeFilter, startDate, endDate]);

    const handleTransfer = async () => {
        if (!tFrom || !tTo || tAmount <= 0) return;
        if (tFrom === tTo) { addToast('يجب اختيار خزنتين مختلفتين', 'error'); return; }
        setIsSaving(true);
        try {
            await api.transferFunds(tFrom, tTo, tAmount, 'تحويل مالي داخلي');
            await fetchData();
            setIsTransferModalOpen(false);
            addToast('تم التحويل بنجاح', 'success');
        } catch (e) { addToast('فشل التحويل', 'error'); } finally { setIsSaving(false); }
    };

    const handleExportTreasury = async () => {
        if (!tFrom || !tAmount || !destAccount) return;
        setIsSaving(true);
        try {
            await api.exportTreasury(tFrom, tAmount, destAccount, 'سحب وتصدير مالي خارجي');
            await fetchData();
            setIsExportModalOpen(false);
            addToast('تم تصدير المبلغ بنجاح', 'success');
        } catch (e) { addToast('فشل التصدير', 'error'); } finally { setIsSaving(false); }
    };

    const handleCsvExport = () => {
        const data = filteredTransactions.map(t => ({
            "التاريخ": new Date(t.date).toLocaleString('ar-EG'),
            "النوع": t.type,
            "الفئة": t.category,
            "المبلغ": t.amount,
            "البيان": t.description,
            "حساب الوجهة": t.destinationAccount || 'داخلي'
        }));
        exportToCsv(`treasury-logs-${Date.now()}.csv`, data);
    };

    if (loading || !settings) return <TreasurySkeleton />;

    return (
        <div className="animate-fadeIn">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h1 className="text-3xl font-black text-slate-800 dark:text-white">الخزينة والحسابات</h1>
