import type { 
    Sale, Product, StoreSettings, ActivityLog, FinancialReport, 
    SalesReturn, Purchase, Partner, Treasury, InstallmentPlan,
    Notification, ShippingCompany, PurchaseReturn, Transaction,
    SyncLog, InactiveCustomer, StagnantProduct, GlobalSearchResults,
    JournalEntry, Shift, UpdatePackage, Supplier, Customer, EmployeePerformanceAnalytics,
    SatisfactionAnalytics, User, SupplierPerformanceData, DashboardAnalytics, PermissionKey, SalesHistoryData, EmployeePerformanceData
} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' } },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.partners) parsed.partners = [];
        if (!parsed.purchaseReturns) parsed.purchaseReturns = [];
        if (!parsed.salesReturns) parsed.salesReturns = [];
        if (!parsed.purchases) parsed.purchases = [];
        if (!parsed.shippingCompanies) parsed.shippingCompanies = [];
        if (!parsed.users) parsed.users = defaultDb.users;
        if (!parsed.installments) parsed.installments = [];
        if (!parsed.notifications) parsed.notifications = [];
        if (!parsed.stockTransfers) parsed.stockTransfers = [];
        if (!parsed.journalEntries) parsed.journalEntries = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({
        id: `act-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    });
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, toTreasuryId?: string, destinationAccount?: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'transfer' && toTreasuryId) {
            const toT = db.treasuries.find((item: any) => item.id === toTreasuryId);
            if (toT) {
                t.balance -= amount;
                toT.balance += amount;
            }
        } else {
            t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        }

        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: category,
            user: 'المدير العام',
            treasuryId,
            toTreasuryId,
            destinationAccount
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => {
                if (item.id === p.id) {
                    const oldStock = item.stock || 0;
                    const diff = p.stock - oldStock;
                    const whStocks = { ...(item.warehouseStocks || {}) };
                    const firstWhId = Object.keys(whStocks)[0] || 'w-1';
                    whStocks[firstWhId] = (whStocks[firstWhId] || 0) + diff;
                    return { ...item, ...p, warehouseStocks: whStocks };
                }
                return item;
            });
            logActivity(db, 'تعديل منتج', `تعديل المنتج: ${p.name}`);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        if (sale.paymentMethod === 'Credit' && !db.settings.loyaltySettings.allowCreditPoints) {
            sale.pointsEarned = 0; 
        }

        if (sale.id) {
            const oldSale = db.sales.find((s: any) => s.id === sale.id);
            if (oldSale && oldSale.paymentMethod === 'Credit' && customer) {
                customer.debt -= (oldSale.total - oldSale.amountPaid);
            }
            db.sales = db.sales.filter((s: any) => s.id !== sale.id);
            db.installments = (db.installments || []).filter((i: any) => i.saleId !== sale.id);
        }

        if (sale.paymentMethod === 'Credit' && customer && customer.creditLimit > 0) {
            const currentDebt = customer.debt || 0;
            const newDebt = currentDebt + (sale.total - sale.amountPaid);
            if (newDebt > customer.creditLimit) {
                throw new Error(`تجاوز العميل حد الائتمان المسموح به (${customer.creditLimit}).`);
            }
        }

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                p.lastSoldDate = new Date().toISOString();
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات');

        if (customer) {
            if (sale.paymentMethod === 'Credit') {
                customer.debt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            }
            if (sale.pointsEarned > 0) customer.points = (customer.points || 0) + sale.pointsEarned;
            customer.lastPurchaseDate = new Date().toISOString();
        }

        if (sale.installmentPlan && !sale.id) {
            if (!db.installments) db.installments = [];
            const months = sale.installmentPlan.months || 1;
            const principal = sale.total - sale.amountPaid;
            const interestRate = sale.installmentPlan.interestRate || 0;
            const interestAmount = principal * (interestRate / 100) * (months / 12);
            const totalWithInterest = principal + interestAmount;
            const monthlyPayment = totalWithInterest / months;

            const generatedPayments = [];
            let currentDueDate = new Date(sale.installmentPlan.startDate || new Date());
            for (let i = 0; i < months; i++) {
                generatedPayments.push({
                    id: `pay-${id}-${i}-${Date.now()}`,
                    amount: monthlyPayment,
                    dueDate: currentDueDate.toISOString().split('T')[0],
                    status: 'Pending'
                });
                currentDueDate.setMonth(currentDueDate.getMonth() + 1);
            }

            const plan = {
                id: `plan-${Date.now()}`,
                saleId: id,
                customerName: sale.customer.name,
                remainingAmount: totalWithInterest,
                totalWithInterest: totalWithInterest,
                downPayment: sale.amountPaid,
                interestRate: interestRate,
                interestAmount: interestAmount,
                monthlyPayment: monthlyPayment,
                numberOfInstallments: months,
                status: 'Active',
                payments: generatedPayments
            };
            db.installments.push(plan);
            logActivity(db, 'خطة تقسيط', `إنشاء خطة تقسيط للفاتورة #${id} للعميل ${sale.customer.name}`);
        }

        logActivity(db, 'عملية بيع', `إتمام فاتورة مبيعات #${id} بمبلغ ${sale.total}`);
        saveDb(db); return finalSale;
    },
    saveSalesReturn: async (data: any) => {
        const db = getDb();
        const id = `RET-${Date.now()}`;
        const finalReturn = { ...data, id, date: new Date().toISOString(), user: { id: 'u-1', name: 'المدير العام' } };
        if (!db.salesReturns) db.salesReturns = [];
        db.salesReturns.unshift(finalReturn);

        const originalSale = db.sales.find((s: any) => s.id === data.originalSaleId);
        let cashToRefund = data.totalRefund;

        if (originalSale) {
            const plan = db.installments.find((i: any) => i.saleId === originalSale.id);
            const customer = db.customers.find((c: any) => c.id === originalSale.customer.id);

            if (plan && plan.status !== 'Paid Off') {
                const reductionAmount = Math.min(plan.remainingAmount, data.totalRefund);
                plan.remainingAmount -= reductionAmount;
                if (customer) customer.debt -= reductionAmount;
                cashToRefund = data.totalRefund - reductionAmount;

                // تسوية الدفعات المستقبلية
                let remainingReduction = reductionAmount;
                for (let i = plan.payments.length - 1; i >= 0; i--) {
                    if (plan.payments[i].status === 'Pending') {
                        const deduct = Math.min(plan.payments[i].amount, remainingReduction);
                        plan.payments[i].amount -= deduct;
                        remainingReduction -= deduct;
                        if (plan.payments[i].amount <= 0) plan.payments[i].status = 'Paid';
                    }
                    if (remainingReduction <= 0) break;
                }

                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
            } else if (originalSale.paymentMethod === 'Credit' && customer) {
                const reduction = Math.min(customer.debt, data.totalRefund);
                customer.debt -= reduction;
                cashToRefund = data.totalRefund - reduction;
            }

            data.items.forEach((retItem: any) => {
                const p = db.products.find((prod: any) => prod.id === retItem.id);
                if (p) {
                    if (!p.warehouseStocks) p.warehouseStocks = {};
                    p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) + retItem.returnQuantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                }
            });
            originalSale.total -= data.totalRefund;
            originalSale.amountPaid = Math.max(0, originalSale.amountPaid - cashToRefund);
        }

        if (cashToRefund > 0) logTransaction(db, 'expense', cashToRefund, `مرتجع نقدي للفاتورة #${data.originalSaleId}`, data.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مبيعات', `تسجيل مرتجع للفاتورة #${data.originalSaleId}. المسترد نقداً: ${cashToRefund}`);
        saveDb(db); return finalReturn;
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => s.status !== 'Draft' && (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = (db.transactions || []).filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));
        const salesReturns = (db.salesReturns || []).filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        let totalRevenue = 0, totalCOGS = 0, totalTax = 0;
        const prodProfitMap: Record<string, { name: string, profit: number }> = {};

        sales.forEach((s: any) => {
            totalRevenue += s.total;
            totalTax += s.vatAmount || 0;
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                const cost = (prod?.costPrice || 0) * item.quantity;
                totalCOGS += cost;
                if (!prodProfitMap[item.id]) prodProfitMap[item.id] = { name: item.name, profit: 0 };
                prodProfitMap[item.id].profit += (item.sellPrice * item.quantity) - cost;
            });
        });

        const totalReturnsValue = salesReturns.reduce((sum: number, r: any) => sum + (r.totalRefund || 0), 0);
        totalRevenue -= totalReturnsValue;
        const totalExpenses = transactions.filter((t:any) => t.type === 'expense').reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - totalExpenses;

        return { 
            totalRevenue, totalCOGS, totalExpenses, totalTax, netProfit, 
            productProfits: Object.entries(prodProfitMap).map(([id, d]) => ({ id, name: d.name, profit: d.profit })),
            dailyStats: []
        };
    },
    getDashboardAnalytics: async () => {
        const db = getDb();
        const sales = db.sales || [];
        const today = new Date().toISOString().split('T')[0];
        const todaySales = sales.filter((s: any) => s.date.startsWith(today));

        return {
            totalSalesToday: todaySales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaySales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + (b.debt || 0), 0),
            totalStockValue: db.products.reduce((a: number, b: any) => a + ((b.stock || 0) * (b.costPrice || 0)), 0),
            monthlySales: [], 
            salesByCategory: [],
            topProducts: (db.products || []).slice(0, 5).map((p: any) => ({ id: p.id, name: p.name, totalRevenue: p.sellPrice * 10 }))
        };
    },
    getInactiveCustomers: async (days: number) => {
        const db = getDb();
        const threshold = Date.now() - (days * 24 * 60 * 60 * 1000);
        return db.customers.filter((c: any) => {
            if (c.id === 'cust-1') return false;
            if (!c.lastPurchaseDate) return true;
            return new Date(c.lastPurchaseDate).getTime() < threshold;
        }).map((c: any) => ({
            id: c.id, name: c.name, phone: c.phone, lastPurchaseDate: c.lastPurchaseDate || 'لا يوجد مشتريات'
        }));
    },
    getStagnantProducts: async (days: number) => {
        const db = getDb();
        const threshold = Date.now() - (days * 24 * 60 * 60 * 1000);
        return db.products.filter((p: any) => {
            if (p.stock <= 0) return false;
            if (!p.lastSoldDate) return true;
            return new Date(p.lastSoldDate).getTime() < threshold;
        }).map((p: any) => ({
            id: p.id, name: p.name, stock: p.stock, lastSoldDate: p.lastSoldDate,
            daysSinceLastSale: p.lastSoldDate ? Math.floor((Date.now() - new Date(p.lastSoldDate).getTime()) / (1000*60*60*24)) : days + 1
        }));
    },
    globalSearch: async (q: string) => {
        const db = getDb();
        const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query) || p.supplier.name.toLowerCase().includes(query)),
            suppliers: db.suppliers.filter((s:any) => s.name.toLowerCase().includes(query) || s.phone.includes(query)),
            partners: db.partners.filter((p:any) => p.name.toLowerCase().includes(query)),
            salesReturns: db.salesReturns.filter((r:any) => r.id.toLowerCase().includes(query) || r.originalSaleId.toLowerCase().includes(query)),
            purchaseReturns: db.purchaseReturns.filter((r:any) => r.id.toLowerCase().includes(query) || r.originalPurchaseId.toLowerCase().includes(query)),
            installments: db.installments.filter((i:any) => i.customerName.toLowerCase().includes(query)),
            stockTransfers: db.stockTransfers.filter((t:any) => t.id.toLowerCase().includes(query))
        };
    },
    getCurrentShift: async (userId: string) => getDb().shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null,
    openShift: async (userId: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash: amount, status: 'Open' };
        if (!db.shifts) db.shifts = [];
        db.shifts.push(shift);
        saveDb(db);
        return shift;
    },
    closeShift: async (shiftId: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === shiftId);
        if (shift) {
            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = notes;
            saveDb(db);
            return shift;
        }
        throw new Error("Shift not found");
    },
    getTransactions: async () => getDb().transactions,
    getTreasuries: async () => getDb().treasuries,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getSales: async () => getDb().sales,
    getCustomers: async () => getDb().customers,
    getPurchases: async () => getDb().purchases,
    getSuppliers: async () => getDb().suppliers,
    getPartners: async () => getDb().partners,
    getSalesReturns: async () => getDb().salesReturns,
    getPurchaseReturns: async () => getDb().purchaseReturns,
    getStockTransfers: async () => getDb().stockTransfers || [],
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        for (const plan of db.installments) {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt -= payment.amount;
                logTransaction(db, 'income', payment.amount, `تحصيل قسط - ${plan.customerName}`, db.treasuries[0].id, 'أقساط');
                logActivity(db, 'تحصيل قسط', `تحصيل مبلغ ${payment.amount} من العميل ${plan.customerName}`);
                saveDb(db); return true;
            }
        }
        return false;
    },
    getSyncLogs: async () => [
        { tableName: 'المنتجات', recordCount: getDb().products.length, lastSynced: new Date().toISOString() },
        { tableName: 'المبيعات', recordCount: getDb().sales.length, lastSynced: new Date().toISOString() }
    ],
    getQueueCount: async () => 0,
    processQueue: async () => {},
    setOnlineStatus: (online: boolean) => {},
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    submitFeedback: async (f: any) => {},
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    updateSale: async (id: string, data: any) => {
        const db = getDb(); db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...data } : s); saveDb(db);
    },
    updatePurchase: async (id: string, data: any) => {
        const db = getDb(); db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...data } : p); saveDb(db);
    },
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    updateSystemVersion: async (v: string, pkg: any) => {},
    getJournalEntries: async () => getDb().journalEntries || [],
    login: async (n: string, p: string) => getDb().users.find((u: any) => u.name === n && u.password === p) || null,
    verifyPassword: async (uid: string, p: string) => { const u = getDb().users.find((u: any) => u.id === uid); return u ? u.password === p : false; },
    getUsers: async () => getDb().users,
    saveUser: async (u: any) => {
        const db = getDb(); if (u.id) db.users = db.users.map((i: any) => i.id === u.id ? { ...i, ...u } : i);
        else { u.id = `u-${Date.now()}`; db.users.push(u); }
        saveDb(db); return u;
    },
    addNotification: async (n: any) => {
        const db = getDb(); if (!db.notifications) db.notifications = [];
        const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n };
        db.notifications.unshift(newN); saveDb(db); return newN;
    },
    getNotifications: async () => getDb().notifications || [],
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb(); products.forEach(p => { const idx = db.products.findIndex((item: any) => item.id === p.id); if (idx !== -1) db.products[idx] = p; });
        saveDb(db);
    },
    deleteProduct: async (id: string) => {
        const db = getDb(); db.products = db.products.filter((p: any) => p.id !== id); saveDb(db);
    },
    saveCustomer: async (c: any) => {
        const db = getDb(); if (c.id) db.customers = db.customers.map((i: any) => i.id === c.id ? { ...i, ...c } : i);
        else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); }
        saveDb(db); return c;
    },
    wipeBusinessData: async () => {
        const db = getDb(); db.products = []; db.sales = []; db.purchases = []; db.customers = db.customers.filter((c: any) => c.id === 'cust-1');
        db.suppliers = []; db.partners = []; db.transactions = []; db.activityLogs = []; db.installments = [];
        db.salesReturns = []; db.purchaseReturns = []; db.shifts = []; db.notifications = []; db.stockTransfers = [];
        saveDb(db);
    },
    saveSupplier: async (s: any) => {
        const db = getDb(); if (s.id) db.suppliers = db.suppliers.map((i: any) => i.id === s.id ? { ...i, ...s } : i);
        else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); }
        saveDb(db); return s;
    },
    savePurchase: async (p: any) => {
        const db = getDb(); const id = p.id || `PUR-${Date.now()}`; const finalP = { ...p, id, date: new Date().toISOString(), status: p.status || 'Paid' };
        db.purchases.unshift(finalP);
        finalP.items.forEach((item: any) => {
            const prod = db.products.find((prod: any) => prod.id === item.productId);
            if (prod) {
                if (!prod.warehouseStocks) prod.warehouseStocks = {};
                prod.warehouseStocks[finalP.warehouseId] = (prod.warehouseStocks[finalP.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
            }
        });
        if (finalP.amountPaid > 0) logTransaction(db, 'expense', finalP.amountPaid, `فاتورة مشتريات #${id}`, finalP.treasuryId, 'مشتريات');
        saveDb(db); return finalP;
    },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => {
        const db = getDb(); logTransaction(db, 'transfer', amount, desc, fromId, 'تحويل مالي', toId);
        saveDb(db); return true;
    },
    saveTransaction: async (t: any) => {
        const db = getDb(); logTransaction(db, t.type, t.amount, t.description, t.treasuryId, t.category);
        saveDb(db); return t;
    },
    saveWarehouse: async (w: any) => {
        const db = getDb(); if (w.id) db.warehouses = db.warehouses.map((i: any) => i.id === w.id ? { ...i, ...w } : i);
        else { w.id = `wh-${Date.now()}`; db.warehouses.push(w); }
        saveDb(db); return w;
    },
    deleteWarehouse: async (id: string) => {
        const db = getDb(); db.warehouses = db.warehouses.filter((w: any) => w.id !== id); saveDb(db);
    },
    saveStockTransfer: async (t: any) => {
        const db = getDb(); const id = `trans-${Date.now()}`; const finalT = { ...t, id, date: new Date().toISOString() };
        if (!db.stockTransfers) db.stockTransfers = []; db.stockTransfers.unshift(finalT);
        const p = db.products.find((prod: any) => prod.id === t.productId);
        if (p) { p.warehouseStocks[t.fromWarehouseId] -= t.quantity; p.warehouseStocks[t.toWarehouseId] = (p.warehouseStocks[t.toWarehouseId] || 0) + t.quantity; }
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => {
        const db = getDb(); if (c.id) db.shippingCompanies = db.shippingCompanies.map((i: any) => i.id === c.id ? { ...i, ...c } : i);
        else { c.id = `ship-${Date.now()}`; db.shippingCompanies.push(c); }
        saveDb(db); return c;
    },
    deleteShippingCompany: async (id: string) => {
        const db = getDb(); db.shippingCompanies = db.shippingCompanies.filter((c: any) => c.id !== id); saveDb(db);
    },
    deleteSalesReturn: async (id: string) => {
        const db = getDb(); db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id); saveDb(db); return true;
    },
    getEmployeePerformanceAnalytics: async () => ({ performanceData: [], topPerformerByValue: undefined, topPerformerByCount: undefined }),
    getInstallmentPlans: async () => getDb().installments || [],
    exportTreasury: async (trId: string, amount: number, destination: string, desc: string) => {
        const db = getDb(); logTransaction(db, 'export', amount, desc, trId, 'تصدير خارجي', undefined, destination);
        saveDb(db); return true;
    },
    savePartner: async (data: any) => {
        const db = getDb(); if (data.id) db.partners = db.partners.map((p: any) => p.id === data.id ? { ...p, ...data } : p);
        else { data.id = `part-${Date.now()}`; db.partners.push(data); }
        saveDb(db); return data;
    },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); }
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, Warehouse, Treasury, PaymentDetail } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import { Search, ShoppingCart, Trash2, Plus, Minus, User, Warehouse as WhIcon, Wallet, Percent, Truck, UserPlus, Gift, CreditCard, DollarSign } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';
import SplitPaymentModal from '../components/pos/SplitPaymentModal';
import InstallmentSetupModal from '../components/sales/InstallmentSetupModal';
import { useShift } from '../hooks/useShift';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();
    const { currentShift } = useShift();
    const [searchParams] = useSearchParams();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [customerQuery, setCustomerQuery] = useState('');
    const [showCustResults, setShowCustResults] = useState(false);
    const [isNewCustModalOpen, setIsNewCustModalOpen] = useState(false);

    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [shippingCost, setShippingCost] = useState(0);
    const [pointsToRedeem, setPointsToRedeem] = useState(0);

    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [showSplitModal, setShowSplitModal] = useState(false);
    const [showInstallmentModal, setShowInstallmentModal] = useState(false);
    const [pendingSplitPayments, setPendingSplitPayments] = useState<PaymentDetail[] | null>(null);

    const editSaleId = searchParams.get('edit');

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t, allSales] = await Promise.all([
                api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries(), api.getSales()
            ]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
            if (editSaleId) {
                const saleToEdit = allSales.find((s:any) => s.id === editSaleId);
                if (saleToEdit) { 
                    setCart(saleToEdit.items); 
                    setSelectedCustomerId(saleToEdit.customer.id); 
                    setGlobalDiscount(saleToEdit.discount); 
                    setGlobalDiscountType(saleToEdit.discountType); 
                    setShippingCost(saleToEdit.shipping); 
                    setSelectedWhId(saleToEdit.warehouseId); 
                    setSelectedTrId(saleToEdit.treasuryId); 
                }
            }
        };
        load();
    }, [editSaleId]);

    const selectedCustomer = useMemo(() => customers.find(c => c.id === selectedCustomerId), [customers, selectedCustomerId]);

    const pointsDiscount = useMemo(() => {
        if (!settings?.loyaltySettings.enabled || !selectedCustomer) return 0;
        return Math.min(pointsToRedeem * settings.loyaltySettings.redemptionRate, selectedCustomer.points * settings.loyaltySettings.redemptionRate);
    }, [pointsToRedeem, selectedCustomer, settings]);

    const subtotalRaw = useMemo(() => cart.reduce((s, i) => s + ((i.sellPrice || 0) * i.quantity), 0), [cart]);

    const subtotal = useMemo(() => cart.reduce((s, i) => {
        const price = i.sellPrice || 0;
        const discount = i.discountPercent ? (price * i.discountPercent / 100) : 0;
        return s + ((price - discount) * i.quantity);
    }, 0), [cart]);

    const discountVal = useMemo(() => globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount, [subtotal, globalDiscount, globalDiscountType]);
    const finalTotal = Math.max(0, subtotal - discountVal - pointsDiscount + shippingCost);

    const handleCheckout = async (method: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit', payments?: PaymentDetail[], plan?: any) => {
        if (!cart.length || !selectedWhId || !selectedTrId) { addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning'); return; }

        const hasCredit = method === 'Credit' || (payments && payments.some(p => p.method === 'Credit'));
        if (hasCredit && !plan) {
            setPendingSplitPayments(payments || null);
            setShowInstallmentModal(true);
            return;
        }

        try {
            const amountPaid = method === 'Split' ? (payments?.filter(p => p.method !== 'Credit').reduce((a, b) => a + b.amount, 0) || 0) : (method === 'Credit' ? 0 : finalTotal);
            const res = await api.saveSale({
                id: editSaleId || undefined,
                customer: { id: selectedCustomerId, name: selectedCustomer?.name },
                cashier: { id: 'u-1', name: 'المدير' },
                items: cart,
                subtotal, total: finalTotal, amountPaid,
                paymentMethod: method, discount: globalDiscount, discountType: globalDiscountType,
                shipping: shippingCost, warehouseId: selectedWhId, treasuryId: selectedTrId,
                payments: payments || (method !== 'Split' ? [{ method: method as any, amount: finalTotal }] : []),
                installmentPlan: plan, pointsRedeemed: pointsToRedeem,
                shiftId: currentShift?.id // ربط الفاتورة بالوردية
            });
            setLastSale(res); setShowReceipt(true); setCart([]); setGlobalDiscount(0); setShippingCost(0); setPointsToRedeem(0); setPendingSplitPayments(null);
            addToast('تمت العملية بنجاح', 'success');
        } catch (e) { addToast('فشل إتمام العملية', 'error'); }
    };

    const addToCart = (p: Product) => {
        const stockInWh = p.warehouseStocks?.[selectedWhId] || 0;
        if (stockInWh <= 0) { addToast('المنتج غير متوفر في المستودع المحدد', 'error'); return; }
        setCart(prev => {
            const ex = prev.find(i => i.id === p.id);
            if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
            return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice, discountPercent: 0 }];
        });
        setSearchTerm('');
    };

    const filteredSearchResults = useMemo(() => {
        if (!searchTerm.trim()) return [];
        return products.filter(p => {
            const matchesQuery = p.name.includes(searchTerm) || p.sku.includes(searchTerm);
            const hasStockInWh = (p.warehouseStocks?.[selectedWhId] || 0) > 0;
            return matchesQuery && hasStockInWh;
        });
    }, [searchTerm, products, selectedWhId]);

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 flex-shrink-0">
                <div className="lg:col-span-3">
                    <div className="relative">
                        <WhIcon className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <select value={selectedWhId} onChange={e => { setSelectedWhId(e.target.value); setCart([]); }} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black text-xs outline-none">
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                        </select>
                    </div>
                </div>
                <div className="lg:col-span-5 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج في المخزن المحدد..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-12 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black outline-none shadow-sm"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {filteredSearchResults.map(p => (
                                <button key={p.id} onClick={() => addToCart(p)} className="w-full p-3 border-b dark:border-slate-700 flex justify-between hover:bg-indigo-50 font-black text-xs">
                                    <span>{p.name} <span className="text-emerald-500 ms-2">({toArabicIndic(p.warehouseStocks?.[selectedWhId] || 0)})</span></span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                            {filteredSearchResults.length === 0 && <p className="p-4 text-center text-xs text-slate-400 font-bold">لا توجد نتائج في هذا المخزن</p>}
                        </div>
                    )}
                </div>
                <div className="lg:col-span-4 flex gap-2">
                    <div className="relative flex-1">
                        <User className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <input type="text" placeholder="بحث عن عميل..." value={showCustResults ? customerQuery : (selectedCustomer?.name || '')} onFocus={() => setShowCustResults(true)} onChange={e => setCustomerQuery(e.target.value)} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border dark:border-slate-800 font-black text-xs outline-none"/>
                        {showCustResults && (
                            <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border overflow-hidden">
                                {customers.filter(c => c.name.includes(customerQuery)).map(c => (
                                    <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setShowCustResults(false); }} className="w-full p-2.5 text-start hover:bg-slate-50 border-b last:border-0 font-bold text-xs">{c.name}</button>
                                ))}
                                <button onClick={() => setIsNewCustModalOpen(true)} className="w-full p-2.5 bg-indigo-50 text-indigo-600 text-[10px] font-black flex items-center justify-center gap-2"><UserPlus size={14}/> إضافة عميل</button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border dark:border-slate-800 shadow-sm overflow-hidden flex flex-col">
                <div className="bg-slate-50 dark:bg-slate-800/50 px-6 py-2 border-b dark:border-slate-700 grid grid-cols-12 text-[10px] font-black text-slate-400 uppercase">
