import type { 
    Sale, Product, StoreSettings, ActivityLog, FinancialReport, 
    SalesReturn, Purchase, Partner, Treasury, InstallmentPlan,
    Notification, ShippingCompany, PurchaseReturn, Transaction,
    SyncLog, InactiveCustomer, StagnantProduct, GlobalSearchResults,
    JournalEntry, Shift, UpdatePackage, Supplier, Customer, EmployeePerformanceAnalytics,
    SatisfactionAnalytics, User, SupplierPerformanceData, DashboardAnalytics, PermissionKey, SalesHistoryData, EmployeePerformanceData
} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' } },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.partners) parsed.partners = [];
        if (!parsed.purchaseReturns) parsed.purchaseReturns = [];
        if (!parsed.salesReturns) parsed.salesReturns = [];
        if (!parsed.purchases) parsed.purchases = [];
        if (!parsed.shippingCompanies) parsed.shippingCompanies = [];
        if (!parsed.users) parsed.users = defaultDb.users;
        if (!parsed.installments) parsed.installments = [];
        if (!parsed.notifications) parsed.notifications = [];
        if (!parsed.stockTransfers) parsed.stockTransfers = [];
        if (!parsed.journalEntries) parsed.journalEntries = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({
        id: `act-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    });
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, toTreasuryId?: string, destinationAccount?: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'transfer' && toTreasuryId) {
            const toT = db.treasuries.find((item: any) => item.id === toTreasuryId);
            if (toT) {
                t.balance -= amount;
                toT.balance += amount;
            }
        } else {
            t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        }

        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: category,
            user: 'المدير العام',
            treasuryId,
            toTreasuryId,
            destinationAccount
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => {
                if (item.id === p.id) {
                    const oldStock = item.stock || 0;
                    const diff = p.stock - oldStock;
                    const whStocks = { ...(item.warehouseStocks || {}) };
                    const firstWhId = Object.keys(whStocks)[0] || 'w-1';
                    whStocks[firstWhId] = (whStocks[firstWhId] || 0) + diff;
                    return { ...item, ...p, warehouseStocks: whStocks };
                }
                return item;
            });
            logActivity(db, 'تعديل منتج', `تعديل المنتج: ${p.name}`);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        if (sale.paymentMethod === 'Credit' && !db.settings.loyaltySettings.allowCreditPoints) {
            sale.pointsEarned = 0; 
        }

        if (sale.id) {
            const oldSale = db.sales.find((s: any) => s.id === sale.id);
            if (oldSale && oldSale.paymentMethod === 'Credit' && customer) {
                customer.debt -= (oldSale.total - oldSale.amountPaid);
            }
            db.sales = db.sales.filter((s: any) => s.id !== sale.id);
            db.installments = (db.installments || []).filter((i: any) => i.saleId !== sale.id);
        }

        if (sale.paymentMethod === 'Credit' && customer && customer.creditLimit > 0) {
            const currentDebt = customer.debt || 0;
            const newDebt = currentDebt + (sale.total - sale.amountPaid);
            if (newDebt > customer.creditLimit) {
                throw new Error(`تجاوز العميل حد الائتمان المسموح به (${customer.creditLimit}).`);
            }
        }

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                p.lastSoldDate = new Date().toISOString();
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات');

        if (customer) {
            if (sale.paymentMethod === 'Credit') {
                customer.debt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            }
            if (sale.pointsEarned > 0) customer.points = (customer.points || 0) + sale.pointsEarned;
            customer.lastPurchaseDate = new Date().toISOString();
        }

        if (sale.installmentPlan && !sale.id) {
            if (!db.installments) db.installments = [];
            const months = sale.installmentPlan.months || 1;
            const principal = sale.total - sale.amountPaid;
            const interestRate = sale.installmentPlan.interestRate || 0;
            const interestAmount = principal * (interestRate / 100) * (months / 12);
            const totalWithInterest = principal + interestAmount;
            const monthlyPayment = totalWithInterest / months;

            const generatedPayments = [];
            let currentDueDate = new Date(sale.installmentPlan.startDate || new Date());
            for (let i = 0; i < months; i++) {
                generatedPayments.push({
                    id: `pay-${id}-${i}-${Date.now()}`,
                    amount: monthlyPayment,
                    dueDate: currentDueDate.toISOString().split('T')[0],
                    status: 'Pending'
                });
                currentDueDate.setMonth(currentDueDate.getMonth() + 1);
            }

            const plan = {
                id: `plan-${Date.now()}`,
                saleId: id,
                customerName: sale.customer.name,
                remainingAmount: totalWithInterest,
                totalWithInterest: totalWithInterest,
                downPayment: sale.amountPaid,
                interestRate: interestRate,
                interestAmount: interestAmount,
                monthlyPayment: monthlyPayment,
                numberOfInstallments: months,
                status: 'Active',
                payments: generatedPayments
            };
            db.installments.push(plan);
            logActivity(db, 'خطة تقسيط', `إنشاء خطة تقسيط للفاتورة #${id} للعميل ${sale.customer.name}`);
        }

        logActivity(db, 'عملية بيع', `إتمام فاتورة مبيعات #${id} بمبلغ ${sale.total}`);
        saveDb(db); return finalSale;
    },
    saveSalesReturn: async (data: any) => {
        const db = getDb();
        const id = `RET-${Date.now()}`;
        const finalReturn = { ...data, id, date: new Date().toISOString(), user: { id: 'u-1', name: 'المدير العام' } };
        if (!db.salesReturns) db.salesReturns = [];
        db.salesReturns.unshift(finalReturn);

        const originalSale = db.sales.find((s: any) => s.id === data.originalSaleId);
        let cashToRefund = data.totalRefund;

        if (originalSale) {
            const plan = db.installments.find((i: any) => i.saleId === originalSale.id);
            const customer = db.customers.find((c: any) => c.id === originalSale.customer.id);

            if (plan && plan.status !== 'Paid Off') {
                const reductionAmount = Math.min(plan.remainingAmount, data.totalRefund);
                plan.remainingAmount -= reductionAmount;
                if (customer) customer.debt -= reductionAmount;
                cashToRefund = data.totalRefund - reductionAmount;

                // تسوية الدفعات المستقبلية
                let remainingReduction = reductionAmount;
                for (let i = plan.payments.length - 1; i >= 0; i--) {
                    if (plan.payments[i].status === 'Pending') {
                        const deduct = Math.min(plan.payments[i].amount, remainingReduction);
                        plan.payments[i].amount -= deduct;
                        remainingReduction -= deduct;
                        if (plan.payments[i].amount <= 0) plan.payments[i].status = 'Paid';
                    }
                    if (remainingReduction <= 0) break;
                }

                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
            } else if (originalSale.paymentMethod === 'Credit' && customer) {
                const reduction = Math.min(customer.debt, data.totalRefund);
                customer.debt -= reduction;
                cashToRefund = data.totalRefund - reduction;
            }

            data.items.forEach((retItem: any) => {
                const p = db.products.find((prod: any) => prod.id === retItem.id);
                if (p) {
                    if (!p.warehouseStocks) p.warehouseStocks = {};
                    p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) + retItem.returnQuantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                }
            });
            originalSale.total -= data.totalRefund;
            originalSale.amountPaid = Math.max(0, originalSale.amountPaid - cashToRefund);
        }

        if (cashToRefund > 0) logTransaction(db, 'expense', cashToRefund, `مرتجع نقدي للفاتورة #${data.originalSaleId}`, data.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مبيعات', `تسجيل مرتجع للفاتورة #${data.originalSaleId}. المسترد نقداً: ${cashToRefund}`);
        saveDb(db); return finalReturn;
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => s.status !== 'Draft' && (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = (db.transactions || []).filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));
        const salesReturns = (db.salesReturns || []).filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        let totalRevenue = 0, totalCOGS = 0, totalTax = 0;
        const prodProfitMap: Record<string, { name: string, profit: number }> = {};

        sales.forEach((s: any) => {
            totalRevenue += s.total;
            totalTax += s.vatAmount || 0;
            s.items.forEach((item: any) => {
                const prod = db.products.find((p: any) => p.id === item.id);
                const cost = (prod?.costPrice || 0) * item.quantity;
                totalCOGS += cost;
                if (!prodProfitMap[item.id]) prodProfitMap[item.id] = { name: item.name, profit: 0 };
                prodProfitMap[item.id].profit += (item.sellPrice * item.quantity) - cost;
            });
        });

        const totalReturnsValue = salesReturns.reduce((sum: number, r: any) => sum + (r.totalRefund || 0), 0);
        totalRevenue -= totalReturnsValue;
        const totalExpenses = transactions.filter((t:any) => t.type === 'expense').reduce((a:any, b:any) => a + b.amount, 0);
        const netProfit = totalRevenue - totalCOGS - totalExpenses;

        return { 
            totalRevenue, totalCOGS, totalExpenses, totalTax, netProfit, 
            productProfits: Object.entries(prodProfitMap).map(([id, d]) => ({ id, name: d.name, profit: d.profit })),
            dailyStats: []
        };
    },
    getDashboardAnalytics: async () => {
        const db = getDb();
        const sales = db.sales || [];
        const today = new Date().toISOString().split('T')[0];
        const todaySales = sales.filter((s: any) => s.date.startsWith(today));

        return {
            totalSalesToday: todaySales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaySales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + (b.debt || 0), 0),
            totalStockValue: db.products.reduce((a: number, b: any) => a + ((b.stock || 0) * (b.costPrice || 0)), 0),
            monthlySales: [], 
            salesByCategory: [],
            topProducts: (db.products || []).slice(0, 5).map((p: any) => ({ id: p.id, name: p.name, totalRevenue: p.sellPrice * 10 }))
        };
    },
    getInactiveCustomers: async (days: number) => {
        const db = getDb();
        const threshold = Date.now() - (days * 24 * 60 * 60 * 1000);
        return db.customers.filter((c: any) => {
            if (c.id === 'cust-1') return false;
            if (!c.lastPurchaseDate) return true;
            return new Date(c.lastPurchaseDate).getTime() < threshold;
        }).map((c: any) => ({
            id: c.id, name: c.name, phone: c.phone, lastPurchaseDate: c.lastPurchaseDate || 'لا يوجد مشتريات'
        }));
    },
    getStagnantProducts: async (days: number) => {
        const db = getDb();
        const threshold = Date.now() - (days * 24 * 60 * 60 * 1000);
        return db.products.filter((p: any) => {
            if (p.stock <= 0) return false;
            if (!p.lastSoldDate) return true;
            return new Date(p.lastSoldDate).getTime() < threshold;
        }).map((p: any) => ({
            id: p.id, name: p.name, stock: p.stock, lastSoldDate: p.lastSoldDate,
            daysSinceLastSale: p.lastSoldDate ? Math.floor((Date.now() - new Date(p.lastSoldDate).getTime()) / (1000*60*60*24)) : days + 1
        }));
    },
    globalSearch: async (q: string) => {
        const db = getDb();
        const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query) || p.supplier.name.toLowerCase().includes(query)),
