    savePurchaseReturn: async (data: any) => {
        const db = getDb();
        const id = `PRET-${Date.now()}`;

        // Find original purchase to get the warehouseId if not provided
        const originalPurchase = db.purchases.find((pur: any) => pur.id === data.originalPurchaseId);
        const warehouseId = data.warehouseId || originalPurchase?.warehouseId || 'w-1';

        const finalReturn = { 
            ...data, 
            id, 
            warehouseId,
            date: data.date || new Date().toISOString(), 
            user: data.user || { id: 'u-1', name: 'المدير العام' } 
        };

        if (!db.purchaseReturns) db.purchaseReturns = [];
        db.purchaseReturns.unshift(finalReturn);

        if (originalPurchase) {
            originalPurchase.total -= data.totalRecovered;
            if (originalPurchase.status === 'Paid' || originalPurchase.status === 'Partial') {
                originalPurchase.amountPaid = Math.max(0, originalPurchase.amountPaid - data.totalRecovered);
            }
        }

        // Update inventory: decrease stock because items are returned to supplier
        data.items.forEach((retItem: any) => {
            const p = db.products.find((prod: any) => prod.id === retItem.productId);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[warehouseId] = (p.warehouseStocks[warehouseId] || 0) - retItem.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
            }
        });

        // Update Treasury: increase balance since we recovered money from the supplier
        if (data.totalRecovered > 0) {
            logTransaction(db, 'income', data.totalRecovered, `مرتجع مشتريات #${data.originalPurchaseId}`, data.treasuryId, 'مرتجعات');
        }

        logActivity(db, 'مرتجع مشتريات', `تسجيل مرتجع لطلب الشراء #${data.originalPurchaseId}. المبلغ المسترد: ${data.totalRecovered}`);
        saveDb(db);
        return finalReturn;
    },
