            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid'; payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt -= payment.amount;
                logTransaction(db, 'income', payment.amount, `تحصيل قسط: ${plan.customerName}`, db.treasuries[0].id, 'أقساط');
                saveDb(db); return true;
            }
        }
        return false;
