const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' } },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        // Migration: Ensure new fields exist
        if (!parsed.suppliers) parsed.suppliers = [];
        if (!parsed.shippingCompanies) parsed.shippingCompanies = [];
        if (!parsed.partners) parsed.partners = [];
        if (!parsed.stockTransfers) parsed.stockTransfers = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift({
        id: `act-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    });
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, toTreasuryId?: string, destinationAccount?: string, shiftId?: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        if (type === 'transfer' && toTreasuryId) {
            const toT = db.treasuries.find((item: any) => item.id === toTreasuryId);
            if (toT) {
                t.balance -= amount;
                toT.balance += amount;
            }
        } else {
            t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        }

        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category: category,
            user: 'المدير العام',
            treasuryId,
            toTreasuryId,
            destinationAccount,
            shiftId // ربط الحركة المالية بالوردية
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item);
            logActivity(db, 'تعديل منتج', `تعديل المنتج: ${p.name}`);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        // منع البيع بدون وردية مفتوحة إذا كانت الميزة مفعلة
        if (db.settings.enableShiftManagement && !sale.shiftId) {
            throw new Error("يجب فتح وردية أولاً قبل تسجيل المبيعات.");
        }

        // تحديث المخزون
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                p.lastSoldDate = new Date().toISOString();
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        // تسجيل المعاملة المالية
        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات', undefined, undefined, sale.shiftId);
        }

        if (customer) {
            if (sale.paymentMethod === 'Credit' || sale.total > sale.amountPaid) {
                customer.debt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            }
            if (sale.pointsEarned > 0) customer.points = (customer.points || 0) + sale.pointsEarned;
            customer.lastPurchaseDate = new Date().toISOString();
        }

        // خطة التقسيط
        if (sale.installmentPlan && !sale.id) {
            if (!db.installments) db.installments = [];
            const months = sale.installmentPlan.months || 1;
            const principal = sale.total - sale.amountPaid;
            const interestAmount = principal * (sale.installmentPlan.interestRate / 100) * (months / 12);
            const totalWithInterest = principal + interestAmount;
            const monthlyPayment = totalWithInterest / months;

            const payments = Array.from({ length: months }, (_, i) => {
                const dueDate = new Date(sale.installmentPlan.startDate);
                dueDate.setMonth(dueDate.getMonth() + i);
                return { id: `pay-${id}-${i}`, amount: monthlyPayment, dueDate: dueDate.toISOString().split('T')[0], status: 'Pending' };
            });

            db.installments.push({
                id: `plan-${Date.now()}`, saleId: id, customerName: sale.customer.name,
                remainingAmount: totalWithInterest, totalWithInterest, downPayment: sale.amountPaid,
                interestRate: sale.installmentPlan.interestRate, interestAmount, monthlyPayment,
                numberOfInstallments: months, status: 'Active', payments
            });
            logActivity(db, 'خطة تقسيط', `إنشاء خطة تقسيط للفاتورة #${id}`);
        }

        logActivity(db, 'عملية بيع', `إتمام فاتورة مبيعات #${id} بمبلغ ${sale.total}`);
        saveDb(db); return finalSale;
    },
    saveSalesReturn: async (data: any) => {
        const db = getDb();
        const id = `RET-${Date.now()}`;
        const finalReturn = { ...data, id, date: new Date().toISOString() };
        if (!db.salesReturns) db.salesReturns = [];
        db.salesReturns.unshift(finalReturn);

        const originalSale = db.sales.find((s: any) => s.id === data.originalSaleId);
        let cashToRefund = data.totalRefund;

        if (originalSale) {
            const customer = db.customers.find((c: any) => c.id === originalSale.customer.id);

            // 1. خصم النقاط المكتسبة من المرتجع (تصحيح محاسبي للولاء)
            if (customer && db.settings.loyaltySettings.enabled) {
                const pointsToDeduct = data.totalRefund * db.settings.loyaltySettings.earningRate;
                customer.points = Math.max(0, (customer.points || 0) - pointsToDeduct);
            }

            // 2. معالجة مديونية العميل والأقساط
            const plan = db.installments.find((i: any) => i.saleId === originalSale.id);
            if (plan && plan.status !== 'Paid Off') {
                const reduction = Math.min(plan.remainingAmount, data.totalRefund);
                plan.remainingAmount -= reduction;
                if (customer) customer.debt -= reduction;
                cashToRefund -= reduction;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
            } else if (originalSale.paymentMethod === 'Credit' && customer) {
                const reduction = Math.min(customer.debt, data.totalRefund);
                customer.debt -= reduction;
                cashToRefund -= reduction;
            }

            // 3. تحديث المخزون
            data.items.forEach((retItem: any) => {
                const p = db.products.find((prod: any) => prod.id === retItem.id);
                if (p) {
                    p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) + retItem.returnQuantity;
                    p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
                }
            });
        }

        if (cashToRefund > 0) {
            logTransaction(db, 'expense', cashToRefund, `مرتجع مبيعات #${data.originalSaleId}`, data.treasuryId, 'مرتجعات');
        }

        logActivity(db, 'مرتجع مبيعات', `تسجيل مرتجع للفاتورة #${data.originalSaleId}`);
        saveDb(db); return finalReturn;
    },
    savePurchase: async (p: any) => {
        const db = getDb();
        const id = p.id || `PUR-${Date.now()}`;
        const finalP = { ...p, id, date: new Date().toISOString() };
        db.purchases.unshift(finalP);

        // تحديث مديونية المورد (Accounts Payable)
        const supplier = db.suppliers.find((s: any) => s.id === p.supplier.id);
        if (supplier && (p.paymentMethod === 'Credit' || p.total > p.amountPaid)) {
            supplier.balance = (supplier.balance || 0) + (p.total - p.amountPaid);
        }

        // تحديث المخزون
        finalP.items.forEach((item: any) => {
            const prod = db.products.find((prod: any) => prod.id === item.productId);
            if (prod) {
                if (!prod.warehouseStocks) prod.warehouseStocks = {};
                prod.warehouseStocks[finalP.warehouseId] = (prod.warehouseStocks[finalP.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
            }
        });

        if (p.amountPaid > 0) {
            logTransaction(db, 'expense', p.amountPaid, `فاتورة مشتريات #${id}`, p.treasuryId, 'مشتريات');
        }
        logActivity(db, 'طلب شراء', `تسجيل مشتريات #${id} من المورد ${p.supplier.name}`);
        saveDb(db); return finalP;
    },
    savePurchaseReturn: async (data: any) => {
        const db = getDb();
        const id = `PRET-${Date.now()}`;
        const finalReturn = { ...data, id, date: new Date().toISOString() };
        if (!db.purchaseReturns) db.purchaseReturns = [];
        db.purchaseReturns.unshift(finalReturn);

        const originalPurchase = db.purchases.find((pur: any) => pur.id === data.originalPurchaseId);
        if (originalPurchase) {
            // تخفيض مديونية المورد أولاً
            const supplier = db.suppliers.find((s: any) => s.id === originalPurchase.supplier.id);
            if (supplier && supplier.balance > 0) {
                const reduction = Math.min(supplier.balance, data.totalRecovered);
                supplier.balance -= reduction;
            }
        }

        data.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a: number, b: number) => a + b, 0);
            }
        });

        if (data.totalRecovered > 0) {
            logTransaction(db, 'income', data.totalRecovered, `مرتجع مشتريات #${data.originalPurchaseId}`, data.treasuryId, 'مرتجعات');
        }
        logActivity(db, 'مرتجع مشتريات', `تسجيل مرتجع لطلب #${data.originalPurchaseId}`);
        saveDb(db); return finalReturn;
    },
    getCurrentShift: async (userId: string) => getDb().shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null,
    openShift: async (userId: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash: amount, status: 'Open' };
        if (!db.shifts) db.shifts = [];
        db.shifts.push(shift);
        logActivity(db, 'فتح وردية', `بدء وردية جديدة برصيد افتتاحي ${amount}`);
        saveDb(db); return shift;
    },
    closeShift: async (shiftId: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === shiftId);
        if (shift) {
            // حساب النقد الفعلي من العمليات (مبدأ الرقابة المحاسبية)
            const shiftTransactions = db.transactions.filter((t: any) => t.shiftId === shiftId);
            const cashIncome = shiftTransactions.filter((t: any) => t.type === 'income').reduce((a: any, b: any) => a + b.amount, 0);
            const cashExpense = shiftTransactions.filter((t: any) => t.type === 'expense').reduce((a: any, b: any) => a + b.amount, 0);

            const expectedCash = shift.startCash + cashIncome - cashExpense;

            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.totalSales = db.sales.filter((s:any) => s.shiftId === shiftId).reduce((a:any, b:any) => a + b.total, 0);
            shift.notes = `${notes || ''} [عجز/زيادة: ${endCash - expectedCash}]`.trim();

            logActivity(db, 'إغلاق وردية', `إغلاق وردية برصيد فعلي ${endCash}. العجز/الزيادة: ${endCash - expectedCash}`);
            saveDb(db); return shift;
        }
        throw new Error("Shift not found");
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = db.transactions.filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));

        let totalRevenue = sales.reduce((a, b) => a + b.total, 0);
        let totalCOGS = 0;
        sales.forEach(s => s.items.forEach((i:any) => totalCOGS += (i.originalPrice || 0) * i.quantity));

        const totalExpenses = transactions.filter((t:any) => t.type === 'expense' && t.category !== 'مرتجعات').reduce((a, b) => a + b.amount, 0);
        const totalReturns = db.salesReturns.filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end)).reduce((a, b) => a + b.totalRefund, 0);

        return { 
            totalRevenue: totalRevenue - totalReturns, totalCOGS, totalExpenses, totalTax: (totalRevenue - totalReturns) * (db.settings.vatRate / 100), 
            netProfit: (totalRevenue - totalReturns) - totalCOGS - totalExpenses, productProfits: [], dailyStats: []
        };
