import type { DashboardAnalytics } from '../types';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import { useTranslation } from '../hooks/useTranslation';
import DashboardSkeleton from '../components/dashboard/DashboardSkeleton';

const StatCard: React.FC<{ title: string; value: string; icon: React.ReactNode, gradient: string, delay: number }> = ({ title, value, icon, gradient, delay }) => (
  <Card className={`p-0 overflow-hidden animate-slide-up group border-none shadow-premium`} style={{ animationDelay: `${delay}ms`}}>
    <div className={`p-8 bg-gradient-to-br ${gradient} text-white h-full relative`}>
      <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-110 transition-transform duration-700">
        {React.cloneElement(icon as React.ReactElement<any>, { size: 120 })}
      </div>
      <div className="relative z-10 flex flex-col justify-between h-full">
        <div className="flex justify-between items-start">
            <div className="p-3 bg-white/20 backdrop-blur-md rounded-2xl">{icon}</div>
        </div>
        <div className="mt-8">
          <p className="text-xs font-black uppercase tracking-widest text-white/70">{title}</p>
          <p className="text-3xl font-black mt-1 leading-none">{value}</p>
        </div>
      </div>
    </div>
  </Card>
);

const DashboardPage: React.FC = () => {
  const [analytics, setAnalytics] = useState<DashboardAnalytics | null>(null);
  const [loading, setLoading] = useState(true);
  const [isConfigOpen, setIsConfigOpen] = useState(false);
  const { settings, updateSettings } = useSettings();
  const { t } = useTranslation();

  const visibleCards = settings?.dashboardVisibleCards || ['revenue', 'transactions', 'receivables', 'stock'];

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const data = await api.getDashboardAnalytics();
        setAnalytics(data);
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const toggleCard = (cardId: string) => {
      const newList = visibleCards.includes(cardId) 
        ? visibleCards.filter(c => c !== cardId)
        : [...visibleCards, cardId];
      if (settings) updateSettings({ ...settings, dashboardVisibleCards: newList });
  };

  if (loading || !analytics || !settings) return <DashboardSkeleton />;

  const currency = settings.currency;

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-black text-slate-800 dark:text-white">لوحة المعلومات</h1>
            <p className="text-slate-500 font-medium mt-1">إحصائيات متقدمة لإدارة أعمالك اليوم.</p>
        </div>
        <Button variant="secondary" onClick={() => setIsConfigOpen(true)} className="rounded-2xl h-12 px-6">
            <Settings size={18} className="me-2" /> تخصيص الواجهة
        </Button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {visibleCards.includes('revenue') && <StatCard title={t('dashboard.total_sales_today')} value={formatCurrency(analytics.totalSalesToday, currency)} icon={<DollarSign />} gradient="from-indigo-600 to-blue-700" delay={0} />}
        {visibleCards.includes('transactions') && <StatCard title={t('dashboard.todays_transactions')} value={toArabicIndic(analytics.todaysTransactions.toString())} icon={<ShoppingBag />} gradient="from-purple-600 to-fuchsia-700" delay={100} />}
        {visibleCards.includes('receivables') && <StatCard title={t('dashboard.total_receivables')} value={formatCurrency(analytics.totalReceivables, currency)} icon={<Landmark />} gradient="from-rose-600 to-pink-700" delay={200} />}
        {visibleCards.includes('stock') && <StatCard title={t('dashboard.stock_value')} value={formatCurrency(analytics.totalStockValue, currency)} icon={<Package />} gradient="from-emerald-600 to-teal-700" delay={300} />}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <Card title="مخطط النمو" className="lg:col-span-2">
            <div className="h-[350px] w-full mt-6">
                <ResponsiveContainer>
                    <AreaChart data={analytics.monthlySales.length > 0 ? analytics.monthlySales : [{name: 'اليوم', sales: analytics.totalSalesToday}]}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(0,0,0,0.05)" />
                        <XAxis dataKey="name" tick={{ fontSize: 12, fill: '#94a3b8', fontWeight: 'bold' }} axisLine={false} tickLine={false} />
                        <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                        <Tooltip />
                        <Area type="monotone" dataKey="sales" stroke="#6366f1" strokeWidth={4} fill="#6366f1" fillOpacity={0.1} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </Card>
        <Card title="الأصناف الرائجة">
            <div className="space-y-6 mt-6">
                {analytics.topProducts.map((p, i) => (
                    <div key={p.id} className="flex items-center gap-4 group">
                        <div className="w-10 h-10 rounded-xl bg-indigo-50 dark:bg-slate-800 flex items-center justify-center font-black text-indigo-600">{toArabicIndic(i+1)}</div>
                        <div className="flex-grow">
                            <p className="font-black text-sm text-slate-800 dark:text-white truncate max-w-[150px]">{p.name}</p>
                            <p className="text-[10px] text-slate-400 font-bold">{formatCurrency(p.totalRevenue, currency)}</p>
                        </div>
                    </div>
                ))}
                {analytics.topProducts.length === 0 && <p className="text-center text-slate-400 text-xs py-10">لا توجد بيانات مبيعات بعد</p>}
            </div>
        </Card>
      </div>

      <Modal isOpen={isConfigOpen} onClose={() => setIsConfigOpen(false)} title="تخصيص لوحة المعلومات">
          <div className="space-y-4">
              <p className="text-sm text-slate-500 font-bold">اختر البطاقات التي ترغب في ظهورها على الشاشة الرئيسية:</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {[
                      { id: 'revenue', label: 'إجمالي مبيعات اليوم' },
                      { id: 'transactions', label: 'عدد المعاملات' },
                      { id: 'receivables', label: 'المديونيات المستحقة' },
                      { id: 'stock', label: 'قيمة المخزون' }
                  ].map(card => (
                      <button 
                        key={card.id} 
                        onClick={() => toggleCard(card.id)}
                        className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all font-black text-sm ${visibleCards.includes(card.id) ? 'border-indigo-600 bg-indigo-50 text-indigo-600' : 'border-slate-100 dark:border-slate-800 text-slate-400 opacity-60'}`}
                      >
                          {card.label}
                          {visibleCards.includes(card.id) && <Check size={18} />}
                      </button>
                  ))}
              </div>
          </div>
      </Modal>
    </div>
  );
};

