    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        for (const plan of db.installments) {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt -= payment.amount;
                logTransaction(db, 'income', payment.amount, `تحصيل قسط: ${plan.customerName}`, db.treasuries[0].id, 'أقساط');
                saveDb(db); return true;
            }
        }
        return false;
    },
    closeShift: async (shiftId: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === shiftId);
        if (shift) {
            const shiftTrans = db.transactions.filter((t: any) => t.shiftId === shiftId);
            const cashIncome = shiftTrans.filter((t: any) => t.type === 'income').reduce((a: any, b: any) => a + b.amount, 0);
            const cashExpense = shiftTrans.filter((t: any) => t.type === 'expense').reduce((a: any, b: any) => a + b.amount, 0);
            const expected = shift.startCash + cashIncome - cashExpense;

            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = `${notes || ''} [فرق: ${endCash - expected}]`.trim();
            saveDb(db); return shift;
        }
        throw new Error("Shift not found");
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = db.transactions.filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));
        let totalRevenue = sales.reduce((a, b) => a + b.total, 0);
        let totalCOGS = 0;
        sales.forEach(s => s.items.forEach((i:any) => totalCOGS += (i.costPrice || 0) * i.quantity));
        const totalExpenses = transactions.filter((t:any) => t.type === 'expense' && t.category !== 'مرتجعات').reduce((a, b) => a + b.amount, 0);
        const totalReturns = db.salesReturns.filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end)).reduce((a, b) => a + b.totalRefund, 0);
        return { 
            totalRevenue: totalRevenue - totalReturns, totalCOGS, totalExpenses, totalTax: (totalRevenue - totalReturns) * (db.settings.vatRate / 100), 
