import type { 
    Sale, Product, StoreSettings, ActivityLog, FinancialReport, 
    SalesReturn, Purchase, Partner, Treasury, InstallmentPlan,
    Notification, ShippingCompany, PurchaseReturn, Transaction,
    SyncLog, InactiveCustomer, StagnantProduct, GlobalSearchResults,
    JournalEntry, Shift, UpdatePackage, Supplier, Customer, EmployeePerformanceAnalytics,
    SatisfactionAnalytics, User, SupplierPerformanceData, DashboardAnalytics, PermissionKey, SalesHistoryData, EmployeePerformanceData
} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' }, enableShiftManagement: true },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        // Migration checks
        if (!parsed.treasuries) parsed.treasuries = defaultDb.treasuries;
        if (!parsed.transactions) parsed.transactions = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, shiftId?: string) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (t) {
        t.balance = type === 'income' ? t.balance + amount : t.balance - amount;
        db.transactions.unshift({
            id: `tr-${Date.now()}-${Math.random()}`,
            date: new Date().toISOString(),
            type,
            amount,
            description,
            category,
            user: 'المدير العام',
            treasuryId,
            shiftId
        });
    }
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        // 1. Stock Deduction (Per Warehouse)
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if (!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
                p.lastSoldDate = new Date().toISOString();
            }
        });

        // 2. Save Sale Record
        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        // 3. Treasury Logic (Income)
        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات', sale.shiftId);
        }

        // 4. Customer Debt & Loyalty Points
        if (customer) {
            // Debt
            if (sale.paymentMethod === 'Credit' || sale.total > sale.amountPaid) {
                customer.debt = (customer.debt || 0) + (sale.total - sale.amountPaid);
            }
            // Points
            if (sale.pointsRedeemed > 0) {
                customer.points = Math.max(0, (customer.points || 0) - sale.pointsRedeemed);
            }
            if (sale.pointsEarned > 0) {
                customer.points = (customer.points || 0) + sale.pointsEarned;
            }
            customer.lastPurchaseDate = new Date().toISOString();
        }

        saveDb(db); return finalSale;
    },
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const today = new Date().toISOString().split('T')[0];
        const todaysSales = db.sales.filter((s: any) => s.date.startsWith(today));

        // Calculate dynamic monthly sales
        const months = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
        const monthlyMap: Record<string, number> = {};
        db.sales.forEach((s: any) => {
            const m = new Date(s.date).getMonth();
            monthlyMap[months[m]] = (monthlyMap[months[m]] || 0) + s.total;
        });

        // Top Products
        const productStats: Record<string, {name: string, total: number}> = {};
        db.sales.forEach((s: any) => s.items.forEach((i: any) => {
            if (!productStats[i.id]) productStats[i.id] = { name: i.name, total: 0 };
            productStats[i.id].total += (i.sellPrice * i.quantity);
        }));

        return {
            totalSalesToday: todaysSales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaysSales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + (b.debt || 0), 0),
            totalStockValue: db.products.reduce((a: number, b: any) => a + ((b.stock || 0) * (b.costPrice || 0)), 0),
            monthlySales: Object.entries(monthlyMap).map(([name, sales]) => ({ name, sales })),
            salesByCategory: [],
            topProducts: Object.entries(productStats)
                .sort((a, b) => b[1].total - a[1].total)
                .slice(0, 5)
                .map(([id, data]) => ({ id, name: data.name, totalRevenue: data.total }))
        };
    },
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) {
            db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? { ...item, ...t } : item);
        } else {
            t.id = `t-${Date.now()}`;
            if (!db.treasuries) db.treasuries = [];
            db.treasuries.push(t);
        }
        saveDb(db); return t;
    },
    deleteTreasury: async (id: string) => {
        const db = getDb();
        const t = db.treasuries.find((item: any) => item.id === id);
        if (t && t.isDefault) throw new Error("لا يمكن حذف الخزينة الافتراضية");
        if (t && t.balance !== 0) throw new Error("لا يمكن حذف خزينة بها رصيد مالي");
        db.treasuries = db.treasuries.filter((item: any) => item.id !== id);
        saveDb(db);
    },
    getTreasuries: async () => getDb().treasuries,
    // Rest of the methods...
    getProducts: async () => getDb().products,
    getCustomers: async () => getDb().customers,
    getSuppliers: async () => getDb().suppliers,
    getSales: async () => getDb().sales,
    getPurchases: async () => getDb().purchases,
    getWarehouses: async () => getDb().warehouses,
    getActivityLogs: async () => getDb().activityLogs,
    getTransactions: async () => getDb().transactions,
    getInstallmentPlans: async () => getDb().installments || [],
    getSalesReturns: async () => getDb().salesReturns || [],
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getPartners: async () => getDb().partners || [],
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    getCurrentShift: async (userId: string) => getDb().shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null,
    openShift: async (userId: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash: amount, status: 'Open' };
        if (!db.shifts) db.shifts = [];
        db.shifts.push(shift);
        saveDb(db); return shift;
    },
    saveSupplier: async (s: any) => { const db = getDb(); if (s.id) db.suppliers = db.suppliers.map((i: any) => i.id === s.id ? { ...i, ...s } : i); else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); } saveDb(db); return s; },
    saveCustomer: async (c: any) => { const db = getDb(); if (c.id) db.customers = db.customers.map((i: any) => i.id === c.id ? { ...i, ...c } : i); else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); } saveDb(db); return c; },
    savePartner: async (p: any) => { const db = getDb(); if (p.id) db.partners = db.partners.map((i: any) => i.id === p.id ? { ...i, ...p } : i); else { p.id = `prt-${Date.now()}`; db.partners.push(p); } saveDb(db); return p; },
    saveWarehouse: async (w: any) => { const db = getDb(); if (w.id) db.warehouses = db.warehouses.map((i: any) => i.id === w.id ? { ...i, ...w } : i); else { w.id = `wh-${Date.now()}`; db.warehouses.push(w); } saveDb(db); return w; },
    saveTransaction: async (t: any) => { const db = getDb(); logTransaction(db, t.type, t.amount, t.description, t.treasuryId, t.category); saveDb(db); return t; },
    deleteProduct: async (id: string) => { const db = getDb(); db.products = db.products.filter((p:any) => p.id !== id); saveDb(db); },
    deleteWarehouse: async (id: string) => { const db = getDb(); db.warehouses = db.warehouses.filter((w:any) => w.id !== id); saveDb(db); },
    deleteSalesReturn: async (id: string) => { const db = getDb(); db.salesReturns = db.salesReturns.filter((r:any) => r.id !== id); saveDb(db); return true; },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => { 
        const db = getDb(); 
        const fromT = db.treasuries.find((t:any)=>t.id===fromId);
        const toT = db.treasuries.find((t:any)=>t.id===toId);
        if(fromT && toT) {
            fromT.balance -= amount; toT.balance += amount;
            db.transactions.unshift({ id: `tr-${Date.now()}`, date: new Date().toISOString(), type: 'transfer', amount, description: desc, treasuryId: fromId, toTreasuryId: toId, category: 'تحويل مالي' });
            saveDb(db); return true;
        }
        return false;
    },
    exportTreasury: async (trId: string, amount: number, dest: string, desc: string) => { 
        const db = getDb(); 
        const t = db.treasuries.find((item:any)=>item.id===trId);
        if(t) {
            t.balance -= amount;
            db.transactions.unshift({ id: `tr-${Date.now()}`, date: new Date().toISOString(), type: 'export', amount, description: desc, treasuryId: trId, destinationAccount: dest, category: 'تصدير مالي' });
            saveDb(db); return true;
        }
        return false;
    },
    savePurchase: async (p: any) => {
        const db = getDb();
        const id = p.id || `PUR-${Date.now()}`;
        const finalP = { ...p, id, date: new Date().toISOString() };
        db.purchases.unshift(finalP);
        finalP.items.forEach((item: any) => {
            const prod = db.products.find((prod: any) => prod.id === item.productId);
            if (prod) {
                if (!prod.warehouseStocks) prod.warehouseStocks = {};
                prod.warehouseStocks[finalP.warehouseId] = (prod.warehouseStocks[finalP.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (p.amountPaid > 0) logTransaction(db, 'expense', p.amountPaid, `فاتورة مشتريات #${id}`, p.treasuryId, 'مشتريات');
        saveDb(db); return finalP;
    },
    saveSalesReturn: async (data: any) => {
        const db = getDb();
        const id = `RET-${Date.now()}`;
        if (!db.salesReturns) db.salesReturns = [];
        db.salesReturns.unshift({ ...data, id, date: new Date().toISOString() });
        data.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (data.totalRefund > 0) logTransaction(db, 'expense', data.totalRefund, `مرتجع مبيعات #${data.originalSaleId}`, data.treasuryId, 'مرتجعات');
        saveDb(db); return { ...data, id };
    },
    savePurchaseReturn: async (data: any) => {
        const db = getDb();
        const id = `PRET-${Date.now()}`;
        if (!db.purchaseReturns) db.purchaseReturns = [];
        db.purchaseReturns.unshift({ ...data, id, date: new Date().toISOString() });
        data.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                p.warehouseStocks[data.warehouseId] = (p.warehouseStocks[data.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (data.totalRecovered > 0) logTransaction(db, 'income', data.totalRecovered, `مرتجع مشتريات #${data.originalPurchaseId}`, data.treasuryId, 'مرتجعات');
        saveDb(db); return { ...data, id };
    },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb();
        const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query) || p.supplier.name.toLowerCase().includes(query)),
            suppliers: db.suppliers.filter((s:any) => s.name.toLowerCase().includes(query)),
            partners: db.partners.filter((p:any) => p.name.toLowerCase().includes(query)),
            salesReturns: db.salesReturns.filter((r:any) => r.id.toLowerCase().includes(query)),
            purchaseReturns: db.purchaseReturns.filter((r:any) => r.id.toLowerCase().includes(query)),
            installments: db.installments.filter((i:any) => i.customerName.toLowerCase().includes(query)),
            stockTransfers: db.stockTransfers.filter((st:any) => st.id.toLowerCase().includes(query))
        };
    },
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        for (const plan of db.installments) {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';
                const customer = db.customers.find((c: any) => c.name === plan.customerName);
                if (customer) customer.debt -= payment.amount;
                logTransaction(db, 'income', payment.amount, `تحصيل قسط: ${plan.customerName}`, db.treasuries[0].id, 'أقساط');
                saveDb(db); return true;
            }
        }
        return false;
    },
    closeShift: async (shiftId: string, endCash: number, notes?: string) => {
        const db = getDb();
        const shift = db.shifts.find((s: any) => s.id === shiftId);
        if (shift) {
            shift.status = 'Closed';
            shift.endTime = new Date().toISOString();
            shift.endCash = endCash;
            shift.notes = notes;
            saveDb(db); return shift;
        }
        throw new Error("Shift not found");
    },
    getFinancialReport: async (start: string, end: string) => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = db.transactions.filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));
        let totalRevenue = sales.reduce((a, b) => a + b.total, 0);
        let totalCOGS = 0;
        sales.forEach(s => s.items.forEach((i:any) => totalCOGS += (i.costPrice || 0) * i.quantity));
        const totalExpenses = transactions.filter((t:any) => t.type === 'expense').reduce((a, b) => a + b.amount, 0);
        return { totalRevenue, totalCOGS, totalExpenses, totalPurchases: 0, totalReturns: 0, totalTax: totalRevenue * (db.settings.vatRate / 100), netProfit: totalRevenue - totalCOGS - totalExpenses, productProfits: [], dailyStats: [] };
    },
    login: async (n: string, p: string) => getDb().users.find((u: any) => u.name === n && u.password === p) || null,
    getUsers: async () => getDb().users,
    saveUser: async (u: any) => { const db = getDb(); if (u.id) db.users = db.users.map((i: any) => i.id === u.id ? { ...i, ...u } : i); else { u.id = `u-${Date.now()}`; db.users.push(u); } saveDb(db); return u; },
    verifyPassword: async (uid: string, p: string) => getDb().users.find((u:any)=>u.id===uid)?.password === p,
    addNotification: async (n: any) => { const db = getDb(); if (!db.notifications) db.notifications = []; const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n }; db.notifications.unshift(newN); saveDb(db); return newN; },
    getNotifications: async () => getDb().notifications || [],
    wipeBusinessData: async () => { const db = getDb(); db.products = []; db.sales = []; db.purchases = []; db.customers = db.customers.filter((c: any) => c.id === 'cust-1'); db.suppliers = []; db.transactions = []; saveDb(db); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    updateSale: async (id: string, data: any) => { const db = getDb(); db.sales = db.sales.map((s:any)=>s.id===id?{...s,...data}:s); saveDb(db); },
    updatePurchase: async (id: string, data: any) => { const db = getDb(); db.purchases = db.purchases.map((p:any)=>p.id===id?{...p,...data}:p); saveDb(db); },
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    getJournalEntries: async () => [],
    getSyncLogs: async () => [],
    getQueueCount: async () => 0,
    processQueue: async () => {},
    setOnlineStatus: (o: boolean) => {},
    submitFeedback: async (f: any) => {},
    getSalesHistoryForForecast: async () => [],
    getSupplierPerformanceData: async () => [],
    getInactiveCustomers: async (d: number) => [],
    getStagnantProducts: async (d: number) => [],
    updateSystemVersion: async (v: string, p: any) => {},
    getEmployeePerformanceAnalytics: async () => ({ performanceData: [] }),
    getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }),
    saveShippingCompany: async (c: any) => { const db = getDb(); if (c.id) db.shippingCompanies = db.shippingCompanies.map((i: any) => i.id === c.id ? { ...i, ...c } : i); else { c.id = `shp-${Date.now()}`; db.shippingCompanies.push(c); } saveDb(db); return c; },
    deleteShippingCompany: async (id: string) => { const db = getDb(); db.shippingCompanies = db.shippingCompanies.filter((c:any) => c.id !== id); saveDb(db); },
    getStockTransfers: async () => getDb().stockTransfers || [],
    bulkUpdateProducts: async (updated: Product[]) => { const db = getDb(); updated.forEach(up => { db.products = db.products.map((p: any) => p.id === up.id ? up : p); }); saveDb(db); }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Transaction, Treasury } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import TransactionFormModal from '../components/treasury/TransactionFormModal';
import { PlusCircle, Wallet, ArrowRightLeft, RefreshCw, Download, Search, Trash2, Building } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import TreasurySkeleton from '../components/treasury/TreasurySkeleton';
import { useToasts } from '../hooks/useToasts';
import { exportToCsv } from '../utils/export';
import ConfirmDialog from '../components/ui/ConfirmDialog';

const TreasuryPage: React.FC = () => {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isTreasuryModalOpen, setIsTreasuryModalOpen] = useState(false);
    const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // نموذج الخزينة الجديدة
    const [newTreasury, setNewTreasury] = useState({ name: '', currency: 'SAR', balance: 0 });

    const [searchTerm, setSearchTerm] = useState('');
    const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

    const { settings } = useSettings();
    const { addToast } = useToasts();

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [transData, treasuryData] = await Promise.all([api.getTransactions(), api.getTreasuries()]);
            setTransactions(transData || []);
            setTreasuries(treasuryData || []);
        } catch (e) { addToast("خطأ في تحميل البيانات", "error"); } finally { setLoading(false); }
    }, [addToast]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const handleCreateTreasury = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newTreasury.name) return;
        setIsSaving(true);
        try {
            await api.saveTreasury({ ...newTreasury, isDefault: false });
            addToast("تم إنشاء الخزينة بنجاح", "success");
            setIsTreasuryModalOpen(false);
            setNewTreasury({ name: '', currency: settings?.currency || 'SAR', balance: 0 });
            await fetchData();
        } catch (e) { addToast("فشل إنشاء الخزينة", "error"); } finally { setIsSaving(false); }
    };

    const handleDeleteTreasury = async () => {
        if (!confirmDeleteId) return;
        try {
            await api.deleteTreasury(confirmDeleteId);
            addToast("تم حذف الخزينة بنجاح", "success");
            await fetchData();
        } catch (e: any) {
            addToast(e.message || "فشل الحذف", "error");
        } finally { setConfirmDeleteId(null); }
    };

    const filteredTransactions = useMemo(() => {
        return transactions.filter(t => 
            t.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
            t.category.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [transactions, searchTerm]);

    if (loading || !settings) return <TreasurySkeleton />;

    return (
        <div className="animate-fadeIn">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-3xl font-black text-slate-800 dark:text-white">الخزينة والحسابات</h1>
                    <p className="text-sm text-slate-500 font-bold">إدارة السيولة النقدية وتتبع الحركات المالية.</p>
                </div>
                <div className="flex flex-wrap gap-2">
                    <Button onClick={() => setIsTreasuryModalOpen(true)} variant="secondary" className="rounded-2xl h-11 border-indigo-200 text-indigo-600 font-black">
                        <Building size={18} className="me-2" /> إنشاء خزينة
                    </Button>
                    <Button onClick={() => setIsTransferModalOpen(true)} variant="secondary" className="rounded-2xl h-11 font-black">
                        <ArrowRightLeft size={18} className="me-2" /> تحويل بين الخزائن
                    </Button>
                    <Button onClick={() => setIsModalOpen(true)} className="rounded-2xl h-11 px-6 shadow-lg shadow-indigo-500/20 font-black">
                        <PlusCircle size={18} className="me-2" /> تسجيل حركة
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                {treasuries.map(t => (
                    <div key={t.id} className="bg-white dark:bg-slate-800 p-6 rounded-3xl border shadow-sm group hover:border-indigo-200 transition-all relative">
                        {!t.isDefault && (
                            <button onClick={() => setConfirmDeleteId(t.id)} className="absolute top-4 end-4 p-2 text-slate-300 hover:text-rose-500 transition-colors">
                                <Trash2 size={16} />
                            </button>
                        )}
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-2xl text-indigo-600"><Wallet size={24} /></div>
                            <h4 className="font-black text-slate-800 dark:text-white text-lg">{t.name}</h4>
                        </div>
                        <p className="text-2xl font-black text-slate-800 dark:text-white mt-4">{formatCurrency(t.balance || 0, t.currency || settings.currency)}</p>
                        {t.isDefault && <span className="text-[10px] font-black text-indigo-500 uppercase mt-2 block">الخزينة الافتراضية</span>}
                    </div>
                ))}
            </div>

            <Card className="p-0 shadow-premium overflow-hidden border-none">
                <div className="p-6 bg-slate-50 dark:bg-slate-900/50 border-b dark:border-slate-800 flex justify-between items-center gap-4 flex-wrap">
                    <h3 className="font-black text-lg">سجل الحركات المالية</h3>
                    <div className="relative w-full sm:w-72">
                        <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="بحث في الوصف أو الفئة..." 
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full h-11 ps-10 pe-4 rounded-xl bg-white dark:bg-slate-800 border dark:border-slate-700 font-bold text-xs outline-none focus:border-indigo-500"
                        />
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-start">
                        <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                            <tr>
                                <th className="px-6 py-4">التاريخ</th>
                                <th className="px-6 py-4">النوع</th>
                                <th className="px-6 py-4">الفئة</th>
                                <th className="px-6 py-4">البيان</th>
                                <th className="px-6 py-4 text-end">المبلغ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y dark:divide-slate-800">
                            {filteredTransactions.map(t => (
                                <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                                    <td className="px-6 py-4 font-bold text-xs">{new Date(t.date).toLocaleDateString('ar-EG')}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 text-[10px] font-black rounded-full ${t.type === 'income' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                                            {t.type === 'income' ? 'إيداع' : 'سحب'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4"><span className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500">{t.category}</span></td>
                                    <td className="px-6 py-4 font-medium text-xs max-w-xs truncate">{t.description}</td>
                                    <td className={`px-6 py-4 text-end font-black text-lg ${t.type === 'income' ? 'text-emerald-600' : 'text-rose-600'}`}>
                                        {formatCurrency(t.amount || 0, settings.currency)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
