                            className="w-full p-2.5 border rounded-xl dark:bg-slate-800 outline-none focus:border-indigo-500 font-black" 
                        />
                    </div>
                    <div className="flex justify-end gap-2 pt-4">
                        <Button variant="secondary" type="button" onClick={() => setIsTreasuryModalOpen(false)}>إلغاء</Button>
                        <Button type="submit" isLoading={isSaving}>إنشاء الخزينة</Button>
                    </div>
                </form>
            </Modal>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="تسجيل حركة">
                <TransactionFormModal transaction={null} onSave={async (d) => { await api.saveTransaction(d); await fetchData(); setIsModalOpen(false); }} onCancel={() => setIsModalOpen(false)} isLoading={isSaving} />
            </Modal>

            <ConfirmDialog 
                isOpen={!!confirmDeleteId} 
                onClose={() => setConfirmDeleteId(null)} 
                onConfirm={handleDeleteTreasury} 
                title="حذف الخزينة" 
                message="هل أنت متأكد من حذف هذه الخزينة؟ لا يمكن تراجع عن هذا الإجراء ولا يمكن حذف الخزينة إلا إذا كان رصيدها صفراً."
            />
        </div>
    );
};

