    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let foundPlan: any = null;
        let foundPayment: any = null;

        if (db.installments) {
            for (const plan of db.installments) {
                const payment = plan.payments?.find((p: any) => p.id === paymentId);
                if (payment) {
                    foundPlan = plan;
                    foundPayment = payment;
                    break;
                }
            }
        }

        if (foundPlan && foundPayment && foundPayment.status === 'Pending') {
            foundPayment.status = 'Paid';
            foundPayment.paidAt = new Date().toISOString();

            // Add to treasury
            const defaultTreasury = db.treasuries.find((t: any) => t.isDefault) || db.treasuries[0];
            if (defaultTreasury) {
                logTransaction(db, 'income', foundPayment.amount, `تحصيل قسط: ${foundPlan.customerName}`, defaultTreasury.id, 'أقساط');
            }

            // Update remaining amount
            foundPlan.remainingAmount = Math.max(0, foundPlan.remainingAmount - foundPayment.amount);

            // Check if finished
            if (foundPlan.remainingAmount <= 0) {
                foundPlan.status = 'Paid Off';
            }

            // Update customer debt
            const sale = db.sales.find((s: any) => s.id === foundPlan.saleId);
            if (sale) {
                const customer = db.customers.find((c: any) => c.id === sale.customer.id);
                if (customer) {
                    customer.debt = Math.max(0, customer.debt - foundPayment.amount);
                }
            }

            saveDb(db);
            return true;
        }
        return false;
    }
};

