import type { 
    Sale, Product, StoreSettings, ActivityLog, FinancialReport, 
    SalesReturn, Purchase, Partner, Treasury, InstallmentPlan,
    Notification, ShippingCompany, PurchaseReturn, Transaction,
    SyncLog, InactiveCustomer, StagnantProduct, GlobalSearchResults,
    JournalEntry, Shift, UpdatePackage, Supplier, Customer, EmployeePerformanceAnalytics,
    SatisfactionAnalytics, User, SupplierPerformanceData, DashboardAnalytics, PermissionKey, SalesHistoryData, EmployeePerformanceData
} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' }, enableShiftManagement: true },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: [],
        feedback: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.treasuries || parsed.treasuries.length === 0) parsed.treasuries = defaultDb.treasuries;
        if (!parsed.transactions) parsed.transactions = [];
        if (!parsed.notifications) parsed.notifications = [];
        if (!parsed.activityLogs) parsed.activityLogs = [];
        if (!parsed.installments) parsed.installments = [];
        if (!parsed.salesReturns) parsed.salesReturns = [];
        if (!parsed.purchaseReturns) parsed.purchaseReturns = [];
        if (!parsed.stockTransfers) parsed.stockTransfers = [];
        if (!parsed.journalEntries) parsed.journalEntries = [];
        if (!parsed.partners) parsed.partners = [];
        if (!parsed.shippingCompanies) parsed.shippingCompanies = [];
        if (!parsed.feedback) parsed.feedback = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, extra?: any) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (!t) return;

    if (type === 'income') {
        t.balance += amount;
    } else {
        t.balance -= amount;
    }

    const transaction = {
        id: `tr-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        date: new Date().toISOString(),
        type,
        amount,
        description,
        category,
        user: 'المدير العام',
        treasuryId,
        ...extra
    };

    db.transactions.unshift(transaction);
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
        }
        saveDb(db); return p;
    },
    // FIX: Added bulkUpdateProducts for multiple product price updates
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        db.products = db.products.map(p => {
            const updated = products.find(up => up.id === p.id);
            return updated ? updated : p;
        });
        saveDb(db);
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);
        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);
        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات', { shiftId: sale.shiftId });
        }
        if (customer) {
            const unpaid = sale.total - sale.amountPaid;
            if (unpaid > 0) customer.debt = (customer.debt || 0) + unpaid;
            if (sale.pointsRedeemed > 0) customer.points = Math.max(0, (customer.points || 0) - sale.pointsRedeemed);
            if (sale.pointsEarned > 0) customer.points = (customer.points || 0) + sale.pointsEarned;
            customer.lastPurchaseDate = new Date().toISOString();
        }
        saveDb(db); return finalSale;
    },
    // FIX: Added updateSale for editing existing sales
    updateSale: async (id: string, updates: any) => {
        const db = getDb();
        db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...updates } : s);
        saveDb(db);
    },
    // FIX: Added savePurchase to handle buying inventory
    savePurchase: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.purchases = db.purchases.map((item: any) => item.id === p.id ? { ...item, ...p } : item);
        } else {
            p.id = `pur-${Date.now()}`;
            p.date = new Date().toISOString();
            p.status = p.paymentMethod === 'Credit' ? 'Unpaid' : (p.amountPaid < p.total ? 'Partial' : 'Paid');
            db.purchases.unshift(p);
        }
        p.items.forEach((item: any) => {
            const prod = db.products.find((pr: any) => pr.id === item.productId);
            if (prod) {
                prod.warehouseStocks[p.warehouseId] = (prod.warehouseStocks[p.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (p.amountPaid > 0) {
            logTransaction(db, 'expense', p.amountPaid, `فاتورة مشتريات #${p.id}`, p.treasuryId, 'مبيعات');
        }
        saveDb(db);
        return p;
    },
    // FIX: Added updatePurchase for editing existing purchases
    updatePurchase: async (id: string, updates: any) => {
        const db = getDb();
        db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...updates } : p);
        saveDb(db);
    },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => { 
        const db = getDb(); 
        const fromT = db.treasuries.find((t:any)=>t.id===fromId);
        const toT = db.treasuries.find((t:any)=>t.id===toId);
        if(fromT && toT && fromT.balance >= amount) {
            logTransaction(db, 'transfer', amount, `تحويل صادر إلى ${toT.name}: ${desc}`, fromId, 'تحويلات');
            logTransaction(db, 'income', amount, `تحويل وارد من ${fromT.name}: ${desc}`, toId, 'تحويلات', { fromTreasuryId: fromId });
            saveDb(db); return true;
        }
        return false;
    },
    exportTreasury: async (trId: string, amount: number, dest: string, desc: string) => { 
        const db = getDb(); 
        const t = db.treasuries.find((item:any)=>item.id===trId);
        if(t && t.balance >= amount) {
            logTransaction(db, 'export', amount, `تصدير مالي إلى ${dest}: ${desc}`, trId, 'تصدير مالي', { destinationAccount: dest });
            saveDb(db); return true;
        }
        return false;
    },
    saveTreasury: async (t: any) => {
        const db = getDb();
