const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' }, enableShiftManagement: true },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: [],
        feedback: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.treasuries || parsed.treasuries.length === 0) parsed.treasuries = defaultDb.treasuries;
        if (!parsed.transactions) parsed.transactions = [];
        if (!parsed.sales) parsed.sales = [];
        if (!parsed.products) parsed.products = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, extra?: any) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (!t) return;

    if (type === 'income') {
        t.balance += amount;
    } else {
        t.balance -= amount;
    }

    const transaction = {
        id: `tr-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        date: new Date().toISOString(),
        type,
        amount,
        description,
        category,
        user: 'المدير العام',
        treasuryId,
        ...extra
    };

    db.transactions.unshift(transaction);
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if(!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات', { shiftId: sale.shiftId });
        }

        if (customer) {
            const unpaid = sale.total - sale.amountPaid;
            if (unpaid > 0) customer.debt = (customer.debt || 0) + unpaid;
            if (sale.pointsRedeemed > 0) customer.points = Math.max(0, (customer.points || 0) - sale.pointsRedeemed);
            if (sale.pointsEarned > 0) customer.points = (customer.points || 0) + sale.pointsEarned;
            customer.lastPurchaseDate = new Date().toISOString();
        }
        saveDb(db); return finalSale;
    },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => { 
        const db = getDb(); 
        const fromT = db.treasuries.find((t:any)=>t.id===fromId);
        const toT = db.treasuries.find((t:any)=>t.id===toId);
        if(fromT && toT && fromT.balance >= amount) {
            logTransaction(db, 'transfer', amount, `تحويل صادر إلى ${toT.name}: ${desc}`, fromId, 'تحويلات');
            logTransaction(db, 'income', amount, `تحويل وارد من ${fromT.name}: ${desc}`, toId, 'تحويلات', { fromTreasuryId: fromId });
            saveDb(db); return true;
        }
        return false;
    },
    exportTreasury: async (trId: string, amount: number, dest: string, desc: string) => { 
        const db = getDb(); 
        const t = db.treasuries.find((item:any)=>item.id===trId);
        if(t && t.balance >= amount) {
            logTransaction(db, 'export', amount, `تصدير مالي إلى ${dest}: ${desc}`, trId, 'تصدير مالي', { destinationAccount: dest });
            saveDb(db); return true;
        }
        return false;
    },
    getTreasuries: async () => getDb().treasuries,
    getTransactions: async () => getDb().transactions,
    getFinancialReport: async (start: string, end: string): Promise<FinancialReport> => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = db.transactions.filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));
        const returns = db.salesReturns.filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        const totalRevenue = sales.reduce((a:number, b:any) => a + b.total, 0);
        const totalReturns = returns.reduce((a:number, b:any) => a + b.totalRefund, 0);
        const totalExpenses = transactions.filter((t:any) => t.type === 'expense').reduce((a:number, b:any) => a + b.amount, 0);

        let totalCOGS = 0;
        sales.forEach((s:any) => s.items.forEach((i:any) => totalCOGS += (i.originalPrice || 0) * i.quantity));

        const netProfit = (totalRevenue - totalReturns) - totalCOGS - totalExpenses;

        return {
            totalRevenue: totalRevenue - totalReturns,
            totalCOGS,
            totalExpenses,
            totalPurchases: 0,
            totalReturns,
            totalTax: (totalRevenue - totalReturns) * (db.settings.vatRate / 100),
            netProfit,
            productProfits: [],
            dailyStats: []
        };
    },
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const today = new Date().toISOString().split('T')[0];
        const todaysSales = db.sales.filter((s: any) => s.date.startsWith(today));
        return {
            totalSalesToday: todaysSales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaysSales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + (b.debt || 0), 0),
            totalStockValue: db.products.reduce((a: number, b: any) => a + ((b.stock || 0) * (b.costPrice || 0)), 0),
            monthlySales: [],
            salesByCategory: [],
            topProducts: db.products.slice(0, 5).map((p: any) => ({ id: p.id, name: p.name, totalRevenue: 0 }))
        };
    },
    getCustomers: async () => getDb().customers,
    getSuppliers: async () => getDb().suppliers,
    getSales: async () => getDb().sales,
    getPurchases: async () => getDb().purchases,
    getWarehouses: async () => getDb().warehouses,
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? { ...item, ...t } : item);
        else { t.id = `t-${Date.now()}`; db.treasuries.push(t); }
        saveDb(db); return t;
    },
    deleteTreasury: async (id: string) => {
        const db = getDb();
        const t = db.treasuries.find((item: any) => item.id === id);
        if (t && t.isDefault) throw new Error("لا يمكن حذف الخزينة الافتراضية");
        if (t && t.balance !== 0) throw new Error("لا يمكن حذف خزينة بها رصيد مالي");
        db.treasuries = db.treasuries.filter((item: any) => item.id !== id);
        saveDb(db);
    },
    saveCustomer: async (c: any) => { const db = getDb(); if (c.id) db.customers = db.customers.map((i: any) => i.id === c.id ? { ...i, ...c } : i); else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); } saveDb(db); return c; },
    saveSupplier: async (s: any) => { const db = getDb(); if (s.id) db.suppliers = db.suppliers.map((i: any) => i.id === s.id ? { ...i, ...s } : i); else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); } saveDb(db); return s; },
    saveWarehouse: async (w: any) => { const db = getDb(); if (w.id) db.warehouses = db.warehouses.map((i: any) => i.id === w.id ? { ...i, ...w } : i); else { w.id = `wh-${Date.now()}`; db.warehouses.push(w); } saveDb(db); return w; },
    saveTransaction: async (t: any) => { const db = getDb(); logTransaction(db, t.type, t.amount, t.description, t.treasuryId, t.category); saveDb(db); return t; },
    deleteProduct: async (id: string) => { const db = getDb(); db.products = db.products.filter((p:any) => p.id !== id); saveDb(db); },
    deleteWarehouse: async (id: string) => { const db = getDb(); db.warehouses = db.warehouses.filter((w:any) => w.id !== id); saveDb(db); },
    getCurrentShift: async (userId: string) => getDb().shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null,
    openShift: async (userId: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash: amount, status: 'Open' };
        if (!db.shifts) db.shifts = [];
        db.shifts.push(shift);
        saveDb(db); return shift;
    },
    closeShift: async (id: string, endCash: number, notes?: string) => {
        const db = getDb(); const shift = db.shifts.find((s: any) => s.id === id);
        if (shift) {
            shift.status = 'Closed'; shift.endTime = new Date().toISOString(); shift.endCash = endCash; shift.notes = notes;
            saveDb(db); return shift;
        }
        throw new Error("Shift not found");
    },
    getPartners: async () => getDb().partners || [],
    getSalesReturns: async () => getDb().salesReturns || [],
    saveSalesReturn: async (r: any) => {
        const db = getDb(); r.id = `sr-${Date.now()}`; r.date = new Date().toISOString(); if (!db.salesReturns) db.salesReturns = []; db.salesReturns.unshift(r);
        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (r.totalRefund > 0) logTransaction(db, 'expense', r.totalRefund, `مرتجع مبيعات #${r.originalSaleId}`, r.treasuryId, 'مرتجعات');
        saveDb(db); return r;
    },
    deleteSalesReturn: async (id: string) => {
        const db = getDb(); const ret = db.salesReturns.find((r: any) => r.id === id);
        if (ret) {
            logTransaction(db, 'income', ret.totalRefund, `التراجع عن مرتجع #${id}`, ret.treasuryId, 'مرتجعات');
            ret.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.id);
                if (p) p.warehouseStocks[ret.warehouseId] -= item.returnQuantity;
            });
            db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id);
            saveDb(db); return true;
        }
        return false;
    },
    savePurchase: async (p: any) => {
        const db = getDb(); p.id = p.id || `pur-${Date.now()}`; p.date = new Date().toISOString(); db.purchases.unshift(p);
        p.items.forEach((item: any) => {
            const prod = db.products.find((pr: any) => pr.id === item.productId);
            if (prod) {
                prod.warehouseStocks[p.warehouseId] = (prod.warehouseStocks[p.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (p.amountPaid > 0) logTransaction(db, 'expense', p.amountPaid, `شراء بضاعة #${p.id}`, p.treasuryId, 'مشتريات');
        saveDb(db); return p;
    },
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb(); const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query)),
            suppliers: db.suppliers.filter((s:any) => s.name.toLowerCase().includes(query)),
            partners: db.partners.filter((p:any) => p.name.toLowerCase().includes(query)),
            salesReturns: db.salesReturns.filter((r:any) => r.id.toLowerCase().includes(query)),
            purchaseReturns: [], installments: [], stockTransfers: []
        };
    },
    getUsers: async () => getDb().users,
    login: async (n: string, p: string) => getDb().users.find((u: any) => u.name === n && u.password === p) || null,
    verifyPassword: async (uid: string, p: string) => getDb().users.find((u:any)=>u.id===uid)?.password === p,
    wipeBusinessData: async () => { const db = getDb(); db.products = []; db.sales = []; db.purchases = []; db.customers = db.customers.filter((c: any) => c.id === 'cust-1'); db.suppliers = []; db.transactions = []; db.shifts = []; db.salesReturns = []; saveDb(db); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    addNotification: async (n: any) => { const db = getDb(); if (!db.notifications) db.notifications = []; const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n }; db.notifications.unshift(newN); saveDb(db); return newN; },
    getNotifications: async () => getDb().notifications || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    getSyncLogs: async () => [], getQueueCount: async () => 0, processQueue: async () => {}, setOnlineStatus: (o: boolean) => {}, getEmployeePerformanceAnalytics: async () => ({ performanceData: [] }), getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }), getSalesHistoryForForecast: async () => [], getSupplierPerformanceData: async () => [], getInactiveCustomers: async (d: number) => [], getStagnantProducts: async (d: number) => [], updateSystemVersion: async (v: string, p: any) => {}, getJournalEntries: async () => []
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { Transaction, Treasury } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import TransactionFormModal from '../components/treasury/TransactionFormModal';
import { PlusCircle, Wallet, ArrowRightLeft, RefreshCw, Search, Trash2, Building, ExternalLink, Calendar, Filter } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic } from '../utils/localization';
import TreasurySkeleton from '../components/treasury/TreasurySkeleton';
import { useToasts } from '../hooks/useToasts';
import ConfirmDialog from '../components/ui/ConfirmDialog';

const TreasuryPage: React.FC = () => {
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);
    const [loading, setLoading] = useState(true);

    // Modals
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isTreasuryModalOpen, setIsTreasuryModalOpen] = useState(false);
    const [isTransferModalOpen, setIsTransferModalOpen] = useState(false);
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);

    const [isSaving, setIsSaving] = useState(false);

    // Search & Filter States
    const [searchTerm, setSearchTerm] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [filterType, setFilterType] = useState('all');

    const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

    // Form States
    const [newTreasury, setNewTreasury] = useState({ name: '', currency: 'SAR', balance: 0 });
    const [transferData, setTransferData] = useState({ from: '', to: '', amount: 0, desc: '' });
    const [exportData, setExportData] = useState({ from: '', dest: '', amount: 0, desc: '' });

    const { settings } = useSettings();
    const { addToast } = useToasts();

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [transData, treasuryData] = await Promise.all([api.getTransactions(), api.getTreasuries()]);
            setTransactions(transData || []);
            setTreasuries(treasuryData || []);
            if (treasuryData.length > 0) {
                setTransferData(prev => ({ ...prev, from: treasuryData[0].id, to: treasuryData[1]?.id || treasuryData[0].id }));
                setExportData(prev => ({ ...prev, from: treasuryData[0].id }));
            }
        } catch (e) { addToast("خطأ في تحميل البيانات", "error"); } finally { setLoading(false); }
    }, [addToast]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const handleCreateTreasury = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newTreasury.name) return;
        setIsSaving(true);
        try {
            await api.saveTreasury({ ...newTreasury, isDefault: false });
            addToast("تم إنشاء الخزينة بنجاح", "success");
            setIsTreasuryModalOpen(false);
            setNewTreasury({ name: '', currency: settings?.currency || 'SAR', balance: 0 });
            await fetchData();
        } catch (e) { addToast("فشل إنشاء الخزينة", "error"); } finally { setIsSaving(false); }
    };

    const handleTransfer = async (e: React.FormEvent) => {
        e.preventDefault();
        if (transferData.from === transferData.to) { addToast("لا يمكن التحويل لنفس الخزينة", "warning"); return; }
        setIsSaving(true);
        try {
            const success = await api.transferFunds(transferData.from, transferData.to, transferData.amount, transferData.desc);
            if (success) {
                addToast("تم التحويل بنجاح", "success");
                setIsTransferModalOpen(false);
                setTransferData({ ...transferData, amount: 0, desc: '' });
                await fetchData();
            } else { addToast("رصيد غير كافٍ في الخزينة المصدر", "error"); }
        } catch (e) { addToast("خطأ في العملية", "error"); } finally { setIsSaving(false); }
    };

    const handleExport = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            const success = await api.exportTreasury(exportData.from, exportData.amount, exportData.dest, exportData.desc);
            if (success) {
                addToast("تم التصدير المالي بنجاح", "success");
                setIsExportModalOpen(false);
                setExportData({ ...exportData, amount: 0, dest: '', desc: '' });
                await fetchData();
            } else { addToast("رصيد غير كافٍ للتصدير", "error"); }
        } catch (e) { addToast("خطأ في العملية", "error"); } finally { setIsSaving(false); }
    };

    const filteredTransactions = useMemo(() => {
        return transactions.filter(t => {
            const matchesSearch = t.description.toLowerCase().includes(searchTerm.toLowerCase()) || t.category.toLowerCase().includes(searchTerm.toLowerCase());
            const transDate = t.date.split('T')[0];
            const matchesDate = (!startDate || transDate >= startDate) && (!endDate || transDate <= endDate);
            const matchesType = filterType === 'all' || t.type === filterType;
            return matchesSearch && matchesDate && matchesType;
        });
    }, [transactions, searchTerm, startDate, endDate, filterType]);

    if (loading || !settings) return <TreasurySkeleton />;

    return (
        <div className="animate-fadeIn pb-10">
            <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center mb-10 gap-6">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white tracking-tight">الخزينة والحسابات</h1>
                    <p className="text-slate-500 font-bold mt-1">مركز التحكم في السيولة النقدية وتدفق الأموال.</p>
                </div>
                <div className="flex flex-wrap gap-3">
                    <Button onClick={() => setIsExportModalOpen(true)} variant="secondary" className="rounded-2xl h-12 px-6 font-black bg-emerald-50 text-emerald-600 border-emerald-100 hover:bg-emerald-100 shadow-sm border">
                        <ExternalLink size={18} className="me-2" /> تصدير مالي
                    </Button>
                    <Button onClick={() => setIsTransferModalOpen(true)} variant="secondary" className="rounded-2xl h-12 px-6 font-black border-indigo-100 text-indigo-600 bg-white dark:bg-slate-900 shadow-sm">
                        <ArrowRightLeft size={18} className="me-2" /> تحويل بين الخزائن
                    </Button>
                    <Button onClick={() => setIsTreasuryModalOpen(true)} variant="secondary" className="rounded-2xl h-12 px-6 font-black border-slate-200 bg-white dark:bg-slate-900 shadow-sm">
                        <Building size={18} className="me-2" /> إضافة خزينة
                    </Button>
                    <Button onClick={() => setIsModalOpen(true)} className="rounded-2xl h-12 px-8 shadow-xl shadow-indigo-500/20 font-black">
                        <PlusCircle size={18} className="me-2" /> تسجيل حركة
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
                {treasuries.map(t => (
                    <div key={t.id} className="bg-white dark:bg-slate-900 p-8 rounded-4xl border border-slate-100 dark:border-slate-800 shadow-premium relative group overflow-hidden">
                        <div className="absolute -right-4 -bottom-4 opacity-5 group-hover:scale-110 transition-transform text-indigo-500"><Wallet size={120} /></div>
                        {!t.isDefault && (
                            <button onClick={() => setConfirmDeleteId(t.id)} className="absolute top-6 end-6 p-2 text-slate-300 hover:text-rose-500 transition-colors z-10">
                                <Trash2 size={16} />
                            </button>
                        )}
                        <div className="flex items-center gap-4 mb-6 relative z-10">
                            <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-500/20"><Wallet size={24} /></div>
                            <div>
                                <h4 className="font-black text-slate-800 dark:text-white text-lg">{t.name}</h4>
                                {t.isDefault && <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">الافتراضية</span>}
                            </div>
                        </div>
                        <p className="text-3xl font-black text-slate-800 dark:text-white relative z-10">{formatCurrency(t.balance || 0, t.currency || settings.currency)}</p>
                    </div>
                ))}
            </div>

            <Card className="p-0 border-none shadow-premium overflow-hidden">
                <div className="p-8 bg-slate-50 dark:bg-slate-900/50 border-b dark:border-slate-800 space-y-6">
                    <div className="flex justify-between items-center">
                        <h3 className="font-black text-xl flex items-center gap-2">
                            <Filter size={20} className="text-indigo-600"/>
                            سجل الحركات المفصل
                        </h3>
                        <button onClick={fetchData} className="p-2 text-slate-400 hover:text-indigo-600 transition-colors"><RefreshCw size={20}/></button>
                    </div>

                    {/* Advanced Search & Filtering */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
                        <div className="lg:col-span-2 relative">
                            <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={18} />
                            <input 
                                type="text" 
                                placeholder="ابحث في الوصف أو الفئة..." 
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                className="w-full h-12 ps-12 pe-4 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 font-bold text-xs outline-none focus:border-indigo-500 shadow-sm"
                            />
                        </div>
                        <div className="flex items-center gap-2 bg-white dark:bg-slate-800 p-1 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm">
                            <div className="flex items-center gap-1 px-2 border-e dark:border-slate-700">
                                <span className="text-[10px] font-black text-slate-400 uppercase">من</span>
                                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="p-1 text-[10px] border-none bg-transparent font-bold outline-none dark:text-white" />
                            </div>
                            <div className="flex items-center gap-1 px-2">
                                <span className="text-[10px] font-black text-slate-400 uppercase">إلى</span>
                                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="p-1 text-[10px] border-none bg-transparent font-bold outline-none dark:text-white" />
                            </div>
                        </div>
                        <select 
                            value={filterType} 
                            onChange={e => setFilterType(e.target.value)}
                            className="h-12 px-4 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 font-bold text-xs outline-none focus:border-indigo-500 shadow-sm"
                        >
                            <option value="all">كل الأنواع</option>
                            <option value="income">إيداع (وارد)</option>
                            <option value="expense">سحب (منصرف)</option>
                            <option value="transfer">تحويل</option>
                            <option value="export">تصدير</option>
                        </select>
                        <Button onClick={() => { setSearchTerm(''); setStartDate(''); setEndDate(''); setFilterType('all'); }} variant="secondary" className="h-12 rounded-2xl font-black text-xs border-slate-100">إعادة ضبط</Button>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-start">
                        <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b dark:border-slate-800">
                            <tr>
                                <th className="px-8 py-5">التاريخ</th>
                                <th className="px-8 py-5">النوع</th>
                                <th className="px-8 py-5">الفئة</th>
                                <th className="px-8 py-5">البيان</th>
                                <th className="px-8 py-5 text-end">المبلغ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y dark:divide-slate-800">
                            {filteredTransactions.map(t => (
                                <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                                    <td className="px-8 py-5">
                                        <div className="flex items-center gap-2 font-bold text-xs text-slate-600 dark:text-slate-400">
                                            <Calendar size={14} className="opacity-50"/>
                                            {new Date(t.date).toLocaleDateString('ar-EG')}
                                        </div>
                                    </td>
                                    <td className="px-8 py-5">
                                        <span className={`px-3 py-1.5 text-[10px] font-black rounded-xl border ${
                                            t.type === 'income' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                                            t.type === 'expense' ? 'bg-rose-50 text-rose-600 border-rose-100' : 
                                            t.type === 'transfer' ? 'bg-blue-50 text-blue-600 border-blue-100' : 
                                            'bg-amber-50 text-amber-600 border-amber-100'}`}>
                                            {t.type === 'income' ? 'إيداع' : t.type === 'expense' ? 'سحب' : t.type === 'transfer' ? 'تحويل' : 'تصدير'}
                                        </span>
                                    </td>
                                    <td className="px-8 py-5"><span className="px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500 uppercase tracking-wide">{t.category}</span></td>
                                    <td className="px-8 py-5 font-bold text-xs text-slate-700 dark:text-slate-300 max-w-md truncate">
                                        {t.description} 
