                    </div>
                    <div>
                        <label className="block text-xs font-black text-slate-400 uppercase mb-2 ms-1">بيان التحويل</label>
                        <input type="text" value={transferData.desc} onChange={e => setTransferData({...transferData, desc: e.target.value})} className="w-full h-12 p-4 border border-slate-100 dark:border-slate-700 rounded-2xl font-bold outline-none dark:bg-slate-800 dark:text-white" placeholder="مثال: تغذية عهدة الكاشير، تحويل للأمانات..." />
                    </div>
                    <div className="flex justify-end gap-3 pt-4">
                        <Button variant="secondary" type="button" onClick={() => setIsTransferModalOpen(false)} className="rounded-xl px-6">إلغاء</Button>
                        <Button type="submit" isLoading={isSaving} className="rounded-xl px-10 font-black shadow-lg">إتمام التحويل</Button>
                    </div>
                </form>
            </Modal>

            {/* Modal: Export Funds */}
            <Modal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} title="تصدير مالي خارجي">
                <form onSubmit={handleExport} className="space-y-6">
                    <div>
                        <label className="block text-xs font-black text-slate-400 uppercase mb-2 ms-1">من خزينة</label>
                        <select value={exportData.from} onChange={e => setExportData({...exportData, from: e.target.value})} className="w-full h-12 px-4 border border-slate-100 dark:border-slate-700 rounded-2xl font-bold dark:bg-slate-800 dark:text-white">
                            {treasuries.map(t => <option key={t.id} value={t.id}>{t.name} ({formatCurrency(t.balance, settings.currency)})</option>)}
                        </select>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase mb-2 ms-1">الجهة المستلمة</label>
                            <input type="text" required value={exportData.dest} onChange={e => setExportData({...exportData, dest: e.target.value})} className="w-full h-12 p-4 border border-slate-100 dark:border-slate-700 rounded-2xl font-bold outline-none dark:bg-slate-800 dark:text-white" placeholder="اسم البنك، المالك، المورد..." />
                        </div>
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase mb-2 ms-1">المبلغ</label>
                            <input type="number" required value={exportData.amount || ''} onChange={e => setExportData({...exportData, amount: parseFloat(e.target.value)||0})} className="w-full h-12 p-4 border border-slate-100 dark:border-slate-700 rounded-2xl font-black text-indigo-600 outline-none text-center bg-slate-50 dark:bg-slate-800" />
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-black text-slate-400 uppercase mb-2 ms-1">البيان</label>
                        <input type="text" value={exportData.desc} onChange={e => setExportData({...exportData, desc: e.target.value})} className="w-full h-12 p-4 border border-slate-100 dark:border-slate-700 rounded-2xl font-bold outline-none dark:bg-slate-800 dark:text-white" placeholder="إيداع بنكي، سحب للمالك..." />
                    </div>
                    <div className="flex justify-end gap-3 pt-4">
                        <Button variant="secondary" type="button" onClick={() => setIsExportModalOpen(false)} className="rounded-xl px-6">إلغاء</Button>
                        <Button type="submit" isLoading={isSaving} className="rounded-xl px-10 font-black bg-emerald-600 hover:bg-emerald-700 shadow-lg">تأكيد التصدير</Button>
                    </div>
                </form>
            </Modal>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="تسجيل حركة يدوية">
                <TransactionFormModal transaction={null} onSave={async (d) => { await api.saveTransaction(d); await fetchData(); setIsModalOpen(false); }} onCancel={() => setIsModalOpen(false)} isLoading={isSaving} />
            </Modal>

            <ConfirmDialog 
                isOpen={!!confirmDeleteId} 
                onClose={() => setConfirmDeleteId(null)} 
                onConfirm={async () => { await api.deleteTreasury(confirmDeleteId!); await fetchData(); setConfirmDeleteId(null); }} 
                title="حذف الخزينة" 
                message="هل أنت متأكد من حذف هذه الخزينة؟ لا يمكن حذف الخزينة إلا إذا كان رصيدها صفراً وليست الخزينة الافتراضية."
            />
        </div>
    );
};

export default TreasuryPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { api } from '../services/mockApi';
import type { Product, Sale, Customer, Warehouse, Treasury, PaymentDetail } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import CustomerForm from '../components/customers/CustomerForm';
import { Search, ShoppingCart, Trash2, Plus, Minus, User, Warehouse as WhIcon, Wallet, Percent, Truck, UserPlus, Gift, CreditCard, DollarSign, Lock } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency, toArabicIndic, formatAmount } from '../utils/localization';
import { useToasts } from '../hooks/useToasts';
import ReceiptModal from '../components/sales/ReceiptModal';
import SplitPaymentModal from '../components/pos/SplitPaymentModal';
import InstallmentSetupModal from '../components/sales/InstallmentSetupModal';
import { useShift } from '../hooks/useShift';
import ShiftManagerModal from '../components/shifts/ShiftManagerModal';

const PosPage: React.FC = () => {
    const { settings } = useSettings();
    const { addToast } = useToasts();
    const { currentShift } = useShift();
    const [searchParams] = useSearchParams();
    const navigate = useNavigate();

    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [treasuries, setTreasuries] = useState<Treasury[]>([]);

    const [searchTerm, setSearchTerm] = useState('');
    const [cart, setCart] = useState<any[]>([]);

    const [selectedCustomerId, setSelectedCustomerId] = useState('cust-1');
    const [customerQuery, setCustomerQuery] = useState('');
    const [showCustResults, setShowCustResults] = useState(false);
    const [isNewCustModalOpen, setIsNewCustModalOpen] = useState(false);
    const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);

    const [selectedWhId, setSelectedWhId] = useState('');
    const [selectedTrId, setSelectedTrId] = useState('');

    const [globalDiscount, setGlobalDiscount] = useState(0);
    const [globalDiscountType, setGlobalDiscountType] = useState<'amount' | 'percent'>('amount');
    const [shippingCost, setShippingCost] = useState(0);
    const [pointsToRedeem, setPointsToRedeem] = useState(0);

    const [showReceipt, setShowReceipt] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [showSplitModal, setShowSplitModal] = useState(false);
    const [showInstallmentModal, setShowInstallmentModal] = useState(false);
    const [pendingSplitPayments, setPendingSplitPayments] = useState<PaymentDetail[] | null>(null);

    const editSaleId = searchParams.get('edit');

    useEffect(() => {
        const load = async () => {
            const [p, c, w, t, allSales] = await Promise.all([
                api.getProducts(), api.getCustomers(), api.getWarehouses(), api.getTreasuries(), api.getSales()
            ]);
            setProducts(p); setCustomers(c); setWarehouses(w); setTreasuries(t);
            if (w.length) setSelectedWhId(w.find(i => i.isDefault)?.id || w[0].id);
            if (t.length) setSelectedTrId(t.find(i => i.isDefault)?.id || t[0].id);
            if (editSaleId) {
                const saleToEdit = allSales.find((s:any) => s.id === editSaleId);
                if (saleToEdit) { 
                    setCart(saleToEdit.items); 
                    setSelectedCustomerId(saleToEdit.customer.id); 
                    setGlobalDiscount(saleToEdit.discount); 
                    setGlobalDiscountType(saleToEdit.discountType); 
                    setShippingCost(saleToEdit.shipping); 
                    setSelectedWhId(saleToEdit.warehouseId); 
                    setSelectedTrId(saleToEdit.treasuryId); 
                }
            }
        };
        load();
    }, [editSaleId]);

    const selectedCustomer = useMemo(() => customers.find(c => c.id === selectedCustomerId), [customers, selectedCustomerId]);

    const pointsDiscount = useMemo(() => {
        if (!settings?.loyaltySettings.enabled || !selectedCustomer) return 0;
        return Math.min(pointsToRedeem * settings.loyaltySettings.redemptionRate, selectedCustomer.points * settings.loyaltySettings.redemptionRate);
    }, [pointsToRedeem, selectedCustomer, settings]);

    const subtotalRaw = useMemo(() => cart.reduce((s, i) => s + ((i.sellPrice || 0) * i.quantity), 0), [cart]);

    const subtotal = useMemo(() => cart.reduce((s, i) => {
        const price = i.sellPrice || 0;
        const discount = i.discountPercent ? (price * i.discountPercent / 100) : 0;
        return s + ((price - discount) * i.quantity);
    }, 0), [cart]);

    const discountVal = useMemo(() => globalDiscountType === 'percent' ? (subtotal * globalDiscount / 100) : globalDiscount, [subtotal, globalDiscount, globalDiscountType]);
    const finalTotal = Math.max(0, subtotal - discountVal - pointsDiscount + shippingCost);

    const handleCheckout = async (method: 'Cash' | 'Card' | 'Transfer' | 'Split' | 'Credit', payments?: PaymentDetail[], plan?: any) => {
        if (settings?.enableShiftManagement && !currentShift) {
            setIsShiftModalOpen(true);
            return;
        }

        if (!cart.length || !selectedWhId || !selectedTrId) { addToast('يرجى اختيار المنتجات وتحديد المخزن والخزينة', 'warning'); return; }

        const hasCredit = method === 'Credit' || (payments && payments.some(p => p.method === 'Credit'));
        if (hasCredit && !plan) {
            setPendingSplitPayments(payments || null);
            setShowInstallmentModal(true);
            return;
        }

        try {
            const amountPaid = method === 'Split' ? (payments?.filter(p => p.method !== 'Credit').reduce((a, b) => a + b.amount, 0) || 0) : (method === 'Credit' ? 0 : finalTotal);
            const res = await api.saveSale({
                id: editSaleId || undefined,
                customer: { id: selectedCustomerId, name: selectedCustomer?.name },
                cashier: { id: 'u-1', name: 'المدير' },
                items: cart,
                subtotal, total: finalTotal, amountPaid,
                paymentMethod: method, discount: globalDiscount, discountType: globalDiscountType,
                shipping: shippingCost, warehouseId: selectedWhId, treasuryId: selectedTrId,
                payments: payments || (method !== 'Split' ? [{ method: method as any, amount: finalTotal }] : []),
                installmentPlan: plan, pointsRedeemed: pointsToRedeem,
                shiftId: currentShift?.id 
            });
            setLastSale(res); setShowReceipt(true); setCart([]); setGlobalDiscount(0); setShippingCost(0); setPointsToRedeem(0); setPendingSplitPayments(null);
            addToast('تمت العملية بنجاح', 'success');
        } catch (e) { addToast('فشل إتمام العملية', 'error'); }
    };

    const addToCart = (p: Product) => {
        const stockInWh = p.warehouseStocks?.[selectedWhId] || 0;
        if (stockInWh <= 0) { addToast('المنتج غير متوفر في المستودع المحدد', 'error'); return; }
        setCart(prev => {
            const ex = prev.find(i => i.id === p.id);
            if (ex) return prev.map(i => i.id === p.id ? {...i, quantity: i.quantity + 1} : i);
            return [...prev, { id: p.id, name: p.name, quantity: 1, sellPrice: p.sellPrice, originalPrice: p.costPrice, discountPercent: 0 }];
        });
        setSearchTerm('');
    };

    const filteredSearchResults = useMemo(() => {
        if (!searchTerm.trim()) return [];
        return products.filter(p => {
            const matchesQuery = p.name.includes(searchTerm) || p.sku.includes(searchTerm);
            const hasStockInWh = (p.warehouseStocks?.[selectedWhId] || 0) > 0;
            return matchesQuery && hasStockInWh;
        });
    }, [searchTerm, products, selectedWhId]);

    // UI Guard for Shift
    const isShiftLocked = settings?.enableShiftManagement && !currentShift;

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] gap-4 animate-fadeIn overflow-hidden relative">
            {isShiftLocked && (
                <div className="absolute inset-0 z-[100] bg-slate-900/40 backdrop-blur-md flex items-center justify-center rounded-4xl">
                    <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-2xl text-center max-w-sm animate-scaleUp border dark:border-slate-800">
                        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 text-rose-600 rounded-full flex items-center justify-center mx-auto mb-6">
                            <Lock size={40} />
                        </div>
                        <h2 className="text-2xl font-black text-slate-800 dark:text-white mb-2">الوردية مغلقة</h2>
                        <p className="text-slate-500 font-bold mb-8">يجب فتح وردية جديدة قبل البدء في عمليات البيع لضمان دقة التقارير.</p>
                        <Button onClick={() => setIsShiftModalOpen(true)} className="w-full h-12 rounded-xl text-lg font-black bg-indigo-600 shadow-lg shadow-indigo-500/20">فتح وردية العمل</Button>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 flex-shrink-0">
                <div className="lg:col-span-3">
                    <div className="relative">
                        <WhIcon className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <select value={selectedWhId} onChange={e => { setSelectedWhId(e.target.value); setCart([]); }} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 font-black text-xs outline-none shadow-sm">
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                        </select>
                    </div>
                </div>
                <div className="lg:col-span-5 relative">
                    <Search className="absolute top-1/2 -translate-y-1/2 start-4 text-slate-400" size={20} />
                    <input type="text" placeholder="ابحث عن منتج في المخزن المحدد..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full h-12 ps-12 rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 font-black outline-none shadow-sm"/>
                    {searchTerm && (
                         <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border dark:border-slate-700 max-h-60 overflow-y-auto">
                            {filteredSearchResults.map(p => (
                                <button key={p.id} onClick={() => addToCart(p)} className="w-full p-3 border-b dark:border-slate-700 flex justify-between hover:bg-indigo-50 font-black text-xs">
                                    <span>{p.name} <span className="text-emerald-500 ms-2">({toArabicIndic(p.warehouseStocks?.[selectedWhId] || 0)})</span></span>
                                    <span className="text-indigo-600">{formatAmount(p.sellPrice)}</span>
                                </button>
                            ))}
                            {filteredSearchResults.length === 0 && <p className="p-4 text-center text-xs text-slate-400 font-bold">لا توجد نتائج في هذا المخزن</p>}
                        </div>
                    )}
                </div>
                <div className="lg:col-span-4 flex gap-2">
                    <div className="relative flex-1">
                        <User className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={16} />
                        <input type="text" placeholder="بحث عن عميل..." value={showCustResults ? customerQuery : (selectedCustomer?.name || '')} onFocus={() => setShowCustResults(true)} onChange={e => setCustomerQuery(e.target.value)} className="w-full h-12 ps-10 pe-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 font-black text-xs outline-none shadow-sm"/>
                        {showCustResults && (
                            <div className="absolute top-full left-0 right-0 z-[100] mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-xl border overflow-hidden">
                                {customers.filter(c => c.name.includes(customerQuery)).map(c => (
                                    <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setShowCustResults(false); }} className="w-full p-2.5 text-start hover:bg-slate-50 border-b last:border-0 font-bold text-xs">{c.name}</button>
                                ))}
                                <button onClick={() => setIsNewCustModalOpen(true)} className="w-full p-2.5 bg-indigo-50 text-indigo-600 text-[10px] font-black flex items-center justify-center gap-2"><UserPlus size={14}/> إضافة عميل</button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden flex flex-col">
                <div className="bg-slate-50 dark:bg-slate-800/50 px-6 py-2 border-b dark:border-slate-700 grid grid-cols-12 text-[10px] font-black text-slate-400 uppercase">
                    <div className="col-span-5">المنتج</div>
                    <div className="col-span-2 text-center">السعر</div>
                    <div className="col-span-1 text-center">الكمية</div>
                    <div className="col-span-2 text-center">خصم %</div>
                    <div className="col-span-2 text-end">الإجمالي</div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                    {cart.map(item => (
                        <div key={item.id} className="grid grid-cols-12 gap-2 items-center p-2.5 bg-slate-50 dark:bg-slate-800/40 rounded-xl border border-slate-100 dark:border-slate-700/50 hover:border-indigo-300 transition-colors">
                            <div className="col-span-5 flex flex-col">
                                <span className="font-black text-xs truncate">{item.name}</span>
                                <span className="text-[10px] text-slate-400">SKU: {products.find(p=>p.id===item.id)?.sku}</span>
                            </div>
                            <div className="col-span-2">
                                <input type="number" step="0.01" value={item.sellPrice} onChange={e => setCart(prev => prev.map(i => i.id === item.id ? {...i, sellPrice: parseFloat(e.target.value)||0} : i))} className="w-full p-1.5 border border-slate-200 dark:border-slate-700 rounded-lg text-center font-black text-xs text-indigo-600 bg-white dark:bg-slate-800"/>
                            </div>
                            <div className="col-span-1 flex items-center justify-center gap-2">
                                <button onClick={() => setCart(prev => prev.map(i => i.id === item.id ? {...i, quantity: Math.max(1, i.quantity - 1)} : i))} className="p-1 text-slate-400 hover:bg-white dark:hover:bg-slate-700 rounded"><Minus size={10}/></button>
                                <span className="font-black text-xs">{toArabicIndic(item.quantity)}</span>
                                <button onClick={() => setCart(prev => prev.map(i => i.id === item.id ? {...i, quantity: i.quantity + 1} : i))} className="p-1 text-indigo-600 hover:bg-white dark:hover:bg-slate-700 rounded"><Plus size={10}/></button>
                            </div>
                            <div className="col-span-2 flex justify-center">
                                <input type="number" value={item.discountPercent} onChange={e => setCart(prev => prev.map(i => i.id === item.id ? {...i, discountPercent: parseFloat(e.target.value)||0} : i))} className="w-12 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-center text-[10px] font-bold py-1.5"/>
