    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => { db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item); });
        saveDb(db); return true;
    },
    saveUser: async (u: any) => {
        const db = getDb(); if (u.id) db.users = db.users.map((item: any) => item.id === u.id ? { ...item, ...u } : item); else { u.id = `u-${Date.now()}`; db.users.push(u); } saveDb(db); return u;
    },
    saveStockTransfer: async (st: any) => {
        const db = getDb(); st.id = `st-${Date.now()}`; st.date = new Date().toISOString(); if (!db.stockTransfers) db.stockTransfers = []; db.stockTransfers.unshift(st);
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if(!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => { const db = getDb(); if (c.id) db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === c.id ? { ...item, ...c } : item); else { c.id = `sc-${Date.now()}`; db.shippingCompanies.push(c); } saveDb(db); return c; },
    deleteShippingCompany: async (id: string) => { const db = getDb(); db.shippingCompanies = db.shippingCompanies.filter((item: any) => item.id !== id); saveDb(db); },
    savePurchaseReturn: async (r: any) => {
        const db = getDb(); r.id = `pr-${Date.now()}`; if (!db.purchaseReturns) db.purchaseReturns = []; db.purchaseReturns.unshift(r);
        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if(!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (r.totalRecovered > 0) logTransaction(db, 'income', r.totalRecovered, `مرتجع مشتريات #${r.originalPurchaseId}`, r.treasuryId, 'مرتجعات');
        saveDb(db); return r;
    },
    getActivityLogs: async () => getDb().activityLogs || [],
    submitFeedback: async (f: any) => { const db = getDb(); if (!db.feedback) db.feedback = []; db.feedback.push({ ...f, id: `fb-${Date.now()}`, date: new Date().toISOString() }); saveDb(db); },
    updateSale: async (id: string, updates: any) => { const db = getDb(); db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...updates } : s); saveDb(db); },
    updatePurchase: async (id: string, updates: any) => { const db = getDb(); db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...updates } : p); saveDb(db); },
    savePartner: async (p: any) => { const db = getDb(); if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? { ...item, ...p } : item); else { p.id = `part-${Date.now()}`; db.partners.push(p); } saveDb(db); return p; },
    getSyncLogs: async () => [], getQueueCount: async () => 0, processQueue: async () => {}, setOnlineStatus: (o: boolean) => {}, getEmployeePerformanceAnalytics: async () => ({ performanceData: [] }), getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }), getSalesHistoryForForecast: async () => [], getSupplierPerformanceData: async () => [], getInactiveCustomers: async (d: number) => [], getStagnantProducts: async (d: number) => [], updateSystemVersion: async (v: string, p: any) => {}, getJournalEntries: async () => []
};

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import type { Sale } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { Printer, Download, Search, Edit, Eye, RotateCcw } from 'lucide-react';
import { exportToCsv } from '../utils/export';
import ReceiptModal from '../components/sales/ReceiptModal';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency } from '../utils/localization';
import TableSkeleton from '../components/ui/TableSkeleton';
import { useToasts } from '../hooks/useToasts';

const SalesPage: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [loading, setLoading] = useState(true);
  const [isReceiptModalOpen, setIsReceiptModalOpen] = useState(false);
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const { settings } = useSettings();
  const { addToast } = useToasts();
  const navigate = useNavigate();

  const fetchSales = async () => {
    setLoading(true);
    try {
        const data = await api.getSales();
        setSales(data);
    } catch (e) {
        addToast("خطأ في تحميل المبيعات", "error");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchSales();
  }, []);

  const filteredSales = useMemo(() => {
    return sales.filter(sale => {
        const transDate = sale.date.split('T')[0];
        const matchesDate = (!startDate || transDate >= startDate) && (!endDate || transDate <= endDate);

        const lowercasedTerm = searchTerm.toLowerCase();
        const matchesSearch = !searchTerm || 
            sale.id.toLowerCase().includes(lowercasedTerm) ||
            sale.customer.name.toLowerCase().includes(lowercasedTerm);

        return matchesDate && matchesSearch;
    });
  }, [sales, searchTerm, startDate, endDate]);

  const handleExport = () => {
    const dataToExport = filteredSales.map(s => ({
        id: s.id,
        date: s.date,
        customer: s.customer.name,
        total: s.total,
        paymentMethod: s.paymentMethod
    }));
    exportToCsv(`sales-${new Date().toISOString().split('T')[0]}.csv`, dataToExport);
    addToast('تم تصدير سجل المبيعات.', 'success');
  };

  const handleOpenReceipt = (sale: Sale) => {
    setSelectedSale(sale);
    setIsReceiptModalOpen(true);
  };

  const handleEditSale = (saleId: string) => {
    navigate(`/pos?edit=${saleId}`);
  };

  return (
    <div className="animate-fadeIn">
      <div className="flex flex-col xl:flex-row justify-between items-center gap-4 mb-6">
        <h1 className="text-3xl font-black text-slate-800 dark:text-white">سجل المبيعات</h1>

        <div className="flex flex-col sm:flex-row items-center gap-2 w-full xl:w-auto">
             <div className="relative flex-grow sm:flex-grow-0 sm:w-64">
                <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={20} />
                <input 
                  type="text" 
                  placeholder="ابحث برقم الفاتورة أو العميل..." 
                  value={searchTerm} 
                  onChange={e => setSearchTerm(e.target.value)} 
                  className="w-full p-2 ps-10 border rounded-xl dark:bg-slate-700 dark:border-slate-600 font-bold shadow-sm outline-none focus:border-indigo-500 transition-all"
                />
             </div>

             <div className="flex items-center gap-2 bg-white dark:bg-slate-800 p-1 rounded-xl border dark:border-slate-700 shadow-sm">
                <div className="flex items-center gap-1">
                    <span className="text-[10px] font-black text-slate-400 px-1 uppercase">من</span>
                    <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="p-1 text-xs border-none bg-transparent font-bold outline-none" />
                </div>
                <div className="flex items-center gap-1 border-s dark:border-slate-700">
                    <span className="text-[10px] font-black text-slate-400 px-1 uppercase">إلى</span>
                    <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="p-1 text-xs border-none bg-transparent font-bold outline-none" />
                </div>
             </div>

            <Button onClick={handleExport} variant="secondary" className="rounded-xl shadow-sm">
              <Download size={18} />
            </Button>
        </div>
      </div>

      <Card className="p-0 border-none shadow-premium overflow-hidden">
        {loading ? <TableSkeleton cols={6} hasActions /> : !settings ? <p className="p-6 text-center">جاري تحميل...</p> : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-start">
              <thead className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-50 dark:bg-slate-800/50">
                <tr>
                  <th className="px-6 py-4">رقم الفاتورة</th>
                  <th className="px-6 py-4">التاريخ</th>
                  <th className="px-6 py-4">العميل</th>
                  <th className="px-6 py-4">الإجمالي</th>
                  <th className="px-6 py-4">طريقة الدفع</th>
                  <th className="px-6 py-4 text-center">إجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-800">
                {filteredSales.map((sale) => (
                  <tr key={sale.id} className={`hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors ${sale.status === 'Refunded' ? 'bg-rose-50/30 dark:bg-rose-900/5' : ''}`}>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                            <span className="font-black text-indigo-600 font-mono">{sale.id.toUpperCase()}</span>
                            {sale.status === 'Refunded' && (
                                <span className="flex items-center gap-1 px-2 py-0.5 bg-rose-100 text-rose-600 rounded-lg text-[9px] font-black border border-rose-200">
                                    <RotateCcw size={10} /> مرتجع
                                </span>
                            )}
                        </div>
                    </td>
                    <td className="px-6 py-4 font-bold">{new Date(sale.date).toLocaleDateString('ar-EG')}</td>
                    <td className="px-6 py-4 font-medium">{sale.customer.name}</td>
                    <td className="px-6 py-4 font-black text-slate-800 dark:text-white">{formatCurrency(sale.total, settings.currency)}</td>
                    <td className="px-6 py-4">
                        <span className="px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-full text-[10px] font-black">
                            {sale.paymentMethod === 'Cash' ? 'نقدي' : sale.paymentMethod === 'Card' ? 'بطاقة' : sale.paymentMethod === 'Split' ? 'مجزأ' : 'آجل'}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex justify-center items-center gap-2">
                        <button onClick={() => handleOpenReceipt(sale)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-xl transition-all" title="عرض"><Eye size={18} /></button>
                        <button onClick={() => handleEditSale(sale.id)} className="p-2 text-amber-500 hover:bg-amber-50 rounded-xl transition-all" title="تعديل في POS"><Edit size={18} /></button>
                        <button onClick={() => handleOpenReceipt(sale)} className="p-2 text-slate-500 hover:bg-slate-100 rounded-xl transition-all" title="طباعة"><Printer size={18} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {!loading && filteredSales.length === 0 && (
              <div className="text-center py-20 text-slate-400 font-bold">لا توجد فواتير تطابق معايير البحث.</div>
            )}
          </div>
        )}
      </Card>
      <ReceiptModal isOpen={isReceiptModalOpen} onClose={() => setIsReceiptModalOpen(false)} sale={selectedSale} />
    </div>
  );
};

export default SalesPage;

