        const db = getDb();
        let success = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';

                const sale = db.sales.find((s: any) => s.id === plan.saleId);
                if (sale) {
                    const customer = db.customers.find((c: any) => c.id === sale.customer.id);
                    if (customer) customer.debt = Math.max(0, (customer.debt || 0) - payment.amount);
                    logTransaction(db, 'income', payment.amount, `تحصيل قسط #${paymentId} - عميل: ${sale.customer.name}`, sale.treasuryId, 'أقساط');
                }
                logActivity(db, 'تحصيل قسط', `تم تحصيل قسط بمبلغ ${payment.amount} من ${plan.customerName}`);
                success = true;
            }
        });
        if (success) saveDb(db);
        return success;
    },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb(); const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query)),
            suppliers: db.suppliers.filter((s:any) => s.name.toLowerCase().includes(query)),
            partners: db.partners.filter((p:any) => p.name.toLowerCase().includes(query)),
            salesReturns: db.salesReturns.filter((r:any) => r.id.toLowerCase().includes(query)),
            purchaseReturns: [], installments: [], stockTransfers: []
        };
    },
    getUsers: async () => getDb().users,
    login: async (n: string, p: string) => getDb().users.find((u: any) => u.name === n && u.password === p) || null,
    verifyPassword: async (uid: string, p: string) => getDb().users.find((u:any)=>u.id===uid)?.password === p,
    wipeBusinessData: async () => { const db = getDb(); db.products = []; db.sales = []; db.purchases = []; db.customers = db.customers.filter((c: any) => c.id === 'cust-1'); db.suppliers = []; db.transactions = []; db.shifts = []; db.salesReturns = []; db.installments = []; saveDb(db); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    addNotification: async (n: any) => { const db = getDb(); if (!db.notifications) db.notifications = []; const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n }; db.notifications.unshift(newN); saveDb(db); return newN; },
    getNotifications: async () => getDb().notifications || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => { db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item); });
        logActivity(db, 'تحديث جماعي للأسعار', `تم تحديث أسعار ${products.length} منتج`);
        saveDb(db); return true;
    },
    saveUser: async (u: any) => {
        const db = getDb(); if (u.id) db.users = db.users.map((item: any) => item.id === u.id ? { ...item, ...u } : item); else { u.id = `u-${Date.now()}`; db.users.push(u); } logActivity(db, 'إدارة المستخدمين', `حفظ بيانات المستخدم: ${u.name}`); saveDb(db); return u;
    },
    saveStockTransfer: async (st: any) => {
        const db = getDb(); st.id = `st-${Date.now()}`; st.date = new Date().toISOString(); if (!db.stockTransfers) db.stockTransfers = []; db.stockTransfers.unshift(st);
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if(!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        logActivity(db, 'تحويل مخزني', `تحويل ${st.quantity} من المنتج ${p?.name}`);
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => { const db = getDb(); if (c.id) db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === c.id ? { ...item, ...c } : item); else { c.id = `sc-${Date.now()}`; db.shippingCompanies.push(c); } saveDb(db); return c; },
    deleteShippingCompany: async (id: string) => { const db = getDb(); db.shippingCompanies = db.shippingCompanies.filter((item: any) => item.id !== id); saveDb(db); },
    savePurchaseReturn: async (r: any) => {
        const db = getDb(); r.id = `pr-${Date.now()}`; if (!db.purchaseReturns) db.purchaseReturns = []; db.purchaseReturns.unshift(r);
        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if(!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (r.totalRecovered > 0) logTransaction(db, 'income', r.totalRecovered, `مرتجع مشتريات #${r.originalPurchaseId}`, r.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مشتريات', `تسجيل مرتجع مشتريات بمبلغ مسترد ${r.totalRecovered}`);
        saveDb(db); return r;
    },
    getActivityLogs: async () => getDb().activityLogs || [],
    submitFeedback: async (f: any) => { const db = getDb(); if (!db.feedback) db.feedback = []; db.feedback.push({ ...f, id: `fb-${Date.now()}`, date: new Date().toISOString() }); saveDb(db); },
    updateSale: async (id: string, updates: any) => { const db = getDb(); db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...updates } : s); saveDb(db); },
    updatePurchase: async (id: string, updates: any) => { const db = getDb(); db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...updates } : p); saveDb(db); },
    savePartner: async (p: any) => { const db = getDb(); if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? { ...item, ...p } : item); else { p.id = `part-${Date.now()}`; db.partners.push(p); } saveDb(db); return p; },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const sales = db.sales || [];
        const performanceData: EmployeePerformanceData[] = db.users.map((u: any) => {
            const userSales = sales.filter((s: any) => s.cashier?.id === u.id);
            const totalSalesValue = userSales.reduce((sum: number, s: any) => sum + s.total, 0);
            const totalSalesCount = userSales.length;
            const averageSaleValue = totalSalesCount > 0 ? totalSalesValue / totalSalesCount : 0;
            const userReturns = db.salesReturns.filter((r: any) => r.user?.id === u.id);
            const totalReturnsValue = userReturns.reduce((sum: number, r: any) => sum + r.totalRefund, 0);
            const returnRate = totalSalesValue > 0 ? (totalReturnsValue / totalSalesValue) * 100 : 0;

            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue,
                totalSalesCount,
                averageSaleValue,
                totalReturnsValue,
                returnRate
            };
        });

        return {
            performanceData,
            topPerformerByValue: [...performanceData].sort((a, b) => b.totalSalesValue - a.totalSalesValue)[0],
            topPerformerByCount: [...performanceData].sort((a, b) => b.totalSalesCount - a.totalSalesCount)[0],
        };
    },
    getSyncLogs: async () => [], getQueueCount: async () => 0, processQueue: async () => {}, setOnlineStatus: (o: boolean) => {}, getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }), getSalesHistoryForForecast: async () => [], getSupplierPerformanceData: async () => [], getInactiveCustomers: async (d: number) => [], getStagnantProducts: async (d: number) => [], updateSystemVersion: async (v: string, p: any) => {}, getJournalEntries: async () => []
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import type { SalesReturn } from '../types';
import { api } from '../services/mockApi';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { PlusCircle, Search, RotateCcw } from 'lucide-react';
import { useSettings } from '../hooks/useSettings';
import { formatCurrency } from '../utils/localization';
import SalesReturnModal from '../components/returns/SalesReturnModal';
import TableSkeleton from '../components/ui/TableSkeleton';
import { useToasts } from '../hooks/useToasts';
import ConfirmDialog from '../components/ui/ConfirmDialog';

const SalesReturnsPage: React.FC = () => {
    const [returns, setReturns] = useState<SalesReturn[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [reversingId, setReversingId] = useState<string | null>(null);
    const { settings } = useSettings();
    const { addToast } = useToasts();

    const fetchReturns = useCallback(async () => {
        setLoading(true);
        try {
            const data = await api.getSalesReturns();
            setReturns(data || []);
        } catch (e) {
            setReturns([]);
            addToast("خطأ في تحميل المرتجعات", "error");
        } finally {
            setLoading(false);
        }
    }, [addToast]);

    useEffect(() => { fetchReturns(); }, [fetchReturns]);

    const handleReverse = async () => {
        if (!reversingId) return;
        try {
            const success = await api.deleteSalesReturn(reversingId);
            if (success) {
                addToast("تم التراجع عن المرتجع بنجاح واستعادة البيانات.", "success");
                fetchReturns();
            }
        } catch (e) { addToast("فشل التراجع عن المرتجع", "error"); }
        finally { setReversingId(null); }
    };

    const filteredReturns = useMemo(() => {
        const list = Array.isArray(returns) ? returns : [];
        if (!searchTerm) return list;
        const q = searchTerm.toLowerCase();
        return list.filter(r => 
            (r.id || "").toLowerCase().includes(q) || 
            (r.originalSaleId || "").toLowerCase().includes(q)
        );
    }, [returns, searchTerm]);

    return (
        <div className="animate-fadeIn">
            <div className="flex flex-col xl:flex-row justify-between items-center gap-4 mb-6">
                <h1 className="text-3xl font-black text-slate-800 dark:text-white">مرتجعات المبيعات</h1>
                <div className="flex flex-col sm:flex-row items-center gap-2 w-full xl:w-auto">
                    <div className="relative flex-grow sm:flex-grow-0 sm:w-64">
                        <Search className="absolute top-1/2 -translate-y-1/2 start-3 text-slate-400" size={20} />
                        <input 
                            type="text" 
                            placeholder="بحث برقم المرتجع أو الفاتورة..." 
                            value={searchTerm} 
                            onChange={e => setSearchTerm(e.target.value)} 
                            className="w-full p-2 ps-10 border rounded-xl dark:bg-slate-700 dark:border-slate-600 font-bold shadow-sm outline-none focus:border-indigo-500 transition-all"
                        />
                    </div>
                    <Button onClick={() => setIsModalOpen(true)} className="rounded-xl font-black shadow-lg shadow-indigo-500/20"><PlusCircle size={20} className="me-2" /> إضافة مرتجع</Button>
                </div>
            </div>
            <Card className="p-0 border-none shadow-premium overflow-hidden">
                {loading ? <TableSkeleton cols={5} hasActions /> : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-start">
                            <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black uppercase text-slate-400">
                                <tr>
                                    <th className="px-6 py-4 text-start">رقم المرتجع</th>
                                    <th className="px-6 py-4 text-start">التاريخ</th>
                                    <th className="px-6 py-4 text-start">الفاتورة الأصلية</th>
                                    <th className="px-6 py-4 text-start">المسترد</th>
                                    <th className="px-6 py-4 text-center">إجراءات</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y dark:divide-slate-800">
                                {filteredReturns.map((r) => (
                                    <tr key={r.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-colors">
                                        <td className="px-6 py-4 font-black text-indigo-600">{r.id.toUpperCase()}</td>
                                        <td className="px-6 py-4 font-bold">{new Date(r.date).toLocaleDateString('ar-EG')}</td>
                                        <td className="px-6 py-4 font-mono">{r.originalSaleId.toUpperCase()}</td>
                                        <td className="px-6 py-4 font-black text-red-500">{formatCurrency(r.totalRefund, settings?.currency || 'SAR')}</td>
                                        <td className="px-6 py-4 text-center">
                                            <button onClick={() => setReversingId(r.id)} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-all" title="تراجع (Undo)">
                                                <RotateCcw size={18}/>
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                        {filteredReturns.length === 0 && <div className="p-20 text-center text-slate-400 font-bold">لا توجد مرتجعات تطابق البحث.</div>}
                    </div>
                )}
            </Card>
            <SalesReturnModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={async (d) => { setIsSaving(true); await api.saveSalesReturn(d); await fetchReturns(); setIsModalOpen(false); setIsSaving(false); }} isLoading={isSaving} />
            <ConfirmDialog 
                isOpen={!!reversingId} 
                onClose={() => setReversingId(null)} 
                onConfirm={handleReverse} 
                title="تأكيد التراجع عن المرتجع" 
                message="سيتم حذف سجل المرتجع واسترداد الكميات للمخزن وسحب المبلغ من الخزينة. هل أنت متأكد؟"
                confirmText="نعم، تراجع عن المرتجع"
            />
        </div>
    );
};

