} from '../types';
import { PERMISSION_KEYS } from '../permissions';

const DB_KEY = 'techno_power_ultra_db_v5';

const getDb = () => {
    const defaultDb = {
        settings: { storeName: 'تكنو باور POS', vatRate: 15, currency: 'SAR', nextInvoiceNumber: 1000, invoiceNumberPrefix: 'INV-', navigationStyle: 'grid', homeGridItems: ['dashboard', 'pos', 'products', 'sales', 'purchases', 'customers', 'treasury', 'reports', 'partners'], dashboardVisibleCards: ['revenue', 'transactions', 'receivables', 'stock'], visiblePages: PERMISSION_KEYS, loyaltySettings: { enabled: true, earningRate: 0.1, redemptionRate: 0.5, allowCreditPoints: false }, invoiceDesign: { template: 'modern', showLogo: true, accentColor: '#4f46e5' }, enableShiftManagement: true },
        products: [],
        customers: [{ id: 'cust-1', name: 'عميل نقدي', phone: '000', debt: 0, points: 0, tier: 'Regular', creditLimit: 0 }],
        sales: [],
        purchases: [],
        suppliers: [],
        partners: [],
        shippingCompanies: [],
        treasuries: [{ id: 't-1', name: 'الخزينة الرئيسية', balance: 0, currency: 'SAR', isDefault: true }],
        warehouses: [{ id: 'w-1', name: 'المستودع الرئيسي', location: 'المقر', isDefault: true }],
        activityLogs: [],
        installments: [],
        salesReturns: [],
        purchaseReturns: [],
        users: [{ id: 'u-1', name: 'المدير العام', email: 'admin@techno.com', password: 'password', roleId: 'r-1', permissions: PERMISSION_KEYS.reduce((a, k) => ({...a, [k]: true}), {}) }],
        transactions: [],
        shifts: [],
        notifications: [],
        stockTransfers: [],
        journalEntries: [],
        feedback: []
    };
    try {
        const stored = localStorage.getItem(DB_KEY);
        const parsed = stored ? JSON.parse(stored) : defaultDb;
        if (!parsed.treasuries || parsed.treasuries.length === 0) parsed.treasuries = defaultDb.treasuries;
        if (!parsed.transactions) parsed.transactions = [];
        if (!parsed.sales) parsed.sales = [];
        if (!parsed.products) parsed.products = [];
        if (!parsed.activityLogs) parsed.activityLogs = [];
        if (!parsed.installments) parsed.installments = [];
        return parsed;
    } catch (e) { return defaultDb; }
};

const saveDb = (db: any) => {
    localStorage.setItem(DB_KEY, JSON.stringify(db));
    window.dispatchEvent(new Event('storage_updated'));
};

const logActivity = (db: any, action: string, details: string) => {
    const log: ActivityLog = {
        id: `act-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        timestamp: new Date().toISOString(),
        action,
        details,
        user: 'المدير العام'
    };
    if (!db.activityLogs) db.activityLogs = [];
    db.activityLogs.unshift(log);
};

const logTransaction = (db: any, type: 'income' | 'expense' | 'transfer' | 'export', amount: number, description: string, treasuryId: string, category: string, extra?: any) => {
    if (amount <= 0) return;
    const t = db.treasuries.find((item: any) => item.id === treasuryId);
    if (!t) return;

    if (type === 'income') {
        t.balance += amount;
    } else {
        t.balance -= amount;
    }

    const transaction = {
        id: `tr-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        date: new Date().toISOString(),
        type,
        amount,
        description,
        category,
        user: 'المدير العام',
        treasuryId,
        ...extra
    };

    db.transactions.unshift(transaction);
};

export const api = {
    getSettings: async () => getDb().settings,
    saveSettings: async (s: StoreSettings) => {
        const db = getDb(); db.settings = s; saveDb(db); return s;
    },
    getProducts: async () => getDb().products,
    saveProduct: async (p: any) => {
        const db = getDb();
        if (p.id) {
            db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item);
            logActivity(db, 'تعديل منتج', `تم تعديل بيانات المنتج: ${p.name}`);
        } else { 
            p.id = `prod-${Date.now()}`; 
            if (!p.warehouseStocks) p.warehouseStocks = { 'w-1': p.stock || 0 };
            db.products.push(p); 
            logActivity(db, 'إضافة منتج', `تم إضافة منتج جديد: ${p.name}`);
        }
        saveDb(db); return p;
    },
    saveSale: async (sale: any) => {
        const db = getDb();
        const customer = db.customers.find((c: any) => c.id === sale.customer.id);

        sale.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                if(!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[sale.warehouseId] = (p.warehouseStocks[sale.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });

        const id = sale.id || `${db.settings.invoiceNumberPrefix}${db.settings.nextInvoiceNumber++}`;
        const finalSale = { ...sale, id, date: new Date().toISOString(), status: 'Completed' };
        db.sales.unshift(finalSale);

        if (sale.amountPaid > 0) {
            logTransaction(db, 'income', sale.amountPaid, `فاتورة مبيعات #${id}`, sale.treasuryId, 'مبيعات', { shiftId: sale.shiftId });
        }

        if (customer) {
            const unpaid = sale.total - sale.amountPaid;
            if (unpaid > 0) customer.debt = (customer.debt || 0) + unpaid;

            // إصلاح: حساب نقاط الولاء
            if (db.settings.loyaltySettings?.enabled) {
                const earned = Math.floor(sale.total * (db.settings.loyaltySettings.earningRate || 0));
                customer.points = (customer.points || 0) + earned;
                finalSale.pointsEarned = earned;
            }

            if (sale.pointsRedeemed > 0) customer.points = Math.max(0, (customer.points || 0) - sale.pointsRedeemed);
            customer.lastPurchaseDate = new Date().toISOString();
        }

        if (sale.installmentPlan) {
            const planData = sale.installmentPlan;
            const principal = sale.total - (sale.amountPaid || 0);
            const interestAmount = principal * (planData.interestRate / 100) * (planData.months / 12);
            const totalWithInterest = principal + interestAmount;

            const plan: InstallmentPlan = {
                id: `ins-${Date.now()}`,
                customerName: sale.customer.name,
                saleId: id,
                downPayment: sale.amountPaid || 0,
                interestRate: planData.interestRate,
                interestAmount,
                totalWithInterest,
                remainingAmount: totalWithInterest,
                numberOfInstallments: planData.months,
                monthlyPayment: totalWithInterest / planData.months,
                status: 'Active',
                payments: Array.from({ length: planData.months }).map((_, i) => {
                    const dueDate = new Date(planData.startDate);
                    dueDate.setMonth(dueDate.getMonth() + i);
                    return {
                        id: `pay-${id}-${i}`,
                        amount: totalWithInterest / planData.months,
                        dueDate: dueDate.toISOString(),
                        status: 'Pending'
                    };
                })
            };
            if (!db.installments) db.installments = [];
            db.installments.unshift(plan);
        }

        logActivity(db, 'عملية بيع', `تم إصدار فاتورة مبيعات #${id} بقيمة ${sale.total}`);
        saveDb(db); return finalSale;
    },
    transferFunds: async (fromId: string, toId: string, amount: number, desc: string) => { 
        const db = getDb(); 
        const fromT = db.treasuries.find((t:any)=>t.id===fromId);
        const toT = db.treasuries.find((t:any)=>t.id===toId);
        if(fromT && toT && fromT.balance >= amount) {
            logTransaction(db, 'transfer', amount, `تحويل صادر إلى ${toT.name}: ${desc}`, fromId, 'تحويلات');
            logTransaction(db, 'income', amount, `تحويل وارد من ${fromT.name}: ${desc}`, toId, 'تحويلات', { fromTreasuryId: fromId });
            logActivity(db, 'تحويل مالي', `تم تحويل ${amount} من ${fromT.name} إلى ${toT.name}`);
            saveDb(db); return true;
        }
        return false;
    },
    exportTreasury: async (trId: string, amount: number, dest: string, desc: string) => { 
        const db = getDb(); 
        const t = db.treasuries.find((item:any)=>item.id===trId);
        if(t && t.balance >= amount) {
            logTransaction(db, 'export', amount, `تصدير مالي إلى ${dest}: ${desc}`, trId, 'تصدير مالي', { destinationAccount: dest });
            logActivity(db, 'تصدير مالي', `تم تصدير مبلغ ${amount} من ${t.name} إلى ${dest}`);
            saveDb(db); return true;
        }
        return false;
    },
    getTreasuries: async () => getDb().treasuries,
    getTransactions: async () => getDb().transactions,
    getFinancialReport: async (start: string, end: string): Promise<FinancialReport> => {
        const db = getDb();
        const sales = db.sales.filter((s:any) => (!start || s.date >= start) && (!end || s.date <= end));
        const transactions = db.transactions.filter((t:any) => (!start || t.date >= start) && (!end || t.date <= end));
        const returns = db.salesReturns.filter((r:any) => (!start || r.date >= start) && (!end || r.date <= end));

        const totalRevenue = sales.reduce((a:number, b:any) => a + b.total, 0);
        const totalReturns = returns.reduce((a:number, b:any) => a + b.totalRefund, 0);

        const totalExpenses = transactions
            .filter((t:any) => t.type === 'expense' && t.category !== 'مرتجعات')
            .reduce((a:number, b:any) => a + b.amount, 0);

        let totalCOGS = 0;
        sales.forEach((s:any) => {
            if (s.status !== 'Refunded') {
                s.items.forEach((i:any) => totalCOGS += (i.originalPrice || 0) * i.quantity);
            }
        });

        const netProfit = (totalRevenue - totalReturns) - totalCOGS - totalExpenses;

        return {
            totalRevenue: totalRevenue - totalReturns,
            totalCOGS,
            totalExpenses,
            totalPurchases: 0,
            totalReturns,
            totalTax: (totalRevenue - totalReturns) * (db.settings.vatRate / 100),
            netProfit,
            productProfits: [],
            dailyStats: []
        };
    },
    getDashboardAnalytics: async (): Promise<DashboardAnalytics> => {
        const db = getDb();
        const today = new Date().toISOString().split('T')[0];
        const todaysSales = db.sales.filter((s: any) => s.date.startsWith(today));
        return {
            totalSalesToday: todaysSales.reduce((a: number, b: any) => a + b.total, 0),
            todaysTransactions: todaysSales.length,
            totalReceivables: db.customers.reduce((a: number, b: any) => a + (b.debt || 0), 0),
            // FIX: Changed parameter name from 'b' to 'p' to fix 'Cannot find name p' error
            totalStockValue: db.products.reduce((a: number, p: any) => a + ((p.stock || 0) * (p.costPrice || 0)), 0),
            monthlySales: [],
            salesByCategory: [],
            topProducts: db.products.slice(0, 5).map((p: any) => ({ id: p.id, name: p.name, totalRevenue: 0 }))
        };
    },
    getCustomers: async () => getDb().customers,
    getSuppliers: async () => getDb().suppliers,
    getSales: async () => getDb().sales,
    getPurchases: async () => getDb().purchases,
    getWarehouses: async () => getDb().warehouses,
    saveTreasury: async (t: any) => {
        const db = getDb();
        if (t.id) db.treasuries = db.treasuries.map((item: any) => item.id === t.id ? { ...item, ...t } : item);
        else { t.id = `t-${Date.now()}`; db.treasuries.push(t); }
        logActivity(db, 'إدارة الخزائن', `تم تحديث/إضافة الخزينة: ${t.name}`);
        saveDb(db); return t;
    },
    deleteTreasury: async (id: string) => {
        const db = getDb();
        const t = db.treasuries.find((item: any) => item.id === id);
        if (t && t.isDefault) throw new Error("لا يمكن حذف الخزينة الافتراضية");
        if (t && t.balance !== 0) throw new Error("لا يمكن حذف خزينة بها رصيد مالي");
        db.treasuries = db.treasuries.filter((item: any) => item.id !== id);
        logActivity(db, 'حذف خزينة', `تم حذف الخزينة: ${t.name}`);
        saveDb(db);
    },
    saveCustomer: async (c: any) => { const db = getDb(); if (c.id) db.customers = db.customers.map((i: any) => i.id === c.id ? { ...i, ...c } : i); else { c.id = `cust-${Date.now()}`; c.debt = 0; c.points = 0; db.customers.push(c); } logActivity(db, 'إدارة العملاء', `حفظ بيانات العميل: ${c.name}`); saveDb(db); return c; },
    saveSupplier: async (s: any) => { const db = getDb(); if (s.id) db.suppliers = db.suppliers.map((i: any) => i.id === s.id ? { ...i, ...s } : i); else { s.id = `sup-${Date.now()}`; db.suppliers.push(s); } logActivity(db, 'إدارة الموردين', `حفظ بيانات المورد: ${s.name}`); saveDb(db); return s; },
    saveWarehouse: async (w: any) => { const db = getDb(); if (w.id) db.warehouses = db.warehouses.map((i: any) => i.id === w.id ? { ...i, ...w } : i); else { w.id = `wh-${Date.now()}`; db.warehouses.push(w); } logActivity(db, 'إدارة المستودعات', `حفظ مستودع: ${w.name}`); saveDb(db); return w; },
    saveTransaction: async (t: any) => { const db = getDb(); logTransaction(db, t.type, t.amount, t.description, t.treasuryId, t.category); logActivity(db, 'حركة خزينة يدوية', `تم تسجيل ${t.type === 'income' ? 'إيداع' : 'سحب'} بمبلغ ${t.amount}`); saveDb(db); return t; },
    deleteProduct: async (id: string) => { const db = getDb(); const p = db.products.find((i:any)=>i.id===id); db.products = db.products.filter((p:any) => p.id !== id); logActivity(db, 'حذف منتج', `تم حذف المنتج: ${p?.name}`); saveDb(db); },
    deleteWarehouse: async (id: string) => { const db = getDb(); db.warehouses = db.warehouses.filter((w:any) => w.id !== id); saveDb(db); },
    getCurrentShift: async (userId: string) => getDb().shifts.find((s: any) => s.userId === userId && s.status === 'Open') || null,
    openShift: async (userId: string, amount: number) => {
        const db = getDb();
        const shift = { id: `shift-${Date.now()}`, userId, startTime: new Date().toISOString(), startCash: amount, status: 'Open' };
        if (!db.shifts) db.shifts = [];
        db.shifts.push(shift);
        logActivity(db, 'فتح وردية', `تم فتح وردية جديدة برصيد افتتاح ${amount}`);
        saveDb(db); return shift;
    },
    closeShift: async (id: string, endCash: number, notes?: string) => {
        const db = getDb(); const shift = db.shifts.find((s: any) => s.id === id);
        if (shift) {
            shift.status = 'Closed'; shift.endTime = new Date().toISOString(); shift.endCash = endCash; shift.notes = notes;
            logActivity(db, 'إغلاق وردية', `تم إغلاق الوردية #${id} برصيد نهائي ${endCash}`);
            saveDb(db); return shift;
        }
        throw new Error("Shift not found");
    },
    getPartners: async () => getDb().partners || [],
    getSalesReturns: async () => getDb().salesReturns || [],
    saveSalesReturn: async (r: any) => {
        const db = getDb(); 
        r.id = `sr-${Date.now()}`; 
        r.date = new Date().toISOString(); 
        if (!db.salesReturns) db.salesReturns = []; 
        db.salesReturns.unshift(r);

        const originalSale = db.sales.find((s:any) => s.id === r.originalSaleId);
        if (originalSale) originalSale.status = 'Refunded';

        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.id);
            if (p) {
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) + item.returnQuantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (r.totalRefund > 0) logTransaction(db, 'expense', r.totalRefund, `مرتجع مبيعات #${r.originalSaleId}`, r.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مبيعات', `تم تسجيل مرتجع للفاتورة #${r.originalSaleId} بمبلغ مسترد ${r.totalRefund}`);
        saveDb(db); return r;
    },
    deleteSalesReturn: async (id: string) => {
        const db = getDb(); const ret = db.salesReturns.find((r: any) => r.id === id);
        if (ret) {
            logTransaction(db, 'income', ret.totalRefund, `التراجع عن مرتجع #${id}`, ret.treasuryId, 'مرتجعات');
            ret.items.forEach((item: any) => {
                const p = db.products.find((prod: any) => prod.id === item.id);
                if (p) p.warehouseStocks[ret.warehouseId] -= item.returnQuantity;
            });
            db.salesReturns = db.salesReturns.filter((r: any) => r.id !== id);
            logActivity(db, 'تراجع عن مرتجع', `تم التراجع عن المرتجع #${id}`);
            saveDb(db); return true;
        }
        return false;
    },
    savePurchase: async (p: any) => {
        const db = getDb(); p.id = p.id || `pur-${Date.now()}`; p.date = new Date().toISOString(); db.purchases.unshift(p);
        p.items.forEach((item: any) => {
            const prod = db.products.find((pr: any) => pr.id === item.productId);
            if (prod) {
                prod.warehouseStocks[p.warehouseId] = (prod.warehouseStocks[p.warehouseId] || 0) + item.quantity;
                prod.stock = Object.values(prod.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (p.amountPaid > 0) logTransaction(db, 'expense', p.amountPaid, `شراء بضاعة #${p.id}`, p.treasuryId, 'مشتريات');
        logActivity(db, 'عملية شراء', `تم تسجيل طلب شراء #${p.id} بمبلغ ${p.total}`);
        saveDb(db); return p;
    },
    getPurchaseReturns: async () => getDb().purchaseReturns || [],
    getInstallmentPlans: async () => getDb().installments || [],
    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let success = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';

                const sale = db.sales.find((s: any) => s.id === plan.saleId);
                if (sale) {
                    const customer = db.customers.find((c: any) => c.id === sale.customer.id);
                    if (customer) customer.debt = Math.max(0, (customer.debt || 0) - payment.amount);
                    logTransaction(db, 'income', payment.amount, `تحصيل قسط #${paymentId} - عميل: ${sale.customer.name}`, sale.treasuryId, 'أقساط');
                }
                logActivity(db, 'تحصيل قسط', `تم تحصيل قسط بمبلغ ${payment.amount} من ${plan.customerName}`);
                success = true;
            }
        });
        if (success) saveDb(db);
        return success;
    },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb(); const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query)),
            suppliers: db.suppliers.filter((s:any) => s.name.toLowerCase().includes(query)),
            partners: db.partners.filter((p:any) => p.name.toLowerCase().includes(query)),
            salesReturns: db.salesReturns.filter((r:any) => r.id.toLowerCase().includes(query)),
            purchaseReturns: [], installments: [], stockTransfers: []
        };
    },
    getUsers: async () => getDb().users,
    login: async (n: string, p: string) => getDb().users.find((u: any) => u.name === n && u.password === p) || null,
    verifyPassword: async (uid: string, p: string) => getDb().users.find((u:any)=>u.id===uid)?.password === p,
    wipeBusinessData: async () => { const db = getDb(); db.products = []; db.sales = []; db.purchases = []; db.customers = db.customers.filter((c: any) => c.id === 'cust-1'); db.suppliers = []; db.transactions = []; db.shifts = []; db.salesReturns = []; db.installments = []; saveDb(db); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    addNotification: async (n: any) => { const db = getDb(); if (!db.notifications) db.notifications = []; const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n }; db.notifications.unshift(newN); saveDb(db); return newN; },
    getNotifications: async () => getDb().notifications || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => { db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item); });
        logActivity(db, 'تحديث جماعي للأسعار', `تم تحديث أسعار ${products.length} منتج`);
        saveDb(db); return true;
    },
    saveUser: async (u: any) => {
        const db = getDb(); if (u.id) db.users = db.users.map((item: any) => item.id === u.id ? { ...item, ...u } : item); else { u.id = `u-${Date.now()}`; db.users.push(u); } logActivity(db, 'إدارة المستخدمين', `حفظ بيانات المستخدم: ${u.name}`); saveDb(db); return u;
    },
    saveStockTransfer: async (st: any) => {
        const db = getDb(); st.id = `st-${Date.now()}`; st.date = new Date().toISOString(); if (!db.stockTransfers) db.stockTransfers = []; db.stockTransfers.unshift(st);
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if(!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        logActivity(db, 'تحويل مخزني', `تحويل ${st.quantity} من المنتج ${p?.name}`);
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => { const db = getDb(); if (c.id) db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === c.id ? { ...item, ...c } : item); else { c.id = `sc-${Date.now()}`; db.shippingCompanies.push(c); } saveDb(db); return c; },
    deleteShippingCompany: async (id: string) => { const db = getDb(); db.shippingCompanies = db.shippingCompanies.filter((item: any) => item.id !== id); saveDb(db); },
    savePurchaseReturn: async (r: any) => {
        const db = getDb(); r.id = `pr-${Date.now()}`; if (!db.purchaseReturns) db.purchaseReturns = []; db.purchaseReturns.unshift(r);
        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if(!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (r.totalRecovered > 0) logTransaction(db, 'income', r.totalRecovered, `مرتجع مشتريات #${r.originalPurchaseId}`, r.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مشتريات', `تسجيل مرتجع مشتريات بمبلغ مسترد ${r.totalRecovered}`);
        saveDb(db); return r;
    },
    getActivityLogs: async () => getDb().activityLogs || [],
    submitFeedback: async (f: any) => { const db = getDb(); if (!db.feedback) db.feedback = []; db.feedback.push({ ...f, id: `fb-${Date.now()}`, date: new Date().toISOString() }); saveDb(db); },
    updateSale: async (id: string, updates: any) => { const db = getDb(); db.sales = db.sales.map((s: any) => s.id === id ? { ...s, ...updates } : s); saveDb(db); },
    updatePurchase: async (id: string, updates: any) => { const db = getDb(); db.purchases = db.purchases.map((p: any) => p.id === id ? { ...p, ...updates } : p); saveDb(db); },
    savePartner: async (p: any) => { const db = getDb(); if (p.id) db.partners = db.partners.map((item: any) => item.id === p.id ? { ...item, ...p } : item); else { p.id = `part-${Date.now()}`; db.partners.push(p); } saveDb(db); return p; },
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const sales = db.sales || [];
        const performanceData: EmployeePerformanceData[] = db.users.map((u: any) => {
            const userSales = sales.filter((s: any) => s.cashier?.id === u.id);
            const totalSalesValue = userSales.reduce((sum: number, s: any) => sum + s.total, 0);
            const totalSalesCount = userSales.length;
            const averageSaleValue = totalSalesCount > 0 ? totalSalesValue / totalSalesCount : 0;
            // FIX: Changed 'user?.id' to 'r.user?.id' to fix 'Cannot find name user' error
            const userReturns = db.salesReturns.filter((r: any) => r.user?.id === u.id);
            const totalReturnsValue = userReturns.reduce((sum: number, r: any) => sum + r.totalRefund, 0);
            const returnRate = totalSalesValue > 0 ? (totalReturnsValue / totalSalesValue) * 100 : 0;

            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue,
                totalSalesCount,
                averageSaleValue,
                totalReturnsValue,
                returnRate
            };
        });

        return {
            performanceData,
            topPerformerByValue: [...performanceData].sort((a, b) => b.totalSalesValue - a.totalSalesValue)[0],
            topPerformerByCount: [...performanceData].sort((a, b) => b.totalSalesCount - a.totalSalesCount)[0],
        };
    },
    getSyncLogs: async () => [], getQueueCount: async () => 0, processQueue: async () => {}, setOnlineStatus: (o: boolean) => {}, getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }), getSalesHistoryForForecast: async () => [], getSupplierPerformanceData: async () => [], getInactiveCustomers: async (d: number) => [], getStagnantProducts: async (d: number) => [], updateSystemVersion: async (v: string, p: any) => {}, getJournalEntries: async () => []
};

