                        <span className="text-4xl">⚡</span>
                    </div>
                    <h2 className="text-2xl font-bold">مرحباً بعودتك، {user?.name}</h2>
                    <p className="text-slate-600 dark:text-slate-300 mt-1">تم قفل الجلسة بسبب عدم النشاط.</p>
                </div>
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 text-start">
