    recordInstallmentPayment: async (paymentId: string) => {
        const db = getDb();
        let success = false;
        db.installments.forEach((plan: any) => {
            const payment = plan.payments.find((p: any) => p.id === paymentId);
            if (payment && payment.status === 'Pending') {
                payment.status = 'Paid';
                payment.paidDate = new Date().toISOString();
                plan.remainingAmount -= payment.amount;
                if (plan.remainingAmount <= 0) plan.status = 'Paid Off';

                const sale = db.sales.find((s: any) => s.id === plan.saleId);
                if (sale) {
                    const customer = db.customers.find((c: any) => c.id === sale.customer.id);
                    if (customer) customer.debt = Math.max(0, (customer.debt || 0) - payment.amount);
                    logTransaction(db, 'income', payment.amount, `تحصيل قسط #${paymentId} - عميل: ${sale.customer.name}`, sale.treasuryId, 'أقساط');
                }
                logActivity(db, 'تحصيل قسط', `تم تحصيل قسط بمبلغ ${payment.amount} من ${plan.customerName}`);
                success = true;
            }
        });
        if (success) saveDb(db);
        return success;
    },
    globalSearch: async (q: string): Promise<GlobalSearchResults> => {
        const db = getDb(); const query = q.toLowerCase();
        return {
            products: db.products.filter((p:any) => p.name.toLowerCase().includes(query) || p.sku.includes(query)),
            sales: db.sales.filter((s:any) => s.id.toLowerCase().includes(query) || s.customer.name.toLowerCase().includes(query)),
            customers: db.customers.filter((c:any) => c.name.toLowerCase().includes(query) || c.phone.includes(query)),
            purchases: db.purchases.filter((p:any) => p.id.toLowerCase().includes(query)),
            suppliers: db.suppliers.filter((s:any) => s.name.toLowerCase().includes(query)),
            partners: db.partners.filter((p:any) => p.name.toLowerCase().includes(query)),
            salesReturns: db.salesReturns.filter((r:any) => r.id.toLowerCase().includes(query)),
            purchaseReturns: [], installments: [], stockTransfers: []
        };
    },
    getUsers: async () => getDb().users,
    getRoles: async () => getDb().roles,
    saveRole: async (role: any) => {
        const db = getDb();
        if (role.id) {
            db.roles = db.roles.map((r: any) => r.id === role.id ? role : r);
            // مزامنة تلقائية: تحديث جميع المستخدمين الذين يمتلكون هذا الدور لتعكس صلاحياتهم الجديدة فوراً
            db.users = db.users.map((u: any) => u.roleId === role.id ? { ...u, permissions: { ...role.permissions } } : u);
        } else {
            role.id = `r-${Date.now()}`;
            db.roles.push(role);
        }
        saveDb(db);
        return role;
    },
    login: async (n: string, p: string) => getDb().users.find((u: any) => u.name === n && u.password === p) || null,
    verifyPassword: async (uid: string, p: string) => getDb().users.find((u:any)=>u.id===uid)?.password === p,
    wipeBusinessData: async () => { const db = getDb(); db.products = []; db.sales = []; db.purchases = []; db.customers = db.customers.filter((c: any) => c.id === 'cust-1'); db.suppliers = []; db.transactions = []; db.shifts = []; db.salesReturns = []; db.installments = []; saveDb(db); },
    reset: () => { localStorage.removeItem(DB_KEY); window.location.reload(); },
    addNotification: async (n: any) => { const db = getDb(); if (!db.notifications) db.notifications = []; const newN = { id: `notif-${Date.now()}`, date: new Date().toISOString(), ...n }; db.notifications.unshift(newN); saveDb(db); return newN; },
    getNotifications: async () => getDb().notifications || [],
    getStockTransfers: async () => getDb().stockTransfers || [],
    getCustomerPurchaseHistory: async (id: string) => getDb().sales.filter((s: any) => s.customer.id === id),
    getCustomerReturnsHistory: async (id: string) => getDb().salesReturns.filter((r: any) => r.customer?.id === id),
    bulkUpdateProducts: async (products: Product[]) => {
        const db = getDb();
        products.forEach(p => { db.products = db.products.map((item: any) => item.id === p.id ? { ...item, ...p } : item); });
        logActivity(db, 'تحديث جماعي للأسعار', `تم تحديث أسعار ${products.length} منتج`);
        saveDb(db); return true;
    },
    saveUser: async (u: any) => {
        const db = getDb();
        // مزامنة تلقائية: عند حفظ مستخدم جديد أو تعديل مستخدم، إذا كان له دور، يتم نسخ صلاحيات الدور له
        const role = db.roles.find((r: any) => r.id === u.roleId);
        if (role) {
            u.permissions = { ...role.permissions };
        }
        if (u.id) db.users = db.users.map((item: any) => item.id === u.id ? { ...item, ...u } : item); 
        else { u.id = `u-${Date.now()}`; db.users.push(u); } 
        logActivity(db, 'إدارة المستخدمين', `حفظ بيانات المستخدم: ${u.name}`); 
        saveDb(db); return u;
    },
    saveStockTransfer: async (st: any) => {
        const db = getDb(); st.id = `st-${Date.now()}`; st.date = new Date().toISOString(); if (!db.stockTransfers) db.stockTransfers = []; db.stockTransfers.unshift(st);
        const p = db.products.find((prod: any) => prod.id === st.productId);
        if (p) {
            if(!p.warehouseStocks) p.warehouseStocks = {};
            p.warehouseStocks[st.fromWarehouseId] = (p.warehouseStocks[st.fromWarehouseId] || 0) - st.quantity;
            p.warehouseStocks[st.toWarehouseId] = (p.warehouseStocks[st.toWarehouseId] || 0) + st.quantity;
            p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
        }
        logActivity(db, 'تحويل مخزني', `تحويل ${st.quantity} من المنتج ${p?.name}`);
        saveDb(db); return true;
    },
    getShippingCompanies: async () => getDb().shippingCompanies || [],
    saveShippingCompany: async (c: any) => { const db = getDb(); if (c.id) db.shippingCompanies = db.shippingCompanies.map((item: any) => item.id === c.id ? { ...item, ...c } : item); else { c.id = `sc-${Date.now()}`; db.shippingCompanies.push(c); } logActivity(db, 'إدارة شركات الشحن', `حفظ بيانات شركة الشحن: ${c.name}`); saveDb(db); return c; },
    deleteShippingCompany: async (id: string) => {
        const db = getDb();
        db.shippingCompanies = db.shippingCompanies.filter((c: any) => c.id !== id);
        logActivity(db, 'حذف شركة شحن', `تم حذف شركة شحن ذو المعرف: ${id}`);
        saveDb(db);
        return true;
    },
    savePurchaseReturn: async (r: any) => {
        const db = getDb(); r.id = `pr-${Date.now()}`; if (!db.purchaseReturns) db.purchaseReturns = []; db.purchaseReturns.unshift(r);
        r.items.forEach((item: any) => {
            const p = db.products.find((prod: any) => prod.id === item.productId);
            if (p) {
                if(!p.warehouseStocks) p.warehouseStocks = {};
                p.warehouseStocks[r.warehouseId] = (p.warehouseStocks[r.warehouseId] || 0) - item.quantity;
                p.stock = Object.values(p.warehouseStocks as Record<string, number>).reduce((a, b) => a + b, 0);
            }
        });
        if (r.totalRecovered > 0) logTransaction(db, 'income', r.totalRecovered, `مرتجع مشتريات #${r.originalPurchaseId}`, r.treasuryId, 'مرتجعات');
        logActivity(db, 'مرتجع مشتريات', `تسجيل مرتجع مشتريات بمبلغ مسترد ${r.totalRecovered}`);
        saveDb(db); return r;
    },
    getActivityLogs: async () => getDb().activityLogs || [],
    getEmployeePerformanceAnalytics: async (): Promise<EmployeePerformanceAnalytics> => {
        const db = getDb();
        const sales = db.sales || [];
        const performanceData: EmployeePerformanceData[] = db.users.map((u: any) => {
            const userSales = sales.filter((s: any) => s.cashier?.id === u.id);
            const totalSalesValue = userSales.reduce((sum: number, s: any) => sum + s.total, 0);
            const totalSalesCount = userSales.length;
            const averageSaleValue = totalSalesCount > 0 ? totalSalesValue / totalSalesCount : 0;
            const userReturns = db.salesReturns.filter((r: any) => r.user?.id === u.id);
            const totalReturnsValue = userReturns.reduce((sum: number, r: any) => sum + r.totalRefund, 0);
            const returnRate = totalSalesValue > 0 ? (totalReturnsValue / totalSalesValue) * 100 : 0;

            return {
                userId: u.id,
                userName: u.name,
                totalSalesValue,
                totalSalesCount,
                averageSaleValue,
                totalReturnsValue,
                returnRate
            };
        });

        return {
            performanceData,
            topPerformerByValue: [...performanceData].sort((a, b) => b.totalSalesValue - a.totalSalesValue)[0],
            topPerformerByCount: [...performanceData].sort((a, b) => b.totalSalesCount - a.totalSalesCount)[0],
        };
    },
    submitFeedback: async (feedback: any) => {
        const db = getDb();
        if (!db.feedback) db.feedback = [];
        db.feedback.push({ id: `fb-${Date.now()}`, date: new Date().toISOString(), ...feedback });
        saveDb(db);
        return true;
    },
    getSyncLogs: async () => [], getQueueCount: async () => 0, processQueue: async () => {}, setOnlineStatus: (o: boolean) => {}, getSatisfactionAnalytics: async () => ({ happy: 0, neutral: 0, unhappy: 0, total: 0 }), getSalesHistoryForForecast: async () => [], getSupplierPerformanceData: async () => [], getInactiveCustomers: async (d: number) => [], getStagnantProducts: async (d: number) => [], updateSystemVersion: async (v: string, p: any) => {}, getJournalEntries: async () => []
};

import React, { useState, useEffect } from 'react';
import type { Role, PermissionKey, Permissions } from '../../types';
import Button from '../ui/Button';
import { PERMISSION_DEFINITIONS } from '../../permissions';
import { Shield, Info } from 'lucide-react';

interface RoleFormProps {
  role: Role | null;
  onSave: (data: Omit<Role, 'id'> & { id?: string }) => void;
  onCancel: () => void;
  isLoading: boolean;
}

const RoleFormModal: React.FC<RoleFormProps> = ({ role, onSave, onCancel, isLoading }) => {
  const [name, setName] = useState('');
  const [permissions, setPermissions] = useState<Permissions>({});

  useEffect(() => {
    if (role) {
      setName(role.name);
      setPermissions(role.permissions);
    } else {
      setName('');
      setPermissions({});
    }
  }, [role]);

  const handlePermissionChange = (key: PermissionKey, checked: boolean) => {
    setPermissions(prev => ({
      ...prev,
      [key]: checked,
    }));
  };

  const handleSelectAll = () => {
    const allPerms: Permissions = {};
    Object.keys(PERMISSION_DEFINITIONS).forEach(key => {
        allPerms[key as PermissionKey] = true;
    });
    setPermissions(allPerms);
  };

  const handleClearAll = () => {
    setPermissions({});
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ id: role?.id, name, permissions });
  };

  const inputStyle = "mt-1 block w-full rounded-xl border-slate-300 dark:border-slate-600 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 bg-white dark:bg-slate-800 dark:text-white p-3 border transition-all font-black";

  return (
    <form onSubmit={handleSubmit} className="space-y-6 animate-fadeIn">
      <div>
        <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ms-1">اسم الدور الوظيفي</label>
        <input 
            type="text" 
            value={name} 
            onChange={e => setName(e.target.value)} 
            required 
            className={inputStyle} 
            placeholder="مثال: كاشير مسائي، مدير مخازن..." 
        />
      </div>

      <div className="space-y-4">
        <div className="flex justify-between items-center px-1">
            <h4 className="text-lg font-black text-slate-800 dark:text-white flex items-center gap-2">
                <Shield size={20} className="text-indigo-600" />
                صلاحيات الوصول المحددة
            </h4>
            <div className="flex gap-2">
                <button type="button" onClick={handleSelectAll} className="text-[10px] font-black text-indigo-600 hover:underline">تحديد الكل</button>
                <button type="button" onClick={handleClearAll} className="text-[10px] font-black text-rose-500 hover:underline">إلغاء الكل</button>
            </div>
        </div>

        <div className="grid grid-cols-1 gap-3 border dark:border-slate-800 rounded-2xl p-4 max-h-[400px] overflow-y-auto bg-slate-50 dark:bg-slate-900/50 custom-scrollbar">
            {Object.entries(PERMISSION_DEFINITIONS).map(([key, { name, description }]) => (
                <label 
                    key={key} 
                    className={`flex items-start gap-4 p-4 rounded-xl border-2 transition-all cursor-pointer group ${permissions[key as PermissionKey] ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20' : 'border-white dark:border-slate-800 bg-white dark:bg-slate-800 hover:border-slate-200'}`}
                >
                    <div className="pt-0.5">
                        <input
                            type="checkbox"
                            checked={permissions[key as PermissionKey] || false}
                            onChange={e => handlePermissionChange(key as PermissionKey, e.target.checked)}
                            className="h-5 w-5 text-indigo-600 border-slate-300 rounded-lg focus:ring-indigo-500"
                        />
                    </div>
                    <div>
                        <p className={`font-black text-sm transition-colors ${permissions[key as PermissionKey] ? 'text-indigo-600' : 'text-slate-700 dark:text-slate-200'}`}>
                            {name}
                        </p>
                        <p className="text-[10px] text-slate-500 dark:text-slate-400 mt-1 leading-relaxed font-bold">
                            {description}
                        </p>
                    </div>
                </label>
            ))}
        </div>
        <div className="flex items-center gap-2 p-3 bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-800 rounded-xl text-amber-700 dark:text-amber-400">
            <Info size={16} />
            <p className="text-[10px] font-bold">سيتم تحديث صلاحيات جميع الموظفين المرتبطين بهذا الدور فور ضغط زر الحفظ.</p>
        </div>
      </div>

      <div className="flex justify-end gap-3 pt-4 border-t dark:border-slate-800">
        <Button type="button" variant="secondary" onClick={onCancel} className="rounded-xl px-6">إلغاء</Button>
        <Button type="submit" isLoading={isLoading} className="rounded-xl px-10 bg-indigo-600 font-black shadow-lg shadow-indigo-500/20">
            {role ? 'حفظ التعديلات' : 'إنشاء الدور'}
        </Button>
      </div>
    </form>
  );
};

export default RoleFormModal;
